P.entries["quest:94241"] = {n="工匠文书: Dark Leather Tunic",s="一张褪色且可转让的委托单，要求交付一件 Dark Leather Tunic，并注明了交货和付款详情。完成交易时必须持有委托单。",h="一张褪色且可转让的委托单，要求交付一件 Dark Leather Tunic，并注明了交货和付款详情。完成交易时必须持有委托单。",kw={"工匠文书","顾客","dark leather tunic","交付","付款","可转让的委托单","外衣"},sec={{t="委托单",b="顾客留下了一张褪色的便条，请你交付一件 Dark Leather Tunic。便条写明了衣物的交付地点和付款安排。委托单可以转交他人，但完成交易时你必须持有它。"}},faq={{q="委托单要求什么物品？",a="顾客要一件 Dark Leather Tunic。",al={"对方要什么物品","深色外衣委托","委托物品"}},{q="我该把外衣送到哪里？",a="委托单上标明了交付地点，地图上也有标记。",al={"交货地点","送到哪里","委托单地点"}},{q="我需要留着委托单吗？",a="需要。完成交易时，你必须持有委托单。",al={"需要便条吗","必须持有委托单","需要委托单"}},{q="我可以把委托单转交给别人吗？",a="可以。便条上说委托单可以转让。",al={"可转让的便条","可以交易吗","转交委托单"}},{q="委托单上说明了付款方式吗？",a="便条上写有付款信息。",al={"报酬多少","付款详情","付款是什么"}}},fp="36,144,8.229.0,27.45.0,29.55.0,27.70.0,36.44.0,30.44.0"}
P.entries["quest:94242"] = {n="工匠文书: Pilferer's Gloves",s="一份可转让的委托书要求交付一双 Pilferer's Gloves，并注明了交付和付款详情。完成交易时必须持有这份委托书。",h="一份可转让的委托书要求交付一双 Pilferer's Gloves，并注明了交付和付款详情。完成交易时必须持有这份委托书。",kw={"工匠文书","交付","手套","付款","pilferer's gloves","可转让","委托书"},sec={{t="书面委托",b="一张褪色的纸条要求交付一双 Pilferer's Gloves。上面写明了交付地点和付款安排，这份委托书可以转交他人。"},{t="完成交易",b="把所需的手套送到地图上标记的地点时，你必须随身携带这份委托书。纸条将交付和付款详情与这份书面委托联系在一起。"}},faq={{q="委托书要求什么？",a="委托书要求交付一双 Pilferer's Gloves。",al={"pilferer's gloves 委托书","手套订单","所需物品"}},{q="手套要送到哪里？",a="交付地点已在你的地图上标出。",al={"交付地点","手套送往何处","标记地点"}},{q="完成交易需要什么？",a="完成交易时，你必须持有这份委托书。",al={"需要委托书","委托书要求","完成交易"}},{q="委托书上写了付款方式吗？",a="委托书上有付款信息。",al={"付款详情","付款金额","手套付款"}},{q="别人可以携带这份委托书吗？",a="可以。这份委托书可以转交他人。",al={"可转让的委托书","转交纸条","可以转交吗"}}},fp="35,141,15.156.0,15.156.0,27.48.0,30.44.0,43.65.0,36.44.0,32.30.0"}
P.entries["quest:94243"] = {n="Craftsman's Writ: Heavy Quiver",s="一张褪色的委托书要求交付一只重型箭袋，并注明了交付和付款详情。委托书可以转交，但完成交易时必须随身携带。",h="一张褪色的委托书要求交付一只重型箭袋，并注明了交付和付款详情。委托书可以转交，但完成交易时必须随身携带。",kw={"工匠委托书","交付","重型箭袋","付款","箭袋","可转交"},sec={{t="委托书",b="纸条要求你取得指定物品，并将其送到地图上标记的位置。交易时必须随身携带委托书。"}},faq={{q="委托书要求什么？",a="顾客要求一只重型箭袋。",al={"重型箭袋委托","需要什么物品"}},{q="要送到哪里？",a="交付地点已在地图上标出。",al={"交付地点","箭袋送到哪里"}},{q="我需要随身携带委托书吗？",a="是的。完成交易时必须随身携带委托书。",al={"是否需要委托书","必须携带委托书"}},{q="我能把委托书交给别人吗？",a="可以。纸条上说委托书可以转交。",al={"转交委托书","别人能用吗"}},{q="委托书提到付款了吗？",a="纸条中包含付款信息，但没有写明金额。",al={"付款金额","箭袋付款"}}},fp="30,121,8.140.0,27.39.0,22.41.0,28.54.0,37.49.0,30.56.0"}
P.entries["quest:94245"] = {n="工匠文书: Barbaric Gloves",s="一份可转让的委托书请求交付 Barbaric Gloves，并注明了交付地点和付款详情。完成交易时，你必须随身携带这份委托书。",h="一份可转让的委托书请求交付 Barbaric Gloves，并注明了交付地点和付款详情。完成交易时，你必须随身携带这份委托书。",kw={"barbaric gloves","工匠文书","交付","手套","付款","可转让","委托书"},sec={{t="顾客的请求",b="一位顾客通过这份褪色的委托书请求一副 Barbaric Gloves。委托书注明了交付地点和付款详情，而且可以转交他人。交付所请求的物品时，你必须持有这份委托书。"}},faq={{q="委托书请求交付什么？",a="顾客请求一副 Barbaric Gloves。",al={"barbaric gloves 委托书","什么手套","工匠委托书"}},{q="我该把手套送到哪里？",a="交付地点已标记在你的地图上。",al={"交付地点","手套送到哪里"}},{q="我需要随身携带委托书吗？",a="需要。完成交易时，你必须持有这份委托书。",al={"需要随身携带委托书","需要委托书"}},{q="这份委托书可以转交吗？",a="可以。委托书上说它可以转交他人。",al={"转交委托书"}},{q="委托书上关于付款写了什么？",a="委托书上注明了付款信息。",al={"付款详情","付款金额"}}},fp="33,151,20.237.0,27.50.0,30.44.0,28.70.0,28.44.0,37.44.0"}
P.entries["quest:94246"] = {n="工匠文书: Red Whelp Gloves",s="一份可转让的委托书，要求交付一双 Red Whelp Gloves，并注明了交付地点和报酬。",h="一份可转让的委托书，要求交付一双 Red Whelp Gloves，并注明了交付地点和报酬。",kw={"工匠文书","交付","报酬","red whelp gloves","可转让","委托书"},sec={{t="书面委托",b="一张褪色的字条要求交付一双 Red Whelp Gloves，并注明了交付地点和报酬。你必须持有委托书才能完成交易。"}},faq={{q="委托书要求交付什么？",a="委托书要求交付一双 Red Whelp Gloves。",al={"red whelp gloves委托书","要求的物品"}},{q="我该把手套送到哪里？",a="委托书提供了一个标记在你地图上的交付地点。",al={"交付地点","手套送到哪里"}},{q="完成交易需要什么？",a="你必须持有委托书才能完成交易。",al={"需要什么","委托书要求"}},{q="委托书可以转让吗？",a="可以。字条上说这份委托书可以转让。",al={"可转让的委托书","别人能接手吗"}},{q="委托书提到报酬了吗？",a="提到了。委托书中包含报酬信息。",al={"报酬金额","手套的报酬"}}},fp="34,114,17.145.0,27.47.0,30.57.0,40.62.0,28.44.0,30.49.0"}
P.entries["quest:94249"] = {n="工匠文书: Azure Silk Hood",s="一份褪色的工匠文书要求交付一件 Azure Silk Hood，并注明交付与付款条件。完成交易时，你必须持有这份委托书。",h="一份褪色的工匠文书要求交付一件 Azure Silk Hood，并注明交付与付款条件。完成交易时，你必须持有这份委托书。",kw={"azure silk hood","工匠文书","交付","付款","丝绸兜帽","可转让","委托书"},sec={{t="书面条款",b="这张便笺用褪色的墨水写成，只列出一件物品：Azure Silk Hood。便笺还注明了交付地点和付款方式。这份委托书可以转交给他人，但完成交易时你必须随身携带。"}},faq={{q="委托书要求什么？",a="客户要求一件 Azure Silk Hood。",al={"azure silk hood委托书","需要什么物品","工匠文书"}},{q="我该把兜帽送到哪里？",a="交付地点已在你的地图上标出。",al={"交付地点","送到哪里","标记的地点"}},{q="完成交易需要什么？",a="你必须持有指定物品和委托书。",al={"需要带什么","需要委托书吗","完成交易"}},{q="委托书说明了付款方式吗？",a="便笺中包含付款信息，但此处没有注明金额。",al={"付款金额","付款条件","我能得到什么"}},{q="别人可以携带这份委托书吗？",a="可以。这份委托书注明可转让。",al={"可转让的委托书","可以转交吗","谁可以持有"}}},fp="33,144,17.225.0,27.42.0,28.44.0,35.60.0,36.91.0,32.40.0"}
P.entries["quest:94250"] = {n="工匠文书: Small Silk Pack",s="一份可转让的委托书要求交付一个 Small Silk Pack，并说明了交付方式和报酬。完成交易时必须持有这份委托书。",h="一份可转让的委托书要求交付一个 Small Silk Pack，并说明了交付方式和报酬。完成交易时必须持有这份委托书。",kw={"工匠文书","交付","报酬","丝绸","small silk pack","可转让","委托书"},sec={{t="委托书",b="一位顾客留下了一张褪色的便条，向你索要一个 Small Silk Pack。便条上写明了交付地点和报酬方式。这份委托书可以转交他人，但完成交易时你必须持有它。"}},faq={{q="委托书要什么？",a="顾客要一个 Small Silk Pack。",al={"small silk pack 委托书","索要什么物品","丝绸包裹需求"}},{q="我该把包裹送到哪里？",a="委托书上写有交付信息，地图上也标出了地点。",al={"交付地点","送到哪里","交货地点在哪里"}},{q="报酬如何结算？",a="委托书上写有报酬信息。",al={"能拿到多少报酬","报酬详情","报酬是什么"}},{q="我能把委托书转交给别人吗？",a="可以。便条上说这份委托书可以转交他人。",al={"委托书能否转让","转交委托书","转交给别人"}},{q="完成交易时需要委托书吗？",a="需要。完成交易时，你必须持有这份委托书。",al={"交付时需要委托书吗","必须留着便条吗","需要委托书"}}},fp="33,141,8.220.0,27.42.0,28.79.0,23.44.0,40.44.0,44.70.0"}
P.entries["quest:94252"] = {n="工匠文书: Red Woolen Boots",s="一份可转让的委托书要求交付一双 Red Woolen Boots，并注明交付地点和报酬信息。完成交易时，你必须持有这份委托书。",h="一份可转让的委托书要求交付一双 Red Woolen Boots，并注明交付地点和报酬信息。完成交易时，你必须持有这份委托书。",kw={"靴子","工匠文书","交付","报酬","red woolen boots","可转让","委托书"},sec={{t="书面委托",b="一张褪色的纸条请你提供一双 Red Woolen Boots。上面注明了交付地点和报酬安排。委托书可以转让，但完成交易时你必须持有它。"}},faq={{q="委托书要求提供什么？",a="委托书要求提供一双 Red Woolen Boots。",al={"红靴委托书","要求提供什么靴子"}},{q="靴子要交到哪里？",a="委托书注明了交付信息，地图上会显示标记地点。",al={"交付地点","红靴交到哪里"}},{q="报酬如何安排？",a="委托书上注明了报酬信息。",al={"靴子的报酬","报酬是多少"}},{q="我能转让这份委托书吗？",a="可以。纸条上说这份委托书可以转让。",al={"可转让委托书","别人能代为携带吗"}},{q="完成交易时需要持有委托书吗？",a="需要。完成交易时，你必须持有这份委托书。",al={"需要随身携带委托书吗","完成交易"}}},fp="34,143,19.213.0,27.47.0,29.81.0,24.44.0,25.44.0,44.75.0"}
P.entries["quest:94253"] = {n="Craftsman's Writ: Colorful Kilt",s="一位顾客通过可转让的委托书订制多彩褶裙，打算穿上它混入祖尔格拉布。",h="一位顾客通过可转让的委托书订制多彩褶裙，打算穿上它混入祖尔格拉布。",kw={"多彩褶裙","工匠委托书","交付","伪装","祭仪师","祖尔格拉布"},sec={{t="伪装",b="委托书要求你提供一条多彩褶裙，并送到标记的地点。顾客打算穿得像祖尔格拉布的祭仪师一样，偷偷穿过大门，并称这条褶裙很适合伪装。"}},faq={{q="委托书要求提供什么？",a="委托书要求提供一条多彩褶裙，并送到地图上标记的地点。",al={"多彩褶裙委托书","所需物品"}},{q="顾客为什么想要多彩褶裙？",a="顾客打算穿得像祖尔格拉布的祭仪师一样，偷偷潜入其中，并称这条褶裙会派上用场。",al={"褶裙用途","褶裙伪装"}},{q="我可以转让这份委托书吗？",a="可以。委托书上写明它可以转让。",al={"转让委托书","转交委托书"}},{q="我该把褶裙送到哪里？",a="委托书指示你前往地图上标记的地点。",al={"交付地点","送到哪里"}}},fp="31,121,10.206.0,27.88.0,43.104.0,25.38.0,32.56.0"}
P.entries["quest:94255"] = {n="工匠文书: Spider Silk Slippers",s="一份可转让的委托书征求一双 Spider Silk Slippers，并注明了交付和付款详情。完成交易时，请随身带着委托书。",h="一份可转让的委托书征求一双 Spider Silk Slippers，并注明了交付和付款详情。完成交易时，请随身带着委托书。",kw={"工匠文书","交付","付款","拖鞋","spider silk slippers","可转让","委托书"},sec={{t="书面请求",b="一位顾客用褪色的墨迹写下委托书，请你取得 Spider Silk Slippers。委托书注明了交付地点和付款安排。委托书可以转交给他人，但交易时你必须持有它。"}},faq={{q="委托书要什么？",a="顾客想要 Spider Silk Slippers。",al={"要什么拖鞋","蛛丝请求"}},{q="我该把拖鞋送到哪里？",a="委托书注明了交付地点，该地点已在你的地图上标出。",al={"交付地点","送到哪里"}},{q="如何付款？",a="委托书中写有付款信息。",al={"付款金额","付款详情"}},{q="我能把委托书交给别人吗？",a="可以。委托书注明了它可以转让。",al={"能否转让","转交委托书"}},{q="我需要留着委托书吗？",a="需要。你必须持有委托书才能完成交易。",al={"需要委托书","没有它能否完成"}}},fp="38,148,17.224.0,27.43.0,32.57.0,23.44.0,36.38.0,27.75.0"}
P.entries["quest:94260"] = {n="工匠文书: Catseye Draught",s="一份可转让的委托书要求交付一瓶Catseye Draught，并注明了交付和付款详情。完成交易时，你必须持有这份委托书。",h="一份可转让的委托书要求交付一瓶Catseye Draught，并注明了交付和付款详情。完成交易时，你必须持有这份委托书。",kw={"catseye draught","工匠文书","交付","付款","可转让","委托书"},sec={{t="书面请求",b="这张褪色的便条写着一位顾客的请求，要求交付一瓶Catseye Draught。便条还注明了交付地点和付款详情，并说明委托书可以转交他人。交付所需物品时，你必须持有这份委托书，才能完成交易。"}},faq={{q="委托书要求什么？",a="顾客要求交付一瓶Catseye Draught。",al={"catseye draught委托书","要求交付什么物品"}},{q="我该把药剂送到哪里？",a="便条注明了交付地点，该地点已标记在你的地图上。",al={"交付地点","送到哪里"}},{q="完成交易需要委托书吗？",a="需要。完成交易时，你必须持有这份委托书。",al={"是否需要委托书","必须持有委托书"}},{q="委托书可以转交吗？",a="可以。便条说明这份委托书可以转交他人。",al={"可转让的委托书","能否由他人携带"}},{q="便条说明了付款方式吗？",a="便条中包含付款信息。",al={"付款详情","付款金额"}}},fp="33,144,19.253.0,27.42.0,31.58.0,44.69.0,28.44.0,36.44.0"}
P.entries["quest:94261"] = {n="工匠文书: Great Rage Potion",s="月光林地有一份可转让的委托书，求购一瓶 Great Rage Potion。委托人说，永夜港的一些资深德鲁伊需要它来进行隐秘仪式。",h="月光林地有一份可转让的委托书，求购一瓶 Great Rage Potion。委托人说，永夜港的一些资深德鲁伊需要它来进行隐秘仪式。",kw={"工匠文书","德鲁伊","great rage potion","月光林地","永夜港","愤怒","仪式"},sec={{t="月光林地的委托书",b="月光林地的一位顾客请你将一瓶 Great Rage Potion 送到标记地点。委托书可以转让，完成交易时必须由你随身携带。便条上还注明了交付和付款详情。"},{t="永夜港的仪式",b="委托人说，永夜港的一些资深德鲁伊会离开林地中的其他同伴，参与暴力仪式。Great Rage Potion 能帮助他们克服自己努力修炼出的平静。在这片林地，委托人认为愤怒也是维持平衡的一部分。"}},faq={{q="委托书要求什么？",a="委托书要求一瓶 Great Rage Potion，并提到了交付和报酬信息。",al={"great rage potion 委托书","需要什么药水"}},{q="我该把药水送到哪里？",a="委托书指引你前往地图上标记的位置。",al={"委托书交付地点","送到哪里"}},{q="为什么要 Great Rage Potion？",a="委托人说，永夜港的一些资深德鲁伊会在隐秘的暴力仪式中使用它，以克服自身的平静。",al={"为什么要愤怒药水","有什么用途"}},{q="谁会使用这瓶药水？",a="委托人说，永夜港的一些资深德鲁伊会在隐秘仪式中使用 Great Rage Potion。",al={"谁要愤怒药水","德鲁伊药水"}},{q="别人可以携带这份委托书吗？",a="可以。委托书上说它可以转让。",al={"可转让的委托书","可以转交委托书吗"}},{q="完成交易时需要携带委托书吗？",a="需要。完成交易时，委托书必须在你身上。",al={"需要放在背包里吗","需要委托书"}}},fp="35,164,19.220.0,21.268.0,27.87.0,27.56.0,34.125.0,20.114.0,32.38.0,44.69.0"}
P.entries["quest:94274"] = {n="工匠文书: Golden Scale Coif",s="一份褪色且可转让的委托单要求交付一顶 Golden Scale Coif。单据记录了顾客指定的送货地点和付款方式。",h="一份褪色且可转让的委托单要求交付一顶 Golden Scale Coif。单据记录了顾客指定的送货地点和付款方式。",kw={"护头巾","工匠文书","送货","golden scale coif","付款","可转让","委托单"},sec={{t="委托单",b="顾客在一张褪色的字条上请你制作一顶 Golden Scale Coif。字条还写明了送货地点和付款详情。委托单可以转交他人，但完成交易时必须随身携带。"}},faq={{q="委托单要求交付什么？",a="顾客要求交付一顶 Golden Scale Coif。",al={"golden scale coif 委托单","所需物品"}},{q="我该把帽子送到哪里？",a="委托单会在地图上标出送货地点。",al={"送货地点","送到哪里"}},{q="我会如何获得报酬？",a="委托单上写有付款信息。",al={"付款详情","付款内容"}},{q="我可以把委托单转交给别人吗？",a="可以。字条上说明委托单可以转交他人。",al={"可转让的委托单","可以转交吗"}},{q="完成交易时需要委托单吗？",a="需要。完成交易时必须随身携带委托单。",al={"完成交易需要委托单","必须带着字条吗"}}},fp="35,131,8.212.0,27.44.0,28.53.0,19.44.0,36.44.0,47.68.0"}
P.entries["quest:94286"] = {n="工匠文书: Flash Bomb",s="一份可转让的委托书向顾客索取一枚 Flash Bomb。便笺要求将物品送到标记地点，并提供付款信息。",h="一份可转让的委托书向顾客索取一枚 Flash Bomb。便笺要求将物品送到标记地点，并提供付款信息。",kw={"工匠文书","送货","flash bomb","付款","可转让","委托书"},sec={{t="委托书",b="一张褪色的便笺索取一枚 Flash Bomb，并注明了送货地点和付款信息。委托书可以转让，但你必须持有它才能完成交易。地图上会显示标记地点。"}},faq={{q="委托书索取什么？",a="委托书索取一枚 Flash Bomb，并要求提供送货和付款信息。",al={"flash bomb委托书","所需物品","匠人委托书"}},{q="我可以转让委托书吗？",a="可以。便笺上说委托书可以转让。",al={"委托书是否可转让","转交委托书","赠送委托书"}},{q="完成交易需要什么？",a="你需要持有委托书和所需物品，然后将物品送到地图上标记的地点。",al={"所需物品","如何完成交易","送货要求"}}},fp="28,140,8.205.0,27.84.0,24.44.0,40.112.0"}
P.entries["quest:94293"] = {n="工匠文书: Guardian Cloak",s="艾瑟雷索的一位顾客通过一份可转让的委托状请求一件Guardian Cloak。这件斗篷能帮助保护文物，免遭纳迦和半人马侵扰。",h="艾瑟雷索的一位顾客通过一份可转让的委托状请求一件Guardian Cloak。这件斗篷能帮助保护文物，免遭纳迦和半人马侵扰。",kw={"文物","半人马","斗篷","工匠文书","艾瑟雷索","guardian cloak","纳迦","可转让的委托状"},sec={{t="书面委托",b="一份褪色的委托状请你将Guardian Cloak送到标记地点。上面还写明了交付和付款的细节，并注明委托状可以转交给他人。"},{t="艾瑟雷索",b="这位顾客正在研究艾瑟雷索的奥秘。他们打算用这件斗篷包裹在那里发现的文物，将它们藏起来，避开纳迦和半人马。"}},faq={{q="委托状要求什么？",a="顾客要一件Guardian Cloak，褪色的便笺上写着交付和付款的细节。",al={"guardian cloak委托状","他们想要什么物品"}},{q="我能把委托状交给别人吗？",a="可以。便笺上说委托状可以转交。",al={"委托状可以转交吗","转交委托状"}},{q="顾客为什么想要Guardian Cloak？",a="顾客打算用它包裹文物，以妥善保管。",al={"斗篷有什么用","为什么要guardian cloak"}},{q="顾客想把文物藏起来，避开谁？",a="顾客想在艾瑟雷索保护文物，使其免遭纳迦和半人马侵扰。",al={"把文物藏起来避开谁","纳迦和半人马"}}},fp="32,148,17.170.0,15.160.0,27.102.0,36.44.0,44.65.0,50.79.0"}
P.entries["quest:94298"] = {n="工匠文书: Swift Boots",s="一位顾客通过一份可转让的委托书订购一双 Swift Boots。你必须持有委托书才能完成交付和付款。",h="一位顾客通过一份可转让的委托书订购一双 Swift Boots。你必须持有委托书才能完成交付和付款。",kw={"靴子","工匠文书","交付","付款","swift boots","可转让","委托书"},sec={{t="顾客的请求",b="一张褪色的便条请你提供一双 Swift Boots。上面还提到了交付地点和付款。委托书可以转让，但你必须持有它才能完成交易。"}},faq={{q="委托书要求提供什么？",a="顾客订购了一双 Swift Boots。",al={"swift boots 委托书","订购什么靴子"}},{q="我该把靴子送到哪里？",a="交付地点已标记在你的地图上。",al={"交付地点","靴子送到哪里"}},{q="我需要保留委托书吗？",a="需要。你必须随身携带委托书才能完成交易。",al={"是否需要委托书","需要委托书"}},{q="我能把委托书交给别人吗？",a="可以。委托书上说它可以转让。",al={"转让委托书","是否可以转让"}},{q="顾客提到付款了吗？",a="便条提到了付款，但没有写明金额。",al={"靴子付款","付款金额是多少"}}},fp="29,128,20.200.0,27.46.0,29.44.0,27.65.0,36.41.0,34.47.0"}
P.entries["quest:943"] = {n="健忘的勘察员",s="这个任务标志着勘察员雷姆塔维尔在黑海岸的发掘工作所引发的搜寻行动的最后一章。米奈希尔港的考古学家弗拉冈特试图将雷姆塔维尔的发现与他自己的化石以及丢失的雷鲁之石结合起来，以解开古代遗物隐藏的力量。",h="这个任务标志着勘察员雷姆塔维尔在黑海岸的发掘工作所引发的搜寻行动的最后一章。米奈希尔港的考古学家弗拉冈特试图将雷姆塔维尔的发现与他自己的化石以及丢失的雷鲁之石结合起来，以解开古代遗物隐藏的力量。",kw={"黑海岸","探险者协会","弗拉冈特","化石","米奈希尔","雷姆塔维尔","雷鲁之石","湿地","维尔加"},ang={["faction:Alliance"]="联盟的信使和冒险者经常往来于暗夜精灵领地黑海岸和米奈希尔港周围的矮人定居点之间，跨越海洋的阻隔。",["race:Dwarf"]="这个任务链体现了探险者协会的核心使命，即连接跨越大陆的偏远挖掘点，以拼凑出矮人的遗产和泰坦的奥秘。"},sec={{t="跨大陆考古学",b="最初在黑海岸北部协助心不在焉的勘察员雷姆塔维尔的护送任务，最终演变成了横跨无尽之海、前往湿地的沼泽地的旅程。考古学家弗拉冈特原本的化石由勘察员维尔加在他位于湿地的发掘场保管。考古学家弗拉冈特在审查收集到的发现时意识到，要解开化石中蕴含的神秘力量，需要一件关键文物：雷鲁之石。"},{t="遗失在沼泽中",b="在弗拉冈特与维尔加会合之前，一群斑点迅猛龙在路上伏击了他的商队，并吞下了雷鲁之石。为了拼凑出这个谜团，弗拉冈特需要一名冒险者去猎杀这些掠食野兽，找回被吞下的石头，并从维尔加的营地取回最初的化石。随着化石和关键物品的集齐，这两位矮人研究员希望能够揭开这些遗物的真正起源和力量。"}},faq={{q="为什么黑海岸的任务会以湿地作为终点？",a="探险者协会在卡利姆多和东部王国都保持着活跃的运作。首席考古学家杜瑟·灰须将雷姆塔维尔的化石从黑海岸跨海送到了湿地的考古学家弗拉冈特手中，通过共享研究成果将这两个挖掘点联系在了一起。",al={"为什么黑海岸任务会在湿地结束","米奈希尔港的联系","为什么送到湿地"}},{q="雷鲁之石是什么？",a="雷鲁之石是考古学家弗拉冈特找回的一件古代遗物。他认为它是一种密码或催化剂，能够解开保存在黑海岸和湿地发掘出的化石中的沉睡魔法秘密。",al={"雷鲁之石","雷鲁之石是什么","雷鲁遗物"}},{q="谁是考古学家弗拉冈特？",a="考古学家弗拉冈特是矮人探险者协会的一名成员，常驻于米奈希尔港。他研究从周边挖掘点找回的古代遗物，并希望解开勘察员雷姆塔维尔和维尔加所发现的化石中隐藏的力量。",al={"弗拉冈特","谁是弗拉冈特"}},{q="谁持有最初的化石？",a="勘察员维尔加在他位于湿地的挖掘场持有弗拉冈特的原始化石。你已经将雷姆塔维尔在黑海岸发现的化石交付给了弗拉冈特。",al={"化石在哪里","谁有雷姆塔维尔的化石","维尔加的化石"}},{q="为什么迅猛龙会有雷鲁之石？",a="在前往与勘察员维尔加商讨的湿地路上，弗拉冈特遭到了斑点迅猛龙的伏击。在混乱的袭击中，其中一只掠食野兽将石头整颗吞了下去。",al={"迅猛龙吞下的遗物","为什么迅猛龙有石头"}},{q="矮人们期望化石能起到什么作用？",a="弗拉冈特相信化石中蕴含着隐藏的力量和过去的秘密，而雷鲁之石就是解开它们的关键。",al={"化石的力量","化石有什么作用"}}},fp="28,229,29.366.0,19.376.1,48.246.0,26.221.0,31.241.0,28.162.0,38.172.0,45.133.0"}
P.entries["quest:94300"] = {n="工匠文书: Big Voodoo Mask",s="一份可转交他人的委托书，要求交付一件 Big Voodoo Mask，并注明交付和付款详情。完成交易时必须持有委托书。",h="一份可转交他人的委托书，要求交付一件 Big Voodoo Mask，并注明交付和付款详情。完成交易时必须持有委托书。",kw={"big voodoo mask","工匠文书","交付","面具","付款","可转交","委托书"},sec={{t="委托书",b="这张褪色的纸条要求交付一件 Big Voodoo Mask，并说明交付地点和付款方式。末尾写明委托书可以转交他人。交付时必须持有委托书。"}},faq={{q="委托书要求交付什么？",a="顾客要一件 Big Voodoo Mask。",al={"需要什么物品","big voodoo mask委托书"}},{q="我能把委托书转交给别人吗？",a="可以。纸条上说委托书可以转交他人。",al={"委托书能否转交","能否由别人携带"}},{q="完成交易需要什么？",a="完成交易时，你必须持有委托书。",al={"需要带什么","委托书要求"}},{q="委托书上有交付和付款详情吗？",a="有。纸条上注明了交付地点和付款方式。",al={"交付地点","付款方式"}}},fp="33,135,8.234.0,27.42.0,36.44.0,43.69.0,48.75.0"}
P.entries["quest:94312"] = {n="工匠文书: Orange Martial Shirt",s="顾客的委托单要求制作一件Orange Martial Shirt，并注明了交付和付款详情。这张委托单可以转交他人。",h="顾客的委托单要求制作一件Orange Martial Shirt，并注明了交付和付款详情。这张委托单可以转交他人。",kw={"工匠文书","交付","orange martial shirt","付款","衬衣","可转让的委托单"},sec={{t="交付",b="便条注明了交付地点和付款条件。要完成交易，你必须随身携带委托单，顾客要的是一件Orange Martial Shirt。"}},faq={{q="委托单要求制作什么？",a="顾客要求制作一件Orange Martial Shirt。",al={"橙色衬衣委托单","什么衬衣","工匠委托单"}},{q="我该把衬衣交到哪里？",a="交付地点已在你的地图上标出。",al={"交付地点","该送到哪里","委托单位置"}},{q="交易需要什么？",a="你必须持有顾客要求的衬衣和委托单。",al={"需要带什么","需要委托单","如何完成交易"}},{q="委托单上写明了付款方式吗？",a="便条上写有付款信息。",al={"付款详情","要付多少钱","付款"}},{q="委托单可以转交他人吗？",a="可以。便条上写明委托单可以转让。",al={"转交委托单","可转让的委托单","转让委托单"}}},fp="38,127,12.157.0,27.47.0,29.44.0,35.61.0,36.44.0,28.44.0"}
P.entries["quest:94313"] = {n="工匠文书：白色强盗面罩",s="一张褪色的委托书要求交付一顶白色强盗面罩，并注明交付地点和付款条件。委托书可以转交，但完成交易时必须持有它。",h="一张褪色的委托书要求交付一顶白色强盗面罩，并注明交付地点和付款条件。委托书可以转交，但完成交易时必须持有它。",kw={"工匠文书","交付","付款","可转交","白色强盗面罩","委托书"},sec={{t="交付",b="顾客询问你是否带着货物前来。委托书上写明需要一顶白色强盗面罩，并注明交付地点和付款条件。完成交易时，你必须随身携带委托书。"}},faq={{q="委托书要求交付什么？",a="顾客要求交付一顶白色强盗面罩。",al={"白色强盗面罩委托书","需要什么物品"}},{q="我该把面罩送到哪里？",a="交付地点已标记在你的地图上。",al={"交付地点","送到哪里"}},{q="我需要随身携带委托书吗？",a="需要。完成交易时，你必须持有委托书。",al={"需要随身携带委托书吗","没有委托书能交付吗"}},{q="可以让别人携带委托书吗？",a="可以。委托书上写明可以转交。",al={"委托书可以转交吗","把委托书交给别人"}},{q="我到达时，顾客会问什么？",a="顾客会问你是否是来交付货物的。",al={"交付进度文本","你是来交付货物的吗"}}},fp="35,154,12.200.0,27.44.0,28.44.0,28.67.0,32.44.0,41.57.0"}
P.entries["quest:94316"] = {n="工匠文书: Potion of Demonslaying",s="一份可转让的委托书要求提供 Potion of Demonslaying，并注明交付和付款信息。",h="一份可转让的委托书要求提供 Potion of Demonslaying，并注明交付和付款信息。",kw={"工匠文书","交付","付款","药水","potion of demonslaying","可转让","委托书"},sec={{t="委托书",b="这张褪色的纸条要求提供一瓶 Potion of Demonslaying，并注明交付地点和付款方式。完成交易时，你必须随身携带委托书。"}},faq={{q="委托书要求提供什么？",a="委托书要求提供一瓶 Potion of Demonslaying。",al={"什么药水","委托书要求","potion of demonslaying"}},{q="我该在哪里交付？",a="交付地点已在你的地图上标出。",al={"交付地点","交到哪里","标记的地点"}},{q="付款方式是什么？",a="委托书中注明了付款信息。",al={"付款信息","能得到多少报酬","客户付款"}},{q="我可以把委托书交给别人吗？",a="可以。纸条上说这份委托书可以转让。",al={"转让委托书","可以转让吗","转交给别人"}},{q="我需要随身携带委托书吗？",a="需要。完成交易时，你必须随身携带委托书。",al={"需要委托书","必须随身携带","持有委托书"}}},fp="40,108,8.185.0,27.45.0,22.44.0,22.44.0,36.44.0,27.65.0"}
P.entries["quest:94369"] = {n="The Fate of Zephras",s="你将泽风岛面临的危险带给瓦拉纳尔的Talaanis 影歌。守护结界已失效，泽风岛暴露在奥拉基尔面前，泽风岛的居民必须决定如何保护家园。",h="你将泽风岛面临的危险带给瓦拉纳尔的Talaanis 影歌。守护结界已失效，泽风岛暴露在奥拉基尔面前，泽风岛的居民必须决定如何保护家园。",kw={"奥拉基尔","艾拉德林","洛苏娜","阿基尔神殿","塔拉尼斯·影歌","瓦拉纳尔","守护结界","风领主","泽风岛"},sec={{t="向Talaanis传达警讯",b="你告诉Talaanis阿基尔神殿上方发生的事，并转达Elaadrin离开泽风岛的计划。影歌大长老需要了解危险，以及你前往艾泽拉斯执行任务的目的；泽风岛的居民则在寻找拯救家园的方法。"},{t="所剩之事",b="Talaanis思索着这个消息。Lorthuna已经不在了，邪教失去了领袖。泽风岛尚未遭到入侵，不过奥拉基尔可能会在数年或数十年后将目光转向这座岛。恐惧与值得庆贺之事如今并存。"}},faq={{q="我该和谁交谈？",a="你在瓦拉纳尔与塔拉尼斯·影歌交谈。",al={"该和谁交谈","塔拉尼斯","该向谁报告"}},{q="我该告诉塔拉尼斯什么？",a="你告诉塔拉尼斯阿基尔神殿上方发生的事，以及艾拉德林离开泽风岛的计划。",al={"神殿发生了什么","该报告什么","阿基尔神殿的消息"}},{q="泽风岛的居民为什么害怕奥拉基尔？",a="隐藏泽风岛的守护结界已经失效，奥拉基尔可能会选择在居民身处他的领地时发动攻击。",al={"为何害怕奥拉基尔","风领主的威胁","奥拉基尔的威胁"}},{q="影歌大长老需要知道什么？",a="他需要了解危险，以及泽风岛的居民打算在前往艾泽拉斯执行任务时做什么。",al={"塔拉尼斯需要知道什么","大长老的消息","前往艾泽拉斯的意图"}}},fp="19,183,22.251.0,12.225.1,20.47.0,24.102.0,48.104.0,45.122.0"}
P.entries["quest:94373"] = {n="Call of Earth",s="大地的召唤是在安威玛尔由 Teo Hammerstorm 监督的一项神圣试炼，旨在考验入门者的耐心和石头的韧性。申请者必须面对南方的冰鬃巨魔，夺回他们的熊挂件，才能获得大地之油。",h="大地的召唤是在安威玛尔由 Teo Hammerstorm 监督的一项神圣试炼，旨在考验入门者的耐心和石头的韧性。申请者必须面对南方的冰鬃巨魔，夺回他们的熊挂件，才能获得大地之油。",kw={"安威玛尔","大地的召唤","寒脊山谷","大地图腾","冰鬃","冰鬃熊挂件","冰爪熊","油","萨满","提奥·锤风"},ang={["class:Shaman"]="大地的召唤标志着与石头和泥土之灵交流的早期入门阶段，最终会制成大地之油。",["faction:Alliance"]="这项仪式考验刚入门的保卫者，让他们对抗盘踞在安威玛尔南部洞穴中的冰鬃巨魔。",["race:Dwarf"]="这项试炼在安威玛尔附近的寒脊山谷提供，将矮人的坚毅和高山遗产与大地本身永恒的耐心联系在一起。"},sec={{t="石头的智慧",b="在寒脊山谷的安威玛尔，导师 Teo Hammerstorm 注视着准备踏上崎岖大地之路的入门者。Teo 将大地视为一种坚固且不可动摇的基础，引导年轻的流浪者聆听高山的智慧。他警告说，虽然石头是坚固的盾牌，但它的恩惠不会轻易给予，只有展现出真正的毅力和深深的敬意，才能分享大地的秘密。"},{t="大兽穴的试炼",b="为了证明自己已经准备就绪，入门者必须面对潜伏在南方洞穴里的冰鬃巨魔。这些巨魔用在该冰冻高地上游荡的凶猛冰爪熊的皮毛制作粗糙的挂件。从巨魔的大兽穴中收回两个这样的熊挂件，便是申请者拥有元素之灵所期望的坚定决心和勇气的有力证明。"},{t="大地之油",b="在将挂件交给 Teo Hammerstorm 后，这位长者会称赞入门者的耐心——这是大地最优秀的品质，它比崩塌的山峰和雕琢的河谷更为长久。为了认可这份已证明的敬意，Teo 开始准备大地之油，这是使入门者能够感知并走上元素真实之路的重要催化剂。"}},faq={{q="谁提供了大地的召唤这个任务？",a="特奥·锤风 是位于寒脊山谷安威玛尔的一位长者向导，他提供了这项试炼。他指导年轻的入门者学习石头的之道，并要求他们在元素之灵面前证明自己的决心。",al={"谁提供大地的召唤","大地的召唤任务发布者","泰奥·锤暴任务"}},{q="特奥·锤风 要求你做什么？",a="你必须冒险前往安威玛尔南部的洞穴，那里住着冰鬃巨魔，你需要回收两个冰鬃熊挂件，那是巨魔用冰爪熊制成的。将它们交给 特奥·锤风 即可完成试炼。",al={"大地的召唤目标","大地的召唤需要什么","冰鬃挂件任务"}},{q="在哪里可以找到冰鬃熊挂件？",a="这些挂件由生活在安威玛尔以南一个洞穴里的冰鬃巨魔携带。这些护身符是用当地的冰爪熊制成的，并由居住在大兽穴里的巨魔佩戴。",al={"哪里有冰鬃熊挂件","如何获得冰鬃熊挂件","安威玛尔冰鬃洞穴"}},{q="完成任务后，特奥·锤风 会准备什么奖励？",a="“油”是一种由精神导师准备的仪式性混合物或药剂，旨在使修行者与元素之灵相协调。完成这项试炼后，特奥 会制作大地之油，让你能够走上大地的真实之路。",al={"什么是油","矮人大地之油","特奥·锤风制作什么"}},{q="为什么入门者必须在这项试炼中面对冰鬃巨魔？",a="与冰鬃巨魔对峙体现了与大地交流所需的身体毅力和精神韧性。通过从敌对巨魔的洞穴中夺取熊挂件，入门者证明了自己配得上大山的永恒恩惠。",al={"为什么要杀冰鬃巨魔","为什么是冰鬃挂件"}},{q="特奥·锤风 教导了关于大地本质的什么道理？",a="特奥 教导说，耐心是大地最伟大的美德，并指出当高山崩塌、河流缓慢切割出河谷时，大地依然长存。他强调石头会保护那些尊重它的人，但警告说，即使是基岩如果受到轻视也会发生位移。",al={"特奥·锤风大地美德","高山的智慧"}}},fp="13,171,19.289.0,26.279.0,17.273.1,35.180.0,40.189.0,46.135.0,57.139.0,60.162.0,58.204.0"}
P.entries["quest:94374"] = {n="大地的召唤",s="“大地之呼”是一项神圣的萨满仪式，它将初学者的凡人之魂与世界不朽的根基相连。在僻静山中的灵石旁，通过饮下名为大地萨普塔的幻象药剂，寻求者能在冰雪与岩石间学会谦卑、耐心和对元素的感知。",h="“大地之呼”是一项神圣的萨满仪式，它将初学者的凡人之魂与世界不朽的根基相连。在僻静山中的灵石旁，通过饮下名为大地萨普塔的幻象药剂，寻求者能在冰雪与岩石间学会谦卑、耐心和对元素的感知。",kw={"大地的召唤","丹莫罗","大地萨普塔","元素仪式","秘道","萨普塔","萨满","灵石"},ang={["class:Shaman"]="这项仪式代表了萨满必不可少的沟通，通过萨普塔的仪式用酒，将灵魂与岩石结合，并赋予了超越凡人感知的视野。",["faction:Alliance"]="在积雪的山崖间出现元素仪式，显示出萨满传统正在联盟的土地上扎根。",["race:Dwarf"]="在冰封的山峰间，用矮人粗犷的语调诉说着这神圣的交流，将与大地的沟通与丹莫罗的雪山之巅直接联系了起来。"},sec={{t="幻象之酒",b="“大地之呼”是一项关于精神调和的神圣试炼，要求初学者在孤立的山间神龛饮用名为大地萨普塔的附魔药剂。萨普塔由古老的元素魔法锻造而成，它能将饮用者的灵魂与世界的基岩结合，赋予凡人之眼以罕见的力量，去洞察那些常人视力所无法触及的元素之灵与细微流向。由于其效力强劲，这种药剂必须在指定的圣地饮用，以确保灵魂与岩石间的联结能够安全建立。"},{t="雪中的灵石",b="在被积雪覆盖的高山上，沿着一条隐秘的秘道走到尽头，便伫立着灵石。初学者们踏上这段充满苦寒与冰雪的旅程，在古老的岩石前谦卑地伫立。他们怀着毫无骄矜之心，饮下萨普塔，便会发现即使是在最严酷的冬季峭壁上，大地依然以其生命力接纳了他们。山脉成为了不朽体魄的基石，而广袤沉稳的平原则教会了他们耐心这种静谧的力量。"},{t="力量与宁静",b="与岩石沟通是通往精神探索之路的基础仪式。与风、火或咆哮的水流那般躁动不安不同，大地教会人们的是不动如山的纪律与沉稳的韧性。为了通过这项仪式，寻求者必须汲取大地静谧的本质，为应对世界上那些更为狂暴的元素所带来的冲突与混沌二元性，磨砺自己的身心。"}},faq={{q="什么是大地萨普塔？",a="大地萨普塔是一种以魔法制作的强效神秘药剂，旨在将修行者的灵魂直接与元素相连。它并非为意志薄弱者所准备，因为饮用它会刺破凡人的视觉，揭示出常人无法感知的精神与元素真相。",al={"什么是萨普塔","大地萨普塔背景故事","萨普塔的作用"}},{q="在哪里饮用萨普塔？",a="这种药剂必须在特定的圣地饮用。在此仪式中，修行者需要向北沿着秘道登山，去寻找隐藏在峭壁之中的古老灵石。",al={"在哪里饮用萨普塔","灵石位置","灵石在哪里"}},{q="“大地之呼”仪式的目的是什么？",a="“大地之呼”是一项关于沟通与谦卑的基础试炼。通过在灵石旁饮下萨普塔，初学者学会了从山脉中汲取力量，从平原中学会耐心，并在面对更狂暴的元素之前，将自己的凡人之魂与充满生机的世界相调和。",al={"为什么要进行这个任务","大地之呼的含义","大地之呼背景故事"}},{q="谁懂得如何酿造大地萨普塔？",a="只有少数被选中的萨满祭司才拥有酿造萨普塔所需的知识与精神准备。它的配方受到严密保护并被尊崇备至，因为这种药剂将凡人的意识直接与原始力量连接在一起。",al={"谁知道萨普塔的配方","谁都能制作萨普塔吗"}},{q="大地元素与其他元素有何不同？",a="当其他元素力量在暴虐的不安中冲突、燃烧、咆哮时，大地元素代表的是坚定、静止、耐心和不可动摇的根基。初学者必须先在岩石面前学会谦卑，才能去面对其他元素那多变的双重本质。",al={"大地与其他元素的区别","大地与火、水、风的比较"}},{q="这项仪式是在什么环境中进行的？",a="这项任务发生在寒冷积雪的高山之巅，初学者沿着蜿蜒在冰雪与岩石间的秘道前行，不顾凛冽的寒霜，与大地的灵魂进行交流。",al={"大地之呼的场景设定","冰封之地的大地任务"}}},fp="13,213,21.300.0,28.300.0,22.330.0,20.259.0,33.174.0,46.264.0,34.232.0,61.242.0,39.178.0"}
P.entries["quest:94375"] = {n="大地的召唤",s="大地的召唤是丹莫罗冰雪覆盖的土地上，年轻萨满必须经历的元素试炼。通过与当地的大地之灵沟通，受试者将获得一块粗石英，并将其带到安威玛尔的特奥·锤风那里。这块普通的石头证明了他们的沟通成果，并作为他们大地图腾的核心。",h="大地的召唤是丹莫罗冰雪覆盖的土地上，年轻萨满必须经历的元素试炼。通过与当地的大地之灵沟通，受试者将获得一块粗石英，并将其带到安威玛尔的特奥·锤风那里。这块普通的石头证明了他们的沟通成果，并作为他们大地图腾的核心。",kw={"安威玛尔","大地的召唤","寒脊山谷","丹莫罗","大地图腾","粗石英","萨满","特奥·锤风","图腾"},ang={["class:Shaman"]="与大地之灵沟通并获得大地图腾，是每一位萨满学徒必经的基础试炼。",["faction:Alliance"]="在安威玛尔周围进行的萨满仪式，标志着元素灵媒在铁炉堡领地内的影响力和引导作用日益增强。",["race:Dwarf"]="矮人与石头和山脉的联系源远流长，在丹莫罗直接与大地之灵沟通，将他们祖传的石匠工艺与萨满之路桥接在了一起。"},sec={{t="低语之石",b="大地的召唤标志着受试者在丹莫罗迈出了通往萨满精神之路的第一步。在冰封的山峰深处，求道者必须寻找大地之灵并聆听它的教诲。这一试炼需要谦卑：大地之灵只会赠予一块粗石英，这块看似平凡的鹅卵石将成为大地图腾跳动的心脏。它提醒求道者，真正的持久并非取决于规模的大小，而是取决于耐心、力量和坚定的决心。"},{t="山的恩赐",b="回到安威玛尔并交出石头后，特奥·锤风会评估受试者的资格。作为一名工匠和向导，特奥需要确凿的证据来证明山灵已经认可了求道者。如果没有粗石英，受试者将无法通过试炼；若有此物，特奥便会将这块原石塑造成大地图腾，将年轻的萨满与大地根基永恒的力量结合在一起。"}},faq={{q="粗石英有什么用？",a="粗石英是由大地元素之灵赐予的，作为沟通的证明。虽然它看起来只是一块普通的鹅卵石，但却是制作大地图腾必不可少的核心。",al={"粗石英用途","什么是粗石英","为什么需要粗石英"}},{q="特奥·锤风是谁？",a="特奥·锤风是位于丹莫罗安威玛尔的一位导师。他负责考验萨满学徒，要求他们在制作神圣图腾前必须先证明自己与元素进行了沟通。",al={"谁是特奥·锤风","特奥·锤风位置","特奥在哪里"}},{q="什么是大地的召唤？",a="大地的召唤是年轻萨满为了寻求与大地之灵的沟通、展示耐心与力量并获得他们第一个大地图腾而进行的神圣试炼。",al={"大地的召唤任务线","什么是大地的召唤","大地图腾任务"}},{q="大地之灵向受试者提出了什么要求？",a="大地之灵要求受试者保持坚强、耐心和寻求智慧。它教导人们，即使是最微小的事物也能比其他事物存续更久，真正的力量源于与大地的相互尊重。",al={"大地之灵的教诲","大地之灵的要求","萨满大地哲学"}},{q="安威玛尔位于哪里？",a="安威玛尔是位于丹莫罗寒脊山谷中的矮人定居点。它是年轻矮人受试者进行训练并与周围山脉沟通的集结地。",al={"什么是安威玛尔","安威玛尔背景","大地的召唤发生地点"}},{q="为什么大地图腾很重要？",a="图腾是萨满与元素之灵之间的神圣媒介。大地图腾将持有者的意志与山脉稳固的力量和韧性连接在一起。",al={"图腾的重要性","萨满图腾背景","大地图腾的作用"}}},fp="13,190,20.342.0,20.329.0,29.111.0,23.159.0,26.107.0,47.186.0,26.129.0,33.140.0"}
P.entries["quest:944"] = {n="主宰之剑",s="这个任务派遣联盟冒险者穿过黑海岸向南，代表知识古树奥努去侦察阴森的主宰之剑。目标是调查邪恶的暮光之锤教派是否已经渗透进了那个陨落的上古恐怖存在的遗骸中。",h="这个任务派遣联盟冒险者穿过黑海岸向南，代表知识古树奥努去侦察阴森的主宰之剑。目标是调查邪恶的暮光之锤教派是否已经渗透进了那个陨落的上古恐怖存在的遗骸中。",kw={"黑海岸","主宰之剑","古老领主","奥努","占卜之水","占卜碗","暮光之锤"},ang={["class:Druid"]="德鲁伊们响应奥努的呼唤，旨在了解深埋于地底的古老休眠污秽是如何扰乱周边土地及其野生动物的。",["faction:Alliance"]="黑海岸的联盟部队必须阻止暮光之锤唤醒那些可能会淹没卡利姆多北部苦苦挣扎的定居点的远古恐怖。",["race:NightElf"]="对于暗夜精灵来说，主宰之剑是一个鲜明的提醒，警示着在他们文明出现之前的原始恐怖，看到疯狂的教徒侵犯黑海岸这片神圣的土地是不可容忍的亵渎。"},sec={{t="不安的征兆",b="在调查黑海岸沿岸残留的腐蚀和流离失所的野生动物时，知识古树奥努注意到了一些令人担忧的线索。沿岸的纳迦已经够让人困扰的了，但暮光之锤教派的出现则更为凶兆。这个狂热的教派崇拜的并非普通的黑暗力量，而是那些在远古时代被推翻的世界古老原始领主。"},{t="陨落的领主",b="向南是主宰之剑，这是一处阴森的挖掘点，中心是一头被巨大的石制武器钉住的庞然大物。奥努提供了一瓶占卜之水，并派遣侦察兵进入坑中确认教徒们是否聚集在那里。正如奥努所警告的那样，尽管这头被钉住的巨兽已经死了数个纪元，但它那古老而腐蚀的力量碎片仍然残留在它的骨骸中——这是暮光之锤无法抗拒的战利品。"}},faq={{q="是谁派遣我执行这个任务的？",a="该任务由奥努发布，他是一棵位于黑海岸南部古树之林附近路边的德高望重的知识古树。",al={"任务发布者","谁给予主宰之剑任务","起始非玩家角色"}},{q="什么是主宰之剑？",a="主宰之剑是位于黑海岸南部的一处古老遗迹，数个纪元前，一位恐怖的远古领主在此陨落，其头颅被一把巨大的石制战刃贯穿。它巨大的石化骨骸至今仍深埋在土地之中。",al={"什么是主宰之剑","主宰之剑的背景故事","黑海岸的巨大头骨"}},{q="为什么暮光之锤教派会对这个地点感兴趣？",a="暮光之锤崇拜古老艾泽拉斯的旧日黑暗力量。尽管被钉在战刃上的泰坦般生物早已死去，但它遗骸中仍残留着其原始力量的休眠痕迹与碎片，而这正是教徒们拼命想要掌控的东西。",al={"黑海岸的暮光教派","暮光教徒为什么在这里","暮光之锤与主宰之剑"}},{q="我该如何向奥努复命？",a="你不必亲自走回奥努所在的位置。一旦你探索了主宰之剑的挖掘坑，使用背包里的占卜之水在地上召唤一个占卜碗，这能让你通过魔法直接与奥努交谈。",al={"在哪里交任务","如何使用占卜之水","占卜碗"}},{q="这次侦察任务之后是什么？",a="在你使用占卜碗确认了教徒的行踪后，奥努会立即引导你前往他们的营地，并在任务“暮光营地”中进一步揭露他们的活动细节。",al={"下一个任务","主宰之剑的后续任务"}}},fp="19,162,21.256.0,15.334.0,29.119.0,28.172.0,57.180.0,28.187.0,32.147.0"}
P.entries["quest:94411"] = {n="Meddlesome Mages",s="Meddlesome Mages主要讲述了申达尔高地不断加剧的矛盾，高阶会的学徒们在神圣的巨石阵附近进行非法闯入。当地守护者必须将他们驱逐，以保护维系岛屿的脆弱神秘力量免受鲁莽的奥术干扰。",h="Meddlesome Mages主要讲述了申达尔高地不断加剧的矛盾，高阶会的学徒们在神圣的巨石阵附近进行非法闯入。当地守护者必须将他们驱逐，以保护维系岛屿的脆弱神秘力量免受鲁莽的奥术干扰。",kw={"奥术干预","高阶会","高阶会学徒","多管闲事的法师","申达尔高地","申多雷","巨石阵"},ang={["class:Mage"]="法师们会注意到对鲁莽施法的严厉批评；高阶会的学徒无视维系岛屿的微妙环境平衡，这表明了肆意操纵奥术的危害。"},sec={{t="巨石阵的入侵",b="申达尔高地村庄北部的局势日益紧张，高阶会的学徒们聚集在古老的巨石阵周围。尽管多次被警告不要干扰这些神圣的地方，法师们仍一意孤行地追求他们的奥术利益。当地领导层虽然不愿伤害同为shen'dorei的族人，但已请求外援驱散这些入侵的学徒，以免他们的干扰造成永久性的伤害。"},{t="脆弱的岛屿",b="驱逐高阶会的紧迫性源于维持岛屿的微妙平衡。维系这片土地的神秘力量非常脆弱，使得家园容易受到鲁莽咒语的破坏。对于巨石阵的保卫者来说，高阶会完全无视了他们干预所带来的危险，这意味着哪怕是一个粗心的咒语，也可能破坏岛屿的束缚，给所有居住在那里的人带来毁灭。"}},faq={{q="多管闲事的法师这个任务是关于什么的？",a="多管闲事的法师是一项要求冒险者对抗并驱散高阶会学徒的任务，这些学徒入侵了申达尔高地村庄北部的神圣巨石阵。",al={"什么是多管闲事的法师","多管闲事的法师任务","这个任务是什么"}},{q="高阶会学徒是谁？",a="高阶会是一个法师派系，被当地人称为申多雷兄弟姐妹，他们的学徒无视警告，闯入神圣的土地并进行魔法实验。",al={"高阶会学徒是谁","什么是高阶会","高阶会法师"}},{q="为什么要驱散高阶会学徒？",a="高阶会一再无视远离巨石阵的警告。他们鲁莽的魔法干预威胁到了维系岛屿的脆弱奥术力量，有可能给当地家园带来灾难性的破坏。",al={"为什么要驱散高阶会","为什么要对抗这些学徒","巨石阵的问题"}},{q="高阶会学徒聚集在哪里？",a="对峙发生在申达尔高地内当地村庄北部的巨石阵处。",al={"这个任务在哪里","申达尔高地的位置","村庄北部的巨石阵"}},{q="任务中提到的申多雷是谁？",a="申多雷是任务发布者族人的亲属。尽管内部冲突削弱了他们共同的社区，但当地领导人感到被迫对高阶会采取果断行动以避免灾难。",al={"谁是申多雷","申多雷兄弟姐妹","什么是申多雷"}},{q="法师们对岛屿构成了什么危险？",a="维系岛屿的力量既微妙又脆弱。奥术修行者未经检查的干预可能会破坏这些束缚，从而有可能彻底摧毁岛屿。",al={"有什么危险","岛屿的脆弱力量","岛屿可能会发生什么"}}},fp="16,168,26.347.0,18.259.0,41.133.0,35.191.0,49.195.0,47.100.0,46.196.0,44.133.0"}
P.entries["quest:94413"] = {n="A Magical Affront",s="“魔力之争”是发生在泽弗拉斯（Zephras）的一个任务，重点围绕近期涌现的能量流展开。当地的一个组织试图驾驭并研究这些暴露的奥术能量，而塑风者则认为这些缺口是大地上的创伤，必须予以治愈，这引发了西南森林中的直接冲突。",h="“魔力之争”是发生在泽弗拉斯（Zephras）的一个任务，重点围绕近期涌现的能量流展开。当地的一个组织试图驾驭并研究这些暴露的奥术能量，而塑风者则认为这些缺口是大地上的创伤，必须予以治愈，这引发了西南森林中的直接冲突。",kw={"魔法的冒犯","奥术","能量流","创伤","塑风者","泽弗拉斯"},ang={["class:Druid"]="德鲁伊可能会发现自己陷入了哲学上的矛盾，因为塑风者认为暴露的能量流是自然景观上需要急切治愈的创伤。",["class:Mage"]="对于奥术修行者来说，泽弗拉斯涌现的能量流提供了极其罕见的、直接接触原始神秘能量的机会，因此保护它们具有重要的学术和魔法价值。",["class:Shaman"]="塑风者致力于平息和治愈泽弗拉斯各处的扰动，这使得他们对自然环境的维护工作与驾驭原始魔法流的组织直接产生了冲突。"},sec={{t="现世洋流",b="在泽弗拉斯的地表上，古老的地下原始魔法通道近期冲破了地表。对于当地组织的学者和修行者来说，这种涌现是无价的馈赠。与能量流的直接、有形接触使他们能够前所未有地洞察渗透在该地区的奥术流动，极大地扩展了他们的魔法造诣。"},{t="创伤与纷争",b="并非所有人都将这些暴露的能量视为奇迹。塑风者认为这些缺口是撕裂泽弗拉斯地表的开放性伤口和破坏性的创伤。他们决心治愈受损的大地，因此聚集在破裂点，试图压制或修补暴露的能量流。对于依赖这些原始力量的组织来说，这种干涉构成了无法容忍的威胁，促使他们派遣冒险者前往西南部的森林，将塑风者驱逐出去。"}},faq={{q="塑风者是什么人？",a="塑风者是活跃在泽弗拉斯的一个组织，他们不认为涌现的能量流是原始能量的馈赠，而将其视为大地上不自然的创伤或疤痕，必须予以治愈。他们的行为使他们与试图研究和引导能量流的组织产生了直接对立。",al={"塑风者是谁","什么是塑风者","塑风者 泽弗拉斯"}},{q="为什么组织想要驱逐塑风者？",a="研究泽弗拉斯能量流的组织需要利用它们涌现出的力量来提升其神秘学理解。由于塑风者积极尝试“治愈”并关闭或修补这些能量流，该组织认为他们的行为是一种不可容忍的冒犯，并要求将其驱逐。",al={"为什么要杀塑风者","为什么要与塑风者战斗","塑风者冲突"}},{q="泽弗拉斯的能量流是什么？",a="能量流是贯穿世界的神秘能量通道。在泽弗拉斯，这些通道近期涌现到了地表，暴露出的直接魔法力量渗透在大地上，使奥术修行者获得了前所未有的研究机会。",al={"什么是泽弗拉斯能量流","泽弗拉斯能量流","地表能量流"}},{q="冲突中的能量流位于何处？",a="本任务中提到的冲突能量流位于泽弗拉斯的西南部森林中，塑风者已经聚集在那里，开始关闭或修补暴露的魔法涌流。",al={"能量流森林在哪里","能量流位置","西南部森林"}},{q="为什么塑风者认为能量流是创伤？",a="塑风者认为原始的地下能量突然破土而出，是在泽弗拉斯地表上留下的剧烈创伤。在他们看来，恢复自然平衡需要修补这些撕裂处，这与希望保持缺口开启的奥术施法者直接对立。",al={"为什么塑风者想要治愈能量流","能量流对泽弗拉斯有害吗","治愈创伤"}},{q="泽弗拉斯在这次冲突中有什么意义？",a="泽弗拉斯是这些暴露的能量流涌现的土地。原始魔法力量在其地表的突然出现，使其成为了试图掌握这些奥术能量的人与将其视为需要恢复的不自然缺口的人之间的爆发点。",al={"什么是泽弗拉斯","魔力之争发生在什么地方","泽弗拉斯传说"}}},fp="17,236,17.287.0,16.313.0,24.195.0,51.208.0,33.200.0,39.139.0,51.254.0,53.214.0"}
P.entries["quest:94414"] = {n="The Anchors of Zephras",s="“泽风之锚”是由泽风岛上的Halaan Hawk-Eye所提供的入门任务。Halaan邀请旅行者借用他那远眺的目光，去观察那些系留并守护着这座浮空岛的古老锚柱。尽管从远处看这些高耸的巨石似乎完好无损，但Halaan警告说，风之灵用来维持稳定的魔法已经开始动摇了。",h="“泽风之锚”是由泽风岛上的Halaan...",kw={"锚柱","泽风之锚","哈兰·鹰眼","地脉","天视","风之灵","泽风岛"},ang={["class:Mage"]="Halaan将他敏锐的视力与那些能够汲取泽风岛下方地脉之力的魔法区分开来。",["class:Shaman"]="锚柱直接依赖于风之灵的祝福，这使得它们魔法中的任何不稳定对于寻求维持平衡的萨满祭司而言，都是一个紧迫的元素问题。"},sec={{t="岛屿的系留",b="泽风岛的锚柱是由风之灵所赐予的古老而高耸的巨石。它们深植于岛屿的神秘基座之中，起到固定、稳定和支撑这片陆地悬浮于动荡天空之中的作用。注视着其中任何一座锚柱，便是见证泽风岛得以漂浮的脆弱平衡，而这一切持续依赖于风之灵的眷顾。"},{t="令人不安的变动",b="尽管锚柱在肉眼看来依然巍然屹立且未受损伤，但它们已经变得不再稳定。Halaan Hawk-Eye指出，维持它们运作的魔法和谐最近变得不稳定且前后不一。在没有明显的物理损伤迹象的情况下，这种微妙的衰退引起了守护林地之人的警觉，暗示着威胁岛屿的深层失衡正在发生。"},{t="Halaan的天赋",b="虽然缺乏能够洞察世界彼端的“天视”或引动泽风岛深层地脉的奥术能力，但Halaan拥有一种更单纯、更敏锐的天赋：在极远距离上拥有清晰明锐的视力。通过借出这种视角，他让其他人能够细致地观察远处的锚柱，鼓励新来者在对当下心存感激的同时，也要警惕家园命运的变迁。"}},faq={{q="泽风岛上的锚柱是什么？",a="锚柱是风之灵所赐予的古老神秘建筑。它们结合、锚定并以魔法支撑着泽风岛，使其在周围的世界之上保持稳定。",al={"什么是锚","泽风岛锚柱","什么是锚柱"}},{q="锚柱出了什么问题？",a="虽然锚柱没有显示出明显的物理损伤或外部衰退，但其维持稳定的魔法近期变得不稳定且前后不一，引发了人们对究竟是什么在悄然干扰它们运作的担忧。",al={"为什么锚失效了","锚柱问题","锚发生了什么"}},{q="哈兰·鹰眼是谁？",a="哈兰·鹰眼是一位居住在泽风岛林地中的守护者。他拥有敏锐且深远的天然视力，监视着这片土地的健康状况，并思考着岛屿的神秘福祉。",al={"哈兰的背景","谁是哈兰"}},{q="哈兰的天赋是什么？",a="哈兰的天赋是极其敏锐的长距离视力。与那些挥舞天视以洞察世界之间，或引导地脉能量的神秘主义者不同，哈兰的力量是自然且平凡的，这使他能够以纯净的清晰度感知遥远的地标。",al={"哈兰的天赋","哈兰如何远视"}},{q="什么是天视？",a="天视是泽风岛上某些修行者所拥有的神秘感知力，它使他们能够穿透面纱，直接洞察世界之间，这远超普通人的肉眼视觉。",al={"什么是天视","天视的含义"}},{q="驱动锚柱的魔法来自哪里？",a="锚柱是由风之灵赐予泽风岛的。哈兰说锚柱负责束缚和维持岛屿，但没有解释它们持续力量的来源。",al={"谁制造了锚柱","锚柱的起源"}}},fx={["61bc2f74"]={q="为什么 哈兰·鹰眼 想让你查看锚桩？",a="哈兰·鹰眼 守望着林地，十分关心 泽风岛 的安危。古老的锚桩是风之精灵的馈赠，能束缚并维系这座岛屿，但它们的魔法最近变得不稳定、不规律。尽管锚桩看起来没有受到物理损坏，哈兰 仍愿意与你分享他那远及千里的视野，让你亲眼看看锚桩，了解故土的微妙处境。",al={"哈兰 的动机","为什么要查看锚桩","哈兰 为什么想要这样做"}}},fp="22,192,19.274.0,18.282.0,13.287.0,38.155.0,37.135.0,23.142.0,22.148.0,17.114.0,51.159.0"}
P.entries["quest:94427"] = {n="A Lesson in Divinity",s="你的教团派你前往幽暗城贸易区寻找 Tanis Alderwood。帮助对方，正是通过善行彰显恩典的机会。",h="你的教团派你前往幽暗城贸易区寻找 Tanis Alderwood。帮助对方，正是通过善行彰显恩典的机会。",kw={"神性之道","神性","恩典","乞讨","塔尼斯·桤木","贸易区","幽暗城"},ang={["class:Priest"]="作为一名牧师，你的教团将神性诠释为为善而行善，并说悲剧可能威胁到你生前所坚守的恩典。"},sec={{t="恩典的召唤",b="你的教团教导说，神性意味着为善而行善，而非追求成神。教团说，悲剧让你来到了这里，并让你去幽暗城贸易区寻找 Tanis Alderwood。Tanis 需要帮助，或许能从你的恩典中受益。"},{t="Tanis 的恳求",b="你走近 Tanis 时，对方担心你会伤害他们。Tanis 说自己与你或你的教团无冤无仇，恳求你不要打扰他们。"}},faq={{q="塔尼斯·桤木 是谁？",a="塔尼斯·桤木 是幽暗城贸易区一位需要帮助的人。",al={"塔尼斯","塔尼斯 是谁","贸易区的人"}},{q="我为何被派去找 塔尼斯？",a="你的教团说，塔尼斯 或许能从你的恩典中受益。",al={"为何找 塔尼斯","帮助 塔尼斯","这意味着什么"}},{q="神性对我的教团意味着什么？",a="这意味着为善而行善，而非追求成神。",al={"神性的含义","为善而行善","什么是神性"}},{q="我在哪里能找到 塔尼斯·桤木？",a="塔尼斯·桤木 在幽暗城贸易区。",al={"塔尼斯 的位置","塔尼斯 在哪里","贸易区"}}},fp="20,127,16.244.0,14.156.1,23.66.0,23.60.0,36.88.0,33.60.0"}
P.entries["quest:94434"] = {n="A Lesson in Divinity",s="Tanis Alderwood在幽暗城向你索要新布料。他的妻子正逐渐散架，他希望用绷带把她包起来，撑到药剂师有空为止。",h="Tanis Alderwood在幽暗城向你索要新布料。他的妻子正逐渐散架，他希望用绷带把她包起来，撑到药剂师有空为止。",kw={"神性之课","药剂师","乞丐","黑暗女王","亚麻布","塔尼斯·桤木","幽暗城","妻子"},sec={{t="乞丐的请求",b="Tanis说，药剂师们正忙于黑暗女王的事务。他请你带些亚麻布来，好在等待救助时把妻子包起来。眼下要紧的是她的状况。"}},faq={{q="谁在寻求帮助？",a="塔尼斯·奥德伍德是幽暗城的一名乞丐，他请求你帮助他的妻子。",al={"塔尼斯是谁","塔尼斯·桤木","乞丐"}},{q="塔尼斯的妻子怎么了？",a="塔尼斯说，她真的快散架了，需要用绷带包起来，才能维持住。",al={"妻子散架","他的妻子出了什么事","塔尼斯的妻子"}},{q="药剂师为什么帮不了忙？",a="塔尼斯说，药剂师们正忙于黑暗女王的事务。",al={"药剂师很忙","为什么没有药剂师","黑暗女王的事务"}},{q="塔尼斯需要什么？",a="塔尼斯请你带些新布料给他，好在等待药剂师救助时把妻子包起来。",al={"他需要什么布料","给塔尼斯的亚麻布","帮助乞丐"}}},fp="20,140,15.175.0,23.70.0,31.84.0,32.71.0,21.97.0"}
P.entries["quest:94435"] = {n="A Lesson in Divinity",s="Tanis Alderwood感谢你帮助了他，并称你为朋友。Danitha Morr认为，这个小小的善举能加强被遗忘者与圣光的联系。",h="Tanis Alderwood感谢你帮助了他，并称你为朋友。Danitha Morr认为，这个小小的善举能加强被遗忘者与圣光的联系。",kw={"神性的一课","danitha morr","黑暗女王","被遗忘者","圣光","不信任","象征","tanis alderwood"},ang={["faction:Alliance"]="作为一名联盟旅人，你听Danitha讲述被遗忘者为帮助族人重新兴盛而付出的努力。",["race:Undead"]="作为被遗忘者，你听Danitha号召大家以勇气和正义帮助族人重新兴盛。"},sec={{t="小小的善举",b="Danitha Morr说，你的帮助或许能加强被遗忘者与圣光的联系。她谈到黑暗女王的追随者之间的不信任与阴谋，以及要以勇气和正义面对这种恐惧。她交给你一个象征，指引接下来的路。"}},faq={{q="谁在感谢我？",a="Tanis Alderwood感谢你帮助了他，并说他会永远是你的朋友。",al={"tanis alderwood","tanis是谁","tanis感谢"}},{q="Danitha说我的帮助意味着什么？",a="Danitha说，即使是小小的善举，也能加强被遗忘者与圣光的联系。",al={"为何帮助danitha","小小善举的意义","与圣光的联系"}},{q="Danitha为什么提到不信任？",a="Danitha说，黑暗女王和她麾下的一些人不信任他们，有些人甚至在暗中谋害他们。",al={"被遗忘者不信任","黑暗女王的恐惧","他们为何遭人猜忌"}},{q="Danitha给了我什么？",a="Danitha交给你一个象征，指引接下来的路。",al={"什么象征","danitha的物品","指引未来的象征"}}},fp="20,167,15.256.0,19.89.0,36.95.0,34.107.0,26.47.0"}
P.entries["quest:94436"] = {n="A Lesson in Divinity",s="Danitha Morr请你用生命符记展示牧师的本领。班达里安堡的Deathguard Billmuth前来寻求帮助，想救助一位朋友。",h="Danitha Morr请你用生命符记展示牧师的本领。班达里安堡的Deathguard Billmuth前来寻求帮助，想救助一位朋友。",kw={"神性之课","班达里安堡","达妮莎·莫尔","亡灵卫兵比尔穆斯","被遗忘者","圣光","牧师","生命符记"},ang={["class:Priest"]="身为牧师，Danitha请你用生命符记展示引导圣光的能力。"},sec={{t="求助",b="Billmuth说，牧师们拒绝了他，而他的朋友可能再也找不到其他人帮忙。他并不情愿向你开口，但他需要为被遗忘者寻求援助。生命符记旨在帮助你展示引导圣光的能力，不过拿着它可能会让你感到不适。即使对被遗忘者而言，它的力量也是盟友与指引；他们的诞生与一种与圣光相对的力量息息相关。"}},faq={{q="谁在寻求帮助？",a="班达里安堡的亡灵卫兵比尔穆斯前来为一位朋友寻求帮助。",al={"帮助比尔穆斯","谁需要帮助"}},{q="比尔穆斯为什么要找牧师？",a="比尔穆斯说，牧师们拒绝了他，而你可能是他朋友唯一的希望。",al={"为什么找牧师","牧师拒绝了他"}},{q="生命符记是什么？",a="这是达妮萨·莫尔交给你的一件圣光护符，用来展示你引导圣光的能力。",al={"生命符记","圣光护符"}},{q="为什么拿着生命符记可能会感到疼痛？",a="达妮萨提醒你，这件护符可能会让人感到不适，因为圣光与创造被遗忘者的力量相对。",al={"符记疼痛","圣光伤人"}},{q="亡灵卫兵 比尔穆斯在哪里？",a="亡灵卫兵 比尔穆斯在班达里安堡的楼下。",al={"比尔穆斯位置","班达里安堡"}}},fp="20,173,14.380.0,23.73.0,31.83.0,27.116.0,44.121.0,37.52.0"}
P.entries["quest:94438"] = {n="A Lesson in Divinity",s="Danitha Morr请你前往毒蛛峡谷寻找死亡卫士Falgan。他和一名同伴发现了血色十字军准备袭击布瑞尔的命令，随后两人失散。",h="Danitha Morr请你前往毒蛛峡谷寻找死亡卫士Falgan。他和一名同伴发现了血色十字军准备袭击布瑞尔的命令，随后两人失散。",kw={"神性启蒙","比尔穆斯","布瑞尔","达妮莎·莫尔","死亡卫士法尔甘","血色十字军","生命符记","毒蛛峡谷"},sec={{t="Falgan的归来",b="Falgan奉命与Billmuth一同前往毒蛛峡谷侦察血色十字军的动向。他说，他们发现血色十字军正计划发动某种袭击，并问你是否愿意继续帮助被遗忘者。"}},faq={{q="是谁要我去寻找法尔甘？",a="达妮萨·莫尔请你寻找死亡卫士法尔甘，并在力所能及的范围内帮助他。",al={"谁派我去","达妮莎·莫尔","任务给予者"}},{q="法尔甘在哪里？",a="法尔甘在毒蛛峡谷。",al={"法尔甘的位置","法尔甘在哪里","寻找死亡卫士"}},{q="法尔甘遭遇了什么？",a="一阵声响惊动了血色十字军，暴露了法尔甘和他的同伴。法尔甘留下断后，他的同伴独自回到了布瑞尔。",al={"法尔甘失踪","发生了什么","救回法尔甘"}},{q="法尔甘和比尔穆斯发现了什么？",a="他们发现血色十字军正计划发动某种袭击。",al={"血色十字军的命令","他们发现了什么","袭击计划"}},{q="生命符记有什么用？",a="生命符记可以让死亡卫士法尔甘起死回生。",al={"复活法尔甘","生命符记","如何救回法尔甘"}},{q="法尔甘回来后提出了什么请求？",a="法尔甘问你是否愿意继续帮助被遗忘者。",al={"帮助被遗忘者","接下来做什么","法尔甘的请求"}}},fp="20,163,15.200.0,32.72.0,16.27.0,24.124.0,38.79.0,31.67.0,37.82.0"}
P.entries["quest:94440"] = {n="A Lesson in Divinity",s="亡灵卫兵 Billmuth 请你从毒蛛峡谷夺回血色十字军的进攻计划。这些计划或许能帮助亡灵卫兵为即将到来的袭击做好准备。",h="亡灵卫兵 Billmuth 请你从毒蛛峡谷夺回血色十字军的进攻计划。这些计划或许能帮助亡灵卫兵为即将到来的袭击做好准备。",kw={"神性的教诲","进攻计划","班达里安堡","亡灵卫兵 比尔穆斯","被遗忘者","血色十字军","毒蛛峡谷"},sec={{t="堡垒的命令",b="血色十字军士兵把部署命令放在挎包里，而亡灵卫兵预料到敌人将要来袭。亡灵卫兵请你把计划副本带回班达里安堡，交给亡灵卫兵 Billmuth，好让他们做好设伏准备。"},{t="救下一位朋友",b="Billmuth 感谢你救了他的朋友，并说他会把计划交给指挥官。他还说，你的所作所为让他看出你彻头彻尾是被遗忘者，尽管他的同僚中有人对你所属的职业心存猜疑。"}},faq={{q="比尔穆斯 需要什么？",a="亡灵卫兵 比尔穆斯 请你从毒蛛峡谷夺回血色十字军的进攻计划。",al={"比尔穆斯 想要什么","比尔穆斯 的计划","给 比尔穆斯 的计划"}},{q="进攻计划在哪里？",a="毒蛛峡谷的血色十字军士兵带着进攻计划。",al={"计划在哪里","血色计划位置","寻找进攻计划"}},{q="亡灵卫兵为什么要这些计划？",a="亡灵卫兵预料到敌人将要来袭，想用这些计划做好设伏准备。",al={"为什么要拿计划","计划有什么用","亡灵卫兵设伏"}},{q="计划应该交给谁？",a="把计划交给班达里安堡的亡灵卫兵 比尔穆斯。",al={"计划交给谁","把计划交还给","比尔穆斯 在哪里"}}},fp="20,172,19.209.0,14.221.1,24.94.0,27.62.0,39.81.0,29.57.0"}
P.entries["quest:94441"] = {n="A Lesson in Divinity",s="一位被遗忘者同伴请你向班达里安堡的 Danitha Morr 转达谢意，感谢那里的圣骑士所提供的帮助。你的付出赢得了亡灵卫兵的感激，也为你带来一份救赎的恩赐。",h="一位被遗忘者同伴请你向班达里安堡的 Danitha Morr 转达谢意，感谢那里的圣骑士所提供的帮助。你的付出赢得了亡灵卫兵的感激，也为你带来一份救赎的恩赐。",kw={"神性启蒙","班达里安堡","达妮莎·莫尔","亡灵卫队","被遗忘者","光明","救赎","生命符记"},sec={{t="堡中的谢意",b="一位被遗忘者同伴请你将他们的谢意转达给班达里安堡的 Danitha Morr。亡灵卫兵的其他成员也会听说你和其他圣骑士所提供的帮助。他们很自豪能与你同为被遗忘者，也相信黑暗女王会守护你。"},{t="光明的恩赐",b="Danitha 说，生命符记可以由一位准备好接受圣光至高恩赐之一的圣骑士使用。她赐予你救赎的恩典，让你能够复活倒下的同伴。你的付出对被遗忘者和班达里安堡的圣骑士都意义重大，亡灵卫兵希望这样的善举能赢得其他被遗忘者的心。"}},faq={{q="我该向谁致谢？",a="有人请你向班达里安堡的 达妮萨·莫尔 致谢，感谢那里的圣骑士所提供的帮助。",al={"达妮莎 是谁","向 达妮莎 致谢","达妮莎·莫尔"}},{q="谁会听说这项服务？",a="亡灵卫兵的其他成员也会听说班达里安堡的圣骑士所提供的帮助。",al={"亡灵卫队的谢意","谁会听说","堡中的服务"}},{q="生命符记有什么用？",a="生命符记是为准备好接受圣光至高恩赐之一的圣骑士准备的。",al={"生命符记","有什么用","有什么作用"}},{q="亡灵卫队为何为我感到骄傲？",a="他们很自豪能与你同为被遗忘者，也重视你与班达里安堡的圣骑士一同做出的贡献。",al={"被遗忘者的骄傲","为何骄傲","亡灵卫队的骄傲"}}},fp="20,178,18.262.0,15.335.1,15.82.0,32.82.0,32.101.0,34.129.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="火焰的召唤是一项萨满祭司的任务，指引学徒们进入丹莫罗高地危险而混乱的火焰领域。在掌握了大地之道的耐心教诲后，修行者会被指引去寻找Bruegs Kindleborn，以测试他们是否准备好接受火焰灵契。",h="火焰的召唤是一项萨满祭司的任务，指引学徒们进入丹莫罗高地危险而混乱的火焰领域。在掌握了大地之道的耐心教诲后，修行者会被指引去寻找Bruegs Kindleborn，以测试他们是否准备好接受火焰灵契。",kw={"布鲁格斯·燃生","火焰的召唤","丹莫罗","大地灵契","火焰图腾","火焰灵契","萨满祭司","南门哨岗"},ang={["class:Shaman"]="这项任务标志着萨满祭司的一次关键精神试炼，是从岩石的忍耐向火焰狂暴、毁灭性力量的过渡。",["faction:Alliance"]="随着试炼在丹莫罗的山脉中展开，联盟的萨满祭司们听从长者的指引，唤醒与火元素的沟通。",["race:Dwarf"]="这项仪式在丹莫罗南门哨岗上方的崇山中进行，测试矮人是否拥有能够抑制火焰燃烧渴望的纪律。"},sec={{t="燃烧试炼",b="在通过大地元素证明了自己的耐心与稳重后，萨满祭司会被指引去面对一种更不稳定的力量：火元素之灵。与稳固而坚毅的岩石不同，火焰带来的召唤充满了混乱、毁灭与狂暴的能量。长者会派遣学徒穿越丹莫罗覆盖着积雪的山峰，在尝试驾驭这股狂野的热量之前去寻求指引。"},{t="山巅隐士",b="在南门哨岗上方的崇山峻岭中，导师Bruegs Kindleborn在一处隐蔽的洞穴中守护着。当携带长者推荐信的学徒抵达时，Bruegs会为他们准备火焰灵契。但他发出了严厉的警告：燃烧与吞噬的渴望极易被唤醒，但想要掌控火焰，就必须准确地知道何时该克制。"}},faq={{q="布鲁格斯·金德尔伯恩是谁？",a="布鲁格斯·金德尔伯恩是一位居住在丹莫罗南门哨岗上方高处山洞里的导师。他会评估由长者派来的萨满祭司，以确定他们是否具备接受火焰灵契所需的成熟度与纪律。",al={"布鲁格斯·燃生是谁","布鲁格斯·燃生背景故事","布鲁格斯在哪里"}},{q="什么是火焰灵契？",a="灵契是一种元素药剂或制剂，允许萨满祭司与该元素的灵魂进行沟通。火焰灵契赋予了与火焰及其原始力量沟通的能力，这需要精神上的专注以及此前在大地之道上的基础。",al={"什么是火焰灵契","火焰灵契","灵契的含义"}},{q="布鲁格斯·金德尔伯恩在哪里？",a="布鲁格斯·金德尔伯恩位于丹莫罗东部遥远的雪山之中，藏身于俯瞰南门哨岗的一处洞穴里。",al={"哪里可以找到布鲁格斯·燃生","南门哨岗洞穴","火焰的召唤在哪里交任务"}},{q="火焰的召唤的目的是什么？",a="火焰的召唤是萨满祭司的成人礼，针对的是那些已经展现出耐心并掌握了大地之道的萨满。它召唤他们去面对毁灭的混乱力量，并在布鲁格斯·金德尔伯恩的注视下进行考验。",al={"什么是火焰的召唤","丹莫罗火焰图腾任务"}},{q="为什么萨满祭司必须在学习火焰之前先学习岩石的教诲？",a="大地代表着坚定的耐心、稳定与控制。如果没有岩石所教授的基础，萨满祭司就有可能被火焰那不稳定的渴望与毁灭性的激情所淹没。",al={"为什么要先学岩石","记住岩石教给你的知识"}},{q="在进行火焰的召唤之前需要什么先决条件？",a="该任务建立在之前的试炼之上，学徒在那些试炼中展现了耐心并将自己扎根于大地。只有当学生的纪律得到充分证明时，长者才会将他们送到布鲁格斯·金德尔伯恩那里。",al={"火焰的召唤先决条件","耐心任务关联"}}},fp="12,175,17.311.0,24.321.0,25.214.0,26.225.0,35.122.0,40.155.0,57.173.0,68.186.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="火焰的召唤是一项神圣的试炼，旨在考验入门者是否有能力驾驭元素之火。祈求者必须手持眠炎火炬，沿着洛克莫丹一条隐蔽的山路前行，在眠炎圣殿寻找Braldir Ashmantle。",h="火焰的召唤是一项神圣的试炼，旨在考验入门者是否有能力驾驭元素之火。祈求者必须手持眠炎火炬，沿着洛克莫丹一条隐蔽的山路前行，在眠炎圣殿寻找Braldir Ashmantle。",kw={"布拉尔迪尔·灰烬斗篷","火焰的召唤","火焰图腾","洛克莫丹","萨满","眠炎圣殿","眠炎火炬","国王谷"},ang={["class:Shaman"]="这项试炼考验着萨满祭司学徒与火焰元素之灵沟通的决心，要求他们将神圣的火炬带到洛克莫丹的一座与世隔绝的山峰上。",["faction:Alliance"]="虽然联盟领地上的普通游客眼中只有荒凉的山石，但圣殿的守护者守卫着不为凡人所知的古老元素秘密。",["race:Dwarf"]="任务对话反映了矮人的语言，并指引入门者越过国王谷，进入卡兹莫丹崎岖的峭壁中。"},sec={{t="国王谷之外的道路",b="获得火焰图腾不仅仅需要强大的体魄。入门者必须携带未点燃的眠炎火炬，攀登至洛克莫丹高耸的峭壁之上。穿过国王谷的石刻，那条艰险的攀登之路通向一座与世隔绝的山峰，那里的元素之力远高于凡人行走的道路。"},{t="眠炎圣殿",b="在风吹过的山峰之巅矗立着Braldir Ashmantle，他是守护眠炎圣殿的守卫。毫无准备的流浪者和寻宝者爬上高处，只会发现寂静与裸露的岩石。对于携带神圣火炬的真正入门者，Braldir会揭示圣殿火盆中沉睡的深层元素力量，等待着被重新点燃。"}},faq={{q="什么是火焰的召唤任务？",a="火焰的召唤是入门者为了获得火焰图腾而必须经历的成人礼。任务指引祈求者进入洛克莫丹的峭壁，向圣山之巅的布拉尔迪尔·灰衣献上眠炎火炬。",al={"火焰的召唤是什么","萨满火焰任务洛克莫丹","火焰图腾任务"}},{q="布拉尔迪尔·灰衣是谁？",a="布拉尔迪尔·灰衣是驻守在洛克莫丹高处峭壁中眠炎圣殿的守护者。他会拒见普通的游客和寻宝者，只欢迎那些携带眠炎火炬的人。",al={"布拉尔迪尔·灰幔是谁","洛克莫丹圣殿守护者"}},{q="眠炎圣殿在哪里？",a="眠炎圣殿坐落在洛克莫丹高耸的峭壁之中，沿着国王谷之外的一条秘道即可到达。",al={"眠炎圣殿在哪里","眠炎位置"}},{q="眠炎火炬的作用是什么？",a="眠炎火炬是入门者携带的仪式信物，用来证明他们沟通元素之火的真诚意图和准备工作。布拉尔迪尔·灰衣要求在接见前先看到火炬。",al={"什么是眠炎火炬","眠炎火炬用途"}},{q="为什么祈求者必须前往洛克莫丹？",a="安置眠炎圣殿的神圣元素之巅俯瞰着国王谷之外的洛克莫丹，这里因远离普通游客而备受青睐。",al={"为什么要去洛克莫丹","为什么火焰圣殿在洛克莫丹"}},{q="如何通过这项试炼获得火焰图腾？",a="在找到布拉尔迪尔·灰衣并用火炬证明意图后，入门者必须在圣殿的火盆中引燃火焰，带着燃烧的火炬返回，从而正式获得火焰图腾。",al={"找到布拉尔迪尔后会发生什么","如何获得火焰图腾"}}},fp="12,157,35.270.0,31.328.0,31.202.0,25.204.0,49.124.0,54.195.0,45.165.0,48.166.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="火焰的召唤是洛克莫丹的一项元素试炼，初学者在这里准备与永恒之火进行沟通，并获得他们的火焰图腾。在Braldir Ashmantle的引导下，候选人必须从当地的狗头人和穴居人那里收集元素试剂，以酿造一种具有约束力的火焰灵契。这次旅程教导人们，火焰不仅是毁灭的工具，更是锻造的源泉和生命的呼吸本身。",h="火焰的召唤是洛克莫丹的一项元素试炼，初学者在这里准备与永恒之火进行沟通，并获得他们的火焰图腾。在Braldir...",kw={"布拉尔迪尔·灰烬斗篷","火焰的召唤","永恒之火","火焰灵契","火焰焦油","火焰图腾","洛克莫丹","石窟预言者","隧道鼠地卜师"},ang={["class:Shaman"]="与火焰沟通需要通过专门的灵契建立元素纽带，从而通向与永恒之火的沟通并获得火焰图腾。",["faction:Alliance"]="这项试炼设定在矮人领地洛克莫丹，将萨满仪式牢牢扎根于联盟土地上，以对抗当地穴居人和狗头人的威胁。",["race:Dwarf"]="Braldir Ashmantle以一种朴实的、矮人的元素火焰视角在洛克莫丹指导初学者，将其视为锻造和创造的呼吸，而非单纯的破坏。"},sec={{t="火焰之路",b="在洛克莫丹崎岖的峭壁中，一位名叫Braldir Ashmantle的元素导师监督着那些寻求火焰力量的初学者的道路。与火灵沟通绝非简单的召唤；凡人的灵魂必须首先通过一种被称为火焰灵契的神圣药剂，与燃烧的元素相调和。没有这种准备，永恒之火的热量只会将人吞噬，而不会带来启迪。Braldir要求请求者从山谷的敌对居民那里收集两种与火焰紧密相连的关键试剂，以证明他们的决心。"},{t="大地与火花的试剂",b="制作火焰灵契需要富含元素共鸣的物质。在北方，隧道鼠地卜师在他们错综复杂的巢穴中采集粘稠的火焰焦油，为他们的地下魔法提供燃料。在南方，被称为石窟预言者的穴居人神秘主义者带着装满原始元素护身符的试剂袋穿过崎岖的丘陵。夺取这些物品需要与洛克莫丹最根深蒂固的两种害虫进行斗争，强行获取将初学者的灵魂与火焰绑定所需的材料。"},{t="智慧的磨砺",b="在收到试剂后，Braldir Ashmantle提供了用耐心来调节原始破坏力的智慧。对于这位经验丰富的导师来说，火焰不仅仅是愤怒和灰烬，它代表着生命、锻造工艺以及创造的呼吸本身。对元素真正的掌握在于平衡：正如阴影赋予光意义一样，火焰阻止石头仅仅成为冰冷的记忆。掌握火焰需要知道何时去融合，而不是仅仅去燃烧。"}},faq={{q="火焰的召唤的目的是什么？",a="火焰的召唤是渴望与永恒之火沟通的萨满祭司候选人的通过仪式。为了与火灵沟通并获得火焰图腾，必须首先准备一份火焰灵契，将他们凡人的灵魂与该元素绑定。",al={"什么是火焰的召唤","这是一个什么任务","火焰的召唤的目的"}},{q="布拉尔迪尔·灰衣是谁？",a="布拉尔迪尔·灰衣是一位居住在洛克莫丹的元素向导。他指导初学者掌握火焰的平衡，并在收集到适当的元素试剂后准备必要的火焰灵契。",al={"谁给予火焰的召唤","布拉尔迪尔·灰幔是谁","布拉尔迪尔·灰幔的位置"}},{q="什么是火焰灵契？",a="火焰灵契是一种由火焰相关试剂制成的元素药剂或制剂。饮用或使用它会使萨满的灵魂与火焰元素位面相协调并绑定，从而实现与永恒之火的视觉沟通。",al={"什么是火焰灵契","火焰灵契有什么作用","为什么要用火焰灵契"}},{q="在哪里可以找到火焰焦油？",a="火焰焦油由居住在洛克莫丹北部狗头人洞穴中的隧道鼠地卜师携带。地卜师们利用这些焦油进行原始的火焰工艺。",al={"在哪里获得火焰焦油","火焰焦油位置","狗头人洞穴的火焰焦油"}},{q="在哪里可以找到石窟试剂袋？",a="试剂袋必须从潜伏在洛克莫丹南部丘陵的石窟预言者身上夺取。这些穴居人神秘主义者使用这些袋子来盛放与元素魔法相关的试剂。",al={"在哪里获得试剂袋","石窟预言者的试剂袋","石窟试剂袋位置"}},{q="布拉尔迪尔·灰衣如何看待火焰元素？",a="布拉尔迪尔并没有将火焰视为盲目的破坏，而是教导说火焰是锻造、生命和创造的呼吸。它与其他力量保持平衡，通过调和冰冷的石头，赋予存在以温暖和意义。",al={"布拉尔迪尔对火焰的看法","洛克莫丹火焰的意义","矮人的火焰哲学"}}},fp="12,263,21.387.0,31.422.0,23.387.0,36.157.0,25.144.0,21.164.0,28.119.0,47.147.0,52.193.0"}
P.entries["quest:94467"] = {n="火焰的召唤",s="火焰的召唤是一项元素试炼，初学者需要饮下调制好的火焰灵契，以感知并面对一个次级火焰显化。通过制服这个灵魂并将余烬置于神圣火盆中，祈求者便能赢得火焰的眷顾。",h="火焰的召唤是一项元素试炼，初学者需要饮下调制好的火焰灵契，以感知并面对一个次级火焰显化。通过制服这个灵魂并将余烬置于神圣火盆中，祈求者便能赢得火焰的眷顾。",kw={"火盆","火焰的召唤","火焰灵契","余烬","次级火焰显化","萨满试炼","永恒火焰神龛"},ang={["class:Shaman"]="这是一项萨满与火焰沟通的基础试炼，需要使用神圣的灵契来感知并对抗火焰之灵。"},sec={{t="火焰仪式",b="火焰的召唤是一项考验精神与勇气的传统试炼。在元素知识的指引下，初学者会获得一种调制好的火焰灵契，用以唤醒对不可见世界的感知。在神龛饮下药水并向山顶攀登时，凡人双眼与原始力量之间的界限会变得模糊，显露出一个等待挑战的沉睡火焰显化。"},{t="面对显化",b="与次级火焰显化的对抗是对决断力和耐力的考验。这个元素灵魂不会主动攻击，但一旦受到挑战，其强度会随着时间的推移而不断攀升。将其击败后会掉落余烬，必须将其带到永恒火焰神龛顶部的火盆中，点燃火炬以确保获得该灵魂持久的眷顾。"}},faq={{q="什么是火焰的召唤？",a="火焰的召唤是一项神圣的成人礼，初学者饮下特制的火焰灵契来感知火焰之灵，在战斗中与它对抗，并将它的余烬献给火盆，从而赢得火焰的眷顾。",al={"什么是火焰的召唤","火焰的召唤任务","火焰图腾试炼"}},{q="火焰灵契的用途是什么？",a="火焰灵契是一种调制好的药水，能够开启初学者的灵视，让他们看到在山顶等待他们的隐形元素之灵。",al={"火焰灵契用途","为什么要喝灵契","灵契有什么用"}},{q="试炼中会出现什么灵魂？",a="这项试炼要求初学者在山顶对抗一个次级火焰显化，它会一直等待直到受到攻击才加入战斗。",al={"我要和什么灵魂战斗","火焰的召唤怪物","火焰显化"}},{q="为什么必须尽快击败火焰之灵？",a="战斗持续的时间越长，元素之灵就会变得越凶猛、越炽热，因此迅速、果断地出击对于在火焰变得势不可挡之前将其制服至关重要。",al={"为什么要快速击杀","火焰的召唤战斗","火焰之灵计时"}},{q="余烬如何处理？",a="在击败次级火焰显化后，将其余烬带到永恒火焰神龛顶部的火盆中，点燃仪式火炬。",al={"余烬交到哪里","火焰的召唤火盆","永恒火焰神龛火盆"}},{q="赢得火焰的眷顾意味着什么？",a="完成仪式并点燃火炬，将赢得火元素直接的眷顾与沟通，与火焰建立起至关重要的联系。",al={"奖励是什么","仪式有什么奖励","火焰眷顾"}}},fp="12,165,17.289.0,24.311.0,25.159.0,38.135.0,37.96.0,45.150.0,37.157.0,40.124.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="火焰的召唤是一项神圣的试炼，学徒需要从俯瞰洛克莫丹的制高点取得恒焰火炬，并将其带到丹莫罗。将火焰带回导师 Bruegs Kindleborn 的身边，既证明了旅行者对元素的掌握，也能赢得属于他们的火焰图腾。",h="火焰的召唤是一项神圣的试炼，学徒需要从俯瞰洛克莫丹的制高点取得恒焰火炬，并将其带到丹莫罗。将火焰带回导师 Bruegs Kindleborn 的身边，既证明了旅行者对元素的掌握，也能赢得属于他们的火焰图腾。",kw={"布鲁格斯·燃生","火焰的召唤","丹莫罗","火焰图腾","烈焰之子","洛克莫丹","萨满祭司","恒焰火炬"},ang={["class:Shaman"]="这项仪式完成了卡兹莫丹萨满学徒的火焰试炼，使他们获得引导火焰并与火元素交流所需的火焰图腾。",["faction:Alliance"]="随着精神召唤在卡兹莫丹的联盟领地中扎根，像 Bruegs Kindleborn 这样的导师会引导新学徒掌握元素艺术。",["race:Dwarf"]="将火焰从洛克莫丹上方的山巅带回丹莫罗，反映了矮人精神追求者与其家园山脉的元素力量之间深厚的联系。"},sec={{t="洛克湖上的火焰",b="火焰的召唤标志着学徒在元素交流道路上的关键时刻。在山脊高处，狂风呼啸而过，学徒点燃了俯瞰洛克莫丹的恒焰火炬。跳动的火焰映照着觉醒的精神，激发起一种元素共鸣，学徒必须悉心呵护，沿着山路将其安全带回丹莫罗的雪谷之中。"},{t="烈焰之子的奖赏",b="在丹莫罗，元素导师 Bruegs Kindleborn 正在等待着旅行者，他将评判旅行者内心的火焰是否真正觉醒。呈上燃烧的火炬证明了请愿者拥有与火焰交流的意志和敬意。Kindleborn 会宣布学徒为“烈焰之子”，并授予火焰图腾，使其成为族群中元素指引的传承者。"}},faq={{q="什么是火焰的召唤？",a="火焰的召唤是卡兹莫丹萨满祭司的一项精神试炼。在俯瞰洛克莫丹的火盆处点燃恒焰火炬后，学徒必须带着燃烧的火焰穿过群山，回到丹莫罗寻找 布鲁格斯·焰生。",al={"什么是 火焰的召唤","火焰的召唤 任务","火焰的召唤 要做什么"}},{q="布鲁格斯·焰生 是谁？",a="布鲁格斯·焰生 是一位居住在丹莫罗的导师和元素向导。他负责监督火焰的元素仪式，并向完成旅程的学徒授予火焰图腾。",al={"布鲁格斯·燃生 是谁","布鲁格斯·燃生 在哪里","布鲁格斯·燃生 位置"}},{q="什么是恒焰火炬？",a="恒焰火炬是一把神圣的仪式火炬，需要在俯瞰洛克莫丹的火盆处点燃。它象征着学徒与元素之火的内在连接，必须安全地带回丹莫罗交给 布鲁格斯·焰生。",al={"什么是恒焰火炬","恒焰火炬","在哪里获取火炬"}},{q="完成这项试炼能得到什么？",a="在安全地将恒焰火炬送到 布鲁格斯·焰生 手中后，这位导师会认可你那燃烧的精神，并授予你火焰图腾，标志着你已成为烈焰之子。",al={"火焰的召唤 的奖励是什么","能获得火焰图腾吗","火焰的召唤 图腾"}},{q="这段旅程发生在什么地方？",a="旅程始于俯瞰洛克莫丹的制高点（在那里点燃火炬），随后沿着山路返回积雪覆盖的丹莫罗领地，与 布鲁格斯·焰生 会合。",al={"火焰的召唤 在哪里进行","火焰的召唤 路径","要把火炬带到哪里"}},{q="为什么 布鲁格斯 会提到玛多兰？",a="布鲁格斯 发誓时所说的“以玛多兰之胡须起誓”，指的是玛多兰·铜须，即在三锤之战中带领铜须部族的受人尊敬的矮人领袖。",al={"为什么提到 玛多兰 的胡须","玛多兰 的含义","布鲁格斯 提到的 玛多兰 是谁"}}},fp="12,162,23.241.0,22.320.0,25.218.0,25.156.0,35.200.0,47.173.0,35.148.0,32.169.0"}
P.entries["quest:94480"] = {n="A Gift From Our Enemies",s="你将偷来的饲料带给洛格玛的Gorg，以便喂饱它的盟友。附近的豺狼人和步步逼近的暮光威胁着这处聚居地。",h="你将偷来的饲料带给洛格玛的Gorg，以便喂饱它的盟友。附近的豺狼人和步步逼近的暮光威胁着这处聚居地。",kw={"盟友","农场","豺狼人","戈尔格","丰盛炖菜","洛格玛","偷来的饲料","暮光"},sec={{t="给洛格玛的食物",b="戈尔格正在洛格玛等你送来收集到的偷来的饲料。附近的威胁不只有人类：豺狼人从山上传来咆哮，暮光势力也在步步逼近。让洛格玛的盟友吃饱，或许能帮助他们保持力量。"},{t="丰盛的炖菜",b="饲料散发着浓烈的土腥味，底下还透着一股令人不快的气息。戈尔格认出这是你从农场偷来的东西，并说它能给盟友做成丰盛的炖菜。"}},faq={{q="戈尔格为什么想要偷来的饲料？",a="戈尔格会用偷来的饲料为洛格玛的盟友做一锅丰盛的炖菜。",al={"饲料用途","戈尔格 饲料","偷来的饲料做什么用"}},{q="洛格玛附近有哪些威胁？",a="人类是一种威胁，附近山上的豺狼人也在咆哮，暮光势力更是步步逼近。",al={"附近的豺狼人","暮光威胁","洛格玛附近有什么"}},{q="戈尔格是谁？",a="戈尔格是在洛格玛接收偷来的饲料，并说这些饲料能做成丰盛炖菜的人。",al={"戈尔格是谁","gorg是谁"}},{q="我该把偷来的饲料送到哪里？",a="把偷来的饲料送给洛格玛的戈尔格。",al={"饲料地点","饲料送到哪里","戈尔格位置"}}},fp="23,134,16.224.0,13.177.1,35.73.0,30.92.0,12.91.0,32.40.0"}
P.entries["quest:94481"] = {n="A Serving of Strength",s="训练师让你把炖肉送到训练场，喂给Rog’mar新兵。守卫补给线愈发艰难，这些炖肉能让他们填饱肚子。",h="训练师让你把炖肉送到训练场，喂给Rog’mar新兵。守卫补给线愈发艰难，这些炖肉能让他们填饱肚子。",kw={"一份力量","rog’mar新兵","炖肉","补给线","新兵","训练场","战士"},sec={{t="给新兵的食物",b="训练场的新兵需要食物，训练师便让你带上丰盛的炖肉。你要去西边喂Rog’mar新兵。他们的抱怨可以先放一边；如今守卫补给线愈发艰难，战士们很感激你带来的食物。"}},faq={{q="谁需要炖肉？",a="训练场的Rog’mar新兵需要炖肉。",al={"谁饿了","谁能吃到食物","新兵的食物"}},{q="我该把炖肉送到哪里？",a="Rog’mar新兵在西边的训练场。",al={"在哪里喂新兵","新兵的位置","炖肉在哪里"}},{q="为什么要给他们炖肉？",a="守卫补给线变得艰难，炖肉能让新兵填饱肚子。",al={"为什么给炖肉","食物有什么用","为什么喂新兵"}},{q="训练师怎么看新兵的抱怨？",a="训练师说，新兵有任何后续抱怨，都可以直接找他们。",al={"新兵的抱怨","他们为什么抱怨","训练师生气了吗"}},{q="训练师感激这些食物吗？",a="是的。尽管战士们嘴上那么说，训练师和战士们都很感激这些食物。",al={"训练师领情吗","感谢炖肉","战士们很感激"}}},fp="21,149,17.274.0,19.57.0,25.63.0,28.86.0,56.80.0,37.91.0"}
P.entries["quest:94483"] = {n="Show Them How It's Done",s="一名指挥官派你前往河流以南，袭击 Farholde 训练营。此番进攻旨在牵制人类，不让他们靠近要塞，为指挥官处理其他事务争取时间。",h="一名指挥官派你前往河流以南，袭击 Farholde 训练营。此番进攻旨在牵制人类，不让他们靠近要塞，为指挥官处理其他事务争取时间。",kw={"farholde","人类","要塞","牧师","河流","斥候","训练营"},sec={{t="河畔",b="指挥官派你前往河流以南的 Farholde 营地，那里有斥候报告称驻有人类部队。你需要击杀 Farholde 牧师和 Farholde 斥候。阻止人类靠近他们的要塞，能为指挥官处理其他事务争取时间。"}},faq={{q="是谁要我袭击营地？",a="一名指挥官收到斥候关于河流以南训练营的报告后，派你去对付 Farholde 部队。",al={"谁下达了命令","指挥官要求"}},{q="Farholde 营地在哪里？",a="训练营位于河流以南。",al={"营地在哪里","farholde 位置"}},{q="我该攻击谁？",a="指挥官指定 Farholde 牧师和 Farholde 斥候为目标。",al={"攻击谁","目标"}},{q="为什么要攻击人类？",a="牵制人类，不让他们靠近要塞，是为了给指挥官处理其他事务争取时间。",al={"为何与人类战斗","目的是什么"}},{q="袭击之后会发生什么？",a="指挥官说行动迅速，并打算继续处理别处的事务。",al={"接下来做什么","袭击营地之后"}}},fp="23,160,12.264.0,37.119.0,29.42.0,28.72.0,22.96.0,30.74.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Unnerving Silence 起因于影风森林东北部一个洞穴内的德鲁伊隐修会突然中断了通讯。随着 Ban'aethall 的毁灭以及该地区日益动荡，一名调查员被派遣前往寻找 Elegael Thornpaw，以评估该隐修会的命运。",h="Unnerving Silence 起因于影风森林东北部一个洞穴内的德鲁伊隐修会突然中断了通讯。随着 Ban'aethall 的毁灭以及该地区日益动荡，一名调查员被派遣前往寻找 Elegael...",kw={"班艾萨尔","德鲁伊","德鲁伊隐修会","艾勒盖尔·棘爪","影风森林","令人不安的寂静"},ang={["class:Druid"]="与影风森林中一个隐居隐修会的联络中断，引起了那些致力于维持荒野平衡的德鲁伊们的直接关注。调查 Elegael Thornpaw 的沉默，是为了保护同胞并查明是什么破坏了他们的沟通。"},sec={{t="树冠下的寂静",b="Ban'aethall 陷落后，一片寂静的忧虑笼罩着荒野。那座村庄化为废墟，且神秘的动荡在领地内蔓延，原本稳固的联络线开始断裂。特别是影风森林东北部一处深藏在洞穴中的德鲁伊隐修会，他们定期的派遣突然中断，令盟友们感到不安。"},{t="寻找隐修会",b="前往影风森林的旅者肩负着寻找 Elegael Thornpaw 的重任，她是这些洞穴德鲁伊中的杰出人物。深入那阴影笼罩的东北部，调查员必须查明该隐修会究竟只是退隐以与自然进行更深层次的沟通，还是已经沦陷于摧毁了 Ban'aethall 的危险之中。"}},faq={{q="令人不安的沉默 这个任务是关于什么的？",a="令人不安的沉默 是一项调查任务，旨在探寻影风森林中一个德鲁伊隐修会突然失联的原因。忧心忡忡的当事人请求途经此地的旅者搜索东北部的一个洞穴，查明那个隐居的组织遭遇了什么。",al={"令人不安的寂静 任务","什么是 令人不安的寂静"}},{q="埃雷加尔·荆爪 在哪里可以找到？",a="埃雷加尔·荆爪 住在影风森林东北部边缘的一处洞穴中。她是驻扎在那里的隐居德鲁伊隐修会的联络人。",al={"艾勒盖尔·棘爪 在哪里","艾勒盖尔·棘爪 位置","寻找 棘爪"}},{q="埃雷加尔·荆爪 是谁？",a="埃雷加尔·荆爪 是居住在影风森林东北部洞穴中的德鲁伊隐修会成员。她长期的沉默和未按时发送联络信息，引发了对该隐修会安全状况的严重担忧。",al={"谁是 艾勒盖尔·棘爪","棘爪 背景故事"}},{q="什么是影风森林？",a="影风森林是一片树木繁茂的区域，其东北部隐藏着一个德鲁伊洞穴隐修会。在广泛的地区动荡和 班艾萨尔 陷落后，与这片森林居住者之间的联络变得极度不稳定。",al={"什么是影风森林","影风森林隐修会"}},{q="什么是 班艾萨尔？",a="班艾萨尔 是影风森林深处的一座村庄，最近已化为废墟。它的毁灭，加上整个领地内更广泛的动荡，加剧了人们的担忧，即像影风森林隐修会这样的附近营地可能也处于危险之中。",al={"班艾萨尔 发生了什么","班艾萨尔 废墟背景故事","班艾萨尔 陷落"}},{q="为什么德鲁伊隐修会没有消息了？",a="影风森林德鲁伊的定期信息和报告已莫名中断。鉴于 班艾萨尔 的毁灭以及地区局势的不断升级，人们严重担心他们可能遭遇了灾难或被敌对势力袭击。",al={"为什么德鲁伊停止发送信息","为什么德鲁伊保持沉默"}}},fp="17,142,21.259.0,19.271.0,42.188.0,36.131.0,24.183.0,26.223.0,20.193.0,39.222.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="Tears of the Lady 是在影风森林中为 Elegael 执行的一项紧急救援任务。为了救治被困在 Nightclaw Den 中的受伤同伴，旅行者必须在当地的树干上搜寻 Lady's Tear，这是一种对于包扎严重伤口至关重要的防腐苔藓。",h="Tears of the Lady 是在影风森林中为 Elegael 执行的一项紧急救援任务。为了救治被困在 Nightclaw Den 中的受伤同伴，旅行者必须在当地的树干上搜寻 Lady's...",kw={"艾勒盖尔","女士之泪","苔藓","夜爪巢穴","药膏","影风森林","女士的眼泪"},ang={["class:Priest"]="虽然牧师们可以引导圣光来治愈凡人的伤势，但在魔法救援力量薄弱时，像 Lady's Tear 这样的天然药膏可以作为受伤幸存者的重要物理敷料。",["profession:Herbalism"]="草药师和战地医疗人员都很看重 Lady's Tear，因为它具有粘性的防腐分泌物，可以在荒野紧急情况下迅速封住伤口并防止感染。"},sec={{t="影风森林的绝望补救措施",b="在影风森林阴影笼罩的深处，Elegael 急需援助来救治被困在 Nightclaw Den 中的同伴。由于身负重伤的盟友正等待救援，且常规补给匮乏，需要直接从周围的荒野中搜寻野外医疗用品。这次行动的关键在于在被遗弃的伤员生命耗尽之前，获取到这些天然药物。"},{t="疗伤苔藓",b="Elegael 计划配制的药膏中，至关重要的成分是 Lady's Tear，这是一种附着在影风森林各处树木根部的细长苔藓。这种植物会分泌出一种粘稠的、具有天然防腐特性的分泌物，能够封住开放性伤口，并保护严重外伤免受潮湿荒野环境的影响而恶化。提供足够的苔藓，Elegael 就能配制出稳定伤者状况所需的敷料。"}},faq={{q="女士之泪 是关于什么的？",a="女士之泪 是由影风森林中的 埃雷加尔 所指导的一项恢复工作。受伤的同伴仍被困在 夜爪巢穴 中，埃雷加尔 需要当地的植物来配制紧急药膏以维持他们的生命。",al={"什么是 女士之泪","女士之泪 任务信息"}},{q="什么是 女士之泪？",a="女士之泪 是一种生长在影风森林各处树木根部的细长苔藓。它会分泌出一种天然的粘性树液，作为强效防腐剂，非常适合用于包扎和封盖开放性伤口。",al={"什么是 女士之泪","女士之泪 苔藓","什么是 女士之泪 苔藓"}},{q="谁是 埃雷加尔？",a="埃雷加尔 是一位组织了影风森林医疗救助工作的幸存者。在将受伤的同伴留在 夜爪巢穴 后，埃雷加尔 正收集医疗物资以配制治疗用品，然后返回营救他们。",al={"谁是 艾勒盖尔","女士之泪 任务发布者"}},{q="什么是 夜爪巢穴？",a="夜爪巢穴 是影风森林附近的一个地点，埃雷加尔 的几名受伤盟友被困在那里。他们的情况岌岌可危，迫使人们必须急切地搜集治疗草药。",al={"什么是 夜爪巢穴","夜爪巢穴 在哪里"}},{q="为什么 埃雷加尔 需要 女士之泪 苔藓？",a="这种苔藓能提供一种重要的防腐分泌物，用于配制医用药膏。这种粘性物质可以封住开放性伤口，并帮助被困在洞穴中的幸存者抵御感染。",al={"为什么需要 女士之泪","这种苔藓有什么作用"}},{q="在哪里可以找到 女士之泪 苔藓？",a="女士之泪 苔藓通常附着在影风森林各处的树木根部。虽然 埃雷加尔 已经收集了触手可及的部分，但还需要从周围的树林中搜寻更多。",al={"女士之泪 在哪里生长","寻找 女士之泪"}}},fp="17,157,32.238.0,16.312.0,42.164.0,20.178.0,15.135.0,26.156.0,39.165.0,32.153.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="\"Feathers for Binding\" 是影风森林中的一项任务，主要目标是从幼年尖叫兽身上收集保温羽毛，用于制作保护性的药膏。虽然这些通常温顺的生物变得极具攻击性，但它们的羽毛对于保护杀菌药膏免受外界环境影响至关重要。冒险者必须勇敢面对这些充满敌意的幼崽，以获取区域护理所需的材料。",h="\"Feathers for Binding\"...",kw={"杀菌树液","束缚用的羽毛","药膏","影风森林","影风森林尖叫兽","尖叫兽"},ang={["class:Druid"]="德鲁伊可能会对猎杀这些幼年林地野兽与任务发布者感同身受，尽管日益增长的攻击性和紧迫的医疗需求让人别无选择。",["profession:Herbalism"]="草药师和自然治疗者能够理解结合苔藓、杀菌树液和隔热羽毛来制作有效的战地敷料或药膏时的精妙平衡。"},sec={{t="森林疗法",b="在影风森林深处，准备战地药物往往需要从土地中寻找资源。在治疗重伤时，草药师和治疗者会使用一种基于苔藓和杀菌树液的特制药膏。为了确保药液不会迅速干涸或在恶劣天气下失去效力，需要耐用的绝缘敷料。影风森林幼年尖叫兽的羽毛提供了一种理想的天然屏障，既能保护伤口，又能封住药物。"},{t="反常的敌意",b="获取这些绒羽变得出乎意料地危险。在通常情况下，影风森林的幼年尖叫兽是温顺的林间居民。然而近来，一股莫名其妙的攻击性浪潮席卷了它们。这些幼年掠食者挥舞着足以造成致命伤的强力爪子，现在会凶猛地攻击路人。收集它们的羽毛需要冒险者面对这些从无害幼崽转变为真正威胁的生物。"},{t="令人遗憾的必要之举",b="要求旅行者猎杀幼年生物让当地的看护者感到沉重，他们公开哀悼这种淘汰的必要性。然而，随着多重紧急情况威胁着该地区，且这些野兽变得越来越危险，减少它们的数量具有双重目的：收集重要的治疗材料，同时压制森林道路上日益增长的威胁。每一根收集到的羽毛都受到尊重，以确保它们的牺牲没有被浪费。"}},faq={{q="为什么药膏需要影风森林尖叫兽的羽毛？",a="幼年影风森林尖叫兽的羽毛具有天然的隔热特性。放在苔藓层上，它们可以作为一种保护性敷料，防止杀菌药液干涸，同时保护伤口免受恶劣环境的影响。",al={"羽毛的用途","为什么使用尖叫兽羽毛","药膏羽毛"}},{q="幼年尖叫兽有多危险？",a="虽然影风森林尖叫兽通常是温顺的生物，但它们最近变得异常具有敌意。尽管它们还很年幼，但却拥有巨大的利爪，足以剖开毫无防备的旅行者的腹部。",al={"尖叫兽的危险性","尖叫兽危险吗","尖叫兽的攻击性"}},{q="为什么要猎杀幼年尖叫兽而不是成年个体？",a="任务发布者对捕杀幼兽表示了由衷的悔意。然而，由于它们突然激增的攻击性，以及需要应对其他相互竞争的荒野紧急情况，在收集所需药物的同时减少它们的数量被认为是一项痛苦的必要之举。",al={"为什么要杀死幼年尖叫兽","杀死幼年尖叫兽"}},{q="在哪里可以找到影风森林尖叫兽？",a="影风森林尖叫兽在影风森林的林冠和灌木丛中游荡，旅行者必须小心穿过树林才能追踪到它们。",al={"影风森林在哪里","尖叫兽位置","尖叫兽在哪里"}},{q="除了这些羽毛外，还使用了哪些其他成分？",a="这种药膏由当地的苔藓和杀菌树液分层组成，然后用从幼年尖叫兽身上采集的绒羽进行包裹和隔热。",al={"药膏成分","药膏里有什么"}},{q="为什么尖叫兽最近变得如此具有敌意？",a="它们突然产生敌意的确切原因尚不清楚，但这些平时温和的幼兽变得异常好斗，这增加了当地看护者所面临的危机。",al={"为什么尖叫兽很愤怒","尖叫兽攻击性的原因"}}},fp="20,179,22.275.0,26.255.0,23.313.0,63.166.0,43.170.0,58.225.0,43.142.0,63.106.0,50.175.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Unwanted and Unworthy是泽弗拉斯（Zephras）上的一个任务，冒险者们将在任务中协助埃雷加尔（Elegael）对奥拉凯斯邪教徒进行报复，此前这些邪教徒在影风森林发动了一场血腥的伏击。玩家通过击杀邪教徒并找回被盗的传家宝，为牺牲的德鲁伊复仇，并为大长老（High Elder）收回神圣的祖传遗物。",h="Unwanted and...",kw={"奥拉凯斯","染血的传家宝","埃雷加尔","步兵","传家宝","影风森林","申多雷","风暴追猎者","泽弗拉斯"},ang={["class:Druid"]="奥拉凯斯邪教徒在对泽弗拉斯的无端袭击中流下了当地德鲁伊的鲜血，使得这次打击成为了一次直接的复仇行动，也是对自然平衡的捍卫。"},sec={{t="影风森林的伏击",b="当奥拉凯斯邪教徒在影风森林对当地德鲁伊发动突然袭击时，泽弗拉斯宁静的平衡被瞬间打破。埃雷加尔曾认为这些狂热者不过是“脑子里塞满云雾”的无害梦想家，却因他们袭击手段的极度残忍而措手不及。这场袭击导致德鲁伊的鲜血洒满了森林，引发了对肇事的步兵和风暴追猎者进行迅速报复的呼声。"},{t="被玷污的传家宝与逝去的青春",b="对埃雷加尔来说，邪教徒的背叛剥夺了他们的传承：他们不再配被称为shen'dorei，他们的遗骸也不配得到故乡之风的吹拂。许多邪教徒是原本拥有光明未来却因狂热而生命过早终结的年轻人。通过找回他们血迹斑斑的传家宝，冒险者们协助确保这些神圣物品被交还给大长老，等待更睿智、更值得拥有的下一代。"}},faq={{q="谁是奥拉凯斯邪教徒？",a="奥拉凯斯邪教徒是一群活跃在泽弗拉斯岛上、痴迷于风暴的狂热信徒。据埃雷加尔所言，他们曾经只被视为愚蠢或“脑子里塞满云雾”，但他们突然对当地德鲁伊转向了残暴的暴力行径。",al={"奥拉凯斯是谁","奥拉凯斯邪教","邪教徒是谁"}},{q="谁是埃雷加尔？",a="埃雷加尔是泽弗拉斯的一位神多雷守护者或德鲁伊，曾遭到奥拉凯斯邪教徒的伏击。由于对年轻生命的背叛和流血事件感到悲痛，埃雷加尔寻求报复并找回被盗的祖传遗物。",al={"埃雷加尔是谁","任务发布者埃雷加尔"}},{q="什么是染血的传家宝？",a="这些染血的传家宝属于那些被卷入奥拉凯斯邪教的年轻神多雷。埃雷加尔收集它们，以便最终能归还给大长老的收藏，并传给未来更值得拥有的后代。",al={"染血的传家宝","为什么要收集传家宝","什么是传家宝"}},{q="什么是申多雷？",a="申多雷是居住在泽弗拉斯的族群。埃雷加尔认为，奸诈的奥拉凯斯邪教徒因其暴力的背叛和对岛屿和谐的亵渎，已经失去了被称为申多雷的权利。",al={"申多雷的含义","什么是申多雷"}},{q="影风森林在哪里？",a="影风森林是位于泽弗拉斯的一片林区，奥拉凯斯步兵和风暴追猎者在此活动，这也是针对德鲁伊的无端伏击发生的地方。",al={"影风森林位置","影风森林在哪里"}},{q="为什么奥拉凯斯邪教徒要伏击德鲁伊？",a="这些邪教徒的具体动机对埃雷加尔来说仍是一个令人不安的谜团。尽管长期以来他们被视为无害的狂热者，但他们突然且恶毒的暴动打破了岛上维持的脆弱平衡。",al={"邪教徒为何攻击","邪教动机","为何伏击德鲁伊"}}},fp="21,124,27.286.0,32.360.0,30.198.0,15.244.0,32.200.0,24.189.0,27.146.0,48.174.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="“The Ties That Bind”是影风森林中的一个任务，其核心在于德鲁伊教团内部的一场痛苦背叛。艾蕾加尔·荆爪发现失踪的教团德鲁伊哈林投靠了入侵的邪教徒并担任指挥官，于是下令将其处决。当亲人背叛了自己的种族时，这个任务揭示了履行职责所要付出的惨痛个人代价。",h="“The Ties That...",kw={"塞纳里奥议会","哈林指挥官","邪教徒","德鲁伊","艾蕾加尔·荆爪","哈林","影风森林","束缚的纽带"},ang={["class:Druid"]="塞纳里奥议会将维护平衡与亲缘视为神圣之事，因此哈林的背叛以及他在教团德鲁伊同僚之间造成的血腥杀戮，被视为对该组织尤为严重的冒犯。"},sec={{t="森林中的背叛",b="在影风森林深处，德鲁伊们遭遇了一群凶残的邪教徒，他们播撒着恐怖与鲜血。对于艾蕾加尔·荆爪来说，这场袭击因为一个痛苦的发现而变得更加沉重：在屠杀现场弥漫着前教团德鲁伊哈林的气息。哈林几个月前就失踪了，但他并没有在荒野中丧生，而是投靠了入侵的邪教徒，指挥他们对昔日的同胞发起了残酷的攻势。"},{t="血缘与羁绊",b="哈林的背叛不仅是违背了对塞纳里奥议会的誓言。当艾蕾加尔呈上这位阵亡指挥官的首级时，她透露哈林其实是她的表亲。尽管她对他的暴行感到愤怒，但亲手处决自己的亲人依然是她独自难以承受的重担。他的死为这个恶行导致无数无辜生命逝去的叛徒画上了一个血腥的句号。"}},faq={{q="谁提供了“羁绊”这个任务？",a="艾蕾加尔·荆爪是一名驻扎在影风森林的德鲁伊。在应对邪教徒入侵的过程中，她在发现哈林指挥官参与了屠杀后，指引冒险者去将他除掉。",al={"谁给予羁绊任务","影风森林任务发布者","谁是艾蕾加尔·荆爪"}},{q="哈林指挥官是谁？",a="哈林指挥官曾是塞纳里奥议会的一名德鲁伊，在邪教徒袭击前几个月失踪。他并没有成为步步逼近的黑暗的受害者，而是主动加入了敌对的邪教徒，并指挥他们的军队对抗自己的同胞。",al={"谁是哈林","哈林指挥官背景故事","哈林背景"}},{q="为什么艾蕾加尔想要哈林指挥官死？",a="哈林背弃了他的德鲁伊教团，指挥邪教徒屠杀无辜生命，并沾染了同僚的鲜血。由于他的所作所为以及对森林构成的威胁，艾蕾加尔下令将他处决。",al={"为什么要杀死哈林","哈林的罪行","哈林做了什么"}},{q="艾蕾加尔·荆爪和哈林之间有什么关系？",a="哈林指挥官是艾蕾加尔·荆爪的表亲。虽然她对他的罪行深感愤怒，但她承认，亲手处决自己的血亲将是一个沉重的负担，因此她决定请求冒险者的帮助。",al={"艾蕾加尔和哈林的关系","艾蕾加尔和哈林是如何认识的"}},{q="为什么邪教徒会出现在影风森林？",a="邪教徒出现在影风森林的确切动机即便是当地德鲁伊也感到困惑。然而，他们的队伍是由像哈林这样的前教团成员带头的，正是他指挥了针对森林守护者的暴力与屠杀。",al={"影风森林的邪教徒","为什么邪教徒在影风森林"}},{q="这个任务发生在什么地方？",a="任务事件发生在影风森林内，艾蕾加尔·荆爪在那里调查邪教徒的入侵，并面对表亲背叛的残酷现实。",al={"羁绊发生在哪里","影风森林位置"}}},fp="18,192,22.310.0,17.349.1,40.171.0,25.191.0,45.206.0,60.166.0,50.198.0,33.133.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="The Wounds of Betrayal 是影风森林中的一个任务，围绕着针对稀有的辛多雷德鲁伊的惨烈袭击后的余波展开。伊莱加尔派遣玩家将紧急草药膏送到夜牙洞穴，救治她受伤的同胞，并寻找失踪的伴侣乔雷尔·风歌。这次任务很快揭示了背叛带来的苦涩代价，并引发了针对奥拉凯斯的复仇冲突。",h="The Wounds of Betrayal...",kw={"奥拉凯斯","德鲁伊","伊莱加尔","乔雷尔·风歌","夜牙洞穴","影风森林","辛多雷","背叛的伤痕"},ang={["class:Druid"]="作为荒野的德鲁伊守护者，目睹同道修行者——特别是稀有的辛多雷德鲁伊——屈服于背叛和重伤，背负着沉重的个人情感负担。",["race:NightElf"]="暗夜精灵崇尚德鲁伊传统，这使得影风森林中同胞德鲁伊的苦难以及与背叛的斗争产生了深刻的共鸣。"},sec={{t="对辛多雷的援助",b="The Wounds of Betrayal 始于伊莱加尔，一位在影风森林中处理毁灭性袭击后果的辛多雷德鲁伊。在匆忙准备了药用草药膏后，她急需一名冒险者将援助送到撤退至附近夜牙洞穴的同胞手中，那里就在穿过空地的北面。辛多雷德鲁伊的人数极其稀少，因此每一位成员的幸存对于他们脆弱的聚居地来说都至关重要。"},{t="寻找乔雷尔·风歌",b="除了为洞穴中七位受伤的德鲁伊提供紧急救治外，伊莱加尔心中还有一个恳求：寻找她的伴侣乔雷尔·风歌。当她为了准备药物而逃离战斗时，乔雷尔已是奄奄一息。冒险深入夜牙洞穴的黑暗深处，揭示了圣地所遭受的真正破坏，以及乔雷尔所面临的残酷命运。"},{t="复仇誓言",b="在得知乔雷尔的悲惨结局以及同胞们遭受的恐怖伤亡后，伊莱加尔的冷静因悲痛与愤怒而崩塌。她咬牙切齿，带着痛苦的咆哮，摒弃了绝望，转而寻求彻底的报复，发誓任何与阴影中的奥拉凯斯结盟的人，都将因屠杀她的族人而遭受她无情的愤怒。"}},faq={{q="是谁发布了 背叛之伤 任务？",a="该任务由伊莱加尔发布，她是一位辛多雷德鲁伊，在影风森林发生暴力袭击后，正绝望地试图救治她受伤的同胞。",al={"谁发布了 背叛之伤","背叛之伤 任务发布者","伊莱加尔是谁"}},{q="夜牙洞穴位于哪里？",a="夜牙洞穴是一个位于影风森林穿过空地北面的洞穴，受伤的辛多雷德鲁伊已撤退至此寻求庇护。",al={"夜牙洞穴在哪里","夜牙洞穴位置","受伤的德鲁伊在哪里"}},{q="乔雷尔·风歌是谁？",a="乔雷尔·风歌是伊莱加尔的伴侣。他在袭击中身受重伤并留在了夜牙洞穴内，玩家会在那里发现他悲惨的命运。",al={"乔雷尔·风歌是谁","乔雷尔·风歌的命运","乔雷尔在哪里"}},{q="什么是辛多雷德鲁伊？",a="辛多雷是一个稀有的群体，其中只有极少数德鲁伊修行者。由于他们人数稀少，伊莱加尔强调，他们当中幸存的每一个生命都极其珍贵。",al={"什么是辛多雷","谁是辛多雷德鲁伊","辛多雷德鲁伊背景故事"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是应对袭击或与袭击德鲁伊者结盟的敌人。在得知乔雷尔的命运和她教派所受的毁灭性打击后，伊莱加尔发誓要向奥拉凯斯及其任何盟友复仇。",al={"谁是奥拉凯斯","奥拉凯斯","伊莱加尔为何憎恨奥拉凯斯"}},{q="在任务中乔雷尔·风歌发生了什么？",a="当你找到夜牙洞穴中的乔雷尔·风歌时，你发现他的情况发生了悲剧性的转变。带着他的命运以及幸存德鲁伊的严峻处境的消息返回找伊莱加尔，使她陷入了悲痛，并立下了愤怒的复仇誓言。",al={"乔雷尔·风歌发生了什么","乔雷尔还活着吗","乔雷尔的结局"}}},fp="22,202,22.265.0,31.307.1,20.247.2,43.111.0,31.123.0,24.120.0,31.101.0,21.214.0,46.206.0"}
P.entries["quest:94490"] = {n="Ripped Missive",s="Ripped Missive是从Haalien身上找回的一封血迹斑斑的信件，它揭示了一场针对影风森林中一座德鲁伊大兽穴的残酷邪教徒袭击。信中的内容揭露了这场屠杀背后冷酷的动机，并暗示了源自瓦拉纳尔内部的危险颠覆活动。",h="Ripped Missive是从Haalien身上找回的一封血迹斑斑的信件，它揭示了一场针对影风森林中一座德鲁伊大兽穴的残酷邪教徒袭击。信中的内容揭露了这场屠杀背后冷酷的动机，并暗示了源自瓦拉纳尔内部的危险颠覆活动。",kw={"邪教徒","德鲁伊大兽穴","艾勒盖尔·棘爪","哈利恩","洛瑟鲁姆","晶塔","撕破的信件","影风森林","瓦拉纳尔"},ang={["class:Druid"]="德鲁伊们会在这封信中发现悲惨的苦果，信中揭露了在大兽穴中被屠杀的德鲁伊仅仅是因为挡了那些寻找远古晶塔的邪教徒的路。"},sec={{t="血迹斑斑的命令",b="这份破损且沾满血迹的文件被塞在Haalien的护腕后面，其中包含有关最近影风森林中发生的暴力事件的严峻情报。在激烈的冲突后找回，这片文字揭示了袭击当地德鲁伊大兽穴的邪教徒的阴暗意图，为那些寻求为死者伸张正义的人提供了重要的线索。"},{t="无谓的屠杀",b="当把这张羊皮纸交给影风森林的Elegael Thornpaw时，这次突袭的可怕真相大白了。邪教徒并非因为与德鲁伊有特定的积怨才发动袭击；他们是为了寻找一座神秘的晶塔，仅仅因为大兽穴的居民挡了他们的路就将其杀害。Elegael对这场无谓的屠杀感到愤怒，誓要向森林中残留的任何邪教徒复仇。"},{t="瓦拉纳尔的背叛",b="除了揭示邪教徒对晶塔的关注外，这封信还带来了一个更令人震惊的消息：指令似乎直接源自瓦拉纳尔。这一严峻的事实指向了在定居点内部活动的叛徒。为了在更多生命逝去之前揭露这个阴谋，必须立即将此信件送到瓦拉纳尔的Lotheluum手中。"}},faq={{q="什么是撕破的信件？",a="撕破的信件是一封在战斗后发现被塞在哈利恩护腕后面的血迹斑斑、破损的信件。它包含揭露邪教徒袭击影风森林德鲁伊大兽穴动机的关键情报。",al={"什么是撕破的信件","撕破的信件任务","血迹斑斑的便条 哈利恩"}},{q="这封信是从哪里找回的？",a="这封信是直接从哈利恩身上找回的，是在一场激烈的对峙后发现被塞在他们的一个护腕后面。信件在战斗中受损并沾染了血迹。",al={"谁掉落了撕破的信件","撕破的信件来自哪里","哈利恩是谁"}},{q="谁应该收到撕破的信件？",a="这封信最初被带给影风森林的埃雷加尔·荆爪。在阅读了这份文件后，埃雷加尔指示将其迅速送到瓦拉纳尔的洛瑟鲁姆手中，以警告潜在的背叛。",al={"谁需要撕破的信件","我应该把撕破的信件交给谁","艾勒盖尔·棘爪 信件"}},{q="为什么邪教徒袭击德鲁伊大兽穴？",a="信件揭示，邪教徒袭击德鲁伊大兽穴并非出于对德鲁伊本身的仇恨，而是为了夺取位于那里的一座晶塔。居住在其中的德鲁伊仅仅因为挡在邪教徒的路上就被无情地杀害了。",al={"为什么邪教徒袭击德鲁伊大兽穴","邪教徒在大兽穴的动机","为什么哈利恩发动袭击"}},{q="袭击命令源自何处？",a="信件表明邪教徒的指令源自瓦拉纳尔，暗示有一名叛徒正隐藏在定居点内部并策划行动。",al={"命令来自哪里","谁派遣了哈利恩","瓦拉纳尔的叛徒"}},{q="洛瑟鲁姆是谁，为什么要通知他们？",a="洛瑟鲁姆是位于瓦拉纳尔的一位联系人。埃雷加尔·荆爪命令冒险者将这封信带给洛瑟鲁姆，提醒他们邪教徒的致命指令可以追溯到隐藏在瓦拉纳尔的某个人。",al={"洛瑟鲁姆是谁","为什么要把信件带给洛瑟鲁姆","洛瑟鲁姆 瓦拉纳尔"}}},fp="14,167,19.240.0,19.260.1,21.250.2,27.155.0,36.126.0,38.158.0,42.114.0,38.96.0,47.166.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="《大兽穴的命运》讲述了邪教徒突袭隐秘德鲁伊大兽穴后的惨烈余波。一位冒险者被派遣将一份寻获的信件送往瓦拉纳尔的洛瑟鲁姆，带去伤亡惨重的消息。这份公文揭露了一个令人深感不安的事实：瓦拉纳尔内部有人一直向敌人提供关键情报。",h="《大兽穴的命运》讲述了邪教徒突袭隐秘德鲁伊大兽穴后的惨烈余波。一位冒险者被派遣将一份寻获的信件送往瓦拉纳尔的洛瑟鲁姆，带去伤亡惨重的消息。这份公文揭露了一个令人深感不安的事实：瓦拉纳尔内部有人一直向敌人提供关键情报。",kw={"邪教徒","德鲁伊大兽穴","大长老","洛瑟鲁姆","信件","大兽穴的命运","叛徒","瓦拉纳尔"},ang={["class:Druid"]="德鲁伊们深刻地感受到了这场悲剧的沉重，因为在大兽穴倒下的是他们的同伴，而他们隐秘的避难所却被背叛给了敌对的邪教徒。"},sec={{t="大兽穴的惨剧",b="在邪教徒对德鲁伊大兽穴发动暴力入侵后，幸存的守卫者们饱受摧残，哀悼着同伴的逝去。尽管在外部援助下，紧迫的危机得到了控制，但无论是肉体上还是精神上的创伤都极其巨大。倒下的人无法复生，而身负重伤的幸存者在附近仍有残留邪教徒徘徊的情况下，也无力进行长途跋涉。"},{t="瓦拉纳尔的背叛",b="一份寻获的信件证实，邪教徒并非随机行事；瓦拉纳尔内有人一直潜伏其中，向他们积极泄露情报。当洛瑟鲁姆看到这份公文时，他对同伴的屠杀以及有人在他们的定居点内逍遥法外这一恐怖暗示感到极其惊恐。他下定决心不能让他们的牺牲被遗忘，于是将证据直接呈交给了大长老。"}},faq={{q="洛瑟鲁姆是谁？",a="洛瑟鲁姆是瓦拉纳尔的一位人物，负责接收有关德鲁伊大兽穴的报告。在得知袭击事件并审阅了那份寻获的信件后，他为阵亡的同伴深感悲痛，并发誓要将背叛的证据直接呈交给大长老。",al={"洛瑟鲁姆","洛瑟鲁姆是谁","洛瑟鲁姆非玩家角色"}},{q="德鲁伊大兽穴发生了什么？",a="德鲁伊大兽穴遭到了敌对邪教徒的毁灭性打击，导致多名守卫者死亡。尽管在一位冒险者的帮助下消除了直接威胁，但幸存的保护者们已伤痕累累，并发现了这次袭击是在内部人员指引下进行的证据。",al={"大兽穴发生了什么","德鲁伊大兽穴袭击","大兽穴的命运背景故事"}},{q="那份寻获的信件揭露了什么？",a="信件揭露，潜伏在瓦拉纳尔定居点内的一名内应一直在秘密向邪教提供情报。这些情报表明，针对大兽穴的致命突袭正是通过当地的破坏活动和间谍行为才得以实现。",al={"信件说了什么","大兽穴信件","背叛信件"}},{q="洛瑟鲁姆提到的大长老是谁？",a="大长老是瓦拉纳尔的一位显赫权威，洛瑟鲁姆向其负责。由于伤亡惨重且面临现行叛徒的威胁，洛瑟鲁姆立即将信件和惨剧的消息上报给了大长老。",al={"大长老是谁","瓦拉纳尔大长老","大长老"}},{q="谁该为袭击德鲁伊大兽穴负责？",a="这次袭击是由在该地区活动的邪教成员执行的。多亏了瓦拉纳尔内部一名内应的指引，邪教徒成功对大兽穴的居民造成了灾难性的损失。",al={"谁袭击了大兽穴","谁袭击了德鲁伊大兽穴","大兽穴邪教徒"}},{q="为什么大兽穴的幸存者不能亲自递送信件？",a="大兽穴的幸存者在袭击后伤势过重，无法承受前往瓦拉纳尔的长途跋涉。除了身体状况不适合赶路之外，幸存者还留下来清除残余的邪教徒，并派出一名冒险者前去报信。",al={"为什么要递送信件","任务发布者受伤","为什么幸存者不能去瓦拉纳尔"}}},fp="19,269,18.340.0,21.379.1,17.202.0,31.204.0,39.171.0,45.194.0,48.164.0,69.180.0"}
P.entries["quest:94493"] = {n="A Sacrifice in Vain",s="Elegael Thornpaw担心奥拉凯斯教徒会击溃她大兽穴中受伤的同伴。原本要送往瓦拉纳尔的消息没有送达，她只得求助。",h="Elegael Thornpaw担心奥拉凯斯教徒会击溃她大兽穴中受伤的同伴。原本要送往瓦拉纳尔的消息没有送达，她只得求助。",kw={"徒劳的牺牲","奥拉凯斯教徒","大兽穴","艾蕾盖尔·棘爪","援军","瓦拉纳尔","伤者"},sec={{t="求援",b="奥拉凯斯教徒几乎毫无预警地袭击了Elegael Thornpaw的同伴。她的巢穴里许多人受了伤，或是濒临死亡，她不知道他们还能撑多久。她曾试着向瓦拉纳尔送信，但消息没能送达。援军迟迟不见踪影，Elegael请求你帮忙。"}},faq={{q="谁在求助？",a="奥拉凯斯教徒正在袭击埃雷加尔·荆爪的同伴，她因此请求援助。",al={"谁需要帮助","艾勒盖尔·棘爪","艾勒盖尔"}},{q="大兽穴里的人遭遇了什么？",a="奥拉凯斯教徒几乎毫无预警地伏击了他们。许多人受了伤，或已奄奄一息。",al={"大兽穴伤者","这里发生了什么","教徒袭击"}},{q="瓦拉纳尔为什么没有派来援军？",a="埃雷加尔的消息没有送达瓦拉纳尔，因此援军尚未抵达。",al={"援军在哪里","瓦拉纳尔来信","致瓦拉纳尔的消息"}},{q="埃雷加尔需要什么？",a="埃雷加尔请求你帮助受伤的同伴，在奥拉凯斯教徒的袭击中活下来。",al={"如何提供帮助","帮助艾勒盖尔","她请求什么"}}},fp="19,163,14.316.0,23.75.0,39.83.0,41.77.0,23.83.0"}
P.entries["quest:94494"] = {n="水之召唤",s="“水之召唤”是一项精神试炼，旨在让萨满祭司能够与水元素的净化本质进行沟通。在与风、地、火元素达成和谐后，受训者将前往洛克莫丹寻找诺里克·洛克塔恩，他会敦促受训者迈出学习水之纯净的第一步。",h="“水之召唤”是一项精神试炼，旨在让萨满祭司能够与水元素的净化本质进行沟通。在与风、地、火元素达成和谐后，受训者将前往洛克莫丹寻找诺里克·洛克塔恩，他会敦促受训者迈出学习水之纯净的第一步。",kw={"水之召唤","元素","大山","纯净","萨满","图腾试炼","水之图腾"},ang={["class:Shaman"]="这项试炼标志着与元素灵魂调谐的基本步骤，从大地和火焰开始，进而理解水的流动性与纯净。",["race:Dwarf"]="导师那粗犷的矮人语调反映了矮人萨满是如何通过崎岖的山路来与自然进行沟通的。"},sec={{t="纯净之道",b="“水之召唤”是萨满祭司元素平衡之旅中至关重要的一步。随着大地让每一步变得扎实，狂风在身后呼啸，心中的火焰熊熊燃烧，旅行者被召唤去领悟水的深层本质。它不仅是一种外部力量，更是纯净与坚韧的精神体现。"},{t="元素的飞升",b="在一位有着山峰般稳重语调的资深导师的指引下，受训者被催促着毫不犹豫地前进。萨满的共鸣从不会轻易授予；它需要肉体的努力、坚韧的精神以及对崎岖地形的攀登。正如导师所警告的那样，大山不会等待任何人，通往真正理解的旅程必须从那决定性的第一步开始。"}},faq={{q="什么是水之召唤？",a="“水之召唤”代表了萨满祭司寻求与水元素沟通的精神洗礼。在已经领悟了大地之稳固、风之疾驰和火焰之火花后，请求者被召唤去学习水之深层真理。",al={"什么是水之召唤","水之召唤任务","这个任务是什么"}},{q="谁指引了这段旅程？",a="铁炉堡的萨满训练师艾尔德兰·风暴断裂者将受训者指引至洛克莫丹的诺里克·洛克塔恩处。诺里克说了这番话，敦促受训者采取果断行动，并提醒旅行者，元素与高地不会等待犹豫不决的人。",al={"谁给予水之召唤","谁说大山不会等待任何人","水之召唤导师"}},{q="“大山不会等待任何人”是什么意思？",a="这是迈出艰苦攀登第一步的号召。萨满的旅程往往通向灵魂居住的高峰和偏远荒野，这需要坚定的决心，而不是徘徊不定的怀疑。",al={"大山不会等待任何人是什么意思","大山不会等待任何人","大山的含义"}},{q="水之纯净的真理是什么？",a="在萨满的修行中，每种元素都提供独特的教导。如果说岩石提供了稳定性，火焰点燃了决心，那么水则体现了净化、流动与纯净——这是平衡内心灵魂的重要智慧。",al={"为什么是水之纯净","水之纯净的真理","水元素的含义"}},{q="在这里水与其他元素有何关联？",a="这段旅程承认大地、风和火是已经在脚步、呼吸和腹中感受到的基础，然后才接触水。与元素和谐共处需要掌握平衡，而不是孤立地追求单一的力量。",al={"哪些元素优先","水的先决条件","水之召唤元素"}},{q="受训者听完这些话后要去哪里？",a="受训者必须迈出第一步。诺里克·洛克塔恩会派他们前往湿地，寻找住在南部瀑布下方洞穴里的赫夫达娜·萨格伦德，以获取水之水塔。",al={"水之召唤下一步会发生什么","我现在要去哪里","水之召唤的下一步"}}},fp="13,164,18.179.0,24.227.0,26.141.0,36.205.0,53.171.0,36.156.0,49.173.0,53.148.0"}
P.entries["quest:94495"] = {n="水之召唤",s="“水之召唤”将精神探索者派遣至湿地，去领悟水的净化之力并寻找水之萨普塔。在南侧瀑布下方的一处隐蔽洞穴中，矮人赫薇达娜·萨格伦德迎接那些勇闯荒野的旅者。",h="“水之召唤”将精神探索者派遣至湿地，去领悟水的净化之力并寻找水之萨普塔。在南侧瀑布下方的一处隐蔽洞穴中，矮人赫薇达娜·萨格伦德迎接那些勇闯荒野的旅者。",kw={"水之召唤","矮人","赫薇达娜·萨格伦德","萨满祭司","南侧瀑布","水之灵契","湿地"},ang={["class:Shaman"]="该任务是学习水的本质并获取水之萨普塔以与水之灵沟通的重要一步。",["faction:Alliance"]="这段旅程将旅者带入危险的湿地深处，远离任何矮人或联盟的巡逻队。",["race:Dwarf"]="赫薇达娜认出这位寻求者是敢于在危险的沼泽地和潜伏的黑铁矮人面前闯荡的同胞。"},sec={{t="水的本质",b="理解水的旅程始于关于其双重本质的简单课程：水象征着重生，在纯净时能切石净污，但一旦被污染，它便会带来毁灭。寻求沟通的初学者被派遣到野外，从那些栖居于水元素旁的人那里获取水之萨普塔。"},{t="瀑布下的庇护所",b="在湿地潮湿的沼泽深处，赫薇达娜·萨格伦德和她的家人居住在一个直接位于南侧瀑布下方的隐蔽洞穴中。他们远离铁炉堡卫兵的保护，忍受着潜伏在周围沼泽中的黑铁矮人的威胁，以维持他们在奔流瀑布旁的隐居生活。"}},faq={{q="赫薇达娜·萨格伦德是谁？",a="赫薇达娜·萨格伦德是一位矮人，她与家人住在湿地南侧瀑布下方的一个洞穴里。她帮助那些寻求与水沟通以及探索水之萨普塔秘密的萨满祭司。",al={"赫薇达娜是谁","赫薇达娜·萨格伦德","赫薇达娜在哪里"}},{q="什么是水之萨普塔？",a="水之萨普塔是萨满祭司用来与水之灵沟通的一种仪式药剂。在东部王国，寻求者会被指引去南侧瀑布附近找赫薇达娜·萨格伦德获取此物。",al={"什么是水之萨普塔","萨普塔含义","为什么要获取水之萨普塔"}},{q="在哪里可以找到赫薇达娜·萨格伦德？",a="赫薇达娜和她的家人隐居在湿地南侧瀑布正下方的一个洞穴里。",al={"赫薇达娜住在哪里","洞穴在哪里","南侧瀑布位置"}},{q="为什么赫薇达娜要住在危险的湿地？",a="尽管沼泽中潜伏着黑铁矮人，且完全没有城市守卫的保护，赫薇达娜和她的族人出于各自的原因，选择了这个瀑布洞穴作为隐居之所。",al={"为什么住在湿地","湿地的危险","湿地的黑铁矮人"}},{q="这里传授的水的课程是什么？",a="水代表着重生，在纯净时可以切开岩石、洗净污垢、安抚疲惫。然而，如果受到腐蚀或污染，它会摧毁所触及的一切。",al={"水意味着什么","水的哲学","水的课程"}},{q="“水之召唤”任务的目的是什么？",a="“水之召唤”是萨满祭司的一项成人仪式，引导初学者理解水元素的本质，并从隐居的向导那里寻找水之萨普塔。",al={"这是什么类型的任务","这是为谁准备的任务","矮人萨满任务"}}},fp="13,172,19.234.0,25.277.0,25.191.0,24.183.0,37.114.0,49.167.0,40.130.0,47.114.0"}
P.entries["quest:94497"] = {n="水之召唤",s="“水之召唤”是在湿地进行的一项精神任务，指引修行者走上获取萨普塔的道路。通过在山间瀑布与海潮交汇的咸淡水入海口收集水源，寻求者在穿越沼泽的危险时，也能领悟到水的生命能量。",h="“水之召唤”是在湿地进行的一项精神任务，指引修行者走上获取萨普塔的道路。通过在山间瀑布与海潮交汇的咸淡水入海口收集水源，寻求者在穿越沼泽的危险时，也能领悟到水的生命能量。",kw={"水之召唤","黑铁矮人","入海口","赫瓦娜","萨普塔","水囊","湿地"},ang={["class:Shaman"]="寻求萨普塔需要理解不同土地上水的本质，使精神与水的各种表现形式相调和。",["race:Dwarf"]="赫瓦娜感叹着矮人氏族之间挥之不去的分裂，尤其是当黑铁矮人甚至入侵到湿地这样偏北的地方时。"},sec={{t="萨普塔之道",b="为了获得萨普塔并与灵魂沟通，修行者必须寻找各种形态的水。赫瓦娜指引寻求者观察水是如何流动、如何改变生命以及滋养大地。这段旅程始于理解入海口的水，那里是大海的潮汐与高地淡水径流汇合之处。"},{t="淡水与咸水交汇之处",b="在赫瓦娜洞穴下方的瀑布底部，高地泉水流入沼泽，与被海潮带入内陆的咸水相撞。海潮携带的沉积物、矿物质和能量与清澈的山间融雪截然不同，这使得入海口成为了自然智慧的源泉。"},{t="沼泽中的阴影",b="在湿地收集水源并非没有危险。除了危险的沼泽生物外，黑铁矮人也已经向北推进，进入了令人不安的距离。赫瓦娜怀着遗憾注视着矮人氏族之间持续不断的敌对状态，并感叹如果他们能放下世仇，矮人一族本可以取得多么伟大的成就。"}},faq={{q="什么是萨普塔？",a="萨普塔是一种用于与元素之灵沟通的神圣饮品。为了获得它，修行者必须寻找各种状态的水，并理解它如何塑造大地以及滋养万物。",al={"什么是萨普塔","萨普塔的含义","为何寻找萨普塔"}},{q="赫瓦娜是谁？",a="赫瓦娜在她位于湿地瀑布上方的洞穴中发布这项任务。她作为向导，指引修行者收集水样，以使他们与元素调和。",al={"谁发布水之召唤","赫瓦娜在哪里","赫瓦娜的洞穴"}},{q="为什么要收集淡水与咸水交汇处的水？",a="入海口的水代表了一种特殊的汇流，高地融雪和淡水泉水在此与海潮混合。这种淡水与富含矿物质的咸水的碰撞，携带了独特的沉积物和精神智慧。",al={"为何选择入海口的水","湿地的咸淡水","淡水与盐水的汇合"}},{q="瀑布附近潜伏着什么危险？",a="黑铁矮人已经潜入北方的湿地，对于试图进入沼泽和瀑布的旅行者和元素寻求者来说，他们构成了现实的威胁。",al={"湿地里的黑铁矮人","为什么黑铁矮人会在这里","黑铁矮人的威胁"}},{q="成为一名“容器”意味着什么？",a="“容器”是指已经开始积极寻求水的智慧，并携带大自然的水作为祭品，以发展更深层次元素调和的修行者。",al={"什么是容器","水的容器"}},{q="空的棕色水囊有什么用途？",a="空的棕色水囊是赫瓦娜提供的容器，用于从沼泽瀑布底部收集咸淡水样本。",al={"空的棕色水囊的使用方法","使用了什么水囊"}}},fp="13,176,20.273.0,26.308.0,20.248.0,18.191.0,16.149.0,52.128.0,38.136.0,37.126.0,43.116.0"}
P.entries["quest:94499"] = {n="水之召唤",s="“水之召唤”是一项任务，要求旅行者前往赤脊山的石堡瀑布，调查止水湖的流水是否存在污染。萨满祭司需要装满一个空的红色水囊并将其带回湿地的赫尔达娜·萨格伦德，从而揭示当地鱼人变异的真正原因，并为他们的精神试炼获得一种关键试剂。",h="“水之召唤”是一项任务，要求旅行者前往赤脊山的石堡瀑布，调查止水湖的流水是否存在污染。萨满祭司需要装满一个空的红色水囊并将其带回湿地的赫尔达娜·萨格伦德，从而揭示当地鱼人变异的真正原因，并为他们的精神试炼获得一种关键试剂...",kw={"水之召唤","赫尔达娜·萨格伦德","止水湖","夜行鱼人","赤脊山","药剂","暗影巫师","石堡瀑布","湿地"},ang={["class:Shaman"]="这项任务是酿造水之药剂的关键一步，在与水之灵沟通之前，考验萨满祭司跨越遥远水域的奉献精神和感知力。"},sec={{t="可疑的瀑布",b="位于湿地的赫尔达娜·萨格伦德派遣有志成为萨满祭司的冒险者前往赤脊山，调查从石堡瀑布倾泻而下的水流。虽然止水湖为湖畔镇的居民提供了纯净的水源，但潜伏在瀑布底部的鱼人却变得异常巨大且扭曲。赫尔达娜怀疑是毒素、邪恶法术或者上方古老堡垒的渗漏导致了这一切，因此要求旅行者用空的红色水囊采集样本。"},{t="污染的真正源头",b="在检查了装满的水囊后，赫尔达娜发现从止水湖倾泻而下的水完全干净，并未受到任何污染。当地夜行鱼人所表现出的身体扭曲并非由受到污染的水源引起，而是石堡周围潜伏的暗影巫师所施展的黑暗法术所致。该样本既证明了瀑布的纯净，也考验了萨满祭司的奉献精神，它是酿造精神药剂所必需的关键试剂。"}},faq={{q="谁发布了这个任务，他们位于何处？",a="位于湿地的赫尔达娜·萨格伦德发布了此项任务。她致力于研究水资源以及酿造萨满祭司精神试炼所需药剂的试剂。",al={"谁发布水之召唤","任务发布者赫尔达娜"}},{q="为什么会被派去从石堡瀑布采集水？",a="赫尔达娜怀疑奇怪的毒素、黑暗魔法或污染可能正从上方的旧堡垒渗透过石堡瀑布，导致瀑布底部的鱼人畸变。她需要一份新鲜的样本来进行检查。",al={"为什么要在赤脊山装满水囊","石堡瀑布的目的"}},{q="石堡瀑布的水真的受到污染了吗？",a="没有，水本身证明是完全纯净且未受污染的。赫尔达娜断定，当地鱼人的扭曲状态是源于当地暗影巫师施展的黑暗魔法，而不是因为受污染的径流。",al={"石堡的水是否受到污染","止水湖是否受到腐蚀"}},{q="为什么石堡瀑布周围的鱼人如此巨大且扭曲？",a="与洛克湖或湿地的鱼人相比，瀑布底部的夜行鱼人更为巨大且扭曲。赫尔达娜得出结论，这种变化是当地暗影巫师的邪恶魔法所导致的。",al={"为什么赤脊山的鱼人会变异","石堡鱼人的不同之处"}},{q="水样本是用来做什么的？",a="药剂是一种仪式性的混合物，能让萨满祭司穿透帷幕，感知元素之灵。赫尔达娜从各种水域收集纯净样本，以酿造你需要的那种试剂。",al={"什么是药剂","水之召唤奖励的用途"}},{q="诺瑞克是谁？",a="诺瑞克是参与萨满试炼的伙伴或导师，赫尔达娜提到他会对你成功取回纯净水样本感到满意。",al={"谁是诺瑞克","诺瑞克水之召唤"}}},fp="13,154,17.377.0,29.321.1,48.155.0,56.206.0,50.111.0,65.166.0,34.165.0,14.135.0"}
P.entries["quest:945"] = {n="护送瑟瑞露尼",s="在黑海岸南部，一位名叫瑟瑞露尼的年轻暗夜精灵误入了阴森的主宰之剑挖掘场，并被敌对的邪教徒包围。需要联盟护送她到安全地带，并将她幸存的消息告诉她担忧的姐姐瑟瑞希尔，她正在艾森娜神殿休息。",h="在黑海岸南部，一位名叫瑟瑞露尼的年轻暗夜精灵误入了阴森的主宰之剑挖掘场，并被敌对的邪教徒包围。需要联盟护送她到安全地带，并将她幸存的消息告诉她担忧的姐姐瑟瑞希尔，她正在艾森娜神殿休息。",kw={"灰谷","邪教徒","护送","主宰之剑","艾森娜神殿","瑟瑞露尼","瑟瑞希尔","暮光之锤"},ang={["faction:Alliance"]="帮助像瑟瑞露尼这样受困的旅人，能巩固联盟在保卫灰谷的暗夜精灵中的存在感和善意。",["race:NightElf"]="主宰之剑是卡利姆多历史上的一道古老伤疤。看到你的同胞卡多雷毫无防备地闯入邪教徒的挖掘场，是一个令人清醒的警示，提醒着灰谷内部潜伏的威胁。"},sec={{t="危险的漫步",b="主宰之剑是黑海岸最令人不安的地标之一，那里有一具被巨大的石刃贯穿的古代怪物的巨大头骨。尽管山谷中弥漫着恐惧，瑟瑞露尼还是误闯进了峡谷深处。她很快就被暮光之锤的邪教徒困住，仅凭敏捷的反应和在崎岖地形中隐藏的天赋才得以幸存。"},{t="送往神殿的消息",b="瑟瑞露尼的姐姐瑟瑞希尔住在遥远的南方，平静的艾森娜神殿。虽然瑟瑞露尼以爱冒险且不介意弄脏衣服而闻名，但她冒险进入主宰之剑那令人不适的挖掘场，这让她的亲人都感到震惊。带来瑟瑞露尼平安的消息可以宽慰她那深受困扰的姐姐，她深知目前正在黑海岸的古老土地上挖掘的黑暗势力。"}},faq={{q="瑟瑞露尼是谁？",a="瑟瑞露尼是一位爱冒险的年轻暗夜精灵，她误入了黑海岸南部主宰之剑危险的挖掘场。她是瑟瑞希尔的妹妹。",al={"瑟瑞露尼","这个女孩是谁","受困的精灵"}},{q="瑟瑞希尔是谁？",a="瑟瑞希尔是瑟瑞露尼的姐姐，驻扎在灰谷宁静的艾森娜神殿。得知她的妹妹竟然游荡到如此黑暗且被污染的地方附近，她感到非常不安。",al={"瑟瑞希尔","瑟瑞露尼的姐姐"}},{q="为什么主宰之剑如此危险？",a="主宰之剑是一处古老且不祥的峡谷，很久以前有一位古老的“古老领主”陨落于此。暮光之锤的邪教徒蜂拥至该区域，大肆挖掘遗迹并攻击任何入侵者。",al={"主宰之剑的危险","主宰之剑的邪教徒"}},{q="瑟瑞露尼需要被护送到哪里？",a="瑟瑞露尼需要护送以离开主宰之剑的直接包围圈前往安全地带，之后拯救者必须前往艾森娜神殿通知她的姐姐。",al={"护送目的地","瑟瑞露尼去哪了"}},{q="艾森娜神殿位于哪里？",a="艾森娜神殿位于灰谷西南部，阿斯特兰纳以西，是供奉森林之魂艾森娜的圣地。",al={"艾森娜神殿的位置","瑟瑞希尔在哪"}},{q="瑟瑞露尼在邪教徒的包围下是如何幸存的？",a="瑟瑞露尼能在周围的暮光之锤邪教徒发现她之前，找到岩石和地形间一个隐蔽的藏身处，从而得以避免被抓。",al={"瑟瑞露尼如何躲藏"}}},fp="18,189,17.304.0,18.371.0,17.159.0,16.156.0,40.167.0,41.143.0,39.130.0,49.129.0"}
P.entries["quest:94500"] = {n="Call of Water",s="水之召唤要求冒险者深入灰谷翠绿的树冠之下，从环抱阿斯特兰纳的湖泊中采集纯净而古老的水。这是最后一步采集任务，完成后，旅人便会被派回Norric那里。",h="水之召唤要求冒险者深入灰谷翠绿的树冠之下，从环抱阿斯特兰纳的湖泊中采集纯净而古老的水。这是最后一步采集任务，完成后，旅人便会被派回Norric那里。",kw={"灰谷","阿斯特兰纳","奥伯丁","水之召唤","米奈希尔","诺里克","南海镇","水囊"},ang={["faction:Alliance"]="这项任务引导旅行者沿着联盟的航海路线从东部王国前往卡利姆多，连接了米奈希尔港、奥伯丁以及暗夜精灵的定居点阿斯特兰纳。",["race:NightElf"]="这项任务指引旅人前往阿斯特兰纳周围的纯净水域，那里是卡多雷在灰谷的腹地之一，古老的废墟至今仍未受到侵扰。"},sec={{t="寻找纯净之水",b="水之召唤要求冒险者用灰谷未受污染的水装满水囊。寻水者必须前往阿斯特兰纳，这处庇护之所坐落在清澈而古老的湖水之间，湖水轻拍着往昔时代沉入水中的废墟。这份纯净的水样是任务给予者所需的最后一种液体，随后旅人便会被派往Norric那里。"},{t="通往阿斯特兰纳之路",b="要抵达灰谷深处，必须从东部王国渡海而行。建议旅人乘坐从米奈希尔港驶往奥伯丁的船只，途中会在南海镇停靠。从奥伯丁的码头出发，道路通向内陆，延伸至灰谷翠绿的枝叶之下，旅人被告诫要在林间窥伺的阴影中保持警惕。"}},faq={{q="水之召唤是什么任务？",a="水之召唤是一项要求旅人带着空水囊深入灰谷古老森林的任务。目标是从环抱阿斯特兰纳聚落的湖泊中，采集一份纯净、古老且可能蕴含魔力的水样，再将其交还给任务给予者。",al={"什么是水之召唤","水之召唤任务","水之召唤任务目标"}},{q="这项任务的水要在哪里采集？",a="必须从灰谷深处环绕阿斯特兰纳的湖泊中取水。那里的水依然未受污染，在往昔时代沉入水中的古老废墟间流淌。",al={"哪里有纯净之水","在哪里装满水囊","水之召唤地点"}},{q="如何前往灰谷完成这项任务？",a="建议旅行者从米奈希尔港搭乘船只前往奥伯丁，途中会在南海镇停留。从黑海岸的奥伯丁出发，向南前往灰谷深邃的翡翠森林，即可抵达阿斯特兰纳。",al={"如何前往阿斯特兰纳","前往灰谷","乘船前往阿斯特兰纳"}},{q="阿斯特兰纳的水有何特别之处？",a="环抱阿斯特兰纳的湖泊以水质未受污染而闻名。水面之下，沉没的石质废墟隐约诉说着精灵文明遥远的古老时代，也赋予这里的水纯净且可能蕴含魔力的特质。",al={"阿斯特兰纳的哪个湖泊","阿斯特兰纳水中废墟","阿斯特兰纳湖中废墟"}},{q="诺里克是谁？",a="采集完这最后一份液体样本后，等待旅人的便是诺里克。任务给予者将这份纯净的灰谷之水作为最后一种材料收下，随后便会派冒险者回到诺里克那里。",al={"诺里克是谁","返回诺里克处"}},{q="灰谷中有哪些危险？",a="灰谷是一片古老而茂密的森林，危机四伏。任务给予者告诫旅人时刻保持警惕，提醒他们在翠绿的树冠下行进时，林中有些眼睛始终注视着他们，从不眨眼。",al={"灰谷的危险","灰谷的威胁"}}},fp="13,126,25.233.0,21.285.0,32.174.0,44.137.0,44.197.0,42.188.0,14.146.0,42.147.0"}
P.entries["quest:94501"] = {n="Call of Water",s="“水之召唤”是萨满祭司追求神圣水之图腾仪式时的一场精神试炼。求道者需要将受Hervdana祝福的纯净水送到洛克莫丹的Norric Lochthane手中，以此准备与斯特登的池塘中的灵魂沟通所需的元素水之灵药。",h="“水之召唤”是萨满祭司追求神圣水之图腾仪式时的一场精神试炼。求道者需要将受Hervdana祝福的纯净水送到洛克莫丹的Norric Lochthane手中，以此准备与斯特登的池塘中的灵魂沟通所需的元素水之灵药。",kw={"水之召唤","赫芙达娜","洛克莫丹","月溪镇","诺里克·洛克塞恩","萨满祭司","斯特登的池塘","一瓶最纯净的水","水之灵契","水之图腾"},ang={["class:Shaman"]="这场试炼是与元素沟通以获得水之图腾仪式，并制作看见元素灵魂所需的水之灵药的关键一步。",["faction:Alliance"]="联盟萨满祭司跨越洛克莫丹和西部荒野，寻求与东部大地的水元素灵魂进行沟通。",["race:Dwarf"]="这段旅程将矮人萨满候选人与像Norric Lochthane这样遍布卡兹莫丹的元素导师连接了起来。"},sec={{t="通往水之图腾之路",b="“水之召唤”是渴望与水元素达成和谐的萨满祭司必须经历的精神感应试炼。踏上这条道路，需要收集由Hervdana亲自祝福的水，在将容器带给洛克莫丹的Norric Lochthane之前，以证明求道者对灵魂的耐心与敬畏。"},{t="水之灵药的诞生",b="在收到受祝福的容器后，Norric透露这些神圣的液体旨在酿造一种水之灵药。这种药水能让求道者洞穿虚妄，见到居住在月溪镇附近斯特登的池塘中的水元素灵魂。每一滴水都被视为珍宝，因为即使是湿润的塞子在神圣仪式中也大有用处。"}},faq={{q="谁是诺里克·洛克萨恩？",a="诺里克·洛克萨恩是一位居住在洛克莫丹的导师，他引导候选人完成元素感应。他负责监督获得水之图腾所需的准备工作和仪式。",al={"谁是诺里克","诺里克 洛克莫丹","谁是诺里克·洛克萨恩"}},{q="谁是赫芙达娜？",a="赫芙达娜·赛格伦德是湿地的向导，她与家人住在南部瀑布旁的一个洞穴里，她负责祝福求道者收集的神圣之水，使其拥有酿造水之灵药所需的精神纯度。",al={"谁是赫芙达娜","受赫芙达娜祝福","赫芙达娜的水"}},{q="水之灵药有什么用？",a="水之灵药是一种使用神圣之水调制而成的元素药水。饮用它能让萨满祭司洞穿面纱，感知到存在于天然水池中的隐秘水元素灵魂。",al={"什么是水之灵药","水之灵药的用途","水之灵药的作用"}},{q="斯特登的池塘在哪里？",a="斯特登的池塘位于西部荒野，靠近月溪镇。萨满祭司在饮用准备好的水之灵药后，必须前往那里寻找栖息在其中的水元素灵魂。",al={"斯特登的池塘在哪里","斯特登的池塘位置","斯特登的水元素灵魂"}},{q="为什么一瓶最纯净的水很重要？",a="一瓶最纯净的水中装有酿造水之灵药和进行获得水之图腾所需神圣仪式必不可少的受祝福之水。诺里克告诫说，即使一滴也不能浪费。",al={"为什么要纯净水","一瓶最纯净的水的用途"}},{q="什么是水之图腾仪式？",a="水之图腾仪式是萨满祭司为了与水元素达成共鸣而进行的精神试炼，通过这些仪式证明自己的尊重与平衡，从而获得水之图腾。",al={"什么是水之图腾仪式","如何获得水之图腾"}}},fp="13,168,27.150.0,18.228.1,24.159.0,16.165.0,25.123.0,32.133.0,42.162.0,31.137.0"}
P.entries["quest:94502"] = {n="水之召唤",s="水之召唤是一项元素任务，要求从洛克莫丹前往西部荒野，以恢复一处被腐蚀的泉水的平衡。通过净化斯特登的池塘中的受污染实体，并在遗忘的神龛处执行古老的仪式，请求者可以获得水之灵魂的青睐以及他们的水之图腾。",h="水之召唤是一项元素任务，要求从洛克莫丹前往西部荒野，以恢复一处被腐蚀的泉水的平衡。通过净化斯特登的池塘中的受污染实体，并在遗忘的神龛处执行古老的仪式，请求者可以获得水之灵魂的青睐以及他们的水之图腾。",kw={"水之召唤","洛克莫丹","月溪镇","诺里克","萨满","斯特登的池塘","水之图腾","西部荒野"},ang={["class:Shaman"]="这项试炼是与水之灵魂建立联系并获得水之图腾的关键仪式，展现了对元素力量的和谐与掌控。",["faction:Alliance"]="联盟的萨满必须穿越他们的领土，从洛克莫丹冒险进入动荡的西部荒野，以净化被腐蚀的水域。"},sec={{t="被暗影侵蚀的泉水",b="在月溪镇的阴影之下坐落着斯特登的池塘，这里曾经是一处清澈纯净的泉水。横扫西部荒野的黑暗影响已经玷污了它宁静的水域，迫使当地的水之灵魂陷入了沉寂。岸边矗立着一座古老的神龛，被尘土和蛛网覆盖，废弃已久，等待着有人来唤醒其中沉睡的力量。"},{t="净化仪式",b="位于洛克莫丹的诺里克会指引请求者完成恢复平衡所需的仪式。该仪式要求面对污染斯特登的池塘的邪恶实体，获取其护腕，并将它们与几滴炼金药水一起供奉在石制神龛上。当咒语被念出时，蒸气会召唤出一个被净化的灵魂，它将传授智慧，并证明携带者有资格获得水之图腾。"}},faq={{q="水之召唤是什么任务？",a="水之召唤是一项针对萨满的灵性试炼，旨在与水的元素进行沟通。该任务要求请求者净化西部荒野中斯特登的池塘的腐蚀，利用那里的古老神龛召唤一个被净化的水之灵魂，并获得他们的水之图腾。",al={"水之召唤是什么","水之图腾任务","西部荒野水之任务"}},{q="谁发布了这个任务？",a="该任务由洛克莫丹的导师诺里克发布。他指导请求者进行元素仪式，提供特殊的药水，并引导他们净化被腐蚀的元素水域。",al={"谁发布水之召唤","洛克莫丹 诺里克","任务发布者"}},{q="斯特登的池塘在哪里？",a="斯特登的池塘位于西部荒野西南部的月溪镇外。它曾经是一处纯净的泉水，但在黑暗、腐蚀力量的影响下，如今已变得死寂而浑浊。",al={"斯特登的池塘在哪里","斯特登的池塘位置","月溪镇附近的池塘"}},{q="如何净化斯特登的池塘的腐蚀？",a="要净化水域，你必须击败斯特登的池塘中的腐蚀存在，取走它的护腕，并将它们与剩余的药水一起放置在古老的神龛上，同时念诵诺里克传授的咒语。",al={"如何净化池塘","净化斯特登的池塘","神龛仪式"}},{q="完成此任务能获得什么奖励？",a="完成试炼并将净化的证明带回给洛克莫丹的诺里克，请求者将获得他们的水之图腾，从而获得对水之元素力量的掌控权。",al={"水之召唤有什么奖励","水之图腾奖励"}},{q="为什么斯特登的池塘会被腐蚀？",a="黑暗的来源尚不确定。池塘呈现出反常的停滞状态，周围散布着野兽的白骨，这引发了人们的担忧：它究竟是被西部荒野蔓延的苦难所毒害，还是其本身就是腐蚀的源头。",al={"为什么斯特登的池塘会被腐蚀","什么腐蚀了池塘"}}},fp="13,212,26.284.0,21.359.1,32.235.0,21.168.0,24.152.0,52.195.0,43.169.0,32.211.0"}
P.entries["quest:94503"] = {n="水之召唤",s="水之召唤是一个位于西部荒野的任务，要求冒险者净化受污染的元素力量。玩家通过用圣光驱散不安的灵魂，与水之魂进行沟通，以守护该地区日渐衰弱的生命力。",h="水之召唤是一个位于西部荒野的任务，要求冒险者净化受污染的元素力量。玩家通过用圣光驱散不安的灵魂，与水之魂进行沟通，以守护该地区日渐衰弱的生命力。",kw={"水之召唤","净化","腐蚀","元素","水之魂","水之灵魂","西部荒野"},ang={["class:Shaman"]="与原始元素沟通并净化受污染的水之灵魂是元素的基本仪式，提醒萨满他们平衡自然的永恒职责。",["faction:Alliance"]="该显现居住在西部荒野，这是一个联盟领土，当地的灵魂正承受着侵蚀这片土地的蔓延枯萎。"},sec={{t="净化受污染的水域",b="在西部荒野那片饱受风霜的土地上，自然的水之平衡正面临着受腐蚀灵魂的侵害。被称为水之召唤的仪式需要面对这些邪恶，诵读圣言唤出耀眼的光芒，将这些躁动、污秽的本质驱散为无害的灰烬与平静的薄雾。"},{t="灵魂的警告",b="随着腐蚀实体被击退，水之魂可以安全地现身进行沟通。虽然眼前的腐蚀已有所减退，但灵魂警告说，这片土地的生命能量仍在不断衰弱，提醒勇士们守护生命是一场永无止境的守望。"}},faq={{q="水之召唤是什么？",a="水之召唤是西部荒野的一场灵魂试炼，通过爆发圣光的仪式驱逐腐蚀的灵魂，净化受困的水域，并允许玩家与水之魂沟通。",al={"什么是 水之召唤","水之召唤 西部荒野","西部荒野水任务"}},{q="水之魂在哪里可以找到？",a="水之魂位于西部荒野。它会在周围的腐蚀灵魂被镇压并驱散后出现，等待与那些帮助过水域的人交谈。",al={"水之魂在哪里","显现位置","西部荒野水之灵魂"}},{q="净化腐蚀的灵魂后会发生什么？",a="随着咒语的结束，耀眼的光芒爆发并驱散了腐蚀的灵魂，使它们污秽的本质瓦解并如灰烬般消散，而水流则嘶嘶作响，化作柔和的薄雾。",al={"仪式期间发生了什么","水之召唤 腐蚀灵魂"}},{q="完成任务后，这片土地完全恢复了吗？",a="眼前的腐蚀已被击退并逐渐消退，但元素警告说生命力仍在衰弱，守护生命的重任仍落在凡人手中。",al={"腐蚀消失了吗","我们拯救了水域吗"}},{q="谁被召唤来协助这一显现？",a="该任务认可了玩家的使命，感谢他们的职业挺身而出，净化灵魂并肩负起保护衰弱生命的责任。",al={"谁能执行 水之召唤","水任务职业要求"}},{q="为什么西部荒野的水之灵魂会被腐蚀？",a="腐蚀的灵魂扰乱了西部荒野沿岸的自然水域。虽然这种污染的确切起源尚不明确，但它们恶意的存在直接汲取了该地区的生命活力。",al={"为什么西部荒野的水被腐蚀了","西部荒野水的问题"}}},fp="13,113,28.166.0,20.184.0,22.203.0,52.163.0,53.149.0,53.155.0,47.147.0,49.153.0"}
P.entries["quest:94505"] = {n="水之召唤",s="水之召唤是一项元素试炼，萨满祭司通过它学会与水之灵交流并运用其恢复力量。通过从西部荒野为洛克莫丹的诺里克·洛克萨恩取回水灵碎片，试炼者证明了自己的奉献精神并获得了他们的水之图腾。",h="水之召唤是一项元素试炼，萨满祭司通过它学会与水之灵交流并运用其恢复力量。通过从西部荒野为洛克莫丹的诺里克·洛克萨恩取回水灵碎片，试炼者证明了自己的奉献精神并获得了他们的水之图腾。",kw={"水之召唤","洛克莫丹","诺里克·洛克萨恩","萨满祭司","水灵碎片","水之图腾","西部荒野"},ang={["class:Shaman"]="这项试炼标志着一个基本的通过仪式，赋予萨满祭司与水之灵的交流能力以及用于治愈和维持生命的水之图腾。",["faction:Alliance"]="与卡利姆多的部落萨满祭司不同，联盟的试炼者向洛克莫丹的诺里克·洛克萨恩之类的导师汇报，并面对像西部荒野这样的地方的试炼。"},sec={{t="水之道",b="水之召唤是萨满祭司为了与水元素建立联系而进行的一项至关重要的精神试炼。试炼者被派往西部荒野，并将水灵碎片带回洛克莫丹交给诺里克·洛克萨恩。通过展现他们对水之生命本质及其在净化腐蚀中作用的理解，萨满祭司赢得了他们的水之图腾，并迈出了元素旅程中重要的一步。"},{t="生命赋予者",b="这项试炼传授了一条基础的元素真理：水即生命，而腐蚀则终结生命。萨满祭司肩负着运用水的恢复力量来保护弱小和维持生命的使命。正如导师诺里克·洛克萨恩在收到水灵碎片时所观察到的，水的纯净馈赠远不止简单的肉体修复，还触及了耐力、复苏和精神平衡。"}},faq={{q="诺里克·洛克萨恩是谁？",a="诺里克·洛克萨恩是一位驻守在洛克莫丹的萨满祭司导师。他引导试炼者通过试炼以了解水之灵，通过前往西部荒野的旅程考验他们的决心，并在他们交出交流证明时为他们颁发水之图腾。",al={"诺里克·洛克萨恩是谁","谁给予水之图腾","诺里克 洛克莫丹"}},{q="什么是水灵碎片？",a="水灵碎片是证明试炼者已从西部荒野归来交给洛克莫丹诺里克·洛克萨恩的实物凭证。它标志着试炼者已经与水进行了交流，掌握了其赋予生命的本质，并学会了对抗腐蚀。",al={"什么是水灵碎片","水灵碎片的用途","水灵碎片任务物品"}},{q="为什么试炼会前往西部荒野？",a="试炼者被派往西部荒野是为了理解水赋予生命的力量以及腐蚀是如何威胁它的。即使在那个动荡之地取得的微小胜利，对于证明试炼者保护生命的能力来说也具有重要的意义。",al={"为什么要去西部荒野","西部荒野水任务","前往西部荒野 水之召唤"}},{q="水之图腾的意义是什么？",a="水之图腾体现了萨满祭司与水元素的联系。虽然它主要以通过净水来抚慰和治愈伤口而闻名，但其精神馈赠远超基础的治疗，涵盖了保存与活力。",al={"水之图腾有什么作用","萨满祭司为什么需要水之图腾","水之图腾背景"}},{q="这项试炼关于水传授了什么课程？",a="试炼期间教授的元素哲学强调水赋予生命，而腐蚀则会阻碍生命。萨满祭司肩负着用水的元素力量在任何腐蚀威胁生命的地方进行滋养、保护和恢复平衡的使命。",al={"什么是水即生命","水之召唤哲学","萨满祭司水之教导"}},{q="完成水之召唤后会发生什么？",a="诺里克·洛克萨恩指出，萨满祭司的下一个元素试炼不会立刻到来。他鼓励萨满祭司花时间练习并探索水更深层的奥秘，然后再进行进一步的试炼。",al={"接下来是什么试炼","下一个萨满祭司试炼","水之召唤之后发生什么"}}},fp="13,163,17.305.0,13.267.0,24.236.0,27.193.0,36.173.0,44.145.0,45.201.0,46.170.0"}
P.entries["quest:94532"] = {n="Gnoll Infestation",s="洛格玛的 Neza Bloodsnout 请你驱赶西南丘陵中的豺狼人。他们的存在扰乱了贸易和旅途，但暮光势力的侵袭已使他们的数量减少。",h="洛格玛的 Neza Bloodsnout 请你驱赶西南丘陵中的豺狼人。他们的存在扰乱了贸易和旅途，但暮光势力的侵袭已使他们的数量减少。",kw={"蛮兵","豺狼人肆虐","豺狼人","神秘者","neza bloodsnout","赤脊山","洛格玛","设陷者","暮光"},sec={{t="丘陵中的豺狼人",b="暮光势力侵袭后，赤脊山的豺狼人数量虽已减少，仍在洛格玛西南的丘陵中为患。Neza Bloodsnout 请你清除这项威胁，为盟友扫清道路。豺狼人盘踞期间，贸易和旅人仍会受到阻碍。"}},faq={{q="豺狼人为何是个麻烦？",a="洛格玛西南丘陵中的豺狼人扰乱贸易，也给旅人带来麻烦。",al={"豺狼人扰乱贸易","为何清除豺狼人","豺狼人威胁"}},{q="豺狼人在哪里？",a="他们盘踞在西南方的丘陵中。",al={"豺狼人丘陵","赤脊山豺狼人在哪里"}},{q="谁让我去对付他们？",a="洛格玛的 Neza Bloodsnout 请你消除豺狼人的威胁。",al={"谁发布了豺狼人肆虐任务","neza 任务"}},{q="豺狼人的数量减少了吗？",a="是的。暮光势力侵袭后，他们的数量减少了，但威胁依然存在。",al={"豺狼人数量","暮光豺狼人"}},{q="有哪些豺狼人？",a="提到的豺狼人有 Redridge Mystics、Redridge Trappers 和 Redridge Brutes。",al={"豺狼人种类","神秘者、设陷者、蛮兵"}}},fp="17,187,19.268.0,29.81.0,21.39.0,30.63.0,27.86.0,31.78.0"}
P.entries["quest:94533"] = {n="Snargl's Snout",s="Neza Bloodsnout想把Snargl的鼻子当作战利品。年长的豺狼人发出的刺耳声响，困扰着刺毛丘陵的盟友和侦察兵。",h="Neza Bloodsnout想把Snargl的鼻子当作战利品。年长的豺狼人发出的刺耳声响，困扰着刺毛丘陵的盟友和侦察兵。",kw={"刺毛丘陵","豺狼人","neza bloodsnout","snargl","snargl的鼻子","鼻子","战利品"},sec={{t="送给Neza的战利品",b="Neza Bloodsnout想为收藏品添一件纪念品，而她点名要的是Snargl。你被派往刺毛丘陵取回他的鼻子。Neza希望你动作迅速；进入那片区域的盟友和侦察兵都受到Snargl的声响困扰。"}},faq={{q="Snargl是谁？",a="Snargl是Neza Bloodsnout西南方刺毛丘陵的一名年长豺狼人。",al={"snargl","snargl 豺狼人","年长豺狼人"}},{q="Neza为什么想要Snargl的鼻子？",a="Neza想把Snargl的鼻子作为纪念品，收入她的战利品收藏。",al={"为什么要鼻子","snargl 战利品","neza 收藏"}},{q="Snargl在哪里？",a="Snargl在Neza Bloodsnout西南方的刺毛丘陵。",al={"snargl 位置","snargl 在哪里","刺毛丘陵 豺狼人"}},{q="Snargl带来了什么麻烦？",a="Snargl发出的刺耳声响会困扰进入刺毛丘陵的盟友和侦察兵。",al={"snargl 声响","侦察兵为什么受困扰","豺狼人噪声"}},{q="你回来时Neza会说什么？",a="Neza会说这件战利品比她预想的更重，并欢迎它加入收藏。",al={"snargl 任务完成","neza 反应","鼻子交付"}}},fp="14,133,17.247.0,14.75.0,34.63.0,16.61.0,31.90.0,35.95.0"}
P.entries["quest:94535"] = {n="Bristle Hills Bandits",s="Kreza Darkthorn派你前往刺毛丘陵，那里有豺狼人袭击了盟友矿工。你需要从他们的营地夺回被盗的矿石。",h="Kreza Darkthorn派你前往刺毛丘陵，那里有豺狼人袭击了盟友矿工。你需要从他们的营地夺回被盗的矿石。",kw={"盟友矿工","强盗","刺毛丘陵","豺狼人","kreza darkthorn","被盗的矿石"},sec={{t="丘陵中的矿石",b="盟友矿工报告称，Kreza Darkthorn以南的丘陵中发生了豺狼人袭击。你需要找到刺毛丘陵中的营地，夺回被盗的矿石。矿工们的损失尚待挽回。"},{t="夺回矿石之后",b="Kreza Darkthorn说矿石已经夺回，火焰会抹去留下的任何痕迹或气味。"}},faq={{q="是谁派我去追回被盗的矿石？",a="Kreza Darkthorn让你追回从盟友矿工那里偷走的矿石。",al={"kreza是谁","交付矿石的人"}},{q="强盗在哪里？",a="豺狼人的营地位于刺毛丘陵，在Kreza Darkthorn以南。",al={"豺狼人营地","强盗在哪里"}},{q="是谁偷走了矿石？",a="刺毛丘陵中的豺狼人袭击了盟友矿工，并抢走了他们的矿石。",al={"偷矿石的人","是谁拿走的"}},{q="矿工们遭遇了什么？",a="在南部丘陵工作的盟友矿工报告称，他们遭到豺狼人多次袭击。",al={"矿工遭袭","为何偷矿石"}}},fp="21,139,18.187.0,18.98.1,34.70.0,22.71.0,18.70.0,28.83.0"}
P.entries["quest:94556"] = {n="Jom-jom's Escape",s="Jom-jom想回家，请你护送他去Bolder'ok找Clugfist。",h="Jom-jom想回家，请你护送他去Bolder'ok找Clugfist。",kw={"bolder'ok","clugfist","护送","朋友","家","jom-jom"},sec={{t="回家的路",b="Jom-jom踏上了寻找朋友的旅程。现在，他需要你带他去Bolder'ok找Clugfist，这样他就能回家了。"}},faq={{q="Jom-jom是谁",a="Jom-jom来这里寻找一位朋友，如今想回家。",al={"jom-jom是谁","jom-jom"}},{q="Jom-jom想去哪里",a="Jom-jom想回家，有人请你护送他去Bolder'ok找Clugfist。",al={"jom-jom要去哪里","jom-jom回家"}},{q="Clugfist是谁",a="Jom-jom要在Bolder'ok去找Clugfist。",al={"clugfist","clugfist是谁"}},{q="Jom-jom为什么来这里",a="Jom-jom来这里寻找一位朋友。",al={"jom-jom为何在这里","jom-jom来了"}},{q="Jom-jom把你当朋友吗",a="你救下Jom-jom后，他称你为朋友。",al={"jom-jom的朋友","小家伙"}}},fp="16,81,12.107.0,15.59.0,30.87.0,16.62.0,26.34.0,35.47.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="《The Cult's True Plans》讲述了一位邪教叛逃者不幸身亡后的余波。随着线人死亡且其秘密丢失，调查人员必须咨询Talaanis 影歌，以制定对抗该邪教的新策略。",h="《The Cult's True Plans》讲述了一位邪教叛逃者不幸身亡后的余波。随着线人死亡且其秘密丢失，调查人员必须咨询Talaanis 影歌，以制定对抗该邪教的新策略。",kw={"邪教","叛逃者","维和人员","塔拉尼斯·影歌","教派的真正计划","变节者"},sec={{t="被噤声的叛逃者",b="一名内部人员因对邪教日益临近的阴谋感到恐惧而选择叛逃，希望能寻求外界的帮助。不幸的是，这名叛逃者在分享他所知的信息之前就被杀害了，留下了不详的警告，但关于邪教打算释放什么却没有任何具体细节。"},{t="重新思考应对方案",b="随着主要线人身亡，领导层必须咨询Talaanis Shadowsong以重新评估他们的策略。让维和人员与邪教进行正面交锋被认为是一场必败之战，这迫使那些调查威胁的人寻找另一条前进的道路。"}},faq={{q="在这个任务中提到的变节者是谁？",a="一名邪教叛逃者因对邪教正在策划的事情感到恐惧而寻求援助。不幸的是，他在透露其阴谋细节之前就被杀害了，将宝贵的情报带进了坟墓。",al={"在《教派的真正计划》中谁死了","死去的变节者是谁","变节者的邪教秘密"}},{q="塔拉尼斯·影歌是谁？",a="塔拉尼斯·影歌是在线人突然死亡后，商讨如何应对邪教的关键联络人。你见证了与塔拉尼斯进行的一次战略性谈话，以确定下一步的行动方针。",al={"塔拉尼斯·影歌的角色","塔拉尼斯·影歌是谁","与塔拉尼斯交谈"}},{q="为什么维和人员不能直接攻击邪教？",a="将维和人员直接部署到与邪教势力的正面战斗中被认为风险太大，因为维和人员在正面冲突中表现预计不会很好。因此需要一种更巧妙或替代的策略。",al={"为什么不与邪教战斗","维和人员对阵邪教","直接袭击邪教"}},{q="邪教的真正计划是什么？",a="由于线人在分享他所知信息之前就已死亡，邪教计划的具体性质仍然笼罩在迷雾中。无论他们的目标是什么，其恐怖程度足以让一名成员绝望地选择叛逃。",al={"邪教在策划什么","邪教阴谋","《教派的真正计划》的含义"}},{q="与塔拉尼斯交谈后的下一步是什么？",a="在意识到正面战斗行不通且主要情报来源已死之后，领导层必须设计一种替代方法来揭露并挫败邪教的阴谋。",al={"《教派的真正计划》之后会发生什么","邪教任务的后续步骤"}},{q="在《邪教的真正计划》中发生了什么？",a="你与塔拉尼斯·影歌交谈并观察了一场关于局势的商议。讨论的中心是线人死亡后的余波，并评估为何不能依靠正规军事力量来阻止该邪教。",al={"《教派的真正计划》任务概要","你在《教派的真正计划》中做什么"}}},fp="21,139,19.170.0,23.268.1,45.146.0,27.161.0,55.145.0,33.163.0,51.142.0,42.178.0"}
P.entries["quest:94613"] = {n="My Kingdom for a Horse",s="附近的一座农场丢失了马匹，导致 Farholde 在对抗部落的战役中没有骑兵。你被派往 Wheeler’s Grange 与 Benjy 谈谈。",h="附近的一座农场丢失了马匹，导致 Farholde 在对抗部落的战役中没有骑兵。你被派往 Wheeler’s Grange 与 Benjy 谈谈。",kw={"benjy","部落","失踪的马匹","我愿以王国换一匹马","farholde 骑兵","战马","wheeler’s grange"},sec={{t="失踪的马匹",b="Farholde 的战马来自附近的两座农场，但 Wheeler’s Grange 的马匹全都不见了。原因尚不清楚，而没有马匹，Farholde 就没有骑兵参加对抗部落的战役。你被派去农场与 Benjy 谈谈，了解他的说法。"}},faq={{q="Farholde 为什么需要这些马？",a="Farholde 依靠战马组建骑兵，并认为骑兵是对抗部落的战役所必需的。",al={"为何需要马匹","需要战马","farholde 骑兵"}},{q="Wheeler’s Grange的马匹出了什么事？",a="Wheeler家所有的马匹都不见了，原因尚不清楚。",al={"失踪的马匹","马匹去了哪里","wheeler家的马"}},{q="Benjy是谁？",a="Benjy在Wheeler’s Grange，你被派去向他打听失踪的马匹。",al={"benjy","wheeler’s grange的人","该找谁交谈"}},{q="Farholde 的战马存放在哪里？",a="Farholde 的战马来自附近的两座农场。其中一座是 Wheeler 家族拥有的 Wheeler’s Grange。",al={"养马农场","马匹来自哪里","战马农场"}}},fp="22,159,17.278.0,34.110.0,50.73.0,13.83.0,38.107.0"}
P.entries["quest:94614"] = {n="Freshwater Fiends",s="Wheeler's Grange附近的一位农夫请你赶走河里的Mudfin鱼人。它们威胁着他的牲畜和野生动物，还占据了他最喜欢的钓鱼地点。",h="Wheeler's Grange附近的一位农夫请你赶走河里的Mudfin鱼人。它们威胁着他的牲畜和野生动物，还占据了他最喜欢的钓鱼地点。",kw={"钓鱼地点","freshwater fiends","mudfin","鱼人","神谕","河林","战士","wheeler's grange"},sec={{t="河畔",b="Mudfin鱼人留在Wheeler's Grange附近的河边，农夫的牲畜和当地野生动物因此受苦。它们还占据了农夫最喜欢的钓鱼地点。农夫请你杀死一些鱼人，河林居民也会欢迎你的帮助。"}},faq={{q="农夫为什么想赶走鱼人？",a="农夫说，Mudfin鱼人会危害他的牲畜和野生动物，还占据了他最喜欢的钓鱼地点。",al={"为何击杀鱼人","河边的鱼人"}},{q="Mudfin鱼人在哪里？",a="它们在Wheeler's Grange附近的河边。",al={"mudfin位置","鱼人在哪里"}},{q="涉及哪些鱼人？",a="农夫提到了Mudfin Oracles和Mudfin Warriors。",al={"mudfin类型","哪些鱼人"}},{q="农夫要我做什么？",a="他请你在Wheeler's Grange附近的河边杀死八个Mudfin Oracles和八个Mudfin Warriors。",al={"freshwater fiends任务","要杀多少鱼人"}},{q="谁会感激这份帮助？",a="农夫说，清除一些鱼人会让河林居民感激不尽。",al={"谁想赶走鱼人","河林居民"}}},fp="17,166,12.269.0,42.123.0,29.47.0,27.52.0,34.105.0,30.89.0"}
P.entries["quest:94615"] = {n="Foal Play",s="在 Wheeler's Grange，马厩里的马匹不见了。你四处寻找线索，想查明发生了什么。",h="在 Wheeler's Grange，马厩里的马匹不见了。你四处寻找线索，想查明发生了什么。",kw={"土狼","farholde","小马嬉戏","马匹","失踪的马匹","鱼人","马厩","wheeler's grange"},sec={{t="在庄园搜寻",b="Wheeler's Grange 的马厩或许藏有马匹失踪的线索。马夫说，他起床准备喂马时，马匹就已经不见了。Farholde 郊外的野兽、鱼人、兽人或其他危险都可能是罪魁祸首。你在马厩附近搜寻，试图缩小调查范围。"}},faq={{q="马匹去了哪里？",a="马匹从 Wheeler's Grange 消失了，你在马厩附近寻找它们去向的证据。",al={"失踪的马匹","马匹不见了","马匹去向"}},{q="什么东西可能带走了马匹？",a="马夫认为，Farholde 郊外的野兽、鱼人、兽人或其他危险都可能是罪魁祸首。",al={"谁带走了马匹","马匹失踪的罪魁祸首","是什么带走了它们"}},{q="马匹为何如此重要？",a="马匹是马夫赖以谋生的本钱。",al={"马匹为何重要","马匹谋生","马匹生意"}},{q="我该去哪里找线索？",a="在 Wheeler's Grange 的马厩附近搜寻，寻找与失踪马匹有关的证据。",al={"马厩线索","搜寻地点","小马嬉戏"}}},fp="9,116,22.266.0,24.110.0,33.100.0,29.47.0,30.82.0"}
P.entries["quest:94616"] = {n="水之灵契",s="“水之萨普塔”是一种仪式性的药剂，用于使人的灵魂视觉能够感知到水中隐藏的灵魂和腐化。持有此药剂的人会被派往西部荒野的田野中，寻找被污染的池塘水，以调查元素失衡的情况。",h="“水之萨普塔”是一种仪式性的药剂，用于使人的灵魂视觉能够感知到水中隐藏的灵魂和腐化。持有此药剂的人会被派往西部荒野的田野中，寻找被污染的池塘水，以调查元素失衡的情况。",kw={"元素协调","萨普塔","萨满试炼","被污染的池塘","水之灵契","水之灵魂","西部荒野"},ang={["class:Shaman"]="萨普塔是一种炼金或仪式药剂，被萨满用来调整他们的灵魂感官，以感知那些在普通视觉下无法看见的元素灵魂。",["faction:Alliance"]="调查西部荒野内被腐蚀的水域，将元素净化仪式带到了联盟领地的中心。"},sec={{t="水之视觉",b="在萨满的元素传统中，萨普塔是一种专门调制出的仪式药剂，用来穿透物质领域与灵魂领域之间的面纱。“水之萨普塔”专门将使用者的感官与水元素协调一致，从而赋予他们感知元素扰动和隐形灵魂所需的灵视能力。如果没有这种协调，普通的旅行者即使直视元素显现，也只能看到寻常的涟漪。"},{t="西部荒野的扰动",b="使用“水之萨普塔”的指令会将持有者指引至西部荒野。这片饱受动乱和荒废之苦的联盟土地上，有一处池塘的水遭到了灵魂层面的污染。在萨普塔赋予的感知的引导下，持有者必须找出这些被污染的水域，揭开其中的扰动，并恢复当地水之灵魂的和谐。"}},faq={{q="什么是水之萨普塔？",a="水之萨普塔是为萨满与元素沟通而特制的精神药剂。饮用或使用萨普塔可以暂时开启使用者的感知，使其能看到凡人肉眼无法察觉的元素实体和灵魂失衡。",al={"什么是水之萨普塔","水之萨普塔的目的","水之萨普塔的作用"}},{q="西部荒野的被污染池塘在哪里？",a="被污染的池塘水位于西部荒野境内。萨满们会被指引前往那里，手持水之萨普塔寻找受腐蚀的水源，并解决该地区内滋生的任何灵魂扰动。",al={"被污染的池塘在哪","西部荒野被污染的池塘","被污染的池塘位置"}},{q="为什么水之萨普塔会指引去西部荒野？",a="即使是在像西部荒野这样以农业为主、遭受旱灾的人类土地上，元素之水也可能遭受污染或邪恶腐化的侵袭。任务要求你寻找被污染的池塘水，以调查并恢复当地不安灵魂的平衡。",al={"为什么要去西部荒野","西部荒野水体腐化","为什么西部荒野的水会被污染"}},{q="谁会使用水之萨普塔？",a="水之萨普塔被授予正在接受元素沟通试炼的萨满。通过服用萨普塔，修行者会将他们的感官与水之灵魂协调，从而使其能够感知到隐藏的元素生物或检查被污染的水池。",al={"谁喝水之萨普塔","谁使用水之萨普塔","萨满饮用萨普塔"}},{q="当你带着萨普塔来到被污染的池塘时会发生什么？",a="在西部荒野的被污染池塘附近使用水之萨普塔后，你将获得元素视觉，从而显现出水的灵魂状态，或是召唤出与当地水之试炼相关的隐藏灵魂。",al={"使用萨普塔后会发生什么","萨普塔元素视觉"}},{q="元素萨普塔在萨满传统中是如何运作的？",a="萨普塔将大地的试剂与元素的祝福结合成一种仪式性的药剂。萨满在试炼中依靠它们来与特定的元素——土、火、水或气——达成协调，从而跨越物质世界与灵魂领域之间的鸿沟。",al={"萨普塔如何运作","萨普塔背景知识"}}},fp="11,183,23.267.0,23.267.0,22.127.0,38.138.0,42.163.0,25.180.0,58.170.0,51.171.0"}
P.entries["quest:94617"] = {n="Coyote Huntin'",s="Benjy Wheeler请你解决河西边的郊狼群，它们的首领Sootfur毛色深黑。鱼人把郊狼赶离了惯常的捕鱼地，它们因此开始吃马。",h="Benjy Wheeler请你解决河西边的郊狼群，它们的首领Sootfur毛色深黑。鱼人把郊狼赶离了惯常的捕鱼地，它们因此开始吃马。",kw={"benjy wheeler","郊狼","巢穴","马匹","鱼人","毛皮","sootfur","马厩"},sec={{t="马匹受到威胁",b="Benjy Wheeler说，郊狼曾在岸边捕食鱼类，但鱼人把它们赶离了那片觅食地。如今，郊狼群开始吃马。它们的首领是一只体型较大、毛色深黑的郊狼，名叫Sootfur。Benjy请你带回Sootfur的毛皮，希望其余郊狼会就此散去。"},{t="Benjy的马厩",b="你带着Sootfur的毛皮回来时，Benjy说那只郊狼一直在他的马厩附近翻找。他向你道谢，并说马厩重新运转后，马匹应该就安全了。"}},faq={{q="Sootfur是谁？",a="Sootfur是河西边郊狼群的首领，是一只体型较大、毛色深黑的郊狼。",al={"sootfur","深毛色郊狼","郊狼首领"}},{q="郊狼为什么吃马？",a="鱼人把郊狼赶离了岸边惯常的捕鱼地，所以它们开始吃马。",al={"为何吃马","郊狼吃马","郊狼食物"}},{q="谁要Sootfur的毛皮？",a="Benjy Wheeler请你把Sootfur的毛皮带给他。",al={"benjy","benjy是谁","sootfur的毛皮"}},{q="郊狼巢穴在哪里？",a="郊狼群住在Benjy所在位置以西、河对岸的一处巢穴里。",al={"郊狼巢穴","郊狼在哪里","巢穴位置"}}},fp="14,202,22.300.0,15.190.1,15.79.0,34.109.0,28.51.0,24.67.0"}
P.entries["quest:94618"] = {n="Wheeler's Fleeing Steeds",s="Benjy请你找回一匹马。它在郊狼袭击后逃离了Wheeler's Grange。喂它一些饲料，让它信任你，再牵它回去。",h="Benjy请你找回一匹马。它在郊狼袭击后逃离了Wheeler's Grange。喂它一些饲料，让它信任你，再牵它回去。",kw={"benjy","郊狼","饲料","逃跑的马","马","wheeler's fleeing steeds","wheeler's grange"},sec={{t="逃离庄园",b="Wheeler's Grange的Benjy需要你帮忙，寻找一匹在郊狼袭击后逃跑的马。郊狼叼走了几匹马，其他马则因害怕而逃散。给一匹马喂些饲料，让它信任你，再牵它回去。"}},faq={{q="马匹遭遇了什么？",a="郊狼叼走了大部分马匹，还有一些马因害怕而逃离了Wheeler's Grange。",al={"wheeler's grange的马","遭郊狼袭击的马"}},{q="是谁在求助？",a="Benjy请你找回一匹逃离Wheeler's Grange的马。",al={"是谁给我的","benjy的马"}},{q="这些饲料该怎么用？",a="给一匹马喂些饲料，让它信任你，这样你就能牵它回去。",al={"怎么使用袋子","喂马"}},{q="为什么要寻找这些马？",a="Benjy说，得在郊狼回来之前找到逃跑的马。",al={"为何寻找马匹","它们去了哪里"}}},fp="24,127,20.231.0,28.78.0,23.58.0,31.70.0,32.72.0"}
P.entries["quest:94638"] = {n="Strength and Mercy",s="Ur'endra陷入疯狂，迷失了自我，她的伴侣请求你结束她的痛苦。你的决心为你赢得了一份祝福，让你能化为他同族的形态。",h="Ur'endra陷入疯狂，迷失了自我，她的伴侣请求你结束她的痛苦。你的决心为你赢得了一份祝福，让你能化为他同族的形态。",kw={"德鲁伊祝福","阵风浆果低地","shape of the claw","申达尔高地","strength and mercy","ur'endra","风之魔法"},ang={["class:Druid"]="身为德鲁伊，你需要先证明自己的决心，才能获得化为那位德鲁伊同族形态的祝福。"},sec={{t="沉重的恳求",b="一位德鲁伊请求你结束申达尔高地的Ur'endra的痛苦。她是他的伴侣，但疯狂让她开始攻击自己的同族。风之魔法的消失让许多生灵迷失了自我，Ur'endra也是其中之一。她的巢穴位于此地以西的一个洞穴中，就在申达尔高地与阵风浆果低地之间的峭壁上。"},{t="祝福",b="在申达尔高地，Ur'endra的伴侣为失去她而悲伤，却也认为这是维持平衡所必需的。他看到了你接受如此惨痛代价的决心。他赐予你一份祝福，让你能化为他同族的形态，并嘱咐你扶助弱者，保护需要帮助的人。"}},faq={{q="Ur'endra是谁？",a="Ur'endra是那位请求你结束她痛苦的德鲁伊的伴侣。",al={"ur'endra","urendra是谁","德鲁伊的伴侣"}},{q="Ur'endra为什么攻击自己的同族？",a="Ur'endra陷入疯狂，迷失了自我。风之魔法的消失让许多生灵迷失了自我。",al={"urendra为何疯狂","urendra攻击","urendra怎么了"}},{q="Ur'endra的巢穴在哪里？",a="Ur'endra的巢穴位于那位德鲁伊以西的一个洞穴中，就在申达尔高地与阵风浆果低地之间的峭壁上。",al={"urendra洞穴","urendra在哪里","shen'dar洞穴"}},{q="那位德鲁伊要我做什么？",a="那位德鲁伊请求你结束Ur'endra的痛苦。",al={"urendra任务","要做什么","杀死urendra"}},{q="那位德鲁伊赐予什么祝福？",a="那位德鲁伊赐予你一份祝福，让你能化为他同族的形态。",al={"形态祝福","way of the claw","德鲁伊祝福"}},{q="那位德鲁伊为什么提出这个请求？",a="那位德鲁伊认为，结束Ur'endra的痛苦是维持平衡所必需的。",al={"为何杀死urendra","为何必须如此","平衡"}}},fp="18,141,12.353.0,12.293.1,16.68.0,34.112.0,25.125.0,33.47.0,35.72.0,32.74.0"}
P.entries["quest:94668"] = {n="Bloodmaster's Ring",s="在Bloodmaster's Ring，你击败暮光食人魔证明了自己，随后向Jezap报告。Bloodmaster已准备好判断你是否够格。",h="在Bloodmaster's Ring，你击败暮光食人魔证明了自己，随后向Jezap报告。Bloodmaster已准备好判断你是否够格。",kw={"bloodmaster","bloodmaster's ring","地精","jezap","力量巅峰","暮光食人魔"},sec={{t="Ring中",b="Bloodmaster's Ring的挑战让你来到了这座竞技场的地精Jezap面前。击败暮光食人魔后，你向他报告，Bloodmaster和Jezap都在一旁注视着。他们正在判断，你是否有资格跻身那些敢于逼近力量巅峰边缘的人之列。"}},faq={{q="在Bloodmaster's Ring，我该向谁报告？",a="你要在Bloodmaster's Ring向Jezap报告。",al={"谁是jezap","向jezap报告","bloodmaster's ring地精"}},{q="我来这里之前做了什么？",a="你击碎了那些被判定为弱者的暮光食人魔。",al={"之前发生了什么","暮光食人魔","ring的前置步骤"}},{q="Bloodmaster在寻找什么？",a="Bloodmaster正在判断你是否够格接近力量巅峰。",al={"证明自己","bloodmaster想要什么","我够格吗"}}},fp="18,147,11.267.0,45.46.0,33.49.0,36.72.0"}
P.entries["quest:94669"] = {n="Pay to Play",s="收货人要求你先交一笔押金，才能进入 Bloodmaster's Ring。付清后，你便有资格在那里证明自己的实力。",h="收货人要求你先交一笔押金，才能进入 Bloodmaster's Ring。付清后，你便有资格在那里证明自己的实力。",kw={"bloodmaster's ring","clugfist","付费参赛","证明实力","竞技场","押金"},sec={{t="入场的代价",b="想进入 Bloodmaster's Ring，你得先交一笔押金。收货人说，交押金是为了保障你的安全。若你不交，他们就威胁要告诉 Clugfist，说你拒绝向欢迎你加入的队伍证明实力。你的选择将决定你是否有资格进入竞技场。"}},faq={{q="我为什么得交钱？",a="收货人说，交押金是为了保障你的安全，也是获得进入 Bloodmaster's Ring 资格的必要条件。",al={"为什么交钱","押金","付费参赛任务"}},{q="Clugfist 是谁？",a="Clugfist 是收货人威胁说要告知你拒绝付款之事的人。",al={"谁是 clugfist","clugfist","老 clugfist"}},{q="如果我拒绝呢？",a="收货人说，他们会告诉 Clugfist，你不愿证明自己的实力。",al={"不交钱","拒交押金","不交押金"}},{q="交钱后我能获得什么资格？",a="交纳押金后，你便有资格进入 Bloodmaster's Ring。",al={"获得什么资格","进入竞技场","bloodmaster's ring"}}},fp="11,132,18.294.0,21.106.0,16.76.0,25.90.0,32.67.0"}
P.entries["quest:94670"] = {n="Bloodmaster's Ring",s="Bloodmaster's Ring挑战让你迎战Buzzbeak，赢得名声的机会就在眼前。擂台上的地精觉得这场战斗很轻松。",h="Bloodmaster's Ring挑战让你迎战Buzzbeak，赢得名声的机会就在眼前。擂台上的地精觉得这场战斗很轻松。",kw={"bloodmaster","bloodmaster's ring","buzzbeak","名声","恶魔","战斗","擂台"},sec={{t="踏入擂台",b="擂台上的地精让Buzzbeak登上擂台与你交手。地精说，第一场战斗应该很轻松，但据说这个恶魔会击倒对手并夺走他们的财物。踏入擂台的人都将获得名声。"}},faq={{q="我在Bloodmaster's Ring要和谁战斗？",a="你将在Bloodmaster's Ring迎战Buzzbeak。",al={"bloodmaster战斗","buzzbeak是谁","擂台对手"}},{q="据说Buzzbeak会做什么？",a="据描述，Buzzbeak是个飘忽不定的恶魔，能击倒你并夺走你的财物。",al={"buzzbeak攻击","buzzbeak会做什么","擂台上的恶魔"}},{q="为什么要参加擂台挑战？",a="擂台上的地精承诺，踏入擂台便能赢得名声。",al={"擂台名声","bloodmaster名声","为什么和buzzbeak战斗"}},{q="这场战斗本该很轻松吗？",a="擂台上的地精称，这是轻松的第一场战斗。",al={"轻松的擂台战斗","bloodmaster轻松","buzzbeak难对付"}}},fp="18,129,13.212.0,41.44.0,32.90.0,19.54.0,31.55.0"}
P.entries["quest:94672"] = {n="Encroaching Twilight",s="Tran'gul警告说，暮光之锤袭击了洛格玛以西的一处人类定居点。你被派往阳光林地削弱邪教徒的力量，以免他们在附近站稳脚跟。",h="Tran'gul警告说，暮光之锤袭击了洛格玛以西的一处人类定居点。你被派往阳光林地削弱邪教徒的力量，以免他们在附近站稳脚跟。",kw={"暮光逼近","人类定居点","洛格玛","阳光林地","tran'gul","暮光新信徒","暮光袭击者","暮光之锤"},sec={{t="近在咫尺的威胁",b="西边的人类定居点已经遭到蹂躏，洛格玛可能成为下一个目标。Tran'gul派你前往阳光林地。暮光之锤已在那里开始征讨他们口中的异端。邪教的袭击者和新信徒正威胁着要在洛格玛附近站稳脚跟。"},{t="战斗之后",b="邪教徒的人数减少后，Tran'gul便能追查其空前扩张的源头。"}},faq={{q="Tran'gul担心谁？",a="Tran'gul担心暮光之锤。这个邪教正在攻击他们认定的异端。",al={"威胁是谁","暮光之锤的威胁"}},{q="那个人类定居点遭遇了什么？",a="暮光之锤蹂躏了洛格玛以西的一处人类定居点。",al={"西边的定居点","西边发生了什么"}},{q="我为什么要去阳光林地？",a="Tran'gul派你前往阳光林地，削弱暮光之锤的力量。",al={"为何去阳光林地","阳光林地有什么"}},{q="邪教接下来可能会袭击谁？",a="西边的人类定居点遭袭后，Tran'gul担心洛格玛可能成为下一个目标。",al={"下一个是谁","洛格玛会是下一个吗"}}},fp="20,173,15.274.0,15.96.1,30.75.0,38.65.0,29.74.0,31.74.0"}
P.entries["quest:94678"] = {n="Gnoll Infestation",s="南方哨站的 Cedric Dalton 请你削减赤脊山豺狼人的数量。他们人多势众，使北面的通道危机四伏，也威胁着法霍德要塞以外的居民。",h="南方哨站的 Cedric Dalton 请你削减赤脊山豺狼人的数量。他们人多势众，使北面的通道危机四伏，也威胁着法霍德要塞以外的居民。",kw={"cedric dalton","法霍德要塞","豺狼人肆虐","豺狼人","北面通道","redridge brutes","redridge mystics","redridge trappers","southern watch"},sec={{t="近在咫尺的威胁",b="南方哨站的 Cedric Dalton 面对着岗哨外群山中的豺狼人。他们人多势众，使北面的通道危机四伏，也让法霍德要塞以外的居民身处险境。你需要击杀 Redridge Mystics、Redridge Trappers 和 Redridge Brutes，削弱他们对这片区域的控制。"}},faq={{q="豺狼人为何构成威胁？",a="豺狼人数量众多，且极具攻击性。他们使北面的通道危机四伏，也威胁着居住在法霍德要塞以外的人们。",al={"豺狼人缘由","豺狼人危险","豺狼人肆虐"}},{q="是谁让我处理豺狼人？",a="南方哨站的 Cedric Dalton 请你削弱豺狼人带来的威胁。",al={"豺狼人任务委托人","cedric dalton","南方哨站豺狼人"}},{q="涉及哪些豺狼人？",a="需要击杀的豺狼人包括 Redridge Mystics、Redridge Trappers 和 Redridge Brutes。",al={"豺狼人类型","赤脊山豺狼人","秘法师、陷阱者、蛮兵"}},{q="豺狼人在哪里？",a="他们盘踞在南方哨站外的山丘上，使通往北方的道路危机四伏。",al={"豺狼人位置","豺狼人在哪","岗哨外的山丘"}}},fp="17,161,15.266.0,29.123.0,36.68.0,26.93.0,21.83.0"}
P.entries["quest:94679"] = {n="Snargl's Snout",s="Southern Watch的Cedric Dalton想要一只来自刺毛丘陵的Snargl的鼻子。他认为，杀死一只强大的豺狼人会削弱赤脊山的兵力，并吓住他们。",h="Southern Watch的Cedric Dalton想要一只来自刺毛丘陵的Snargl的鼻子。他认为，杀死一只强大的豺狼人会削弱赤脊山的兵力，并吓住他们。",kw={"刺毛丘陵","cedric dalton","豺狼人","赤脊山","snargl","snargl的鼻子","southern watch"},sec={{t="丘陵中的豺狼人",b="在Southern Watch，Cedric Dalton请你处理Snargl。Snargl是刺毛丘陵一处巢穴中的恶名昭著的豺狼人。Cedric Dalton认为，豺狼人最看重力量，因此Snargl之死或许能削弱赤脊山的兵力，并让他们心生恐惧。Cedric Dalton要你带回Snargl的鼻子。"},{t="归还战利品",b="Cedric Dalton收下Snargl的鼻子作为战利品，并说很快就会派上用场。杀死这只豺狼人，是为了让赤脊山的兵力心生恐惧。"}},faq={{q="Snargl是谁？",a="Snargl是刺毛丘陵一处巢穴中的恶名昭彰的豺狼人。",al={"snargl是谁","snargl豺狼人","刺毛丘陵豺狼人"}},{q="谁想要Snargl的鼻子？",a="Southern Watch的Cedric Dalton要你把Snargl的鼻子带给他。",al={"谁要snargl的鼻子","cedric dalton的请求","southern watch鼻子"}},{q="Cedric Dalton为什么想杀死Snargl？",a="Cedric Dalton认为豺狼人最看重力量，杀死他们中最强大的家伙会削弱他们，并吓住他们。",al={"为什么杀死snargl","豺狼人力量","吓住赤脊山"}},{q="Snargl在哪里？",a="Snargl在刺毛丘陵的一处巢穴中。",al={"snargl的位置","snargl在哪里","刺毛丘陵巢穴"}}},fp="14,159,20.287.0,17.144.1,14.61.0,25.69.0,33.122.0,16.43.0"}
P.entries["quest:94680"] = {n="Twilight Missives",s="Tran'gul想弄清暮光之锤的教徒为何在阳光林地周边日渐增多。他请你带回他们的密信，以便查明他们的目的。",h="Tran'gul想弄清暮光之锤的教徒为何在阳光林地周边日渐增多。他请你带回他们的密信，以便查明他们的目的。",kw={"教徒","密信","洛格玛","阳光林地","tran'gul","暮光密信","暮光 shadowmancers","暮光之锤"},sec={{t="势力渐长",b="Tran'gul发现，暮光之锤的教徒比以往更多地出现在这一带。他们的暮光 Shadowmancers 是教团中受信任的成员，或许掌握着教团行动的情报。Tran'gul请你带回他们的密信，以便查明这个教团的目的。"}},faq={{q="谁在索要暮光密信？",a="洛格玛的 Tran'gul 请你从阳光林地的暮光 Shadowmancers 手中取回密信。",al={"谁要密信","tran'gul的请求","tran'gul是谁"}},{q="我在哪里能找到暮光 Shadowmancers？",a="暮光 Shadowmancers 位于阳光林地。",al={"暗影施法者的位置","暮光教徒在哪里","阳光林地的密信"}},{q="Tran'gul为什么想要这些密信？",a="Tran'gul想进一步了解这些教徒及其目的。",al={"为何要取回密信","tran'gul想知道什么","教徒的文书"}},{q="Tran'gul为何担心这些教徒？",a="Tran'gul发现暮光之锤的教徒比以往更多，他们似乎也更有恃无恐，想要扩大自己的影响力。",al={"暮光教徒为何在此","教徒日渐增多","暮光教徒人数"}}},fp="17,171,18.258.0,35.91.0,44.45.0,36.67.0,45.128.0"}
P.entries["quest:947"] = {n="洞中的蘑菇",s="“洞穴蘑菇”是暗夜精灵巴瑞萨斯·月影在奥伯丁发布的一项联盟任务。在配制某种特制药剂时，巴瑞萨斯委托一位冒险者前往峭壁之泉背后的一处隐秘洞穴，采集珍稀真菌，并核实古树之林所感应到的不安预兆。",h="“洞穴蘑菇”是暗夜精灵巴瑞萨斯·月影在奥伯丁发布的一项联盟任务。在配制某种特制药剂时，巴瑞萨斯委托一位冒险者前往峭壁之泉背后的一处隐秘洞穴，采集珍稀真菌，并核实古树之林所感应到的不安预兆。",kw={"奥伯丁","巴瑞萨斯·月影","洞穴蘑菇","峭壁之泉","黑海岸","毒帽蘑菇","古树之林","欧努","粗糙柄菇"},ang={["faction:Alliance"]="奥伯丁是联盟在卡利姆多海岸的主要堡垒，东部山脉中蔓延的邪恶直接威胁着整个海岸的稳定。",["profession:Herbalism"]="采集者和草药师会喜欢搜寻毒帽蘑菇和粗糙柄菇的过程，尽管这些特殊的样本生长在阴暗的洞穴里，而不是茂密的林地土壤中。",["race:NightElf"]="古树之林始终与黑海岸的自然平衡保持着深刻的共鸣，因此他们在瀑布之下探测到的任何骚动，对卡多雷来说都是需要紧急关注的问题。"},sec={{t="瀑布后的配方",b="巴瑞萨斯·月影需要特定的配料来调制强力药剂：粗糙柄菇和一种难以寻觅的毒帽蘑菇。这些特殊的真菌生长在黑海岸东北部、峭壁之泉后方隐蔽的阴暗潮湿洞穴中。虽然炼金本身很精细，但收集这些样本要比采集普通的林地草药危险得多。"},{t="古树的警告",b="巴瑞萨斯并非因为懒惰而不去那座洞穴。古树之林的古老树木守护者发出了严厉的警告，感应到一股邪恶的力量开始在山洞中筑巢。月影派遣一位强健的探险者而非亲自调查，正是为了确认长老们关于黑海岸北部潜伏着一股邪恶力量的预感是否属实。"}},faq={{q="这项任务在哪里开始？",a="你可以从巴瑞萨斯·月影那里接到这项任务，他居住在黑海岸中部的暗夜精灵沿海定居点奥伯丁。",al={"如何接取洞穴蘑菇任务","巴瑞萨斯·月影的位置","洞穴蘑菇任务起始"}},{q="蘑菇在哪里？",a="它们生长在峭壁之泉后面隐藏的洞穴里，位于奥伯丁东北部的山坡上。",al={"哪里有粗糙柄菇","毒帽蘑菇位置","黑海岸瀑布后的洞穴"}},{q="为什么巴瑞萨斯·月影不亲自去取蘑菇？",a="古树之林明确建议巴瑞萨斯远离那处瀑布。伟大的古树们感觉到一股非自然的邪恶力量正在那个洞穴中栖身。",al={"为什么巴瑞萨斯不去","为什么巴瑞萨斯留在奥伯丁"}},{q="需要哪些特定的蘑菇？",a="月影需要五株粗糙柄菇，外加一株极度危险的毒帽蘑菇才能完成他的药剂。",al={"所需蘑菇","月影需要的真菌"}},{q="这项差事接下来会指向哪里？",a="一旦确认了洞穴中的异状并交付了真菌，旅程将转向南方，前往古树之林寻找远古保护者欧努。",al={"洞穴蘑菇后的后续任务","欧努后续"}},{q="为什么古树们会担心峭壁之泉？",a="古树之林警告巴瑞萨斯，瀑布后的洞穴中可能潜伏着一股日益壮大的邪恶力量。他请求一位旅行者去采集蘑菇并调查这一警告。",al={"古树对峭壁之泉的警告","为什么侦察洞穴"}}},fp="14,210,25.227.0,21.252.1,27.115.0,32.104.0,61.156.0,35.87.0,35.141.0,55.161.1"}
P.entries["quest:94727"] = {n="Digging for Answers",s="暮光之锤正在河林挖掘，寻找某种未知的能量源泉。你被派往阳光林地，盘问他们的一名矿工。",h="暮光之锤正在河林挖掘，寻找某种未知的能量源泉。你被派往阳光林地，盘问他们的一名矿工。",kw={"digging for answers","矿工","河林","source of power","阳光林地","暮光之锤"},sec={{t="阳光林地的矿工",b="暮光之锤派人在阳光林地挖掘，你被派去盘问其中一名矿工。他们的搜寻指向某种能量源泉，但其本质仍然未知。这些狂热分子守口如瓶，矿工或许知道他们在寻找什么。"}},faq={{q="暮光之锤在挖掘什么？",a="暮光之锤似乎正在河林寻找某种能量源泉，但具体是什么仍然未知。",al={"他们在挖掘什么","暮光之锤挖掘","source of power"}},{q="为什么要盘问矿工？",a="暮光之锤的狂热分子守口如瓶，因此你被派往阳光林地盘问他们的一名矿工。",al={"为何盘问矿工","与矿工交谈","寻求答案任务"}},{q="矿工在哪里？",a="矿工正在河林境内的阳光林地挖掘。",al={"阳光林地在哪里","矿工位置","河林挖掘"}}},fp="19,148,20.255.0,42.119.0,29.112.0,21.61.0"}
P.entries["quest:94733"] = {n="Our Ogre Friend",s="一名地精请你去Bolder'ok寻找Gobam，并为Chub'chob的宠物野猪Snufflesnout带些食物。Gobam愿意帮忙，因为Chub'chob是他的朋友。",h="一名地精请你去Bolder'ok寻找Gobam，并为Chub'chob的宠物野猪Snufflesnout带些食物。Gobam愿意帮忙，因为Chub'chob是他的朋友。",kw={"bolder'ok","chub'chob","据点","gobam","地精","我们的食人魔朋友","宠物野猪","snufflesnout"},sec={{t="朋友的请求",b="在你赢下几场战斗后，那名地精请你去Bolder'ok寻找Gobam。他需要为Chub'chob的宠物野猪Snufflesnout找些食物，却说工作缠身，抽不开身。Gobam就在Clugfist的据点以东，地精希望你能找到他。"}},faq={{q="Gobam是谁？",a="Gobam是那名地精派你去Bolder'ok寻找的害羞家伙。",al={"gobam是谁","谁是gobam"}},{q="我在哪里能找到Gobam？",a="Gobam就在Bolder'ok的Clugfist据点以东。",al={"gobam位置","gobam在哪里"}},{q="Snufflesnout是谁？",a="Snufflesnout是Chub'chob的宠物野猪，地精请你为它带些食物。",al={"snufflesnout","野猪食物"}},{q="地精为什么需要帮忙？",a="地精说工作缠身，所以请你为Snufflesnout寻找食物。",al={"为何帮助地精","地精很忙"}},{q="Gobam为什么愿意帮忙？",a="Gobam说他不喜欢那名地精，但他会帮助Chub'chob，因为他们是好朋友。",al={"gobam帮忙","gobam为何帮忙"}}},fp="15,157,20.242.0,13.66.0,23.51.0,20.83.0,30.86.0,20.92.0"}
P.entries["quest:94734"] = {n="A Boar's Delight",s="Gobam请你为Chub'chob的宠物Snufflesnout采集甜浆果和河边植物。这些食材能做成特别的美味。",h="Gobam请你为Chub'chob的宠物Snufflesnout采集甜浆果和河边植物。这些食材能做成特别的美味。",kw={"浆果","gobam","宠物","河草","snufflesnout","甜浆果","美味"},sec={{t="宠物的美味",b="Gobam想为爱吃美食的Snufflesnout做些特别的东西。他请你带回甜浆果和河草，作为制作美味的食材。"}},faq={{q="Gobam是谁",a="Gobam请你带回食材，为Chub'chob的宠物Snufflesnout制作特别的美味。",al={"gobam是谁","谁要浆果"}},{q="Snufflesnout是谁",a="Snufflesnout是Chub'chob的宠物，喜欢美食。",al={"snufflesnout宠物","gobam的宠物"}},{q="Gobam想要哪些食材",a="Gobam请你采集甜浆果和河草，为Snufflesnout制作美味。",al={"浆果和植物","什么食物"}},{q="Gobam为什么想要浆果",a="Gobam想用甜浆果和河草为Snufflesnout制作特别的美味。",al={"为什么要浆果","浆果用来做什么"}}},fp="16,133,13.150.0,13.95.0,20.52.0,33.76.0,28.81.0"}
P.entries["quest:94737"] = {n="A Treat for a Friend",s="Gobam请你把一份礼物送给Bolder'ok的Jezap Jinglesprocket。Jezap说，让Snufflesnout开心最重要，也就是让Chub'chob开心。",h="Gobam请你把一份礼物送给Bolder'ok的Jezap Jinglesprocket。Jezap说，让Snufflesnout开心最重要，也就是让Chub'chob开心。",kw={"送给朋友的礼物","bolder'ok","一包货物","chub'chob","jezap jinglesprocket","snufflesnout"},sec={{t="Gobam的请求",b="Gobam交给你的一包货物是送给Snufflesnout的礼物，她是Chub'chob的宠物野猪。Gobam说，她看到礼物一定会高兴得哼哼直叫。他还让你告诉地精Jezap少说点话。"}},faq={{q="礼物是送给谁的？",a="Gobam说，礼物是送给Snufflesnout的，她是Chub'chob的宠物野猪。",al={"礼物送给谁","snufflesnout的礼物"}},{q="我该把货物送给谁？",a="这包货物是送给Bolder'ok的Jezap Jinglesprocket的。",al={"货物送到哪里","jezap收货"}},{q="我该传什么话？",a="Gobam让你告诉Jezap，别再说个不停了。",al={"告诉jezap什么","地精的口信"}},{q="Snufflesnout是谁？",a="Snufflesnout是Chub'chob的宠物野猪，Jezap曾答应照看她。Jezap开玩笑说，让Snufflesnout开心，其实就是让Chub'chob开心。",al={"snufflesnout是谁","snufflesnout"}}},fp="20,151,15.202.0,21.63.0,34.61.0,33.53.0,20.155.0"}
P.entries["quest:94739"] = {n="Bloodmaster's Ring",s="Bloodmaster's Ring的地精把你送进角斗场的坑中，与Kronk一决高下。观众已经迫不及待地等着下一场较量。",h="Bloodmaster's Ring的地精把你送进角斗场的坑中，与Kronk一决高下。观众已经迫不及待地等着下一场较量。",kw={"解说员","bloodmaster","bloodmaster's ring","较量","参赛者","kronk","斗坑"},sec={{t="下一场较量",b="解说员正在调动观众的情绪，Kronk则作为下一位参赛者等候着。你奉命进入斗坑迎战他，随着这场较量即将开始，周围的喧闹声也越来越响。"}},faq={{q="Kronk是谁？",a="Kronk是Bloodmaster's Ring的下一位参赛者。解说员说他们相识已久，并称Kronk是个强壮的斗士。",al={"kronk","kronk是谁","kronk bloodmaster"}},{q="Bloodmaster要我做什么？",a="你被送进Bloodmaster's Ring的坑中，迎战Kronk。",al={"该做什么","角斗场任务","bloodmaster's ring"}},{q="我为什么要和Kronk交手？",a="解说员介绍Kronk是下一位参赛者，较量将在Bloodmaster's Ring举行。",al={"为什么是kronk","与kronk战斗","kronk战斗"}},{q="较量在哪里举行？",a="较量将在Bloodmaster's Ring的斗坑中举行。",al={"战斗在哪里","斗坑","角斗场位置"}},{q="我进入斗坑后会发生什么？",a="你在斗坑中做好准备时，解说员正准备介绍Kronk。",al={"进入之后","角斗场下一位","接下来会发生什么"}},{q="解说员怎么评价Kronk？",a="解说员说Kronk不太聪明，但很擅长痛打挡在他面前的一切。",al={"kronk的背景","kronk是什么样的人","解说员 kronk"}}},fp="18,136,13.160.0,13.130.0,40.66.0,24.101.0,31.58.0,35.78.0,40.91.0"}
P.entries["quest:94744"] = {n="The Wayward Warrior",s="Krom'rosh请你前往洛格玛以西的暮光之锤据点，与他的兄弟Dag'rosh会合。暮光之锤在阳光林地的据点已衰弱，战斗正转向他们的据点。",h="Krom'rosh请你前往洛格玛以西的暮光之锤据点，与他的兄弟Dag'rosh会合。暮光之锤在阳光林地的据点已衰弱，战斗正转向他们的据点。",kw={"dag'rosh","krom'rosh","食人魔战士","洛格玛","阳光林地","迷途的战士","暮光之锤"},sec={{t="兄弟先行",b="Krom'rosh派你去寻找Dag'rosh，他已和一支侦察队先行出发。你要去洛格玛以西的丘陵寻找他。Krom'rosh说，暮光之锤在阳光林地已失去据点，食人魔战士也倒戈反抗他们。如今战斗正转向邪教据点，他希望你陪在兄弟身边。"}},faq={{q="是谁让我去找Dag'rosh？",a="Krom'rosh请你前往暮光之锤据点，与他的兄弟Dag'rosh会合。",al={"是谁派我去","krom'rosh","谁要找dag'rosh"}},{q="我在哪里能找到Dag'rosh？",a="Krom'rosh说，要去洛格玛以西的丘陵寻找Dag'rosh。",al={"dag'rosh在哪里","dag'rosh的位置","寻找da'grosh"}},{q="Dag'rosh是谁？",a="Dag'rosh是Krom'rosh的兄弟。他已和一支侦察队先行出发。",al={"dag'rosh的来历","krom'rosh的兄弟","dag'rosh是谁"}},{q="暮光之锤在阳光林地遭遇了什么？",a="暮光之锤在阳光林地的据点已衰弱，食人魔战士也倒戈反抗他们。",al={"阳光林地的邪教","暮光之锤的据点","食人魔发生了什么"}}},fp="19,191,15.334.0,34.84.0,26.65.0,16.73.0,53.104.0"}
P.entries["quest:94745"] = {n="Carving a Path",s="Da'grosh要求你前往暮光之帷挑战暮光之锤。他认为，他们依赖邪术和远古诸神，因此不堪一击。",h="Da'grosh要求你前往暮光之帷挑战暮光之锤。他认为，他们依赖邪术和远古诸神，因此不堪一击。",kw={"远古诸神","carving a path","da'grosh","邪术","暮光 champion","暮光 corrupter","暮光 fanatic","暮光之锤","暮光之帷"},sec={{t="暮光之帷",b="Da'grosh指引你前往暮光之帷，那是一座位于他西边的堡垒。他称里面的暮光之锤成员都是懦夫，嘲讽他们依赖邪术和远古诸神。他要你向他们证明，他们不堪一击。"},{t="力量试炼",b="在暮光之帷，Da'grosh要求你击败 Twilight Fanatics、Twilight Corrupters 和 Twilight Champions。他坚称，真正的力量源自自身。"}},faq={{q="Da'grosh要我和谁战斗？",a="Da'grosh要你在暮光之帷与 Twilight Fanatics、Twilight Corrupters 和 Twilight Champions 战斗。",al={"要和谁战斗","da'grosh的敌人"}},{q="暮光之帷在哪里？",a="Da'grosh说，暮光之帷是一座就在他西边的堡垒。",al={"暮光之帷在哪里","暮光堡垒的位置"}},{q="Da'grosh为什么说暮光之锤软弱？",a="Da'grosh认为，他们依赖邪术和远古诸神，所以软弱。",al={"他们为什么软弱","da'grosh谈暮光之锤"}},{q="Da'grosh要我证明什么？",a="Da'grosh要你向暮光之锤证明，他们不堪一击。",al={"我需要证明什么","向他们证明他们不堪一击"}}},fp="14,157,10.237.0,18.173.0,35.115.0,31.81.0,50.77.0,36.74.0"}
P.entries["quest:94748"] = {n="Break Their Chains",s="达格罗什请你解救被囚禁在暮光帷幕中的Rog’mar侦察兵。他的战士需要返回Rog’mar，才能再次投入战斗。",h="达格罗什请你解救被囚禁在暮光帷幕中的Rog’mar侦察兵。他的战士需要返回Rog’mar，才能再次投入战斗。",kw={"break their chains","被俘的兽人","达格罗什","堡垒","rog’mar侦察兵","暮光的重型钉锤","暮光帷幕"},ang={["race:Orc"]="身为兽人，达格罗什请你解救被俘的兽人兄弟姐妹。"},sec={{t="被俘的侦察兵",b="暮光的重型钉锤在发动袭击前俘获了达格罗什的战士。邪教的勇士将他们带到达格罗什以西的一座堡垒，并关押起来。他请你解救被囚禁在暮光帷幕中的兽人兄弟姐妹。"},{t="营救之后",b="达格罗什说，他的战士伤势过重，无法战斗，已经返回Rog’mar。他告诉你，你们的合作还将继续。"}},faq={{q="谁在请求帮助？",a="达格罗什请你解救他被俘的战士。",al={"达格罗什是谁","谁需要帮助"}},{q="谁被俘了？",a="暮光的重型钉锤俘获了达格罗什的战士，也就是Rog’mar侦察兵。",al={"被俘的兽人","rog’mar侦察兵"}},{q="侦察兵被关在哪里？",a="Rog’mar侦察兵被关押在达格罗什以西、暮光帷幕中的一座堡垒里。",al={"侦察兵的位置","他们被关在哪里"}},{q="谁俘获了达格罗什的战士？",a="暮光的重型钉锤勇士俘获了达格罗什的战士。",al={"谁抓走了兽人","暮光的重型钉锤俘虏"}}},fp="18,153,19.261.0,16.130.1,23.50.0,17.79.0,32.101.0,37.71.0"}
P.entries["quest:94773"] = {n="Divine Grace",s="名为 Divine Grace 的课程感谢你为圣光效力。你为身处险地的旅人树立了榜样。",h="名为 Divine Grace 的课程感谢你为圣光效力。你为身处险地的旅人树立了榜样。",kw={"险地","divine grace","课程","圣光","旅人"},sec={{t="感恩之课",b="你效力之后，人们赞颂圣光，也赞扬你为身处险地的旅人树立的榜样。为感谢你的付出，他们将传授你一课。"}},faq={{q="Divine Grace 讲的是什么？",a="Divine Grace 感谢你为圣光效力，并为身处险地的旅人树立榜样。",al={"divine grace","divine grace 是什么","divine grace 任务"}},{q="这堂课是为谁准备的？",a="这堂课是为感谢你效力圣光而传授给你的。",al={"谁能听这堂课","给我的课程","divine grace 奖励"}},{q="我树立了什么榜样？",a="你成为了身处险地及其他地方的旅人们的榜样。",al={"我的榜样","光辉榜样","我做了什么"}}},fp="12,116,18.159.0,27.102.0,23.69.0,23.65.0"}
P.entries["quest:94774"] = {n="Divine Grace",s="你的导师已批准你接受进一步训练，高阶牧师劳瑞娜因此召你前往暴风城的光明大教堂。你对圣光之道的学习即将开始。",h="你的导师已批准你接受进一步训练，高阶牧师劳瑞娜因此召你前往暴风城的光明大教堂。你对圣光之道的学习即将开始。",kw={"光明大教堂","divine grace","高阶牧师劳瑞娜","圣光","圣光的仆从","暴风城","训练"},ang={["class:Priest"]="身为牧师，你已获导师批准，可以进一步修习圣光之道。"},sec={{t="暴风城的召唤",b="你的导师认为你已证明了自己，便派你前往暴风城的光明大教堂。在那里，高阶牧师劳瑞娜已准备好指导你进一步修习。她说，每一位圣光的仆从都有必须学习的课程，而她已准备好与你探讨这些课程。"}},faq={{q="为什么派我去暴风城？",a="你的导师认为你已证明了自己，并已批准你进一步修习圣光之道。",al={"为什么去暴风城","被派往大教堂","为什么去那里"}},{q="高阶牧师劳瑞娜是谁？",a="高阶牧师劳瑞娜就在暴风城的光明大教堂，已准备好指导你修习。",al={"laurena是谁","谁是laurena","高阶牧师"}},{q="在哪里能找到高阶牧师劳瑞娜？",a="高阶牧师劳瑞娜就在暴风城的光明大教堂。",al={"laurena的位置","laurena在哪里","大教堂位置"}},{q="Laurena会提供什么训练？",a="Laurena已准备好与你探讨所有圣光仆从都必须学习的课程。",al={"圣光训练","什么课程","学习圣光之道"}}},fp="12,181,19.290.0,33.108.0,30.101.0,39.65.0,34.81.0"}
P.entries["quest:94789"] = {n="天空的召唤",s="一名萨满祭司被派往阿拉希高地北部的群山，去找Veyric Thundervein。他会传授更多驾驭空气的知识。",h="一名萨满祭司被派往阿拉希高地北部的群山，去找Veyric Thundervein。他会传授更多驾驭空气的知识。",kw={"空气","阿拉希高地","天空的召唤","萨满祭司","空气之灵","veyric thundervein","风系法术"},sec={{t="北部群山",b="一名萨满祭司派你北上，前往阿拉希高地寻找Veyric Thundervein。空气元素难以驾驭，而他能传授你更多知识。日益精进的技艺让你走到了这一步；如今，你的训练将转向风与空气之灵。"}},faq={{q="Veyric Thundervein是谁？",a="Veyric Thundervein就在阿拉希高地北部的群山中，他能在那里传授你更多关于空气的知识。",al={"veyric","veyric是谁","空气训练师"}},{q="在哪里能找到Veyric？",a="前往阿拉希高地北部的群山，寻找Veyric Thundervein。",al={"veyric的位置","veyric在哪","阿拉希空气训练师"}},{q="天空的召唤讲的是什么？",a="一名萨满祭司派你去找Veyric Thundervein，让他传授你更多关于空气元素的知识。",al={"天空的召唤任务","空气训练","风系法术"}},{q="为什么要去阿拉希高地？",a="Veyric Thundervein就在阿拉希高地北部的群山中，他会传授你更多关于空气的知识。",al={"为何去阿拉希","北上任务","寻找veyric"}},{q="Veyric会教些什么？",a="Veyric会教你集中施放风系法术，并召唤空气之灵。",al={"veyric的训练","空气之灵","集中施放风系法术"}}},fp="11,125,18.245.0,26.103.0,23.66.0,26.91.0,35.102.0,23.73.0"}
P.entries["quest:94792"] = {n="Taming the Beast",s="驯服野兽是一项入门级的试炼，有志向的冒险者将在此学习安抚野兽并与其建立羁绊的艺术。在 Josephine Carson 的指导下，新手们会带着一根驯兽棒进入森林，去驯服一只岩皮野猪并练习必要的生存技能。这项任务旨在证明，只要尊重并维护微妙的自然平衡，有了一只忠诚的野兽伙伴，在严酷的荒野中生存就会变得轻松许多。",h="驯服野兽是一项入门级的试炼，有志向的冒险者将在此学习安抚野兽并与其建立羁绊的艺术。在 Josephine Carson...",kw={"动物伙伴","自然的平衡","野兽驯服","猎人宠物","约瑟芬·卡森","岩皮野猪","驯兽棒","驯服野兽"},ang={["class:Druid"]="虽然德鲁伊不像猎人那样保留动物伙伴，但任务中对维护微妙的自然平衡的强调，反映了德鲁伊的核心教义。以关怀和克制的态度与森林中的野生生物互动，就是对他们发誓要保护的自然平衡的尊重。",["class:Hunter"]="对于猎人来说，掌握驯服野生野兽的艺术是一个决定性的成人礼，它从根本上改变了他们在荒野中的生存方式。忠诚的伙伴提供了必要的战斗保护和警觉，在追踪者与野兽之间铸就了持久的伙伴关系。"},sec={{t="与野兽建立羁绊",b="对于许多荒野漫游者来说，独自深入未经开垦的领地无异于自寻死路。一只动物伙伴不仅能在战斗中提供凶猛的保护，还能在艰苦的旅途中给予坚定不移的陪伴。学习如何建立这种羁绊，对于任何立志成为猎人或追踪者的人来说，都是一个至关重要的里程碑。在 Josephine Carson 的指引下，新手们会获赠一根特制的驯兽棒，并被要求前往森林中寻找一只岩皮野猪。安抚并驾驭这种生物是一项基础试炼，它能证明旅行者是否具备引导野兽所需的专注与镇定，而不会因恐惧而失控，或引发不必要的流血冲突。"},{t="自然的平衡",b="驾驭野生动物肩负着深远的道德和生态责任。正如 Josephine Carson 提醒她的学生们所言，将野兽纳入麾下绝不能沦为鲁莽的剥削，因为自然的平衡是脆弱的，必须时刻加以维护。驯服的过程并非为了残忍或统治，而是为了在野兽与主人之间建立和谐与纪律。使用这根附魔的驯兽棒，新手可以在不永久性消耗当地野生动物的前提下，安全地练习驾驭像岩皮野猪这样强大的生物。一旦掌握了指挥和安抚野兽的基础知识，驯兽棒就需要归还，这体现了对自然秩序的尊重高于个人的傲慢。"}},faq={{q="驯服野兽任务的目的是什么？",a="这项任务是为寻求与野生生物建立羁绊的冒险者提供的基础训练。在 约瑟芬·卡森 的指导下，新手将学习如何使用特制的驯兽棒接近并安抚一只野生的岩皮野猪。该练习教导有志成为猎人的冒险者，动物伙伴如何帮助他们在荒野中生存，同时也强调了尊重自然平衡的重要性。",al={"驯服野兽 任务","驯服野兽 是什么","猎人宠物任务"}},{q="约瑟芬·卡森 是谁？",a="约瑟芬·卡森 是一位导师，她指导冒险者掌握管理动物伙伴的微妙艺术。她会提供驯兽棒，并指派学生在附近的树林里用岩皮野猪练习他们的能力。约瑟芬 强调，学会与野兽共事需要耐心、实践以及对自然微妙平衡的深刻认识。",al={"约瑟芬·卡森","谁发布 驯服野兽","驯兽棒任务发布者"}},{q="驯兽棒有什么用？",a="驯兽棒是 约瑟芬·卡森 提供的一种特制工具，用于辅助动物训练。冒险者带着这根棒子进入森林，去安抚并驯服一只野生的岩皮野猪。它能让新手在不伤害当地动物群的前提下，安全地练习指挥野兽，且在试炼完成后必须将其归还给 约瑟芬。",al={"驯兽棒","驯兽棒的作用","如何使用驯兽棒"}},{q="猎人为什么需要动物伙伴？",a="独自在荒野中穿行会让旅行者面临严重的危险和伏击。动物伙伴可以提供可靠的保护、共同的警惕以及战斗中强有力的援助，让危险的环境变得更容易应对。在穿越荒地的漫长而危险的旅途中，忠诚的野兽既是凶猛的前线卫士，也是值得信赖的伙伴。",al={"为什么要获取宠物","野兽伙伴的好处","为什么要驯服野兽"}},{q="在此次试炼中需要驯服什么生物？",a="此次试炼要求冒险者深入森林，使用提供的驯兽棒驯服一只岩皮野猪。这些强壮的野兽是练习基础动物操控技能的理想测试对象，教导旅行者在面对具有攻击性的野生动物时如何保持镇定和纪律，然后返回向 约瑟芬·卡森 报告进度。",al={"我要驯服哪种野猪","岩皮野猪目标","驯服野兽 怪物"}},{q="为什么 约瑟芬·卡森 强调自然的平衡？",a="约瑟芬·卡森 警告说，驯服野生野兽时必须时刻保持谨慎和尊重，而不是贪婪或强迫。自然秩序是脆弱的，鲁莽地破坏当地的野生动物或虐待生物会打破生态平衡。对野兽真正的驾驭，需要理解并尊重它们在生态系统中的位置，而不是仅仅将它们视为可随意丢弃的工具。",al={"自然平衡的含义","自然平衡与驯服","为什么要尊重自然"}}},fp="16,181,19.403.0,21.405.0,50.234.0,24.231.0,32.240.0,38.186.0,46.237.0,58.205.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="训练野兽是年轻猎人的基础任务，引导他们前往闪金镇寻找老练的林务员 Isaac Chan。通过完成这一步骤，猎人将学会如何适当地训练、喂养和复活他们的野兽伙伴，将一头刚驯服的野兽转变为忠诚的战斗伙伴。",h="训练野兽是年轻猎人的基础任务，引导他们前往闪金镇寻找老练的林务员 Isaac Chan。通过完成这一步骤，猎人将学会如何适当地训练、喂养和复活他们的野兽伙伴，将一头刚驯服的野兽转变为忠诚的战斗伙伴。",kw={"艾尔文森林","喂养宠物","闪金镇","猎人宠物","艾萨克·陈","宠物训练","复活宠物","训练野兽","林务员"},ang={["class:Hunter"]="这项任务标志着成长中猎人的重要成人礼，从仅仅是捕捉野兽转变为通过喂养、复活和训练它们来建立持久、纪律严明的羁绊。",["faction:Alliance"]="在艾尔文森林活动的联盟猎人依靠像闪金镇的 Isaac Chan 这样的老练林务员来掌握野兽驯养的基础知识。"},sec={{t="狩猎的责任",b="学会驯服野生生物只是准猎人的第一步；维持持久的伙伴关系需要纪律和知识。该任务引导初出茅庐的猎人去寻找驻扎在闪金镇的经验丰富的林务员 Isaac Chan，以获取野兽训练的必备技能。如果没有适当的指导，驯服的野兽将只是难以管教的野生动物，而非荒野中坚定的盟友。"},{t="林务员的指导",b="到达闪金镇后，Isaac Chan 会传授照料野兽伙伴所需的技能。这些指导超越了简单的战斗指令，包括喂养伙伴以保持其满足感的重要职责，以及学习在伙伴倒下时将其复活的仪式。Chan 提醒他的学生，拥有驾驭野兽的力量同时也意味着有责任尊重自然平衡，并对周围的世界怀有敬畏之心。"}},faq={{q="艾萨克·陈 是谁？",a="艾萨克·陈 是一位资深的、终身的林务员，居住在艾尔文森林的闪金镇。他因对野生动物和荒野生存的深刻理解而备受尊敬，并教导新手猎人如何适当地引导、喂养、复活他们的野兽伙伴，并传授它们技能。",al={"艾萨克·陈 是谁","闪金镇野兽训练师","艾萨克·陈 背景故事"}},{q="训练野兽的目的是什么？",a="虽然猎人可能已经知道如何驯服野兽，但该任务提供了维持这种羁绊的必要知识。它指导猎人如何喂养他们的伙伴，在伙伴战斗中倒下时将其复活，并教给它们新的战斗技能。",al={"这个任务有什么用","为什么要训练野兽","训练野兽 的目的"}},{q="在哪里可以找到 艾萨克·陈？",a="艾萨克·陈 位于闪金镇，这是艾尔文森林的中心城镇，位于北郡山谷正南方，暴风城西南方。",al={"艾萨克·陈 在哪里","我在哪里交这个任务","艾萨克·陈 位置"}},{q="艾萨克·陈 教授什么技能？",a="艾萨克·陈 传授宠物照料和训练的核心原则。这包括喂养野兽以维持其健康，在它战斗中死亡时将其复活，以及在它随你成长时教给它新的能力。",al={"能学到什么技能","学习的宠物技能","艾萨克·陈 教什么"}},{q="为什么 艾萨克·陈 提醒猎人要尊重自然？",a="艾萨克·陈 强调，驾驭野兽需要谦逊而非支配。他敦促猎人尊重自然界的平衡，并对周围的自然怀有敬畏之心，确保猎人和野兽之间的伙伴关系建立在守护而非剥削的基础上。",al={"为什么尊重自然","猎人尊重平衡"}},{q="谁会执行这个任务？",a="训练野兽是专门为那些已经获得了驯服野兽的初始能力，并且需要维持和训练野兽伙伴所需的林地纪律的猎人量身定制的。",al={"谁可以做这个任务","训练野兽 是猎人专属吗"}}},fp="18,184,32.248.0,21.284.0,18.217.0,42.181.0,30.129.0,34.194.0,53.207.0,26.115.0"}
P.entries["quest:948"] = {n="安努",s="这个任务要求旅行者从奥伯丁出发向南前往古树之林，去拜见奥努。在探查了峭壁之泉后的洞穴后，你的发现已经引起了黑海岸最古老的守护者之一的密切关注。",h="这个任务要求旅行者从奥伯丁出发向南前往古树之林，去拜见奥努。在探查了峭壁之泉后的洞穴后，你的发现已经引起了黑海岸最古老的守护者之一的密切关注。",kw={"知识古树","奥伯丁","巴瑞萨斯·月影","峭壁之泉","黑海岸","古树之林","奥努"},ang={["class:Druid"]="德鲁伊们深切地尊崇古树，视其为自然智慧的化身。按照奥努的要求调查奇怪的洞穴生长物，完全符合塞纳里奥议会的职责。",["faction:Alliance"]="对于帮助保卫黑海岸的联盟旅行者来说，获得当地古树的信任与洞见，对于在卡利姆多神秘的北部荒野中穿行至关重要。",["race:NightElf"]="知识古树是卡多雷神圣的伙伴，自从大分裂之前就一直指引着你们的人民。回应奥努的召唤，是维护黑海岸神圣不可侵犯的一项庄严职责。"},sec={{t="来自古树的召唤",b="在带着从峭壁之泉深处采集的真菌样本返回奥伯丁后，巴瑞萨斯·月影意识到，这些发现的意义绝非仅仅是植物学上的好奇。被污染的洞穴的消息很快传到了奥努耳中，这是一位扎根于镇南古树之林那片宁静圣所中的知识古树。尽管古树生物天性耐心且深沉，但奥努如此急切地想要商议，表明黑海岸水道中蔓延的腐蚀可能触及了一些古老而令人不安的力量。"},{t="前往树林",b="沿着奥伯丁南下的道路前行，便可远离海岸遗迹，深入内陆，向山坡走去。古树之林是自然之力的祖传堡垒，在很大程度上躲避了侵蚀海岸线的腐朽蔓延。在这里，奥努等待在参天的石冢和同类灵体之间，准备指引盟友前往荒野边缘那些更深、更可怕的枯萎之源。"}},faq={{q="奥努是谁？",a="奥努是一位知识古树，是一个巨大的、有思想的树人守护者，致力于收集和保存知识。他坐镇在黑海岸南部的古树之林，为这片土地的保卫者提供智慧和指引。",al={"奥努是谁","奥努的身份","奥努是什么"}},{q="为什么奥努想和我谈谈？",a="你最近深入峭壁之泉下的洞穴，为巴瑞萨斯·月影采集了真菌样本。在那里发现的奇特事物引起了博物学家的警觉，促使奥努请求会面，以应对日益严重的腐蚀问题。",al={"为什么奥努召唤我","谈话原因","为什么要去见奥努"}},{q="古树之林在哪里？",a="古树之林位于奥伯丁以南，坐落在东部山脉的山麓边。沿着黑海岸的主路向南走，然后向东前往山坡，就能找到奥努。",al={"奥努的位置","古树之林在哪里","如何找到奥努"}},{q="知识古树是什么样的生物？",a="知识古树是与暗夜精灵及塞纳里奥议会结盟的古老树人生物。它们因其深厚的智慧和记忆而备受尊崇，是自然魔法和历史秘密的活体宝库。",al={"知识古树","奥努是什么生物","树人和古树的区别"}},{q="为什么奥努的召唤被认为是紧急的？",a="众所周知，古树的行事风格深思熟虑、从容不迫，很少会匆忙行事。正如巴瑞萨斯·月影所指出的，如果像奥努这样耐心且有条理的生物主动要求与你商议，那么黑海岸面临的威胁一定非常严重。",al={"为什么紧急","奥努是否担心","巴瑞萨斯的警告"}},{q="与奥努会面后会发生什么？",a="在你到达古树之林后，奥努会请求你的协助，去调查海岸以南更远处的巨大威胁：围绕着主宰之剑正在进行的险恶挖掘活动。",al={"奥努之后的下一个任务","接下来会发生什么","奥努让你去哪里"}}},fp="3,166,27.409.0,20.339.0,11.167.0,35.197.0,35.190.0,44.180.0,39.132.0,34.167.1"}
P.entries["quest:94819"] = {n="Contingency Plan",s="有人派你前往铁炉堡会见 High Priestess Mims。你的下一场试炼即将到来，她正在秘法区等你。",h="有人派你前往铁炉堡会见 High Priestess Mims。你的下一场试炼即将到来，她正在秘法区等你。",kw={"应急计划","high priestess mims","铁炉堡","light","秘法区","下一场试炼","仪式"},sec={{t="等候会面",b="在铁炉堡，High Priestess Mims 正在秘法区等你前去交谈。你的下一场试炼即将到来，而派你前来的人无法离开自己的岗位，见证你们族人的仪式。你前去会见 Mims 时，对方祝愿 Light 与你同行。"}},faq={{q="我应该去见谁？",a="High Priestess Mims 正在铁炉堡的秘法区等你前去交谈。",al={"谁在等候","会见 mims","mims"}},{q="我在哪里能找到 Mims？",a="Mims 应该在铁炉堡的秘法区。",al={"mims 在哪里","mims 的位置","秘法区"}},{q="我为什么要去铁炉堡？",a="High Priestess Mims 想在那里与你交谈，而你的下一场试炼即将到来。",al={"为什么去铁炉堡","铁炉堡有什么","会面"}},{q="派我来的人对我们族人的仪式说了什么？",a="派你来的人希望能见证你们族人的仪式，但表示自己必须留在原处。",al={"我们族人的仪式","特殊仪式","他们为什么不能来"}},{q="对我的旅途有什么祝愿？",a="派你来的人祝愿 Light 与你同行。",al={"light 的祝福","light 与我同行","旅途祝福"}}},fp="16,129,18.253.0,23.76.0,22.47.0,28.82.0,49.97.0,30.61.0"}
P.entries["quest:94822"] = {n="Confounding Flash",s="你的上级派你前往铁炉堡，跟随High Priestess Mims继续接受训练。你为Light所做的贡献已引起他们的注意。",h="你的上级派你前往铁炉堡，跟随High Priestess Mims继续接受训练。你为Light所做的贡献已引起他们的注意。",kw={"confounding flash","hall of mysteries","high priestess mims","铁炉堡","light","上级","训练"},sec={{t="进一步的教导",b="你的上级派你去铁炉堡的秘法大厅寻找High Priestess Mims。他们认为，你所做的贡献已让你具备接受进一步训练的资格。Mims将指导你，只待你抵达便可开始授课。"},{t="拜见Mims",b="High Priestess Mims在铁炉堡接见了你，并指出你来迟了。念及你为Light所做的贡献，她原谅了你的迟到，随后请你用心听取她的教导。"}},faq={{q="是谁派我去铁炉堡的？",a="你的上级让你前往铁炉堡的秘法大厅，接受进一步的训练。",al={"谁派我来的","我的上级是谁"}},{q="High Priestess Mims是谁？",a="High Priestess Mims就是你的上级指示你去铁炉堡寻找的人。她能指导你继续接受训练。",al={"mims是谁","mims"}},{q="为什么派我去接受训练？",a="你的上级认为，你为Light所做的贡献已证明了你的能力。",al={"为什么接受训练","为什么选我"}},{q="在哪里能找到High Priestess Mims？",a="前往铁炉堡的秘法大厅寻找High Priestess Mims。",al={"mims在哪里","hall of mysteries"}}},fp="17,139,16.203.0,11.169.0,25.94.0,27.115.0,33.82.0,36.63.0"}
P.entries["quest:94824"] = {n="Confounding Flash",s="一封信让你前往铁炉堡与高阶女祭司 Mims 谈话。她在 Hall of Mysteries 等你，但信中没有说明缘由。",h="一封信让你前往铁炉堡与高阶女祭司 Mims 谈话。她在 Hall of Mysteries 等你，但信中没有说明缘由。",kw={"confounding flash","hall of mysteries","高阶女祭司 mims","铁炉堡","与 mims 谈话","召见"},sec={{t="铁炉堡的召唤",b="前方的路通往铁炉堡，高阶女祭司 Mims 正在 Hall of Mysteries 等候。信中让你亲自前去与她谈话，却没有说明召见的缘由。信中猜测你的事迹进展顺利，但具体情况还得由 Mims 解释。"}},faq={{q="谁要和我谈话？",a="高阶女祭司 Mims 想让你来铁炉堡与她谈话。",al={"谁召见我","mims 召见","高阶女祭司 mims"}},{q="我该去哪里？",a="有人请你前往铁炉堡的 Hall of Mysteries，与高阶女祭司 Mims 谈话。",al={"mims 在哪里","hall of mysteries 位置","前往铁炉堡"}},{q="Mims 为什么要见我？",a="信中没有说明高阶女祭司 Mims 想与你谈话的原因。",al={"mims 召见我的原因","她想要什么","召见缘由"}},{q="要我做什么？",a="有人请你前往铁炉堡与高阶女祭司 Mims 谈话。",al={"任务是什么","与 mims 谈话","mims 的请求"}}},fp="17,148,19.277.0,27.66.0,14.86.0,29.77.0,28.67.0"}
P.entries["quest:94829"] = {n="What We Lost",s="Elbrim's Farm的一位农夫哀悼着被暮光袭击者杀害的人们。你受托找回他们的遗物，并将遗物放在农场西边的墓地上。",h="Elbrim's Farm的一位农夫哀悼着被暮光袭击者杀害的人们。你受托找回他们的遗物，并将遗物放在农场西边的墓地上。",kw={"邪教徒","elbrim's farm","农夫","农夫的遗物","墓地","墓园","暮光袭击者","我们失去的一切"},sec={{t="农夫的恳求",b="农夫请你收集邪教徒来到Elbrim's Farm时遇害者的遗物。这些田地曾为军队和平民提供粮食，但农夫说，承诺的保护始终没有到来。他们的人倒在农场的废墟中，亲人则葬在西边的墓地里。"},{t="墓前",b="农夫希望你把逝者的遗物带到Elbrim's Farm西边的墓地。此举无法让他们起死回生，但农夫希望他们的灵魂能与亲人一同安息。"}},faq={{q="Elbrim's Farm发生了什么？",a="农夫说，邪教徒来到Elbrim's Farm，毁掉了庄稼，还杀害了在那里劳作的人们。",al={"elbrim's farm发生了什么","农场被毁","这里发生了什么"}},{q="是谁请我找回遗物？",a="Elbrim's Farm的一位农夫请你找回被邪教徒杀害者的遗物。",al={"谁想要遗物","农夫的请求","是谁在请求"}},{q="我收集的是谁的遗物？",a="这些遗物属于曾在Elbrim's Farm的田地里劳作、并在邪教徒到来时遇害的人们。",al={"农夫的遗物","这些属于谁","遗物属于谁"}},{q="遗物应该放在哪里？",a="农夫请你把遗物放在Elbrim's Farm西边墓地里的墓碑上。",al={"遗物放在哪里","该放在哪些墓上","墓地位置"}},{q="农夫为什么想要归还遗物？",a="农夫相信，把逝者的遗物放在他们亲人的墓上，能让他们的灵魂安息。",al={"为什么要找回遗物","让灵魂安息","为什么要遗物"}}},fp="12,158,15.292.0,13.180.0,31.110.0,36.98.0,31.109.0,29.95.0,47.106.0"}
P.entries["quest:94841"] = {n="Lost Shipping Crate",s="一只标有 Friz Frazzlespark 收件信息的货箱在河林失踪了。标签要求将它送回爆破引线港。",h="一只标有 Friz Frazzlespark 收件信息的货箱在河林失踪了。标签要求将它送回爆破引线港。",kw={"货箱","friz frazzlespark","标签","遗失的货箱","地图","爆破引线港","河林"},sec={{t="带有标记的货箱",b="Friz Frazzlespark 的货箱上贴着一张手写标签，写明目的地是河林的爆破引线港。地图标出一处东南海岸，位于一座四面环水的神庙以北，附近还有带翅膀的生物。标签警告，未经监督不得打开货箱，并注明由 Friz 接收。"}},faq={{q="这只货箱属于谁？",a="标签上写着，货箱属于 Friz Frazzlespark。",al={"货箱主人","谁拥有它"}},{q="我该把货箱送到哪里？",a="标签要求将货箱送到河林的爆破引线港，交给 Friz Frazzlespark。",al={"货箱送货地点","货箱递送"}},{q="货箱上的标签写了什么？",a="标签注明了 Friz Frazzlespark 和爆破引线港，警告未经监督不得打开货箱，并写明了河林的送还地点。",al={"货箱标签","上面写了什么"}},{q="可以安全地打开货箱吗？",a="标签写着，未经监督不得打开货箱。",al={"打开货箱","货箱警告"}}},fp="19,137,14.300.0,28.55.0,30.94.0,32.153.0,26.50.0"}
P.entries["quest:94842"] = {n="Unsavory Plant Food",s="伐木队需要制作肥料的原料，Halligan 特纳需要你帮忙收集小龙虾壳、粪肥和Mudfin Murloc Heads。",h="伐木队需要制作肥料的原料，Halligan 特纳需要你帮忙收集小龙虾壳、粪肥和Mudfin Murloc Heads。",kw={"小龙虾壳","肥料","新鲜粪肥","halligan 特纳","jumbo crawfish shells","伐木","mudfin murloc heads","植物肥料"},sec={{t="收集原料",b="Halligan 特纳说，伐木队用小龙虾壳、粪肥和鱼人头颅自制肥料。粪肥来自南边的一处牧场，小龙虾壳和鱼人头颅则在河里。开始种植前，他需要四个Jumbo Crawfish Shells、四份Fresh Manure和八个Mudfin Murloc Heads。"}},faq={{q="Halligan 需要哪些原料？",a="Halligan 需要四个Jumbo Crawfish Shells、四份Fresh Manure和八个Mudfin Murloc Heads。",al={"肥料原料","halligan 需要什么"}},{q="肥料由什么制成？",a="伐木队的肥料由小龙虾壳、粪肥和鱼人头颅按一比一比二的比例制成。",al={"肥料的成分","植物肥料原料"}},{q="粪肥来自哪里？",a="Halligan 说，粪肥来自南边的一处牧场。",al={"粪肥位置","粪肥从哪里找"}},{q="小龙虾壳和鱼人头颅在哪里？",a="Halligan 说，你得涉水进入河里收集小龙虾壳和鱼人头颅。",al={"小龙虾壳位置","mudfin 头颅在哪里"}},{q="谁需要这些原料？",a="Halligan 特纳需要这些原料，为伐木队制作肥料。",al={"谁需要植物肥料","halligan 特纳"}}},fp="19,147,21.321.0,36.102.0,33.105.0,32.57.0,38.78.0,36.80.0"}
P.entries["quest:94843"] = {n="From Seed to Sprout",s="Halligan 特纳用你提供的肥料制作了一套种植工具。他请你在伐木营地的作业地点周围种下树苗。",h="Halligan 特纳用你提供的肥料制作了一套种植工具。他请你在伐木营地的作业地点周围种下树苗。",kw={"肥料","从种子到新芽","halligan 特纳","伐木营地","种植工具","树苗","种子","作业地点"},sec={{t="播种新苗",b="伐木工人在林间劳作时，Halligan 特纳收集了一些种子。他用你带来的肥料制作了一套工具，用来播种并培育树苗。他请你在作业地点周围找些地方把种子种下。"}},faq={{q="谁制作了种植工具？",a="Halligan 特纳用你提供的肥料制作了种植工具。",al={"谁制作了工具","halligan的工具"}},{q="工具里有什么？",a="这套工具用来播种从树上收集的种子，并将它们培育成树苗。",al={"工具内容","什么工具"}},{q="我该在哪里种树苗？",a="Halligan 请你在伐木营地的作业地点周围种下树苗。",al={"种植地点","树苗种植点"}},{q="他们为什么要种树苗？",a="伐木工人砍伐树木，并在原地种植新树。",al={"为何种树苗","种植原因"}}},fp="19,142,14.243.0,26.72.0,19.85.0,34.70.0,31.61.0"}
P.entries["quest:94857"] = {n="If a Tree Falls, and No One Hears...",s="一名被困的伐木工请你去特纳伐木营地求援。他担心继续被困会失血而死，或被野兽吃掉。",h="一名被困的伐木工请你去特纳伐木营地求援。他担心继续被困会失血而死，或被野兽吃掉。",kw={"意外","帮助","如果一棵树倒下","伐木营地","伐木工","被困","特纳伐木营地"},sec={{t="求救",b="一名伐木工因意外被困在事故现场。他请你前往特纳伐木营地求援，赶在他失血过多或被野兽发现之前带人来帮忙。"}},faq={{q="谁被困了？",a="附近伐木营地的一名伐木工因意外被困。",al={"被困的伐木工","需要帮助的人","受伤的工人"}},{q="他需要什么帮助？",a="他请你去特纳伐木营地求援。",al={"如何帮助他","帮助被困的人","他需要什么"}},{q="他为何身处险境？",a="他说，若继续被困，自己可能会失血而死，或被野兽吃掉。",al={"为何被困","他受伤了吗","伐木工出了什么事"}}},fp="36,131,15.156.0,15.71.0,23.53.0,20.73.0"}
P.entries["quest:94858"] = {n="All That's Left",s="暮光之锤袭击后，农夫 Elbrim 请你搜寻附近的谷仓，找回他家人留下的遗物。他希望能把他们带回家，安葬在自己身边。",h="暮光之锤袭击后，农夫 Elbrim 请你搜寻附近的谷仓，找回他家人留下的遗物。他希望能把他们带回家，安葬在自己身边。",kw={"仅存之物","谷仓","安葬","家人","农夫 elbrim","物品","暮光之锤"},sec={{t="家人的遗物",b="Elbrim 无法鼓起勇气走进谷仓。袭击期间，他把那些无力自卫的家人藏在那里。他请你找出家人的物品并带回来。他想知道还剩下什么，也希望能在家中与他们一同安葬。"}},faq={{q="是谁请我搜寻谷仓？",a="农夫 Elbrim 请你到附近的谷仓寻找他家人的物品。",al={"谁让我去谷仓","农夫 elbrim","是谁交代的"}},{q="Elbrim 的家人遭遇了什么？",a="暮光之锤袭击期间，Elbrim 把无力自卫的家人藏在谷仓里。他请你寻找他们的物品，却不知道还剩下什么。",al={"elbrim 的家人","谷仓发生了什么","家人遇袭"}},{q="Elbrim 为什么把他们藏在谷仓里？",a="Elbrim 把无力自卫的家人安置在谷仓里，因为他觉得那里很安全。",al={"为什么是谷仓","他把他们藏在哪","elbrim 藏人"}},{q="Elbrim 要我找什么？",a="Elbrim 请你到附近的谷仓寻找他家人的物品，并把它们带回来。",al={"我要找什么","谷仓里的东西","寻找家人的物品"}},{q="Elbrim 想把家人安葬在哪里？",a="Elbrim 希望能在家中与家人一同安葬。",al={"家人安葬在哪里","家人安葬","一同安息"}}},fp="15,163,20.264.0,36.78.0,33.168.0,37.95.0,33.91.0,41.55.0"}
P.entries["quest:94861"] = {n="Helping Hands",s="Hurley需要你帮忙救回Curly。他午休后一直没有回来，Hurley担心已经所剩时间不多。",h="Hurley需要你帮忙救回Curly。他午休后一直没有回来，Hurley担心已经所剩时间不多。",kw={"curly","援手相助","hurley","午休","失踪的工人","救curly"},sec={{t="Hurley的忧虑",b="Curly午休后没有回来，这让Hurley十分担心。他请你和他一起去救回这名失踪的工人，也担心时间所剩不多。Curly虽然有些愚笨，却是个好工人。Hurley希望他能好好康复，也学会懂点事。"}},faq={{q="Curly是谁？",a="Curly是一名午休后没有回来的工人。Hurley称他是个好工人，不过也觉得他有些愚笨。",al={"curly是谁","谁是curly","curly的来历"}},{q="谁请求帮忙救Curly？",a="Hurley请你和他一起去救Curly。",al={"谁需要帮忙","帮助curly","hurley请求"}},{q="Hurley为什么担心？",a="Curly午休后没有回来，Hurley担心已经所剩时间不多，恐怕来不及救他。",al={"为何担心","curly失踪","curly在哪里"}},{q="Hurley希望Curly怎么样？",a="Hurley希望Curly能好好康复，也学会懂点事。",al={"curly的结局","curly会康复吗","curly康复"}}},fp="13,123,18.248.0,13.120.0,31.46.0,22.85.0,32.52.0"}
P.entries["quest:94863"] = {n="Taming the Beast",s="“驯服野兽”是一项由Josephine Carson监督的猎人训练课程。在学习了驯服野猪的野兽掌控基础知识后，有抱负的猎人必须使用驯兽棒来赢得一只更凶猛的灰森林狼的信任。",h="“驯服野兽”是一项由Josephine Carson监督的猎人训练课程。在学习了驯服野猪的野兽掌控基础知识后，有抱负的猎人必须使用驯兽棒来赢得一只更凶猛的灰森林狼的信任。",kw={"野兽驯服","灰森林狼","猎人","猎人训练","约瑟芬·卡森","驯兽棒","驯服野兽"},ang={["class:Hunter"]="这项训练标志着猎人成长过程中的重要仪式，教会了猎人与荒野中凶猛的掠食者交流所需的耐心与尊重。"},sec={{t="猎人之道",b="猎人与荒野的联系不仅仅需要追踪和射击技巧，更需要赢得野生生物信任所需的尊重与耐心。在通过简单的野猪证明了自己的基础技能后，有抱负的猎人们将面临一项更严峻的挑战：深入森林，驯服一只灰森林狼。在训练师Josephine Carson的注视下，猎人将被授予一根附魔的驯兽棒，用以安抚这只掠食者，并学习猎人与野兽之间微妙的平衡。"},{t="本能与信任的考验",b="Josephine Carson为猎人提供了一根特制的驯兽棒，旨在引导一种能够让猎人接近危险野生动物的安抚力量。这项任务需要耐心和精确，因为必须在不使用致命武力的情况下接近狼，并温和地克服其天生的攻击性。一旦建立了联系，且猎人证明了自己能够与野兽的精神和谐相处，驯兽棒就会归还给Josephine，作为猎人对荒野掌控力日益增强的证明。"}},faq={{q="什么是“驯服野兽”任务？",a="“驯服野兽”是一项猎人训练试验，训练师会要求有抱负的猎人使用附魔的驯兽棒追踪并驯服一只灰森林狼。",al={"驯服野兽任务","灰森林狼任务","驯狼课程"}},{q="谁发布并完成这个任务？",a="约瑟芬·卡森担任这项试验的指导员。她提供驯兽棒，并在任务完成后评估你与森林野兽之间的联系，随后收回驯兽棒。",al={"谁发布驯服野兽","约瑟芬·卡森是谁","驯服野兽交任务地点"}},{q="你需要驯服什么生物？",a="你的任务是驯服一只灰森林狼，这比你之前练习驯服的野猪更进一步，难度也更高。",al={"我要驯服什么","什么野兽","驯服野兽的目标"}},{q="驯兽棒有什么用？",a="驯兽棒是约瑟芬·卡森提供的一种教学工具，旨在帮助见习猎人安抚野生的灰森林狼并与之建立临时的联系，而不会造成永久性的伤害。",al={"驯兽棒的作用","为什么要用驯兽棒","驯兽棒背景故事"}},{q="猎人在这次试验前驯服了什么？",a="在面对灰森林狼之前，你通过掌握如何驯服一只森林野猪，展示了你对野兽掌控的初步能力。",al={"之前的驯服课程","在狼之前驯服了什么"}},{q="灰森林狼会成为永久的伙伴吗？",a="不会，这项试验旨在作为掌握野兽羁绊技巧的集中课程。当你练习完技巧后，需要将驯兽棒归还给约瑟芬·卡森。",al={"狼会保留吗","狼是永久宠物吗"}}},fp="16,174,22.331.0,28.279.0,35.112.0,35.99.0,34.107.0,32.133.0,43.73.0,58.94.0"}
P.entries["quest:94864"] = {n="驯服野兽",s="驯服野兽是猎人在艾尔文森林初期训练的最终考验，由约瑟芬·卡森负责监督。在证明了驯服野猪和狼的能力后，猎人们需要使用驯兽棒来安抚一头森林幼熊，并赢得它的信任。这项最终试炼加深了猎人与野兽之间的协调，并通过尊重与技巧来维护林地的自然平衡。",h="驯服野兽是猎人在艾尔文森林初期训练的最终考验，由约瑟芬·卡森负责监督。在证明了驯服野猪和狼的能力后，猎人们需要使用驯兽棒来安抚一头森林幼熊，并赢得它的信任。这项最终试炼加深了猎人与野兽之间的协调，并通过尊重与技巧来维护林...",kw={"与野兽协调","野兽训练","艾尔文森林","猎人任务","约瑟芬·卡森","驯兽棒","驯服野兽","森林幼熊"},ang={["class:Hunter"]="这项试炼标志着学徒猎人的一个重要成年仪式，将简单的追踪技巧转化为与荒野野兽之间深刻的共情与协调。",["faction:Alliance"]="熟练的兽王猎人加强了联盟的荒野侦察力量，他们提供的训练有素的同伴能够保卫家园并巡逻暴风城领地内的贸易道路。",["race:Human"]="对于在艾尔文森林训练的人类猎人来说，驯服当地野生生物教会了他们与王国的天然掠食者共存的重要性，而不是仅仅将其消灭。"},sec={{t="狩猎的最终试炼",b="艾尔文森林的准猎人们需要接受严格的训练，以了解与他们共享这片土地的野生生物。在已经展示了对狡猾的狼和强韧的野猪的控制力后，猎人们将面临勇气与耐心的终极测试。约瑟芬·卡森指导他们去面对森林幼熊，这是森林中最强壮、最威猛的常见掠食者。这项仪式旨在考验猎人能否承受熊的原始力量，并赢得它的信任，而不是单纯的征服。"},{t="艾尔文森林的尊重与平衡",b="驯服艾尔文森林野生生物的课程核心在于尊重，而非支配。森林熊代表了林地的力量与活力，在维护自然秩序方面发挥着至关重要的作用。通过使用专门制作的驯兽棒，猎人学会了平息野兽的侵略性，并建立起一种真正的相互理解的纽带。成功安抚这种强大的动物不仅能加深猎人对荒野的精神协调，也完成了他们在卡森指导下的基础课程。"}},faq={{q="是谁向猎人指派这项试炼的？",a="约瑟芬·卡森负责监督艾尔文森林猎人的这项试炼。在猎人成功驯服次级野兽后，她会对猎人的进度进行评估，并提供驯服森林熊所需的指导和驯兽棒。试炼完成后，猎人会直接将棒子交还给她，以标志训练的圆满完成。",al={"谁给予驯服野兽任务","驯服野兽任务发布者","约瑟芬·卡森任务"}},{q="在挑战这项试炼之前必须驯服哪些野兽？",a="在进行驯服森林幼熊的挑战之前，猎人必须先通过驯服野猪和狼来证明自己的技巧与耐心。这些初步试炼证明了猎人在尝试面对艾尔文森林熊的强大力量之前，已经能够应对好斗的野兽和群体性野兽。",al={"驯服任务的前置野兽","驯服熊之前驯服什么","在此之前驯服的野兽"}},{q="为什么要让猎人去寻找森林幼熊？",a="森林幼熊代表了艾尔文森林野生生物的力量与威猛。野猪和狼测试了猎人处理敏捷或顽强野兽的能力，而熊则是对忍耐力、尊重和身体勇气的终极考验。赢得这种强大掠食者的信任，证明了猎人已经完全掌握了基础的野兽驯服技巧。",al={"为什么驯服森林幼熊","森林幼熊的目的","为什么艾尔文有熊"}},{q="驯兽棒的用途是什么？",a="驯兽棒是约瑟芬·卡森提供的一种特殊训练工具，用于帮助猎人安抚野生动物。它能引导猎人集中精神，在不杀死森林幼熊的情况下平息其攻击性，从而建立起和平的纽带。试炼结束后，随着训练完成，驯兽棒会被交还给卡森。",al={"驯兽棒的作用","驯兽棒的功能","为什么要使用驯兽棒"}},{q="驯服野兽如何帮助艾尔文森林？",a="驯服野生生物被视为维护艾尔文森林自然平衡的一项必要实践。通过以尊重和克制而非狩猎的方式对待掠食者，猎人有助于保护当地生态系统与整个地区的人类定居点之间的和谐，确保危险的野兽得到和平引导，而不是被消灭。",al={"为什么艾尔文的平衡很重要","艾尔文森林平衡","驯服与森林平衡"}},{q="完成这门课程对猎人意味着什么？",a="完成这项最终任务加深了猎人与荒野野兽之间内在的协调。通过赢得艾尔文森林最强大生物的信任，猎人超越了简单的狩猎技巧，掌握了与艾泽拉斯各地的动物同伴建立终身伙伴关系所需的精神连接。",al={"驯服熊之后会发生什么","猎人训练完成","与野兽协调的意义"}},{q="在哪里可以找到森林幼熊？",a="森林幼熊在艾尔文森林的林区中游荡，与狼和蜘蛛一起生活在茂密的树林中。从附近定居点出发的猎人必须在森林的灌木丛中追踪这些强壮的生物，以便使用驯兽棒并完成卡森的最终指令。",al={"森林幼熊位置","在艾尔文哪里找熊","艾尔文森林熊"}}},fp="16,291,27.363.0,29.396.0,34.219.0,49.184.0,47.224.0,38.240.0,42.245.0,54.219.0,35.246.0"}
P.entries["quest:94872"] = {n="Buying Friendship: 玛格拉姆",s="你因担忧玛格拉姆的实力，决定在玛格拉姆村献上雕刻图腾。这份礼物或许能让部族成为盟友。",h="你因担忧玛格拉姆的实力，决定在玛格拉姆村献上雕刻图腾。这份礼物或许能让部族成为盟友。",kw={"半人马","凄凉之地","友谊","gorhak","玛格拉姆","玛格拉姆村","军需官","图腾"},sec={{t="献给 Gorhak 的礼物",b="有人担心玛格拉姆日益强大，便请你把一袋图腾送给他们的军需官 Gorhak。部族的村庄正在扩大，士兵也愈发大胆。派你来的人对此心存忧虑，但玛格拉姆或许能成为盟友。"},{t="抵达村庄",b="在凄凉之地的玛格拉姆村，Gorhak 收下雕刻图腾，也看出你的礼物另有目的。他不知道你想从他或部族那里得到什么。眼下，他欢迎你这位外来者。"}},faq={{q="我为什么要给玛格拉姆送图腾？",a="有人担心玛格拉姆日益强大，希望这份礼物能赢得他们的信任，让他们有望成为盟友。",al={"图腾缘由","玛格拉姆礼物","购买友谊"}},{q="Gorhak 是谁？",a="Gorhak 是玛格拉姆村的玛格拉姆军需官。",al={"gorhak 是谁","玛格拉姆军需官","图腾送货人"}},{q="我该把图腾送到哪里？",a="把这袋雕刻图腾送到凄凉之地玛格拉姆村的玛格拉姆军需官那里。",al={"图腾送往何处","玛格拉姆村位置"}},{q="Gorhak 对这份礼物怎么看？",a="Gorhak 看出这份礼物另有目的，但仍然欢迎你来到玛格拉姆村。",al={"gorhak 的反应","他收下图腾吗","玛格拉姆欢迎"}},{q="人们为什么担心玛格拉姆？",a="玛格拉姆的村庄正在扩大，士兵也愈发大胆，因此人们担心这个部族的实力。",al={"玛格拉姆壮大","玛格拉姆威胁","担忧缘由"}}},fp="25,131,18.270.0,14.195.1,39.116.0,14.53.0,28.90.0,35.102.0,40.110.0"}
P.entries["quest:94873"] = {n="Buying Friendship: 吉尔吉斯",s="一名外来者在吉尔吉斯村送给吉尔吉斯氏族一包图腾。他们的军需官认为这份礼物能帮助他们对抗玛格拉姆氏族。",h="一名外来者在吉尔吉斯村送给吉尔吉斯氏族一包图腾。他们的军需官认为这份礼物能帮助他们对抗玛格拉姆氏族。",kw={"购买友谊","半人马","吉尔吉斯","吉尔吉斯氏族","吉尔吉斯村","玛格拉姆","molkar","图腾包"},sec={{t="送给吉尔吉斯人的礼物",b="有人准备了一包图腾，让你带给吉尔吉斯村的吉尔吉斯军需官。吉尔吉斯人正被玛格拉姆人步步逼退，他们与世隔绝的处境或许会让他们愿意接受外界的帮助。这份礼物旨在提升你在氏族中的声望。"}},faq={{q="为什么要给吉尔吉斯人送一包图腾？",a="这份礼物旨在提升你在吉尔吉斯氏族中的声望，而他们正被玛格拉姆人步步逼退。",al={"图腾包","为何送图腾","吉尔吉斯人的礼物"}},{q="这包图腾要交给谁？",a="吉尔吉斯村的吉尔吉斯军需官会收下这包图腾。",al={"吉尔吉斯军需官","谁收下图腾包","图腾接收者"}},{q="吉尔吉斯人面临什么困境？",a="吉尔吉斯人正处于对抗玛格拉姆人的劣势一方，而玛格拉姆氏族一反常态地凶残。",al={"吉尔吉斯人的困境","玛格拉姆与吉尔吉斯","为何落败"}},{q="Molkar是谁？",a="Molkar是收下这包图腾的吉尔吉斯军需官。",al={"吉尔吉斯人molkar","军需官molkar","molkar是谁"}}},fp="25,137,21.259.0,38.102.0,22.61.0,32.92.0,14.57.0"}
P.entries["quest:94877"] = {n="Saving Sunnyglade",s="Demar Brant请你将暮光之锤势力赶出阳光林地。这座Farholde西北部的聚居地里，居民失去了家园，暴风城也很少伸出援手。",h="Demar Brant请你将暮光之锤势力赶出阳光林地。这座Farholde西北部的聚居地里，居民失去了家园，暴风城也很少伸出援手。",kw={"demar brant","farholde","难民","拯救阳光林地","阳光林地","暮光新兵","暮光劫掠者","暮光暗影法师","暮光之锤"},sec={{t="失落的聚居地",b="Demar Brant代表着Farholde疲惫不堪的居民，其中包括一些遭遇不幸、却与家人失散的难民。暴风城任由他们依靠日渐匮乏的资源勉强度日。暮光之锤占领了西北部的一处聚居地，Demar请求你将他们赶出阳光林地。"}},faq={{q="谁在求助？",a="Demar Brant请你将暮光之锤势力赶出阳光林地。",al={"demar是谁","demar brant","是谁发出的请求"}},{q="阳光林地发生了什么？",a="暮光之锤占领了Farholde西北部的一处聚居地。",al={"这里发生了什么","阳光林地失守","谁占领了阳光林地"}},{q="Farholde的居民是什么人？",a="许多居民是遭遇不幸、却与家人失散的难民。",al={"farholde居民","谁住在那里","难民"}},{q="Demar为何需要帮助？",a="Farholde的一处聚居地被暮光之锤占领，居民也已无力自保。",al={"为何帮助demar","为何战斗","出了什么问题"}}},fp="17,188,17.280.0,23.71.0,28.64.0,31.61.0,25.114.0"}
P.entries["quest:94879"] = {n="Scraps of Knowledge",s="Ashe Amberall请你在阳光林地搜寻暮光之锤的文件。她希望这些文件能揭示这个教派的意图。",h="Ashe Amberall请你在阳光林地搜寻暮光之锤的文件。她希望这些文件能揭示这个教派的意图。",kw={"ashe amberall","demar","文件","法霍德要塞","知识碎片","阳光林地","twilight pages","暮光之锤"},sec={{t="阳光林地的书页",b="Ashe Amberall从法霍德要塞眺望北方的废墟之城阳光林地。Demar已派出部队，但这座城市仍无力挽回。Ashe相信暮光之锤曾发动过袭击，并在某个中心地点统筹行动。她请你在阳光林地寻找遗失的文件，希望找到足够多的书页，拼凑出这个教派的意图。"}},faq={{q="谁想要暮光书页？",a="法霍德要塞的Ashe Amberall请你寻找Twilight Pages。",al={"谁想要这些书页","ashe的书页","谁委托了我"}},{q="我该去哪里找这些书页？",a="Ashe请你在阳光林地内寻找Twilight Pages。",al={"书页在哪里","阳光林地文件","寻找twilight pages"}},{q="Ashe希望了解什么？",a="Ashe希望这些文件能帮助她拼凑出暮光之锤的意图。",al={"ashe想了解什么","为何寻找书页","暮光计划"}},{q="Ashe为何打听暮光之锤？",a="Ashe认为阳光林地遭受的袭击并非暮光之锤第一次出手，并怀疑这个教派在某个中心地点统筹行动。",al={"为何打听暮光之锤","教派袭击","之前发生过什么"}}},fp="19,131,19.381.0,29.67.0,34.61.0,29.89.0,47.132.0"}
P.entries["quest:94881"] = {n="Curious Trinkets",s="法霍德要塞的 Ashe Amberhall 请你把阳光林地邪教徒的附魔护符带给她，以便了解这个邪教。她相信这些信物能揭示邪教的某些魔法。",h="法霍德要塞的 Ashe Amberhall 请你把阳光林地邪教徒的附魔护符带给她，以便了解这个邪教。她相信这些信物能揭示邪教的某些魔法。",kw={"ashe amberhall","邪教","奇特的小玩意","法霍德要塞","阳光林地","暮光护符","暮光 neophyte","暮光 shadowmancer"},ang={["class:Druid"]="身为德鲁伊，Ashe 认为你或许能帮她调查阳光林地的邪教。"},sec={{t="法霍德的请求",b="Ashe Amberhall 想研究阳光林地的邪教，那里有些成员因魔法造诣而受到青睐并获得信物。她相信这些护符带有邪教徒的魔法。因此，她请你把从暮光 Shadowmancers 和暮光 Neophytes 身上取得的护符带给她。"}},faq={{q="谁在索要护符？",a="法霍德要塞的 Ashe Amberhall 想要研究邪教的护符。",al={"谁想要护符","ashe amberhall","ashe 的请求"}},{q="Ashe 为什么想要护符？",a="Ashe 想进一步了解阳光林地的邪教，并相信邪教的护符蕴含着邪教徒的魔法。",al={"为什么要护符","护符有什么用","ashe 想要信物"}},{q="暮光护符是什么？",a="这是赠予对魔法有亲和力的邪教成员的信物，随后会被注入邪教徒的魔法。",al={"暮光护符","邪教信物","魔法护符"}},{q="谁带着这些护符？",a="阳光林地的暮光 Shadowmancers 和暮光 Neophytes 带着 Ashe 想要的护符。",al={"哪里能找到护符","shadowmancers 的护符","neophytes 的信物"}}},fp="16,184,21.250.0,29.71.0,30.97.0,25.97.0,23.88.0"}
P.entries["quest:94885"] = {n="元帅的日志",s="Field Marshal's Log记录了暮光之锤在河林的行动。它的下落或许能帮助法霍德的人了解敌军动向。",h="Field Marshal's Log记录了暮光之锤在河林的行动。它的下落或许能帮助法霍德的人了解敌军动向。",kw={"demar brant","敌军动向","farholde","元帅日志","field marshal's log","河林","阳光林地","暮光之锤"},sec={{t="Field Marshal's Log",b="法霍德要塞的Demar Brant正在等待Field Marshal's Log。日志记录了暮光之锤部队在河林的行动，而法霍德有人想看看这些记录。作者下落不明。这些笔记或许能揭示敌军曾在哪里活动。"},{t="Farholde的忧虑",b="Demar Brant说，这些笔记送到得太晚了。法霍德早已知道阳光林地中的危险，而你也在那里发现了这些笔记，这让他忧心忡忡。"}},faq={{q="Field Marshal's Log里记载了什么？",a="日志记录了暮光之锤部队在河林各处的行动。",al={"元帅日志","日志记载了什么"}},{q="谁写了这份日志？",a="Field Marshal's Log的作者下落不明。",al={"日志作者","谁写了这些笔记"}},{q="谁想看看这份日志？",a="法霍德有人想看看这份日志。有人请你将它送到法霍德要塞交给Demar Brant。",al={"谁要这份日志","demar brant的日志"}},{q="这份日志为何重要？",a="其中关于暮光之锤行动的记录或许有助于了解敌军动向。",al={"为何要送日志","敌军动向"}},{q="暮光之锤部队曾在哪里活动？",a="日志记录了暮光之锤部队在河林各处的行动。",al={"暮光之锤河林","他们曾在哪里"}}},fp="19,155,7.280.0,18.153.1,35.94.0,18.61.0,25.102.0,24.82.0,47.68.0"}
P.entries["quest:94886"] = {n="The Western Front",s="Farholde的巡逻队在西部边境失踪了。Amberhall女士的调查结果指向暮光重型钉锤营地，因此你受命前往暮光之帷附近寻找Sergeant Riftan。",h="Farholde的巡逻队在西部边境失踪了。Amberhall女士的调查结果指向暮光重型钉锤营地，因此你受命前往暮光之帷附近寻找Sergeant Riftan。",kw={"farholde","amberhall女士","失踪的巡逻队","sergeant riftan","阳光林地","暮光重型钉锤","暮光之帷","西部边境","西部前线"},sec={{t="失踪的巡逻队",b="Farholde的一支巡逻队在西部边境失踪，Sergeant Riftan也下落不明。Amberhall女士的调查结果令人担忧：巡逻队可能已抵达暮光重型钉锤的中央营地。你受命前往西边的暮光之帷附近寻找Riftan。"}},faq={{q="谁失踪了？",a="Farholde的一支巡逻队在西部边境失踪了。你受命寻找Sergeant Riftan。",al={"失踪的巡逻队","riftan在哪里","失踪的军士长"}},{q="我该去哪里寻找Sergeant Riftan？",a="Sergeant Riftan就在西边的暮光之帷附近。",al={"riftan的位置","寻找riftan","军士长在哪里"}},{q="巡逻队为何失踪？",a="Amberhall女士的调查结果让Farholde担心，巡逻队误入了暮光重型钉锤的中央营地。",al={"巡逻队发生了什么","巡逻队为何失踪","暮光重型钉锤巡逻队"}},{q="Amberhall女士是谁？",a="Amberhall女士的调查结果令人担忧：巡逻队可能已抵达暮光重型钉锤的中央营地。",al={"amberhall","amberhall女士的情况","amberhall女士是谁"}},{q="阳光林地发生了什么事？",a="Farholde表示，阳光林地的清理工作由他们自行处理；你则受命查看Sergeant Riftan的情况。",al={"阳光林地的麻烦","阳光林地的清理工作","阳光林地有什么事"}}},fp="17,204,16.283.0,15.105.0,40.58.0,26.112.0,22.121.0,32.110.0"}
P.entries["quest:94887"] = {n="Saving Marshal Ryan",s="联盟需要找到 Marshal Ryan，他是联盟最出色的斥候之一。他最后的报告指向西边一座暮光之锤要塞，而他的日志或许能提供更多线索。",h="联盟需要找到 Marshal Ryan，他是联盟最出色的斥候之一。他最后的报告指向西边一座暮光之锤要塞，而他的日志或许能提供更多线索。",kw={"联盟","日志","marshal ryan","失踪的元帅","营救 marshal ryan","暮光之锤","暮光之帷"},ang={["faction:Alliance"]="作为联盟成员，你正在协助寻找 Marshal Ryan。他的报告对战争行动至关重要。"},sec={{t="失踪的元帅",b="Marshal Ryan 最后的报告显示，他在西边一座暮光之锤要塞附近。你奉命前往暮光之帷寻找他，并带上他的日志。联盟倚重他敏锐的目光和可靠的情报，而他的报告或许能帮助查明他的下落。"}},faq={{q="Marshal Ryan 是谁？",a="Marshal Ryan 是联盟最优秀的成员之一，以敏锐的目光和可靠的情报而备受重视。",al={"marshal ryan 是谁","ryan 是谁"}},{q="Marshal Ryan 在哪里？",a="联盟正在暮光之帷寻找 Marshal Ryan，他在西边一座暮光之锤要塞附近。",al={"ryan 在哪里","寻找 marshal ryan"}},{q="Ryan 为什么失踪了？",a="他最后的报告提到西边一座暮光之锤要塞，而联盟至今没有找到他。",al={"ryan 为何失踪","marshal ryan 遭遇了什么"}},{q="联盟为什么想要他的日志？",a="Marshal Ryan 的日志或许能提供有关他下落的线索。",al={"ryan 的日志有什么用","日志里有什么"}}},fp="19,173,19.277.0,20.95.0,22.99.0,20.104.0,39.58.0"}
P.entries["quest:94890"] = {n="Bring Me His Head",s="军士长Riftan派你重返暮光之帷，霸主Kilgar仍藏身于他的要塞中。获救的士兵已准备好战斗，Riftan要你击败Kilgar。",h="军士长Riftan派你重返暮光之帷，霸主Kilgar仍藏身于他的要塞中。获救的士兵已准备好战斗，Riftan要你击败Kilgar。",kw={"把他的头带给我","兽人","霸主kilgar","获救的士兵","军士长riftan","暮光之帷"},sec={{t="重返要塞",b="获救的士兵跃跃欲试，军士长Riftan说，你的力量助攻势推进至今。兽人霸主Kilgar藏身于暮光之帷的要塞深处。Riftan要你击败他，把他的头带回来。"}},faq={{q="霸主Kilgar是谁？",a="霸主Kilgar是兽人首领，藏身于暮光之帷的要塞深处。",al={"kilgar","kilgar是谁","兽人首领"}},{q="为什么要我重返暮光之帷？",a="获救的士兵已准备好战斗，军士长Riftan说攻势应当继续。他要你返回暮光之帷，把霸主Kilgar的头带回来。",al={"为何返回","暮光之帷任务","接下来做什么"}},{q="谁要Kilgar的头？",a="军士长Riftan要你把霸主Kilgar的头带给他。",al={"riftan要什么","谁要杀kilgar","把他的头带给我"}},{q="Kilgar藏在哪里？",a="霸主Kilgar藏身于暮光之帷的要塞深处。",al={"kilgar的位置","霸主在哪里","kilgar的要塞"}}},fp="17,185,16.255.0,23.86.0,50.180.0,24.61.0,23.72.0"}
P.entries["quest:94891"] = {n="News to Farholde",s="法霍德要塞的Ashe Amberhall正等着你汇报与Sergeant Riftan共事的结果。你的归来将证明这次行动是否成功。",h="法霍德要塞的Ashe Amberhall正等着你汇报与Sergeant Riftan共事的结果。你的归来将证明这次行动是否成功。",kw={"ashe amberhall","法霍德要塞","kilgar","法霍德的消息","报告","sergeant riftan"},sec={{t="向Ashe汇报",b="Sergeant Riftan让你带着报告回法霍德要塞，交给Ashe Amberhall。他把Kilgar的头交给你带上。Ashe说，你离开期间，她开始怀疑自己的判断，如今却称赞你的本领。"}},faq={{q="该向谁汇报？",a="法霍德要塞的Ashe Amberhall正等着你汇报。",al={"该向谁汇报","ashe的报告","法霍德汇报"}},{q="Riftan给了我什么？",a="Sergeant Riftan把Kilgar的头交给你，让你带给Ashe Amberhall。",al={"riftan扔回了什么","kilgar的头","我带着什么"}},{q="我回来时Ashe说了什么？",a="Ashe说，她开始担心自己看错了你的本领，随后又说你确实适合这份差事。",al={"amberhall的反应","ashe的对话","ashe是否担心"}},{q="Ashe怎么评价Riftan？",a="Ashe问Riftan是否还在附近，并说她原以为你们俩会相处融洽。",al={"riftan还活着吗","sergeant riftan怎么样了","ashe和riftan"}}},fp="16,141,17.222.0,21.59.0,25.66.0,33.98.0,32.84.0"}
P.entries["quest:94892"] = {n="Dying Wish",s="Ryan元帅濒临死亡，请你将他的纹章带给骑士指挥官Demar Brant。他最后的话语转向了家乡和Abigail。",h="Ryan元帅濒临死亡，请你将他的纹章带给骑士指挥官Demar Brant。他最后的话语转向了家乡和Abigail。",kw={"abigail","纹章","遗愿","法霍德要塞","骑士指挥官demar brant","ryan元帅","ryan"},sec={{t="Ryan的遗言",b="Ryan的目光渐渐黯淡，他提起家乡和Abigail。元帅把纹章交给你，请你警告骑士指挥官Demar Brant。你带着象征他军衔的纹章前往法霍德要塞，指挥官正在那里等候。"}},faq={{q="谁濒临死亡？",a="Ryan元帅濒临死亡时，请你把他的纹章带给骑士指挥官Demar Brant。",al={"遗愿 谁","ryan元帅"}},{q="Ryan要我做什么？",a="Ryan请你把他的纹章带给骑士指挥官Demar Brant，并警告他。",al={"ryan的请求","纹章怎么处理"}},{q="Abigail是谁？",a="Ryan的遗言提到了Abigail，并说他本该回家。",al={"abigail ryan","abigail是谁"}},{q="我该把纹章带到哪里？",a="把Ryan元帅的纹章带给法霍德要塞里的骑士指挥官Demar Brant。",al={"纹章在哪","demar brant位置"}}},fp="10,132,19.218.0,13.89.0,29.78.0,15.68.0,26.75.0"}
P.entries["quest:94893"] = {n="Delivering Closure",s="Demar请你把元帅 Ryan 的徽章交给暴风城的 Abigail Lawson。Ryan 的死留下了一封信，写给他曾打算迎娶的女人。",h="Demar请你把元帅 Ryan 的徽章交给暴风城的 Abigail Lawson。Ryan 的死留下了一封信，写给他曾打算迎娶的女人。",kw={"abigail lawson","教堂广场","了结遗憾","demar","法霍德要塞","元帅 ryan","ryan 的徽章","暴风城"},sec={{t="暴风城的留言",b="Abigail Lawson 在教堂广场等候，你替 Demar 把元帅 Ryan 的徽章带给她。Ryan 和 Demar 建立法霍德要塞时，她没有加入他们。Ryan 和 Abigail 曾有分歧，但 Demar 不知道原因。他认为自己若在场，她不会欢迎，因此只能让徽章代他传达心意。"},{t="未曾说出口的话",b="Ryan的家人在兽人入侵期间丧生，他对抗部落的责任感也因此变成了仇恨。Abigail曾劝他去暴风城和她及父母一起生活，但Ryan拒绝了。他发誓要留下，直到把兽人赶出家园。此后，Ryan和Abigail再未交谈。"},{t="收下徽章",b="你带来徽章时，Abigail 谈起 Ryan 不肯离开家园，也谈起他们之间漫长的沉默。她称 Demar 是英雄，却提醒你，英雄常会给身边的人带来危险。随后，她将 Ryan 的徽章紧紧握在胸前，骂他是个傻瓜。"}},faq={{q="Abigail Lawson 是谁？",a="Abigail Lawson 曾与元帅 Ryan 订下婚约。她住在暴风城，Ryan 和 Demar 在法霍德要塞时，她没有加入他们。",al={"abigail 是谁","谁是 abigail","ryan 的未婚妻"}},{q="是谁让我带去 Ryan 的徽章？",a="Demar 请你把元帅 Ryan 的徽章交给暴风城的 Abigail Lawson。他认为她不会欢迎自己在场。",al={"是谁派我来的","demar 的徽章","谁要我送徽章"}},{q="Ryan 为什么留下？",a="Ryan 的家人在兽人入侵期间丧生后，他对抗部落的责任感变成了仇恨。他发誓要留下，直到把兽人赶出自己的家园。",al={"ryan 留下的原因","ryan 和兽人","他的家人"}},{q="Abigail 和 Ryan 为什么不再交谈？",a="Abigail 和 Ryan 曾有分歧，但 Demar 不清楚具体缘由。此后，他们便再也没有交谈。",al={"他们为何不再交谈","abigail 和 ryan","他们的分歧"}},{q="Ryan 的徽章有什么用？",a="Demar 请你把元帅 Ryan 的徽章交给暴风城教堂广场的 Abigail Lawson。",al={"元帅的徽章","ryan 的徽章","我要带什么"}}},fp="18,150,22.324.0,17.293.0,18.252.1,22.126.0,36.131.0,25.162.0,39.102.0,27.101.0"}
P.entries["quest:94894"] = {n="The Twilight Threat",s="Farholde请求暴风城出手，抵御暮光之锤活动的突然增加。你将证据带给伯瓦尔·弗塔根，但联盟还有其他战事需要应对。",h="Farholde请求暴风城出手，抵御暮光之锤活动的突然增加。你将证据带给伯瓦尔·弗塔根，但联盟还有其他战事需要应对。",kw={"伯瓦尔·弗塔根","brant","farholde","部落","kilgar","河林","暴风要塞","暮光之锤"},ang={["faction:Alliance"]="作为联盟冒险者，你将Farholde的证据带给伯瓦尔·弗塔根。Farholde的居民则寻求援助，以对抗暮光之锤和部落。"},sec={{t="Farholde的恳求",b="Amberhall女士听说你与暮光之锤打过交道后，Farholde的居民便向你求助。他们发起行动，意在将部落赶出故土，但邪教徒的活动已急剧增加。他们担心，在Farholde腹背受敌之前，暴风城不会回应他们的请求。你将证据带到暴风要塞，交给伯瓦尔·弗塔根。"},{t="暴风城的答复",b="在暴风要塞，伯瓦尔·弗塔根听取了Farholde传来的警告。他说，联盟已经卷入规模大得多的战争，无法把力量耗费在一个小村庄的私人恩怨上。部落摧毁的家园，比河林一带遭到摧毁的还要多。伯瓦尔认为，Brant很可能不会放下傲气，派骑兵来援助联盟。"}},faq={{q="谁在请求暴风城援助？",a="暮光之锤活动日益猖獗，Farholde因此请求暴风城援助。",al={"谁在求助","farholde的恳求","谁派我来"}},{q="Farholde为何担忧？",a="Farholde担心，如果暴风城不回应他们的请求，他们就会腹背受敌，难以招架。",al={"farholde出了什么事","邪教徒的问题","为何担忧"}},{q="我带着什么证据？",a="你将Kilgar's Head带到暴风要塞，交给伯瓦尔·弗塔根。",al={"什么证据","kilgar的头颅","送交头颅"}},{q="伯瓦尔在听取谁的消息？",a="伯瓦尔·弗塔根收到了Farholde的消息。Farholde发起行动，意在将部落赶出故土。",al={"谁传来消息","farholde的报告","伯瓦尔的问题"}},{q="暴风城为何无法支援Farholde？",a="伯瓦尔说，联盟正在应对规模大得多的战争，没有足够的资源支援Farholde解决私人恩怨。",al={"为何没有援助","暴风城支援","伯瓦尔拒绝"}}},fp="19,175,15.357.0,18.365.1,30.69.0,24.100.0,25.62.0,27.105.0,37.120.0"}
P.entries["quest:94895"] = {n="Lost Shipping Crate",s="Friz Frazzlespark 的货箱从河林的爆破引线港失踪了。标签警告，未经看管不得打开，并请你将货箱归还给 Friz。",h="Friz Frazzlespark 的货箱从河林的爆破引线港失踪了。标签警告，未经看管不得打开，并请你将货箱归还给 Friz。",kw={"货箱标签","货箱地图","friz frazzlespark","遗失的货箱","爆破引线港","河林","警告"},sec={{t="有标记的货箱",b="一张地图和一则警告标明了你带着穿过河林的货箱。标签上写着 Friz Frazzlespark 和爆破引线港的名字，并注明货箱遗失时应送回那里。你正把货箱送回主人手中。"}},faq={{q="谁是货箱的主人？",a="标签上写明，货箱的主人是 Friz Frazzlespark。",al={"货箱主人","谁拥有这个","friz 的货箱"}},{q="我该把货箱送到哪里？",a="货箱应送回河林爆破引线港的 Friz Frazzlespark 手中。",al={"货箱归还地点","货箱目的地","爆破引线港"}},{q="标签上有什么警告？",a="标签警告不得擅自处理货箱，并说明未经看管不得打开。",al={"货箱警告","可以打开吗","打开货箱"}},{q="货箱的地图上标记了什么？",a="地图上，东南方海岸边有一个红圈；它位于一座画得很粗糙、四周环水且有飞翼生物盘旋的神庙以北。",al={"货箱地图","地图上有什么","地图上的红圈"}}},fp="19,188,14.214.0,28.69.0,30.87.0,31.85.0,34.131.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="“Aid For The Refugees”聚焦于班艾萨尔的流离失所的幸存者们，这是一个深藏在影风森林中的定居点，在深夜时分被突然疏散。随着他们的家园坠入天空，周围的荒野也变得太过危险而无法进入，难民们只能依靠勇敢的旅行者来找回他们不得不留下的财物。",h="“Aid For The...",kw={"援助难民","班艾萨尔","财物","伊拉妮","难民","影风森林"},sec={{t="绝望的恳求",b="“Aid for the Refugees”是Ealaane和她流离失所的村民同伴们发出的求助。在险些逃离了深藏于影风森林的家园后，幸存者们聚集在一起，几乎一无所有，希望路过的旅行者能勇闯他们留下的危险之地。"},{t="班艾萨尔的灾难",b="班艾萨尔定居点在深夜遭遇了难以想象的命运，整个村庄突然开始坠入天空。这场怪异而恐怖的灾难只给居民们留下了片刻的逃生时间，迫使他们在周围森林变得充满敌意和危险时，不得不放弃了他们的个人财物。"}},faq={{q="伊兰妮是谁？",a="伊兰妮是班艾萨尔的一名难民，在他们的定居点开始崩塌时，她与其他幸存者一起逃了出来。她请求路过并前往影风森林的冒险者们找回留在废墟中的个人财物。",al={"谁发布了援助难民","援助难民任务发布者","伊拉妮"}},{q="班艾萨尔发生了什么？",a="班艾萨尔是深藏于影风森林中的一处定居点。由于一场突如其来的离奇灾难，其居民最近被迫在深夜进行了疏散。",al={"什么是班艾萨尔","班艾萨尔在哪里","班艾萨尔村"}},{q="村民们为什么要疏散班艾萨尔？",a="疏散行动在深夜突然触发，当时班艾萨尔开始坠入天空。村庄和周围的森林变得太过危险，以至于居民们无法留下或返回。",al={"为什么要疏散班艾萨尔","坠入天空","班艾萨尔灾难"}},{q="村民们为什么要请求找回他们的财物？",a="这场灾难在深夜突然降临，迫使村民们在几乎一无所有的情况下逃命。由于森林和废墟现在充满了危险，他们只能依靠有能力的冒险者来取回留下的东西。",al={"为什么要找回财物","被遗弃的财物","为何要回收财物"}},{q="什么是影风森林？",a="影风森林是拥有班艾萨尔定居点的林区。在撕裂了村庄的离奇灾难发生后，这片森林对普通人来说已经变得极其危险。",al={"影风森林在哪里","影风森林背景故事"}},{q="难民们能回到他们的家园吗？",a="不能。据伊兰妮所说，无论是影风森林还是班艾萨尔废墟，对于流离失所的居民来说都太过危险，他们无法独自返回。",al={"难民能回去吗","班艾萨尔安全吗"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="\"The Fate of a Loved One\" 是一项关于 Resaan 的任务，他冒险进入危险的班艾萨尔废墟搜寻补给，却一去不回。一周多过去了，他悲痛的伴侣请求前往该废墟的旅人们查明他的下落，要么带他回家，要么寻回他珍视的传家宝。",h="\"The Fate of a Loved One\" 是一项关于 Resaan...",kw={"班艾萨尔","传家宝","雷萨恩","班艾萨尔废墟","补给","挚爱之人的命运"},sec={{t="绝望的恳求",b="\"The Fate of a Loved One\" 的核心是一位绝望者的请求，他的伴侣 Resaan 冒险重回了班艾萨尔废墟。尽管曾恳切地劝他留下，Resaan 还是执意要闯入废墟寻找补给，留下某人在痛苦的未知中等待。"},{t="消失在废墟中",b="自 Resaan 出发以来已经过去了一周多，这远远超出了能够迅速返回的预期。前往班艾萨尔废墟的旅人们受托在废墟中寻找他——如果他还活着，就指引他回来；如果只剩下不幸的结果，就寻回他的家族传家宝。"}},faq={{q="雷萨恩 是谁？",a="雷萨恩 是一名冒险回到班艾萨尔废墟搜集补给的人，尽管他曾被苦苦哀求留下。在一周多没有音讯后，他的爱人担心他在废墟中遭遇了不幸。",al={"雷萨恩 是谁","雷萨恩 在哪里","寻找 雷萨恩"}},{q="班艾萨尔废墟是什么地方？",a="班艾萨尔废墟是一处危险之地，雷萨恩 冒险前往那里寻找必要的补给。他的爱人认为这趟旅程极其凶险，独自在那里生存一周的可能性微乎其微。",al={"班艾萨尔是什么","班艾萨尔废墟背景故事","班艾萨尔在哪里"}},{q="为什么 雷萨恩 要回到班艾萨尔废墟？",a="雷萨恩 回到班艾萨尔废墟是为了取回补给。尽管他的爱人恳求他不要去，他还是选择了踏上这段危险的旅程。",al={"为什么 雷萨恩 要回去","为什么 雷萨恩 在班艾萨尔废墟"}},{q="任务发布者请求你带回什么？",a="如果 雷萨恩 还活着，任务发布者请求将他平安带回家。如果他已在废墟中遇难，任务发布者请求寻回他的私人传家宝作为最后的纪念。",al={"任务发布者想要什么","如果 雷萨恩 死了会怎样"}},{q="雷萨恩 失踪了多久？",a="自出发前往班艾萨尔废墟以来，雷萨恩 已经失踪了一周多。考虑到该地区的危险，这段漫长的沉默让他的爱人担心发生了最坏的情况。",al={"雷萨恩 失踪了多久","雷萨恩 离开了多久"}},{q="谁发布了这个任务？",a="该任务由 雷萨恩 悲痛的伴侣或爱人发布，他们渴望得到一个了结，并愿意向途经此处前往班艾萨尔废墟的旅人寻求帮助。",al={"谁发布了 挚爱之人的命运","挚爱之人的命运 任务发布者"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="暮光之锤的营地",s="暮光营地是联盟的一项侦察任务，旨在调查在黑海岸南部主宰之剑周围安营扎寨的神秘邪教徒。调查员通过观察水晶球窥见了他们的祭坛，必须潜入挖掘现场，查明暮光之锤试图挖掘出什么东西。",h="暮光营地是联盟的一项侦察任务，旨在调查在黑海岸南部主宰之剑周围安营扎寨的神秘邪教徒。调查员通过观察水晶球窥见了他们的祭坛，必须潜入挖掘现场，查明暮光之锤试图挖掘出什么东西。",kw={"黑海岸","主宰之剑","欧努","观察水晶球","暮光营地","暮光典籍","暮光之锤"},ang={["class:Druid"]="揭露邪教的研究对于塞纳里奥哨兵来说至关重要，他们致力于让那些带有腐蚀性的远古实体安全地保持埋藏状态。",["faction:Alliance"]="阻止邪教诡异的挖掘活动，可以防止一个正在形成的威胁破坏卡利姆多北部的稳定。",["race:NightElf"]="暮光之锤在黑海岸远古树林的枝叶下，用黑暗巫术玷污了神圣的卡利姆多土地。"},sec={{t="探测挖掘点",b="主宰之剑长久以来一直矗立在黑海岸南部的崎岖山丘上，是一个令人不安的石化谜团，但暮光之锤邪教的突然到来，让这处远古奇观变成了一个现实的威胁。在利用观察水晶球窥探了他们的防御工事后，斥候们被派往营地深处，以便在敌人采取防御措施之前查明他们的真实意图。"},{t="插图典籍",b="搜查营地后发现，这些邪教徒并非仅仅是拾荒者或强盗，他们的行动受到深奥神秘学研究的指引。在他们北部营地的深处，放置着一本古老且精心手绘的典籍，里面配有精湛却令人不安的插图。这本典籍证明，暮光之锤正在蓄意调查埋藏在地下的巨大实体。"}},faq={{q="“暮光营地”任务的目标是什么？",a="你必须潜入黑海岸南部主宰之剑附近的暮光之锤营地，并找回一份详述他们动机的线索——具体来说，就是存放在他们营地中的一本手绘仪式典籍。",al={"暮光营地任务目标","暮光营地要做什么"}},{q="是谁派你去调查营地的？",a="该任务直接从主宰之剑上方眺望台的观察水晶球处获取，延续了代表远古守护者欧努所发起的调查。",al={"谁给予暮光营地任务","暮光营地任务发布者"}},{q="在营地哪里可以找到线索？",a="有效的线索是位于营地北部的暮光典籍。营地中的其他典籍可能是危险的诱饵，会向闯入者释放防护魔法。",al={"书在哪里","暮光典籍位置","寻找暮光营地线索"}},{q="暮光之锤为什么会在主宰之剑？",a="这些邪教徒痴迷于上古之神及其仆从的远古黑暗力量。他们正在挖掘被那把巨大的石剑钉住的巨大石化尸骸，试图研究或唤醒残留在其中的任何远古邪恶。",al={"为什么邪教徒在主宰之剑","暮光之锤在黑海岸的目的"}},{q="找到典籍后会发生什么？",a="找回典籍后会引出“重回欧努身边”任务，指示你将发现的文书带往北部的古树之林，交给那里的远古树人。",al={"暮光营地后续任务","找到暮光典籍后去哪里"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94907"] = {n="A Small Favor",s="一名德鲁伊受托将暮光之锤的魔法带回其源头暮光帷幕。Amberhall想抓个教徒爪牙来审问。",h="一名德鲁伊受托将暮光之锤的魔法带回其源头暮光帷幕。Amberhall想抓个教徒爪牙来审问。",kw={"小忙","amberhall","导能装置","德鲁伊","试剂","灵魂石","召唤仪式","twilight shroud","暮光之锤","暮光的萨尔"},ang={["class:Druid"]="身为德鲁伊，Amberhall会先夸你是个乖巧的小德鲁伊，再请你帮这个忙。"},sec={{t="德鲁伊的请求",b="Amberhall在暮光帷幕请求你帮忙。你收集的试剂与暮光之锤的魔法相契合，Amberhall说它们可用于召唤仪式。为了找到这股力量的源头，你需要借助一个导能装置召唤一名教徒爪牙，再用Amberhall的灵魂石将其捕获。"}},faq={{q="Amberhall想让我做什么？",a="Amberhall要你在暮光帷幕借助导能装置召唤暮光的萨尔，并用Amberhall的灵魂石将其捕获。",al={"amberhall的请求","小忙","我要做什么"}},{q="这些试剂有什么用？",a="这些试剂与暮光之锤的魔法相契合，适合用于召唤仪式。",al={"试剂有什么用","为什么要试剂","暮光魔法试剂"}},{q="我该在哪里使用导能装置？",a="导能装置位于暮光帷幕。",al={"导能装置位置","在哪里召唤爪牙","暮光帷幕导能装置"}},{q="为什么要抓住这个爪牙？",a="Amberhall想抓住暮光的萨尔进行审问。",al={"为什么用灵魂石","为什么抓爪牙","审问爪牙"}}},fp="13,143,15.307.0,34.129.0,28.97.0,27.42.0,23.63.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="一位天空之裔同伴看到了你在德鲁伊之道上的潜力，便指引你去雷霆崖找图拉克·符文图腾。他能教你如何前往月光林地的塞纳里奥议会要塞。",h="一位天空之裔同伴看到了你在德鲁伊之道上的潜力，便指引你去雷霆崖找图拉克·符文图腾。他能教你如何前往月光林地的塞纳里奥议会要塞。",kw={"塞纳里奥议会","自然之子","德鲁伊","月光林地","天空之裔","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="作为一名德鲁伊，有人指引你去找图拉克·符文图腾，他能教你如何前往月光林地的塞纳里奥议会。",["race:Skyborne"]="作为一名天空之裔，有人告诉你塞纳里奥议会的德鲁伊会欢迎你，并与你分享他们的知识。"},sec={{t="德鲁伊的欢迎",b="你的导师相信塞纳里奥议会的德鲁伊会欢迎你，并与你分享他们的知识。雷霆崖的图拉克·符文图腾可以教你如何前往他们在月光林地的要塞。"}},faq={{q="我该找谁谈谈？",a="去雷霆崖找图拉克·符文图腾。他能教你如何前往月光林地。",al={"该和谁谈","图拉克·符文图腾","图拉克是谁"}},{q="塞纳里奥议会的要塞在哪里？",a="塞纳里奥议会的要塞位于卡利姆多的月光林地。",al={"议会在哪里","塞纳里奥议会位置","月光林地"}},{q="为什么要派我去月光林地？",a="塞纳里奥议会的德鲁伊可以将他们的知识传授给你。",al={"为何去月光林地","学习德鲁伊之道","德鲁伊训练"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="暴风城的沙德拉斯·月树可以教你如何前往塞纳里奥议会的大本营月光林地。古老教团的德鲁伊有许多智慧可以传授给自然之子。",h="暴风城的沙德拉斯·月树可以教你如何前往塞纳里奥议会的大本营月光林地。古老教团的德鲁伊有许多智慧可以传授给自然之子。",kw={"塞纳里奥议会","自然之子","德鲁伊","卡利姆多","月光林地","沙德拉斯·月树","天翔者","暴风城"},ang={["class:Druid"]="作为一名德鲁伊，你被指引前往塞纳里奥议会。这个古老教团的成员修习德鲁伊之道。",["race:Skyborne"]="作为一名 Skyborne，你将成为最早抵达艾泽拉斯的族人之一，受到欢迎。"},sec={{t="遥远的大本营",b="你被指引去寻找暴风城的暗夜精灵沙德拉斯·月树。他可以教你如何前往卡利姆多的月光林地，那里是塞纳里奥议会的大本营。塞纳里奥议会是一个古老的教团，成员是自然学者和德鲁伊之道的修习者，他们有许多知识可以传授给你。"}},faq={{q="沙德拉斯·月树是谁？",a="沙德拉斯·月树是暴风城的一名暗夜精灵，可以教你如何前往月光林地。",al={"沙德拉斯","暴风城的暗夜精灵","谁教我去月光林地"}},{q="塞纳里奥议会是什么？",a="塞纳里奥议会是一个古老的教团，成员是自然学者和德鲁伊之道的修习者。",al={"塞纳里奥议会","德鲁伊教团","自然教团"}},{q="塞纳里奥议会的大本营在哪里？",a="塞纳里奥议会的大本营位于卡利姆多的月光林地。",al={"塞纳里奥大本营","月光林地在哪里","月光林地"}},{q="我能从塞纳里奥议会学到什么？",a="塞纳里奥议会的德鲁伊有许多智慧可以传授给你。",al={"塞纳里奥教诲","他们能教什么","德鲁伊智慧"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="月光林地",s="一位德鲁伊导师为你指引前往月光林地的道路，让你拜会德迪利特·星焰。在那里，你可以与他谈谈自己刚刚踏上的道路。",h="一位德鲁伊导师为你指引前往月光林地的道路，让你拜会德迪利特·星焰。在那里，你可以与他谈谈自己刚刚踏上的道路。",kw={"熊形态","德迪利特·星焰","德鲁伊","守护者雷姆洛斯","月光林地","永夜港","传送"},ang={["class:Druid"]="作为一名德鲁伊，你的导师欢迎你来到月光林地，并教你一个可以前往那里的法术。"},sec={{t="初次受教",b="你的导师欢迎所有德鲁伊来到月光林地，守护者雷姆洛斯照看着在此休憩的人。你学会了法术“传送：月光林地”，寻求此地的知识或慰藉时，便可前往那里。你的第一课是前往永夜港，与德迪利特·星焰谈谈自己踏上的道路。"},{t="熊形态",b="德迪利特看出你已经掌握了熊形态。他认为你进展顺利。"}},faq={{q="我该在月光林地与谁交谈？",a="前往永夜港村庄，与德迪利特·星焰谈谈你正在走的道路。",al={"该和谁交谈","德迪利特·星焰","永夜港德鲁伊"}},{q="我该如何前往月光林地？",a="你的导师教会你法术“传送：月光林地”，可以将你传送到那里。",al={"月光林地传送","如何前往月光林地","传送法术"}},{q="谁在月光林地守护德鲁伊？",a="守护者雷姆洛斯是月光林地的守护者，照看着在此休憩的德鲁伊。",al={"守护者雷姆洛斯","月光林地守护者","谁守护月光林地"}},{q="德迪利特如何评价我的进展？",a="德迪利特看出你已经掌握了熊形态。",al={"熊形态","是否掌握熊形态","德迪利特的回应"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94923"] = {n="Hats Off",s="Robbie请你去河边鱼人附近找回他丢失的生日帽。他担心家人会知道他去过那里。",h="Robbie请你去河边鱼人附近找回他丢失的生日帽。他担心家人会知道他去过那里。",kw={"生日帽","ellie","帽子","遗失的帽子","鱼人","河流","robbie"},sec={{t="遗失的帽子",b="Robbie在河边玩耍时，弄丢了姐姐送给他的生日帽。他不许靠近鱼人，所以不能请父亲或Ellie帮忙。他猜是某个鱼人捡到了帽子。你需要沿着河边找找看。"}},faq={{q="Robbie是谁？",a="Robbie是个男孩。他在河边玩耍时，弄丢了姐姐送给他的生日帽。",al={"robbie","robbie是谁"}},{q="Robbie丢了什么？",a="Robbie丢了姐姐送给他的生日帽。",al={"robbie的帽子","遗失的帽子"}},{q="Robbie在哪里丢了帽子？",a="Robbie在河里玩耍时弄丢了帽子，请你去鱼人附近的河边找找。",al={"帽子的位置","帽子在哪里"}},{q="Robbie为什么不能请家人帮忙？",a="Robbie不许靠近鱼人。请父亲或Ellie帮忙，就会暴露他去过哪里。",al={"为什么不问爸爸","为什么要隐瞒"}},{q="Robbie知道是不是鱼人拿走了帽子吗？",a="Robbie猜是某个鱼人捡到并留下了他的帽子。",al={"鱼人的帽子","鱼人拿走了吗"}}},fp="8,125,10.268.0,14.89.0,21.55.0,30.111.0,41.111.0,42.62.0"}
P.entries["quest:94924"] = {n="Hunting the Hunters",s="观察者 Cornelius 请你制止河林中的洛格玛偷猎者。他们杀害人和动物，威胁着平原上的所有生命。",h="观察者 Cornelius 请你制止河林中的洛格玛偷猎者。他们杀害人和动物，威胁着平原上的所有生命。",kw={"猎人猎手","兽人偷猎者","偷猎者","河林","洛格玛偷猎者","观察者 cornelius"},sec={{t="平原上的偷猎者",b="洛格玛偷猎者成群出没于河林，观察者 Cornelius 请你去对付他们。他们杀害人、狮子和马匹，威胁着平原上的所有生命。他们的狩猎让所有生灵都不得安宁。"}},faq={{q="是谁要我制止偷猎者？",a="观察者 Cornelius 请你制止洛格玛偷猎者。",al={"是谁派我来的","cornelius 的请求"}},{q="洛格玛偷猎者是什么人？",a="他们是成群出没于河林的兽人猎手。",al={"洛格玛","偷猎者"}},{q="为什么偷猎者构成威胁？",a="他们杀害人、狮子和马匹，威胁着河林中的所有生命。",al={"为何制止偷猎者","偷猎者的威胁"}},{q="偷猎者在哪里出没？",a="洛格玛偷猎者出没于河林的平原。",al={"偷猎者的位置","洛格玛在哪里"}}},fp="19,137,22.217.0,33.56.0,29.58.0,30.74.0,27.56.0"}
P.entries["quest:94925"] = {n="A Fur Trade",s="Watcher Terral正在为Farholde与爆破引线港一名商人的交易寻找狮皮。作为回报，聚居地将获得特制弹药。",h="Watcher Terral正在为Farholde与爆破引线港一名商人的交易寻找狮皮。作为回报，聚居地将获得特制弹药。",kw={"皮毛交易","商人","farholde","狮皮","爆破引线港","prized lion hides","特制弹药","watcher terral"},sec={{t="Farholde的贸易",b="Farholde会通过贸易获取一些物资，但它十分珍视独立。Watcher Terral说，聚居地已与爆破引线港的一名商人商定交换。Farholde提供难以取得且危险的货物，商人则提供特制弹药。如今，商人想要狮皮，Terral请你从草原中央一座大山上的狮群那里带回八张Prized Lion Hides。"}},faq={{q="Watcher Terral需要什么？",a="Watcher Terral需要八张Prized Lion Hides，用于Farholde与爆破引线港一名商人的交易。",al={"terral想要什么","terral的皮毛","狮皮"}},{q="Farholde在和谁交易？",a="Farholde已与爆破引线港的一名商人商定交换。",al={"商人是谁","爆破引线港的交易","皮毛交易商人"}},{q="Farholde能通过交易得到什么？",a="商人会向Farholde提供特制弹药。",al={"弹药有什么用","特制弹药","商人提供什么"}},{q="狮子在哪里？",a="草原中央一座大山的山顶上住着一群狮子。",al={"狮子山","狮群在哪里","草原上的狮子"}}},fp="11,144,18.415.0,30.101.0,29.67.0,36.54.0,20.69.0"}
P.entries["quest:94928"] = {n="A Few Furs for Friz",s="Cornelius请你把狮皮送给爆破引线港的Friz Frazzlespark。交易已经安排妥当，Friz将收到这捆狮皮。",h="Cornelius请你把狮皮送给爆破引线港的Friz Frazzlespark。交易已经安排妥当，Friz将收到这捆狮皮。",kw={"给friz的一些毛皮","cornelius","friz frazzlespark","地精港口","狮皮","爆破引线港"},sec={{t="港口送货",b="Friz Frazzlespark正在爆破引线港等着一捆狮皮。Cornelius已经安排好了交易。把狮皮交给Friz，并告诉她这是Cornelius送来的。"}},faq={{q="这些狮皮是送给谁的？",a="这捆狮皮是送给爆破引线港的Friz Frazzlespark的。",al={"狮皮送给谁","friz狮皮","狮皮交给谁"}},{q="爆破引线港在哪里？",a="爆破引线港是东北方向的一座地精港口。",al={"爆破引线港在哪","爆破引线港位置","地精港口在哪"}},{q="是谁送来的狮皮？",a="狮皮是Cornelius送来的。",al={"谁送来的狮皮","cornelius狮皮","狮皮来自哪里"}},{q="这些是什么皮？",a="这些是狮皮。",al={"什么皮","狮皮","哪种皮"}}},fp="19,137,15.183.0,22.69.0,25.54.0,19.29.0,28.20.0"}
P.entries["quest:94930"] = {n="Lost Shipping Crate",s="Friz Frazzlespark的货箱标明应送回河林的爆破引线港。标签警告，未经看管不得打开。",h="Friz Frazzlespark的货箱标明应送回河林的爆破引线港。标签警告，未经看管不得打开。",kw={"货箱标签","friz frazzlespark","遗失的货箱","爆破引线港","地图上的红圈","河林"},sec={{t="标记的货箱",b="手写标签注明，货箱属于爆破引线港的Friz Frazzlespark。标签警告，不得擅自摆弄或在无人看管时打开货箱。若发现货箱遗失，标签上写明应将其送往河林的爆破引线港，交给Friz。"}},faq={{q="货箱属于谁？",a="标签注明货箱属于Friz Frazzlespark。",al={"货箱所有者","friz是谁","friz货箱"}},{q="货箱应该送到哪里？",a="标签上写着，应将货箱送回河林的爆破引线港，交给Friz Frazzlespark。",al={"货箱位置","货箱送回何处","爆破引线港货箱"}},{q="我能打开货箱吗？",a="标签警告，未经看管不得打开货箱。",al={"打开货箱","里面有什么","货箱警告"}},{q="货箱上的地图显示了什么？",a="地图上有一个大红圈，标在东南方的海岸线上，位于一座四面环水的神庙和一些有翼生物以北。",al={"货箱地图","地图上的红圈","标签上写了什么"}}},fp="19,152,14.260.0,19.52.0,26.94.0,21.62.0,36.124.0"}
P.entries["quest:94931"] = {n="Stolen Saws",s="在伐木场，Halligan 特纳请你找回被豺狼人偷走的锯片。伐木场需要这些锯片。",h="在伐木场，Halligan 特纳请你找回被豺狼人偷走的锯片。伐木场需要这些锯片。",kw={"刺毛丘陵","豺狼人","halligan 特纳","伐木场","锯片","南方哨岗","被偷的锯片"},sec={{t="遗失的锯片",b="南方哨岗挡住了大部分豺狼人，但仍有少数趁夜溜进营地，偷走锯片。伐木场的 Halligan 特纳请你去刺毛丘陵的豺狼人营地寻找锯片，它们可能被藏在那里。伐木场需要找回这些锋利的金属片。"}},faq={{q="谁想要找回锯片？",a="伐木场的 Halligan 特纳想要找回被偷走的锯片。",al={"谁要找回锯片","halligan 特纳锯片"}},{q="锯片是从哪里被偷走的？",a="少数豺狼人躲过南方哨岗，趁夜潜入伐木营地偷走锯片。",al={"豺狼人从哪里偷走锯片","被偷的锯片在哪里"}},{q="豺狼人可能把锯片藏在哪里？",a="锯片可能藏在刺毛丘陵的豺狼人营地里。",al={"豺狼人锯片营地","锯片在哪里"}},{q="豺狼人为什么要锯片？",a="豺狼人很可能会用这些锋利的金属片制作武器。",al={"豺狼人拿锯片做什么","豺狼人制作武器"}},{q="伐木场为什么需要这些锯片？",a="Halligan 说，找回锯片能为伐木场节省时间和资源。",al={"为何找回锯片","伐木场需要锯片"}}},fp="11,110,14.280.0,30.72.0,38.90.0,39.69.0,44.54.0,41.81.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="瓦拉纳尔的一位法师会送你从泽风岛前往达拉然城，那里有法师等候你族人的到来。达拉然是探索艾泽拉斯的起点，但若未做好准备、缺乏经验，城外的土地便危机四伏。",h="瓦拉纳尔的一位法师会送你从泽风岛前往达拉然城，那里有法师等候你族人的到来。达拉然是探索艾泽拉斯的起点，但若未做好准备、缺乏经验，城外的土地便危机四伏。",kw={"教派","达拉然","达拉然城","达纳里斯·星风","法师","天空切割者号","瓦拉纳尔","泽风岛"},ang={["race:Skyborne"]="身为天穹之裔，你正从泽风岛前往达拉然，与等候你族人到来的法师会合。"},sec={{t="抵达达拉然",b="近期与教派有关的事件让讲述者留在瓦拉纳尔，而几位法师正在达拉然等候你族人到来。你将前往旅店外的码头，乘坐天空切割者号前往达拉然城。抵达后，请与Danaaris Stargale交谈。你族人仍在城中安顿下来，而离开达拉然的安全范围后，周边地区可能危机四伏。"}},faq={{q="谁在达拉然等候？",a="几位法师正在达拉然等候你族人到来。抵达后，你需要与达纳里斯·星风交谈。",al={"达拉然的法师","达拉然有哪些人","达拉然法师"}},{q="我该从哪里出发？",a="你将从泽风岛出发，在旅店外码头乘坐天空切割者号前往达拉然城。",al={"如何前往达拉然","从泽风岛出发","天空切割者号"}},{q="讲述者为何留在瓦拉纳尔？",a="近期与教派有关的事件改变了讲述者的计划，因此他们打算暂时留在瓦拉纳尔。",al={"为何留在瓦拉纳尔","教派改变计划","瓦拉纳尔法师"}},{q="达拉然城外安全吗？",a="若未做好准备、缺乏经验，达拉然城外的土地便危机四伏。",al={"达拉然城外安全吗","达拉然附近的危险","达拉然郊外"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="“Welcome to Azeroth”标志着天裔旅客通过Skyborne Portal抵达人类首都暴风城。在向暴风要塞报到后，新来者将获得伯瓦尔·弗塔根公爵的正式认可与许可，得以在联盟领土上自由旅行。",h="“Welcome to Azeroth”标志着天裔旅客通过Skyborne Portal抵达人类首都暴风城。在向暴风要塞报到后，新来者将获得伯瓦尔·弗塔根公爵的正式认可与许可，得以在联盟领土上自由旅行。",kw={"伯瓦尔·弗塔根","高等精灵","高阶会","肯瑞托","传送门","天翔者","暴风要塞","欢迎来到艾泽拉斯"},ang={["faction:Alliance"]="伯瓦尔·弗塔根公爵代表安度因·乌瑞恩国王正式欢迎高阶会，并授予他们自由穿行联盟领土的许可。",["race:Skyborne"]="对于天裔来说，这次觐见正式为通过传送门抵达的高等精灵旅客打开了暴风城和联盟领土的大门。"},sec={{t="抵达首都",b="旅客通过神秘的Skyborne Portal抵达，直接踏入了繁华的暴风城首都。作为报到任务的一部分，新来者穿过城市的大道，前往暴风要塞，向摄政王报到。"},{t="觐见摄政王",b="站在宏伟的王座大厅里，伯瓦尔·弗塔根公爵在收到肯瑞托信使的预先通知后，迎接了到来的高阶会成员。摄政王提到，已经有很长一段时间没有高等精灵走在暴风要塞的走廊里了，他慷慨地接受他们作为客人，并代表国王授予他们在所有联盟领土上自由通行的权利。"}},faq={{q="这个任务是关于什么的？",a="“欢迎来到艾泽拉斯”是一个引导任务，旅行者通过天裔传送门进入暴风城，并在暴风要塞向伯瓦尔·弗塔根公爵报到。",al={"欢迎来到艾泽拉斯是什么","欢迎来到艾泽拉斯任务"}},{q="伯瓦尔·弗塔根是谁？",a="伯瓦尔·弗塔根公爵担任暴风城王位的摄政王，在国王瓦里安失踪期间，代表年轻的安度因·乌瑞恩国王在暴风要塞治理国家。",al={"伯瓦尔 弗塔根是谁","暴风城摄政王"}},{q="为什么伯瓦尔要接待天裔？",a="一位来自肯瑞托的信使通知了伯瓦尔·弗塔根，高阶会成员即将抵达。伯瓦尔接受他们作为王室的客人，并允许他们在联盟领土上自由探索和旅行。",al={"为什么天裔在暴风城","暴风城高等精灵"}},{q="什么是高阶会？",a="高阶会代表了与天裔高等精灵相关的派系或团体，他们的到来是由肯瑞托向暴风城的领导层通报的。",al={"高阶会是谁","高阶会背景故事"}},{q="天裔传送门通向哪里？",a="天裔传送门将旅客直接带入人类首都暴风城，让新来者可以直接前往暴风要塞寻求觐见王室。",al={"天裔传送门目的地","传送门去哪"}},{q="天裔可以在联盟领土内自由活动吗？",a="伯瓦尔·弗塔根代表国王正式欢迎天裔作为客人，并明确允许他们在联盟全境畅行无阻。",al={"天裔是联盟吗","天裔加入联盟"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94961"] = {n="Biting the Hand",s="Fuzzle愿意与任何帮他报仇的人交易。只要你带来暮光指骨，他就答应带你去看宝藏。",h="Fuzzle愿意与任何帮他报仇的人交易。只要你带来暮光指骨，他就答应带你去看宝藏。",kw={"反咬手","fuzzle","豺狼人","报仇","宝藏","暮光指骨"},sec={{t="Fuzzle的提议",b="Fuzzle朝你晃了晃几枚金币，提出一笔交易。这名豺狼人答应，只要你帮他报仇，就给你更多财宝。他让你给他带来二十根暮光 Finger Bones，然后才会让你看看他有什么。"}},faq={{q="Fuzzle是谁？",a="Fuzzle是一个豺狼人，他愿意给你金币，并答应用宝藏换取你帮他报仇。",al={"fuzzle","拿金币的豺狼人"}},{q="Fuzzle想要什么？",a="Fuzzle让你带来二十块暮光指骨，帮他报仇。",al={"他想要什么","fuzzle报仇"}},{q="暮光指骨有什么用？",a="Fuzzle想先要二十块暮光指骨，然后才给你看他的宝藏。",al={"指骨","暮光骨头"}}},fp="15,131,14.206.0,14.97.0,22.82.0,39.75.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="与 Bonegnaw 的战斗，是你在 Bloodmaster's Ring 成为冠军之路上的下一场较量。食人魔们正等着看你能否带来一场精彩的战斗。",h="与 Bonegnaw 的战斗，是你在 Bloodmaster's Ring 成为冠军之路上的下一场较量。食人魔们正等着看你能否带来一场精彩的战斗。",kw={"bloodmaster","bloodmaster's ring","bonegnaw","较量","冠军","战斗","食人魔"},sec={{t="下一场较量",b="你的胜利还不足以让你成为冠军，竞技场里的地精还想再安排一场战斗。你的对手是Bonegnaw，地精还承诺会有惊喜。食人魔们正在观战，下一场比斗就是为取悦他们而准备的。"},{t="战斗之后",b="地精对这场比斗给自己带来的名声很不满意。不过，食人魔们似乎看得很开心，他警告你别为结果沾沾自喜。"}},faq={{q="我的对手是谁？",a="你在 Bloodmaster's Ring 的对手是 Bonegnaw。",al={"与 bonegnaw 战斗","对手是谁"}},{q="我已经是冠军了吗？",a="竞技场里的地精说，你的胜利还不足以让你成为冠军。",al={"bloodmaster 冠军","成为冠军"}},{q="谁在观看这场战斗？",a="食人魔们正在观看 Bloodmaster's Ring 的这场较量。",al={"食人魔观看","谁看得尽兴"}}},fp="18,170,13.226.0,15.151.1,19.52.0,20.66.0,26.54.0"}
P.entries["quest:94963"] = {n="Biting the Hand",s="Fuzzle让你和他一起离开，并承诺等你安全后给你报酬。他咆哮着威胁任何可能追来的人。",h="Fuzzle让你和他一起离开，并承诺等你安全后给你报酬。他咆哮着威胁任何可能追来的人。",kw={"咬手","fuzzle","豺狼人","金币","离开","报酬","安全"},sec={{t="与Fuzzle一同离开",b="Fuzzle已经准备离开，并请你和他一起走。他警告说，谁敢阻拦你们，谁就会被撕成碎片。你的安全最重要；等你脱险后，他会给你报酬。"}},faq={{q="是谁要我离开？",a="Fuzzle请你和他一起离开。",al={"fuzzle是谁","fuzzle？","谁想离开"}},{q="Fuzzle威胁了什么？",a="Fuzzle威胁说，要把任何试图阻拦你的人撕成碎片。",al={"fuzzle说了什么","fuzzle的威胁","他会攻击谁"}},{q="Fuzzle什么时候给我报酬？",a="Fuzzle说，等你安全后就会给你报酬。",al={"fuzzle的报酬","何时报酬","他承诺了什么"}},{q="报酬是什么？",a="Fuzzle积攒了一大笔金币，这些金币都归你。",al={"我能得到什么","fuzzle的金币","fuzzle给的报酬"}}},fp="15,125,19.190.0,26.34.0,26.60.0,34.56.0,19.60.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="一名擂台主持人召唤你前往 Bloodmaster’s Ring 与 Mog’thar 对决。观众正等待下一位挑战者登场。",h="一名擂台主持人召唤你前往 Bloodmaster’s Ring 与 Mog’thar 对决。观众正等待下一位挑战者登场。",kw={"主持人","bloodmaster’s ring","挑战者","观众","mog’thar","擂台"},sec={{t="下一位挑战者",b="主持人一直在调动观众的热情，现在又宣布 Mog’thar 将成为下一位挑战者。你被召唤到 Bloodmaster’s Ring，观众正等着看接下来会发生什么。"}},faq={{q="我在 Bloodmaster’s Ring 要面对谁？",a="你被召唤到 Bloodmaster’s Ring 与 Mog’thar 对决。",al={"与 mog’thar 对决","下一位挑战者是谁","bloodmaster’s ring 对手"}},{q="主持人怎么评价 Mog’thar？",a="主持人说 Mog’thar 可不是好惹的。",al={"mog’thar 是谁","下一位挑战者","mog’thar 是闹着玩的吗"}},{q="为什么要派我进擂台？",a="主持人想再介绍一位挑战者，让观众继续兴奋起来。",al={"为什么要和 mog’thar 对决","擂台对决原因","主持人想做什么"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94965"] = {n="Bloodmaster's Ring",s="地精 Jezap 要你在 Bloodmaster's Ring 中迎战 Snufflesnout，以此向食人魔证明自己。她最喜欢的食物会引她参战，不过 Chub'chob 可能不会善待你。",h="地精 Jezap 要你在 Bloodmaster's Ring 中迎战 Snufflesnout，以此向食人魔证明自己。她最喜欢的食物会引她参战，不过 Chub'chob 可能不会善待你。",kw={"血拳之环","chub'chob","食人魔","snufflesnout","食物"},sec={{t="对你的考验",b="Jezap 在你进入 Bloodmaster's Ring 前摆出一份食物。Snufflesnout 很喜欢它，看到食物便被激起了斗志。你的试炼是迎战 Chub'chob 的同伴，同时向食人魔证明自己。"},{t="战斗之后",b="Chub'chob 的伙伴就是 Snufflesnout。打败她后，你和食人魔之间会闹得一团糟。现在要小心应对他们。"}},faq={{q="Snufflesnout 是谁？",a="Snufflesnout 是 Chub'chob 的伙伴，很喜欢一种特定的食物。",al={"snufflesnout","snuffle snout","chubchob 的宠物"}},{q="为什么要准备食物？",a="Jezap 用 Snufflesnout 最喜欢的食物引她进入 Bloodmaster's Ring。",al={"snufflesnout 喜欢的食物","食物是做什么用的","喂 snufflesnout"}},{q="血拳之环是什么？",a="你在这里迎战 Snufflesnout，向食人魔证明自己。",al={"血拳之环","竞技场","去哪里和 snufflesnout 战斗"}},{q="我为什么要和 Snufflesnout 战斗？",a="Jezap 说，向食人魔证明自己最为重要，而迎战 Snufflesnout 就是你的试炼。",al={"和 snufflesnout 战斗","为什么要和她战斗","向食人魔证明自己"}}},fp="18,207,14.204.0,15.124.1,20.72.0,21.81.0,31.74.0,31.98.0"}
P.entries["quest:94968"] = {n="Eye of Mugg",s="暮光教派的据点比预想中更大，Krom'rosh便派你前往克罗多克要塞。他要你带回首领已死的证据。",h="暮光教派的据点比预想中更大，Krom'rosh便派你前往克罗多克要塞。他要你带回首领已死的证据。",kw={"洞穴","教派首领","eye of mugg","克罗多克要塞","krom'rosh","牺牲","暮光教派"},sec={{t="克罗多克要塞",b="Krom'rosh担心，若暮光教派继续蹂躏这片土地，更多盟友将会被牺牲。进入洞穴的人寥寥无几能活着回来，教派的据点也比他想象的更大。现在，你要进入克罗多克要塞，带回首领已死的证据。"}},faq={{q="是谁派我进入克罗多克要塞？",a="Krom'rosh派你前往克罗多克要塞，带回暮光教派首领已死的证据。",al={"谁派我去","krom'rosh的要求"}},{q="要塞出了什么问题？",a="暮光教派的据点比Krom'rosh预想的更大，他们一直在蹂躏这片土地，并牺牲盟友。",al={"那里发生了什么","暮光教派的问题"}},{q="Krom'rosh为什么要我进去？",a="Krom'rosh想阻止教派继续蹂躏这片土地、牺牲盟友。",al={"为什么进去","为何进入要塞"}},{q="Krom'rosh要什么证据？",a="他要你带回暮光教派首领已死的证据。",al={"需要的证据","要带回什么"}},{q="进入洞穴的人有很多活下来吗？",a="设法进入洞穴的人，只有少数活着回来。",al={"洞穴幸存者","谁活着出来"}}},fp="11,150,19.268.0,46.105.0,32.119.0,36.98.0,34.58.0,38.43.0"}
P.entries["quest:94971"] = {n="A Paladin's Steed",s="圣骑士的战马载着骑手和武器奔赴战场。Danitha Morr 可以教你召唤一匹属于自己的战马。",h="圣骑士的战马载着骑手和武器奔赴战场。Danitha Morr 可以教你召唤一匹属于自己的战马。",kw={"祝圣","danitha morr","坐骑","圣骑士","召唤","战马"},ang={["class:Paladin"]="作为圣骑士，你可以召唤一匹经过特别祝圣的战马，载着你和武器奔赴战场。"},sec={{t="驰骋战场的战马",b="圣骑士长期以来都骑乘经过特别祝圣的战马奔赴战场，战马载着骑手和武器。Danitha Morr 可以教你召唤一匹属于自己的坐骑，让它陪你奔赴战场。"}},faq={{q="圣骑士的坐骑是什么？",a="它是一匹经过特别祝圣的战马，载着圣骑士和武器奔赴战场。",al={"圣骑士战马","战马","圣骑士坐骑"}},{q="谁教我召唤战马？",a="Danitha Morr 会教你召唤战马。",al={"danitha morr","召唤战马","获取圣骑士坐骑"}},{q="圣骑士为何需要战马？",a="战马载着圣骑士和武器奔赴战场。",al={"圣骑士为何骑战马","坐骑有什么用"}}},fp="17,114,21.211.0,28.89.0,36.49.0,32.54.0"}
P.entries["quest:94972"] = {n="Tome of Twilight",s="在克罗多克要塞，有人请你找回《暮光之书》。书中的内容或许能帮助对抗教徒。",h="在克罗多克要塞，有人请你找回《暮光之书》。书中的内容或许能帮助对抗教徒。",kw={"教徒","情报","克罗多克要塞","秘密","暮光之书"},sec={{t="隐秘记录",b="要塞的秘密或许藏着有关教徒的有用情报。有人请你搜查克罗多克要塞，找回《暮光之书》，将其中的信息带回。"}},faq={{q="我要找什么？",a="有人请你从克罗多克要塞找回《暮光之书》。",al={"暮光之书","什么书","哪本书"}},{q="这本书为何重要？",a="这本书或许藏有对抗教徒的有用情报。",al={"为何找书","书有什么用","教徒情报"}},{q="《暮光之书》在哪里？",a="要从克罗多克要塞找回《暮光之书》。",al={"书在哪里","克罗多克的书","要塞里的书"}}},fp="16,123,15.190.0,22.71.0,25.74.0,30.65.0"}
P.entries["quest:94973"] = {n="Krol'dok Moulding",s="在洛格玛附近发现的模具似乎是钥匙的一部分。聚居地里或许有人知道它能打开什么。",h="在洛格玛附近发现的模具似乎是钥匙的一部分。聚居地里或许有人知道它能打开什么。",kw={"钥匙","krol'dok moulding","模具","洛格玛","要塞"},sec={{t="奇怪的模具",b="你有一块似乎是为钥匙制作的模具。洛格玛或许有人知道这块东西有什么用。如果它来自要塞，那可能很重要。"}},faq={{q="这块模具有什么用？",a="这块模具似乎是用来制作钥匙的。",al={"模具碎片","这是什么模具","钥匙模具"}},{q="谁能辨认这块模具？",a="洛格玛或许有人了解这块模具。",al={"谁了解这块模具","询问模具","把模具带去哪里"}},{q="它为什么可能很重要？",a="如果这块模具来自要塞，那它一定很重要。",al={"模具重要吗","要塞模具","为什么在意模具"}}},fp="17,108,15.151.0,25.37.0,30.44.0,20.61.0"}
P.entries["quest:94974"] = {n="Key Ingredients",s="Kreza Darkthorn需要皮革和铁来制作钥匙模具。她看着余烬，你去收集材料。",h="Kreza Darkthorn需要皮革和铁来制作钥匙模具。她看着余烬，你去收集材料。",kw={"余烬","iron bar","钥匙","钥匙材料","kreza darkthorn","模具","thick leather"},sec={{t="制作模具的材料",b="Kreza Darkthorn有一个磨损的模具，或许还能用来打造钥匙。她看着余烬，你给她带来四块Thick Leather和十二根Iron Bar。模具应该还能用，Kreza已经准备好看看能做些什么。"}},faq={{q="Kreza需要什么？",a="Kreza让你带来四块Thick Leather和十二根Iron Bar。",al={"需要什么材料","钥匙材料","kreza需要什么"}},{q="这些材料有什么用？",a="这些材料用来用一个粗糙破旧的模具打造钥匙。",al={"为何需要皮革和铁","钥匙用来做什么","模具材料"}},{q="谁在看着余烬？",a="Kreza Darkthorn说，她会看着余烬，你去收集材料。",al={"谁看着余烬","kreza看余烬","余烬保持炽热"}},{q="Kreza怎么评价这个模具？",a="Kreza说，这个模具粗糙又破旧，但仍可能用来打造钥匙。",al={"模具状况","模具还能用吗","钥匙模具"}}},fp="15,115,26.225.0,21.63.0,27.67.0,30.81.0,39.82.0"}
P.entries["quest:94975"] = {n="A Token of Vengeance",s="一位盟友请你前往克罗多克要塞附近的洞穴网络，寻找藏身于其中的暮光之锤教徒。他们的袭击伤害了你的盟友，也威胁着这片土地。",h="一位盟友请你前往克罗多克要塞附近的洞穴网络，寻找藏身于其中的暮光之锤教徒。他们的袭击伤害了你的盟友，也威胁着这片土地。",kw={"复仇信物","教徒之耳","教徒","隐秘洞穴","克罗多克要塞","暮光之锤"},sec={{t="隐秘洞穴",b="斥候报告称，暮光之锤教徒正在克罗多克要塞附近崎岖的地面下活动。你的盟友说，他们的袭击造成了巨大的伤痛，教徒们还在侵占这片土地。盟友请你找到他们的藏身之处，带回十五只教徒之耳，以示复仇。"}},faq={{q="我要找谁？",a="你要寻找藏身在克罗多克要塞附近洞穴网络中的暮光之锤教徒。",al={"这些教徒是谁","暮光之锤在此","教徒之耳"}},{q="为什么要追捕这些教徒？",a="委托者说，这些教徒伤害了他们的盟友，还在侵占这片土地。",al={"为何复仇","为何与他们战斗","他们做了什么"}},{q="斥候发现了什么？",a="斥候报告称，北方崎岖的地形下有教徒活动，那里有一处隐秘的洞穴网络。",al={"斥候报告","教徒在哪里","教徒动向"}},{q="要我带回什么？",a="你需要从克罗多克要塞的暮光之锤教徒身上收集十五只 Cultist Ears。",al={"要收集什么","教徒之耳任务","需要多少只耳朵"}}},fp="20,158,16.328.0,21.99.0,34.90.0,24.99.0,30.98.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale教你了解野兽与主人之间的羁绊。你的第一个挑战，是在Zephras的水边驯服一只Windsong Crawler。",h="Quel'ana Quickgale教你了解野兽与主人之间的羁绊。你的第一个挑战，是在Zephras的水边驯服一只Windsong Crawler。",kw={"驯服野兽","奎尔安娜·疾风","驯兽棒","瓦拉纳尔","风歌爬行者","泽弗拉斯"},sec={{t="初次羁绊",b="你将从驯兽棒和一只Windsong Crawler开始。在水边驯服一只，练习你的技能，然后把驯兽棒交还给瓦拉纳尔的Quel'ana Quickgale。眼下，你的精进之路将从这只生物开始。"}},faq={{q="奎尔安娜让我驯服什么？",a="奎尔安娜让你在泽弗拉斯的水边驯服一只风歌爬行蟹。",al={"什么野兽","驯服目标","爬行者任务"}},{q="驯兽棒有什么用？",a="驯兽棒用于驯服风歌爬行蟹。",al={"驯兽棒用法","驯服工具","驯兽棒任务"}},{q="在哪里能找到风歌爬行蟹？",a="在泽弗拉斯的水边可以找到风歌爬行蟹。",al={"爬行者位置","爬行者在哪","泽弗拉斯野兽"}},{q="是谁给了我驯兽棒？",a="瓦拉纳尔的奎尔安娜·迅风给了你驯兽棒。",al={"任务给予者","奎尔安娜是谁","奎尔安娜·迅风"}},{q="我为什么要学习驯服野兽？",a="了解野兽与主人之间的羁绊，是你的职业迈向精通的第一步。",al={"为什么驯服爬行者","野兽精通","初次驯服"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="Quel'ana Quickgale请你在阵风浆果低地驯服一只疾风踏行鸟。在开阔地带磨练技艺，将为你迎接后续考验做好准备。",h="Quel'ana Quickgale请你在阵风浆果低地驯服一只疾风踏行鸟。在开阔地带磨练技艺，将为你迎接后续考验做好准备。",kw={"疾风踏行鸟","阵风浆果低地","暴躁的疾风踏行鸟","奎尔安娜·疾风","驯兽棒","驯服野兽","瓦拉纳尔","泽弗拉斯"},sec={{t="穿越平原",b="你已经证明自己能够驯服河中的爬行兽。Quel'ana Quickgale现在交给你一根驯兽棒，并让你前往Zephras的低地寻找一只疾风踏行鸟。这种骄傲的有翼生物在平原上疾驰。赢得它的信任，练习你的本领，然后把驯兽棒带回瓦拉纳尔交给Quel'ana。"}},faq={{q="奎尔安娜想让我驯服什么？",a="奎尔安娜让你在阵风浆果低地驯服一只暴躁的疾风踏行鸟。",al={"驯服什么","驯服疾风踏行鸟","什么野兽"}},{q="我在哪里能找到疾风踏行鸟？",a="暴躁的疾风踏行鸟位于泽弗拉斯平原上的阵风浆果低地。",al={"疾风踏行鸟在哪里","疾风踏行鸟位置","低地在哪里"}},{q="驯兽棒有什么用？",a="奎尔安娜给你驯兽棒，让你驯服一只暴躁的疾风踏行鸟。",al={"驯兽棒用途","驯兽棒有什么用","如何驯服野兽"}},{q="是谁交给我这项任务？",a="瓦拉纳尔的奎尔安娜·迅风让你驯服一只暴躁的疾风踏行鸟，并归还驯兽棒。",al={"是谁派我来的","奎尔安娜是谁","迅风"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:94980"] = {n="Krol'dok Moulding",s="Krol'dok 模具看起来像是钥匙的模具。法霍德要塞里或许有人知道更多。",h="Krol'dok 模具看起来像是钥匙的模具。法霍德要塞里或许有人知道更多。",kw={"法霍德要塞","钥匙","krol'dok 模具","模具"},sec={{t="钥匙模具",b="你拿到一个看起来是用来制作钥匙的模具。法霍德要塞里或许有人知道它的用途，你便带着它去打听详情。"}},faq={{q="Krol'dok 模具是什么？",a="Krol'dok 模具看起来是用来制作钥匙的。",al={"kroldok 模具","krol'dok 模具","这是什么模具"}},{q="谁可能了解这个模具？",a="法霍德要塞里或许有人了解这个模具。",al={"谁了解这个模具","模具专家","询问模具"}},{q="带上模具后会怎么样？",a="你带去询问的人说，会看看能用它做些什么。",al={"模具结果","他们怎么说","钥匙模具"}}},fp="17,107,13.146.0,30.46.0,31.50.0,39.71.0"}
P.entries["quest:94981"] = {n="Key Ingredients",s="Alphonse Dumas需要一些材料，才能用粗糙的模具制作一把钥匙。你需要为他带去Thick Leather和Iron Bars。",h="Alphonse Dumas需要一些材料，才能用粗糙的模具制作一把钥匙。你需要为他带去Thick Leather和Iron Bars。",kw={"alphonse dumas","余烬","iron bars","钥匙","钥匙材料","模具","thick leather"},sec={{t="钥匙所需材料",b="你收集所需材料时，Alphonse Dumas一直让余烬保持炽热。模具虽然粗糙，但合适的材料或许能让他制作出一把钥匙。"}},faq={{q="Alphonse需要什么？",a="Alphonse Dumas请你带去四块Thick Leather和十二根Iron Bars。",al={"所需材料","要带什么","钥匙材料"}},{q="Alphonse在制作什么？",a="Alphonse希望用合适的材料，通过粗糙的模具制作一把钥匙。",al={"他在制作什么","钥匙有什么用","钥匙模具"}},{q="我该把材料交给谁？",a="把Thick Leather和Iron Bars带给Alphonse Dumas。",al={"谁要这些材料","材料要交给谁"}}},fp="15,126,21.141.0,24.73.0,24.80.0,30.56.0"}
P.entries["quest:94982"] = {n="Eye of Mugg",s="布兰特指挥官让你前往克罗多克要塞寻找暮光势力，并带回其首领死亡的证据。洞穴中的威胁会阻碍我们将暮光势力逐出这片土地。",h="布兰特指挥官让你前往克罗多克要塞寻找暮光势力，并带回其首领死亡的证据。洞穴中的威胁会阻碍我们将暮光势力逐出这片土地。",kw={"洞穴","布兰特指挥官","eye of mugg","克罗多克要塞","失踪的斥候","山脉","暮光"},sec={{t="隐秘洞穴",b="布兰特指挥官听说，斥候在山脉西北方发现了一些洞穴，它们隐蔽在天然环境之中。许多前去探查的人都没有回来，布兰特担心他们已经遇难。守望者也曾看到暮光成员在黑暗中出入洞穴。你需要找到这座要塞，并带回首领死亡的证据。"}},faq={{q="是谁派我去克罗多克要塞？",a="布兰特指挥官让你找到暮光要塞，并带回其首领死亡的证据。",al={"布兰特指挥官是谁","布兰特派我去","谁给了这个任务"}},{q="克罗多克要塞在哪里？",a="洞穴位于山脉西北方，隐蔽在天然环境之中。",al={"克罗多克在哪里","克罗多克位置","洞穴在哪里"}},{q="布兰特指挥官为何担心这些洞穴？",a="许多进入洞穴搜集情报的人都没有回来，布兰特担心他们可能已经遇难。",al={"为什么要找洞穴","那里出了什么事","失踪的斥候"}},{q="有人在洞穴附近见过谁？",a="守望者报告说，有暮光成员出入洞穴，且常常是在黑暗中。",al={"洞穴中的暮光势力","克罗多克里有谁","暮光势力"}},{q="布兰特让我带回什么？",a="布兰特让你带回要塞首领已死的证据。",al={"需要什么证据","首领的证据","要带回什么"}}},fp="11,196,16.376.0,36.103.0,29.76.0,49.101.0,33.93.0,37.73.0"}
P.entries["quest:94983"] = {n="Twilight Mementos",s="侦察兵确认暮光之锤的藏身处后，Sergeant Riftan 派你北上前往克罗多克要塞。他要你带回邪教徒落败的证据。",h="侦察兵确认暮光之锤的藏身处后，Sergeant Riftan 派你北上前往克罗多克要塞。他要你带回邪教徒落败的证据。",kw={"洞穴","邪教徒手镯","邪教徒藏身处","克罗多克要塞","侦察兵","sergeant riftan","暮光纪念品","暮光之锤"},sec={{t="侦察兵的报告",b="侦察兵带给 Sergeant Riftan 关于邪教徒藏身处的严峻消息。他们的报告证实了其他人的说法。北边有个洞穴，隐蔽在周围环境之中。Riftan 认为，这让邪教徒得以在群山深处立足。他派你前往克罗多克要塞，带回暮光之锤邪教徒已被击败的证据。"}},faq={{q="是谁派我去北边？",a="Sergeant Riftan 要你前往克罗多克要塞，寻找暮光之锤邪教徒，并带回他们落败的证据。",al={"谁派我去","sergeant riftan"}},{q="侦察兵发现了什么？",a="侦察兵的报告证实了邪教徒藏身处的消息，北边有个隐蔽的洞穴。",al={"侦察兵报告","他们发现了什么"}},{q="藏身处在哪里？",a="藏身处位于北边一个隐蔽在周围环境中的洞穴里。Riftan 认为那里是他们在群山深处的据点。",al={"邪教徒洞穴","邪教徒在哪里"}},{q="Riftan 想要什么证据？",a="Riftan 要你带回克罗多克要塞的邪教徒已被击败的证据。",al={"什么证据","邪教徒证据"}},{q="这些邪教徒是什么人？",a="他们是暮光之锤的成员，侦察兵的报告已经证实了他们藏身处的位置。",al={"暮光教徒","暮光之锤"}}},fp="17,161,15.350.0,29.129.0,25.96.0,21.125.0,28.96.0,21.99.0"}
P.entries["quest:94984"] = {n="Tome of Twilight",s="暮光势力仍在活动，一条线索指向阳光林地以北。你受命寻找 Nar'gurk，并从他的要塞中找回情报。",h="暮光势力仍在活动，一条线索指向阳光林地以北。你受命寻找 Nar'gurk，并从他的要塞中找回情报。",kw={"克罗多克要塞","nar'gurk","暗影魔法","阳光林地","暮光之书","暮光","暮光势力"},sec={{t="北方踪迹",b="暮光势力仍不知从何处而来，因此你被派往克罗多克要塞。一只暮光生物提到了暗影魔法，以及那里的食人魔 Nar'gurk。你受命杀死他，并找回任何可能解释这些势力来源的有价值情报。"}},faq={{q="我要找什么？",a="你要在克罗多克要塞寻找 Nar'gurk，以及那里任何有价值的情报。",al={"nar gurk","书卷情报","暮光要塞"}},{q="克罗多克要塞在哪里？",a="克罗多克要塞位于阳光林地以北。",al={"要塞在哪里","克罗多克位置"}},{q="我为什么要找 Nar'gurk？",a="有人询问一只暮光生物，它以前的主人来自何处；它提到了 Nar'gurk 和暗影魔法。",al={"为何寻找 nar gurk","暮光线索"}},{q="那里可能有什么情报？",a="所寻找的情报或许能帮助解释持续不断的暮光势力来自何处。",al={"有什么情报","暮光之书情报"}}},fp="16,143,13.279.0,22.87.0,29.43.0,30.109.0,32.93.0"}
P.entries["quest:94992"] = {n="Rescue Roundup",s="一匹名叫 Biscuit 的走失马轻轻蹭了蹭你，准备跟你回到 Wheeler's Grange。她的归来意味着农场重新开张了。",h="一匹名叫 Biscuit 的走失马轻轻蹭了蹭你，准备跟你回到 Wheeler's Grange。她的归来意味着农场重新开张了。",kw={"biscuit","demar","马","走失的马","营救马匹","马厩同伴","wheeler's grange"},sec={{t="Biscuit归来",b="Wheeler 走失的马名叫 Biscuit。她低下头，轻轻蹭了蹭你的手臂。你把她带回了 Wheeler's Grange。Wheeler 很感激 Biscuit 回到了家，不过 Biscuit 还要独自待上一阵子。农场又重新开张了。"}},faq={{q="Biscuit是谁？",a="Biscuit是Wheeler的马。她走失了，需要被带回Wheeler's Grange。",al={"biscuit的马","走失的马","biscuit是谁"}},{q="Biscuit要去哪儿？",a="Biscuit需要被带回Wheeler's Grange。",al={"把马带去哪儿","biscuit的位置","马的目的地"}},{q="Wheeler为什么感激？",a="因为你把Biscuit带回了农庄，Wheeler很感激。",al={"为什么感谢","救回biscuit","wheeler的感谢"}},{q="Biscuit是独自待着吗？",a="Wheeler说Biscuit暂时会独自待着，并希望能找到她的一些马厩同伴。",al={"biscuit独自待着","马厩同伴在哪儿","其他马匹"}},{q="Wheeler's Grange开张了吗？",a="Biscuit回来后，Wheeler's Grange重新开张了。",al={"农庄开张","wheeler重新营业","农庄重新开张"}}},fp="14,133,15.248.0,15.95.0,30.53.0,24.65.0,17.90.0,25.56.0"}
P.entries["quest:94997"] = {n="Lingering Essence",s="Riftan请你把一袋被诅咒的纪念物送到法霍德要塞，交给Ashe Amberhall。他希望她能通过研究，查明这些物品蕴含着何种能量。",h="Riftan请你把一袋被诅咒的纪念物送到法霍德要塞，交给Ashe Amberhall。他希望她能通过研究，查明这些物品蕴含着何种能量。",kw={"ashe amberhall","邪教徒","被诅咒的纪念物","能量","法霍德要塞","残留的精华","riftan","satchel of cursed mementos"},sec={{t="在要塞",b="在法霍德要塞，Ashe Amberhall从你手中接过袋子，得知是Riftan派你送来的。她说，Riftan与邪教徒长期斗争，疲惫或许已蒙蔽了他的判断。尽管如此，她也承认他的担忧可能并非空穴来风，于是开始检查那些物品。"}},faq={{q="是谁让我送这袋东西？",a="Riftan请你把Satchel of Cursed Mementos送给Ashe Amberhall。",al={"谁派我来的","riftan的袋子","riftan是谁"}},{q="Ashe Amberhall是谁？",a="Ashe Amberhall是一位备受尊敬的学者，她的研究领域或许能帮助她查明这些物品蕴含的能量。",al={"ashe是谁","amberhall"}},{q="我要把纪念物送到哪里？",a="把Satchel of Cursed Mementos送到法霍德要塞，交给Ashe Amberhall。",al={"袋子要送到哪里","法霍德要塞","袋子的送达地点"}},{q="袋子里装着什么？",a="袋子里装着被诅咒的纪念物，Riftan希望Ashe检查它们蕴含着何种能量。",al={"袋子里有什么","被诅咒的纪念物","袋中物品"}},{q="Riftan为什么要让Ashe检查这些东西？",a="Riftan希望Ashe通过研究，查明这些物品蕴含着何种能量。",al={"为什么找ashe","袋子是做什么的","残留的精华"}},{q="Ashe怎么看待Riftan的担忧？",a="Ashe担心，Riftan与邪教徒长期斗争后的疲惫可能会影响他的判断，不过她也说他的担忧或许有根据。",al={"ashe信任riftan吗","riftan疲惫","ashe的看法"}}},fp="17,153,11.279.0,38.73.0,22.108.0,29.72.0,23.95.0,42.86.0,41.132.0"}
P.entries["quest:94998"] = {n="Curios of Curiosity",s="你带着一袋不同寻常的纪念品去找 Melanie Sable。它们做工精巧，或许派得上用场。",h="你带着一袋不同寻常的纪念品去找 Melanie Sable。它们做工精巧，或许派得上用场。",kw={"做工","奇珍异宝","melanie sable","纪念品","遗存","一袋纪念品"},sec={{t="给 Melanie 的一袋纪念品",b="检查过这些纪念品的人让你把袋子送给 Melanie Sable。他们认为这些物品很安全，但仍不知道它们的来历。它们的做工别具一格，Melanie 或许能找到用途。"}},faq={{q="我该把这些纪念品交给谁？",a="按检查者的要求，把这袋纪念品交给 Melanie Sable。",al={"把袋子送到哪里","melanie sable 是谁"}},{q="这些纪念品是什么？",a="它们是某种事物的遗存，但检查者也不清楚具体是什么。",al={"袋子里有什么","这些奇珍是什么"}},{q="这些纪念品为何与众不同？",a="据说它们的做工相当独特而精巧。",al={"它们有什么特别之处","奇珍的做工"}},{q="这些纪念品安全吗？",a="检查者让你告诉 Melanie，这些纪念品很安全。",al={"袋子安全吗","它们有危险吗"}}},fp="19,104,21.217.0,34.68.0,22.76.0,29.63.0,22.65.0"}
P.entries["quest:94999"] = {n="Eyes for the Watchman",s="Eleanor请你把一份慰问包裹送给驻扎在Southern Watch的Watcher Fredericks。牧场事务缠身，她无法亲自送去。",h="Eleanor请你把一份慰问包裹送给驻扎在Southern Watch的Watcher Fredericks。牧场事务缠身，她无法亲自送去。",kw={"慰问包裹","eleanor","巡逻","牧场","southern watch","watcher fredericks"},sec={{t="给Fredericks的礼物",b="Watcher Fredericks巡逻时会经过Eleanor的牧场，她为他准备了一份小礼物。她既要照看弟弟，又要打理牧场，便请你把礼物送到她家以西的Southern Watch。"}},faq={{q="这份包裹是送给谁的？",a="Eleanor准备的慰问包裹是送给驻扎在Southern Watch的Watcher Fredericks的。",al={"礼物送给谁","包裹送给谁"}},{q="Eleanor为什么不能亲自送去？",a="Eleanor需要照看年幼的弟弟，还要打理牧场。",al={"eleanor为何不送","她为什么不能去"}},{q="Watcher Fredericks在哪里？",a="Watcher Fredericks驻扎在Eleanor牧场以西的Southern Watch。",al={"fredericks在哪里","southern watch的位置"}},{q="Eleanor为什么准备礼物？",a="Fredericks有时会巡逻经过牧场，Eleanor想借此表达谢意。",al={"为什么送包裹","包裹有什么用"}},{q="Fredericks收到包裹后有什么反应？",a="Fredericks感谢你送来Eleanor的礼物，并说以后有机会会回报她。",al={"fredericks的反应","他喜欢吗"}}},fp="21,135,21.202.0,23.85.0,37.64.0,28.75.0,31.88.0,41.95.0"}
P.entries["quest:95"] = {n="斯温的复仇",s="出于悲痛与复仇的驱使，隐士斯温·约根请求过往旅人回到他位于暮色森林南部的破败农场。尽管他多年来一直在追捕屠杀他家人的暗影骑士，但曾有一个可疑的身影在他的谷仓附近埋下了某样东西，那可能藏着真相。",h="出于悲痛与复仇的驱使，隐士斯温·约根请求过往旅人回到他位于暮色森林南部的破败农场。尽管他多年来一直在追捕屠杀他家人的暗影骑士，但曾有一个可疑的身影在他的谷仓附近埋下了某样东西，那可能藏着真相。",kw={"暗影骑士","逆风小径","暮色森林","松散的土堆","树桩","斯温·约根","斯温的复仇","约根农场"},ang={["class:Paladin"]="来自逆风小径的邪恶势力对无辜者的残酷屠杀，必须得到正义的制裁，为死者讨回公道。",["faction:Alliance"]="约根一家的惨剧是暮色森林与世隔绝的又一例证，展示了在没有暴风城常规军队巡逻的情况下，黑暗势力的触角延伸得有多远。"},sec={{t="农场的惨剧",b="斯温·约根曾是一名在暮色森林东南部耕作的普通农夫。在他外出时，从逆风小径策马而下的兜帽暗影骑士袭击了他的家园，屠杀了他的家人，他的人生由此破碎。斯温回到家看到屠杀现场时，瞥见一个不知名的人影在谷仓附近鬼鬼祟祟，慌忙地在土里埋着什么东西。斯温选择了复仇，他立即出发去追杀凶手，将那个被掩埋的东西丢在了身后。"},{t="挖掘秘密",b="如今，心怀愤怒的斯温在西部的山丘上安营扎寨，他需要有人回到约根农场。在农舍和破败谷仓之间的一截老树桩后，有一堆匆忙堆起的松散泥土。找回埋在那里的东西，是了解为何那些暗影骑士会对一位宁静的暮色森林农夫下手的关键第一步。"}},faq={{q="谁是斯温·约根？",a="斯温·约根曾是一位居住在暮色森林东南部，靠近逆风小径边缘的普通农夫。在回家发现家人被邪恶的骑士杀害后，他抛弃了农场，变成了一个一心只想向凶手复仇的隐士。",al={"斯温是谁","斯温背景故事","斯温人物传记"}},{q="斯温的农场发生了什么？",a="斯温的农场遭到了来自逆风小径的神秘暗影骑士的突袭。他们在斯温赶回防守之前就屠杀了他全家，并将农场洗劫一空。",al={"约根农场惨剧","斯温农场发生了什么","为什么斯温的农场被摧毁"}},{q="谁在谷仓后埋了东西？",a="屠杀刚刚发生后，斯温看到一个暗影般的身影潜伏在谷仓附近埋藏物品。为了追击暗影骑士，斯温逃向了荒野，没能抓住那个陌生人，也没能挖掘出被隐藏的东西。",al={"谁埋了那个东西","斯温农场的暗影人影","谁挖了土堆"}},{q="那堆松散的泥土在哪里？",a="那堆松散的泥土位于暮色森林东南部的约根农场，就在谷仓和破败农舍之间的一截老树桩的正后方。",al={"土堆在哪里","土堆位置","树桩在哪里"}},{q="暗影骑士是什么人？",a="暗影骑士是骑马从逆风小径中出来的邪恶兜帽骑士。关于他们的起源知之甚少，但他们在暮色森林的暴力入侵只会留下死亡与废墟。",al={"暗影骑士是什么","暗影骑士背景","逆风小径的骑士"}},{q="为什么斯温自己不挖出那个埋藏的物品？",a="当斯温回到家看到那个人埋藏物品时，他被悲痛所吞噬，立即去追赶撤退的暗影骑士了。等他建立起隐藏的营地时，农场已经被洗劫一空，对他来说那是一个过于痛苦、无法直接重返的地方。",al={"为什么斯温不去检查泥土","斯温为何离开"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="向安努回复",s="“返回奥努身边”是一个联盟任务，它终结了对黑海岸沿岸扎营的邪教徒的初步调查。在突袭了邪教徒的营地并尝试阅读《暮光宝典》后，冒险者获得了一张令人发狂的书页，需要将其交给古树之林里的知识古树奥努。",h="“返回奥努身边”是一个联盟任务，它终结了对黑海岸沿岸扎营的邪教徒的初步调查。在突袭了邪教徒的营地并尝试阅读《暮光宝典》后，冒险者获得了一张令人发狂的书页，需要将其交给古树之林里的知识古树奥努。",kw={"黑海岸","古树之林","令人发狂的书页","古神","奥努","暮光宝典","暮光之锤"},ang={["class:Druid"]="涂鸦中混乱且不自然的共鸣，代表了对自然秩序的亵渎，而德鲁伊正致力于与像奥努这样的树人共同维护这些秩序。",["faction:Alliance"]="调查黑海岸沿岸的邪教活动，可以确保像奥伯丁这样的暗夜精灵定居点免受隐秘威胁的侵害。",["race:NightElf"]="黑暗邪教徒对黑海岸的亵渎威胁到了知识古树们所守护的平衡，这使得奥努的警告与卡多雷息息相关。"},sec={{t="疯狂的一瞥",b="在暮光之锤的营地中发现《暮光宝典》后，任何窥视书中内容的人都会立刻感受到感官遭受的冲击。书写的文字在羊皮纸上游动舞动，原本华丽的卷轴装饰变成了怪诞的图形。精神上的压力如此巨大，以至于凡人的心智在屈服于眩晕之前，只能忍受撕下这一页胡乱涂写的笔记。"},{t="古老的疑虑",b="当这张碎片被送到奥努手中时，这位高大的古树辨认出了弥漫在其上的不自然气息。羊皮纸散发出一种混乱、原始的魔法，奥努将其直接归因于埋藏在地底的古老阴影力量。虽然这些潦草的涂鸦难以辨认，但它们证实了暮光之锤在黑海岸的存在并非单纯的强盗行径，而是某种更深层、更亵渎的计划的一部分。"}},faq={{q="从《暮光宝典》中取出的书页是什么？",a="这张书页被简单地称为“令人发狂的书页”，它是从该邪教的圣书中撕下来的一页。注视它会引起严重的精神痛苦，因为上面的文字会扭曲成与原始虚空魔法相连的怪诞、变幻的图形。",al={"令人发狂的书页","什么是涂鸦","暮光宝典书页"}},{q="奥努是谁？",a="奥努是一棵扎根于黑海岸南部古树之林的知识古树。他作为长者守护者和学者，引导暗夜精灵和联盟盟友对抗森林中出现的腐蚀。",al={"奥努是谁","奥努黑海岸","树人奥努"}},{q="奥努从这些涂鸦中学到了什么？",a="奥努感知到了从书页中散发出的混乱、原始的能量，并确认了古老邪恶实体的影响。这些文字表明暮光之锤的邪教徒正在黑海岸各处积极寻找遗迹地点和掩埋的力量。",al={"奥努发现了什么","涂鸦的含义"}},{q="为什么暮光之锤会出现在黑海岸？",a="该邪教被吸引到黑海岸是为了挖掘精灵遗迹，发掘与原始黑暗和古神有关的远古力量的痕迹，并利用这片土地上的混乱来掩盖他们的仪式。",al={"黑海岸的邪教徒","暮光之锤为何在此"}},{q="这项调查接下来会引向何处？",a="在发现邪教的存在后，奥努将注意力转向了北方的玛塞斯特拉废墟，指挥冒险者在邪教徒夺取这些古代遗物之前将其保护起来。",al={"下一个任务是什么","返回奥努身边后的后续"}},{q="为什么阅读宝典会导致头晕？",a="《暮光宝典》上刻有虚空和混乱的黑暗、疯狂魔法。这些符文会主动迷惑凡人的心智，引起幻觉和昏厥，从而阻止外人解开它们的秘密。",al={"为何宝典导致头晕","暮光宝典的效果"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani派你前往菲拉斯的莫沙彻营地，向巫医尤克里求助。尤克里以魔法闻名，也是一名猎人。",h="Tan'jani派你前往菲拉斯的莫沙彻营地，向巫医尤克里求助。尤克里以魔法闻名，也是一名猎人。",kw={"莫沙彻营地","菲拉斯","猎人","魔法","另一边","tan'jani","巫医尤克里"},sec={{t="Tan'jani的朋友",b="穿越菲拉斯，你可以在莫沙彻营地找到巫医尤克里，他是Tan'jani的老朋友。Tan'jani说尤克里精通魔法，也是一名猎人。你受命去和他谈谈，告别了广阔的平原。"}},faq={{q="是谁派我去找尤克里？",a="Tan'jani派你去找老朋友巫医尤克里。",al={"tan'jani派我去","谁是老tan'jani"}},{q="我在哪里能找到尤克里？",a="巫医尤克里在菲拉斯的莫沙彻营地。",al={"尤克里的位置","巫医在哪里"}},{q="我为什么要去找尤克里？",a="Tan'jani说尤克里正在寻求帮助，请你去和他谈谈。",al={"为什么找尤克里谈话","tan'jani想要什么"}},{q="尤克里是做什么的？",a="巫医尤克里精通魔法，也是一名猎人。",al={"尤克里的职业","巫医猎人"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="瑟伯切尔的Lumina Windsinger讲述了那场让Banon身受重伤的袭击。她说，在路上袭击他们的是一个狼人。",h="瑟伯切尔的Lumina Windsinger讲述了那场让Banon身受重伤的袭击。她说，在路上袭击他们的是一个狼人。",kw={"banon","豺狼人","lumina windsinger","路上的袭击","瑟伯切尔","the debt","狼人"},sec={{t="路上的伤痛",b="瑟伯切尔的Lumina Windsinger向你讲述了路上发生的事。一个体形巨大、形似狼的狼人袭击了她的队伍，杀死了随行的卫兵。Banon挡在那怪物和Lumina之间，Lumina则用一道法术将它赶走。那时，Banon已经被严重咬伤。他催她丢下自己离开，但她留了下来，两人一瘸一拐地继续前行，随后被豺狼人发现。"},{t="Banon的最后时刻",b="瑟伯切尔的Banon在转而攻击Lumina之前，已被豺狼人的利刃刺中多处。她看得出，他仍然认得她，却无法控制自己。Lumina相信，是那个狼人害了他，并发誓要杀死它，不让它给其他生灵带来同样的恐怖。"}},faq={{q="是谁在路上袭击了Lumina和Banon？",a="一个体形巨大、形似狼的狼人在路上袭击了Lumina和Banon。",al={"什么袭击了他们","狼人袭击","路上的袭击者"}},{q="卫兵们怎么样了？",a="狼人杀死了陪同Lumina和Banon的卫兵。",al={"卫兵的命运","卫兵怎么样了","路上的卫兵"}},{q="Lumina是怎么赶走狼人的？",a="Lumina设法施放了一道法术，惊吓了狼人，使它逃走了。",al={"狼人为何逃走","lumina的法术","什么吓跑了它"}},{q="Banon为什么会被咬伤？",a="Banon为了保护Lumina，奋不顾身地挡在狼人面前，被那怪物严重咬伤。",al={"banon被咬伤","banon如何受伤","banon发生了什么事"}},{q="Lumina在哪里向你讲述事情的经过？",a="Lumina Windsinger在瑟伯切尔向你讲述事情的经过。",al={"哪里能找到lumina","lumina的位置","瑟伯切尔"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan警告说，狼人威胁着银松森林，并指出Old Fire-Eye是个敌人，凭借未知魔法抗拒死亡。他请你查明打造一把特殊利刃所需的材料。",h="Trevan警告说，狼人威胁着银松森林，并指出Old Fire-Eye是个敌人，凭借未知魔法抗拒死亡。他请你查明打造一把特殊利刃所需的材料。",kw={"月吻之刃","利刃材料","old fire-eye","银松森林","特殊武器","trevan","狼人"},sec={{t="铁匠的清单",b="Old Fire-Eye是袭击Trevan及其同伴的狼人。Trevan会给你一份清单，列出打造对付他的武器所需的材料。材料备齐后，Trevan相信自己认识一位能打造这把利刃的铁匠。"}},faq={{q="Old Fire-Eye是谁？",a="Old Fire-Eye是体型最大、最凶狠的狼人，他袭击了Trevan及其同伴。",al={"old fire-eye","火眼狼人","大型狼人"}},{q="为什么Old Fire-Eye总能回来？",a="未知魔法让Old Fire-Eye无法真正死去。",al={"fire-eye为什么不会死","old fire-eye的魔法","不会死透的狼人"}},{q="Trevan需要我做什么？",a="Trevan会给你一份清单，列出打造特殊武器所需的材料。",al={"trevan想要什么","trevan的清单","利刃材料"}},{q="为什么需要特殊利刃？",a="Old Fire-Eye凭借未知魔法抗拒死亡，因此Trevan说必须用特殊武器才能彻底击倒他。",al={"月吻之刃为什么","对付old fire-eye的武器","杀死fire-eye"}},{q="谁能打造这把利刃？",a="Trevan相信自己认识一位能打造这把利刃的铁匠。",al={"打造利刃的铁匠","谁打造月刃","利刃铁匠"}}},fp="19,185,14.239.0,20.97.0,39.51.0,30.74.0,30.108.0,24.57.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="Data Hoarders是居住在铁炉堡的一名流亡侏儒耶玛所委托的任务。在诺莫瑞根绝望的大撤退期间，她将家族最珍贵的档案复制到了打孔卡上，却不慎在城市大门外的冰雪漂流中弄丢了几张。找回这些丢失的数据卡意味着要抢救从先进海军工程图纸到无可替代的家族食谱等一切重要资料。",h="Data...",kw={"数据囤积者","丹莫罗","诺莫瑞根","铁炉堡","耶玛","打孔卡","第二次战争","潜艇船体"},ang={["faction:Alliance"]="联盟非常依赖侏儒的独创性；帮助流离失所的难民保存战时工程记录，可以确保宝贵的联盟技术知识不会永远丢失。",["profession:Cooking"]="和世界级的工程图纸放在一起的，还有Quikswitch奶奶的个人辣椒食谱，这证明了美食与军事科学一样，具有同样的情感价值。",["profession:Engineering"]="工程师们可以体会到隐藏在这些卡片中的巨大价值，其中包括真实的第二次战争潜艇船体蓝图和复杂的奥术技术方程。",["race:Gnome"]="对于侏儒冒险者来说，找回这些打孔卡是文化保护的问题，确保重要的发明和家族记忆不会因为他们家园的放射性废墟而遗失。"},sec={{t="冰雪中的混乱",b="当穴居人入侵和随后的核辐射灾难迫使侏儒离开诺莫瑞根时，成千上万的人带着在混乱中抢到的任何物品逃离。耶玛采取了谨慎的措施，将几代人的家族知识转录到实体打孔卡档案中。不幸的是，一个破损的背包将几张关键卡片散落在了这座沦陷城市周围的雪原上。没有这些丢失的打孔卡，剩余的数据就会显示为无法解读的乱码，这可能会抹去她家族的知识遗产。"},{t="方程与辣椒",b="侏儒的数据档案反映了他们文明所侧重的奇异广度。Quikswitch家族的记录包括深奥的奥术技术领域方程、至关重要的第二次战争潜艇船体蓝图，以及Quikswitch奶奶的秘制辣椒食谱。对外人来说，将军事工程与家庭烹饪结合起来似乎很奇怪，但对于在铁炉堡幸存的难民来说，保存家庭生活的美好与保存技术奇迹同样重要。"}},faq={{q="耶玛是谁？",a="耶玛是一位设法逃脱诺莫瑞根陷落的侏儒难民，现在安全地居住在铁炉堡的矮人大厅中。",al={"耶玛","谁发布了数据囤积者","数据囤积者任务发布者"}},{q="丢失的卡片上存储了什么数据？",a="这些打孔卡保存着快换家族的档案，包括奥术技术方程、可追溯到第二次战争的潜艇船体图纸，以及快换奶奶的辣椒食谱。",al={"什么是打孔卡","卡片上有什么","快掣家族档案"}},{q="数据卡是在哪里丢失的？",a="它们在洁娜逃离诺莫瑞根时从她背包的破洞里滑落，埋在了丹莫罗这座地下城市大门外的雪地里。",al={"卡片在哪里","数据卡位置","她在哪里弄丢了卡片"}},{q="为什么没有丢失的卡片，洁娜就无法阅读幸存的卡片？",a="洁娜说，如果没有丢失的打孔卡，数据太乱了，无法恢复。任务中没有解释这些卡片是如何编码或组织这些信息的。",al={"为什么要找回所有卡片","乱码数据","打孔卡数据"}},{q="侏儒在第二次战争中对潜艇发挥了什么作用？",a="在第二次战争期间，侏儒通过先进的工程技术为联盟的军事行动做出了巨大贡献，特别是设计并驾驶潜水艇来对抗部落的海军部队。",al={"侏儒潜艇 第二次战争","潜艇船体设计"}},{q="为什么侏儒难民住在铁炉堡？",a="在诺莫瑞根因穴居人入侵和灾难性辐射而突然陷落后，幸存的侏儒逃离了他们的地下家园，并得到了国王麦格尼·铜须在邻近的矮人城市铁炉堡提供的庇护。",al={"为什么侏儒在铁炉堡","侏儒与矮人同住"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="灰谷的被遗忘者Ulric Frostveil发现，你在寻找科尔宝石，这对联盟施法者来说是再熟悉不过的差事。他指引你前往黑暗深渊，那里的纳迦仍在使用这些宝石。",h="灰谷的被遗忘者Ulric Frostveil发现，你在寻找科尔宝石，这对联盟施法者来说是再熟悉不过的差事。他指引你前往黑暗深渊，那里的纳迦仍在使用这些宝石。",kw={"灰谷","黑暗深渊","被遗忘者","科尔宝石","纳迦","乌尔里克·霜幕"},sec={{t="灰谷中的宝石",b="Ulric让你从灰谷北面的黑暗深渊废墟带回一枚科尔宝石。他说，下面的纳迦仍在使用这些宝石，它们可以强化魔法武器和器具。他警告你不要独自前往。"},{t="Ulric的意图",b="Ulric察觉到宝石中有腐化之力，并说他能驱散纳迦女巫注入其中的邪恶。他还问你是否愿意把宝石卖给他，用于学术研究。"}},faq={{q="乌尔里克·霜幕是谁？",a="乌尔里克·霜幕是灰谷的一名被遗忘者，他请你给他带回一枚科尔宝石。",al={"乌尔里克·霜幕","乌尔里克是谁","灰谷的被遗忘者"}},{q="我在哪里能找到科尔宝石？",a="乌尔里克指引你向北前往黑暗深渊，纳迦仍在那里使用科尔宝石。",al={"科尔宝石位置","宝石在哪里","黑暗深渊宝石"}},{q="科尔宝石有什么用途？",a="科尔宝石有时会被用来强化魔法武器和器具。",al={"科尔宝石用途","宝石魔法","科尔宝石有什么作用"}},{q="乌尔里克为什么想要科尔宝石？",a="乌尔里克请你给他带回一枚科尔宝石，并说他可能会将其用于学术研究。",al={"乌尔里克想要宝石","为什么要宝石","霜幕的宝石"}},{q="还有谁在使用科尔宝石？",a="黑暗深渊的纳迦仍在使用科尔宝石。",al={"纳迦宝石","谁在使用科尔宝石","黑暗深渊纳迦"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="一名地精有一件货物要送给法霍德要塞的骑士指挥官 Demar Brant。你受托将 Frazzlespark's Crate 送给他。",h="一名地精有一件货物要送给法霍德要塞的骑士指挥官 Demar Brant。你受托将 Frazzlespark's Crate 送给他。",kw={"箱子","demar brant","法霍德要塞","frazzlespark","frazzlespark's crate","地精的货物","骑士指挥官"},sec={{t="送往要塞的货物",b="Frazzlespark 让你前往西南方的法霍德要塞，骑士指挥官 Demar Brant 正在那里等候。箱子是送给他的，地精特意说出了他的全名。到了要塞，Demar 称地精不过是达成目的的手段，是他所说的那些交易的一部分；他声称，这些交易能确保自己族人的安全与成功。"}},faq={{q="谁在等着收箱子？",a="骑士指挥官 Demar Brant 正在法霍德要塞等着收 Frazzlespark's Crate。",al={"谁要这个箱子","demar brant 的货物"}},{q="我该把 Frazzlespark's Crate 送到哪里？",a="把 Frazzlespark's Crate 送到法霍德要塞，交给骑士指挥官 Demar Brant。要塞位于 Frazzlespark 西南方。",al={"箱子的位置","法霍德要塞在哪里"}},{q="为什么 Demar 要求别人叫他的全名？",a="Frazzlespark 提到，Demar 总让这名地精叫他的全名，但没有说明原因。",al={"demar 的全名","为什么是骑士指挥官"}},{q="为什么 Frazzlespark 称它为特别货物？",a="Frazzlespark 称这是一件特别货物，并说 Demar Brant 正在法霍德要塞等着收货。",al={"箱子交付","箱子有什么特别之处"}},{q="这件货物为什么重要？",a="Demar Brant 说，为了确保自己族人的安全与成功，有些交易非做不可；他称那名地精不过是达成目的的手段。",al={"为什么要送箱子","地精的安全"}}},fp="20,126,19.303.0,29.82.0,37.102.0,39.95.0,49.98.0,30.152.0"}
P.entries["quest:95062"] = {n="Frazzlespark's Crate",s="Frazzlespark送来一件货物，要送到洛格玛的Old Krom'rosh那里。请迅速且小心地把箱子送去。",h="Frazzlespark送来一件货物，要送到洛格玛的Old Krom'rosh那里。请迅速且小心地把箱子送去。",kw={"箱子","送货","frazzlespark","frazzlespark的箱子","krom'rosh","old krom'rosh","包裹","洛格玛"},sec={{t="谨慎送货",b="Frazzlespark有一件包裹要交给Old Krom'rosh，他正在此处以西不远的洛格玛等候。有人请你迅速且小心地送去，却没有说明原因。Krom'rosh的交易有助于实现他们的目标。"}},faq={{q="谁在等Frazzlespark的箱子？",a="Old Krom'rosh正在洛格玛等Frazzlespark的箱子。",al={"谁收箱子","给krom'rosh的箱子","krom'rosh的包裹"}},{q="洛格玛在哪里？",a="洛格玛就在Frazzlespark以西不远处。",al={"洛格玛在哪里","洛格玛位置","洛格玛地点"}},{q="我该怎么处理这个箱子？",a="迅速且小心地把Frazzlespark的箱子送到洛格玛的Old Krom'rosh那里。",al={"送箱子","frazzlespark送货","该做什么"}},{q="为什么送箱子需要小心？",a="Frazzlespark建议你迅速且小心地送达，但没有说明原因。",al={"为什么要小心","为什么急着送箱子","箱子的原因"}},{q="Krom'rosh为什么要做这类交易？",a="Krom'rosh说，这类交易有助于实现他们的目标。",al={"krom'rosh的交易","为什么建立关系","交易的目的"}}},fp="20,112,18.231.0,40.61.0,17.37.0,32.78.0,41.81.0,48.57.0"}
P.entries["quest:95063"] = {n="Bloodmaster's Ring",s="你在Bolder'ok的Bloodmaster's Ring中惹怒了Chub'chob。竞技场的入场费不提供免于死亡的保障，你只能独自面对他。",h="你在Bolder'ok的Bloodmaster's Ring中惹怒了Chub'chob。竞技场的入场费不提供免于死亡的保障，你只能独自面对他。",kw={"竞技场","血斗士首领","bloodmaster's ring","bolder'ok","chub'chob","clugfist","食人魔"},sec={{t="竞技场的挑战",b="在Bolder'ok的Bloodmaster's Ring中参加几场比斗后，警告才随之而来，而你早已惹恼了Chub'chob。看守提醒你，入场费不包含意外死亡的保障。从此刻起，你只能独自面对Bolder'ok的Bloodmaster Chub'chob。"},{t="新的地位",b="你回到Clugfist身边，带去自己已成为Bloodmaster's Ring冠军的消息。你的胜利让你在这个氏族中结交了一位新朋友。如今，你可以和食人魔们一起战斗、享用盛宴。"}},faq={{q="Chub'chob是谁？",a="Chub'chob是Bolder'ok的Bloodmaster，而你已经在角斗场中惹怒了他。",al={"chub'chob","血斗士首领","chub'chob是谁"}},{q="Bloodmaster's Ring在哪里？",a="Bloodmaster's Ring位于Bolder'ok。",al={"bloodmaster's ring位置","bolder'ok竞技场","在哪里战斗"}},{q="我该告诉谁自己成为了冠军？",a="你把自己成为Bloodmaster's Ring冠军的消息告诉了Bolder'ok的Clugfist。",al={"冠军消息","告诉clugfist","该告诉谁"}},{q="入场费包含意外死亡的保障吗？",a="不包含。看守警告说，入场费不包含意外死亡的保障。",al={"死亡费用","竞技场入场费","入场费能保命吗"}}},fp="18,146,21.260.0,14.196.1,17.80.0,32.39.0,38.102.0,42.75.0"}
P.entries["quest:95064"] = {n="Preventative Measures",s="Terral's Watch的Watcher Cornelius担心兽人正进一步深入平原。他请你遏制兽人日益扩大的势力。",h="Terral's Watch的Watcher Cornelius担心兽人正进一步深入平原。他请你遏制兽人日益扩大的势力。",kw={"兽人","平原","预防措施","洛格玛训练兵","terral's watch","watcher cornelius"},sec={{t="平原上的兽人",b="在Terral's Watch，Watcher Cornelius看到兽人正在河边占地，并向平原扩张。他请你杀死洛格玛训练兵，希望阻止他们推进。"}},faq={{q="谁在请求帮助？",a="Terral's Watch的Watcher Cornelius请你阻止兽人势力日益扩大。",al={"谁需要帮助","科尼利厄斯的请求"}},{q="Cornelius为什么担心兽人？",a="兽人已经占据了河边的土地，而且他们在平原上的势力正在扩大。",al={"为何与兽人战斗","平原上的兽人"}},{q="Cornelius想杀死哪些兽人？",a="Cornelius请你杀死洛格玛训练兵。",al={"洛格玛训练兵","哪些兽人"}},{q="Cornelius在哪里请求帮助？",a="Cornelius在Terral's Watch请求帮助。",al={"terral's watch","科尼利厄斯在哪里"}}},fp="21,132,18.176.0,18.80.0,42.85.0,38.44.0,34.42.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="“Fishin' Time”是吉尔伯特·格雷（Gilbert Gray）发布的一项简单的跑腿任务。这位年迈的垂钓者正悠闲地坐在暴风城港口，享受着迷人的海岸风光。就在鱼群开始上钩时，他的鱼饵用完了，因此他请求路过的冒险者前往城内的运河区，帮他补给鱼饵盒。",h="“Fishin' Time”是吉尔伯特·格雷（Gilbert...",kw={"运河","凯瑟琳·莱兰","钓鱼时间","吉尔伯特·格雷","夜行虫","发光的浮漂","暴风城港口","贸易区"},ang={["faction:Alliance"]="花时间协助像吉尔伯特·格雷这样的老市民，体现了维持暴风城生活与士气的点滴日常琐事。",["race:Human"]="对于以暴风城为家的人类来说，帮助邻里长辈度过一个宁静的午后钓鱼时光，是远离王国政治纷争的一种惬意调剂。"},sec={{t="水边的一天",b="并非暴风城里的每个人都沉浸在政治、战争或迫在眉睫的阴谋之中。在港口边，吉尔伯特·格雷度过着平静的日子，享受着海风，看着浮漂在潮汐中起舞。但狂热的垂钓者很容易忘了查看自己的渔具，而鱼群一阵接一阵地上钩，很快就会耗尽哪怕是准备最充分的饵料罐。与其放弃他珍视的鲈鱼，这位老人转向好心的冒险者请求补给，希望能补充必需品。"},{t="运河边的补给",b="暴风城的本地垂钓需求都经由凯瑟琳·莱兰（凯瑟琳·利兰）满足。她在繁忙的贸易区以西，沿着石砌运河经营着一家知名的渔具店。莱兰为全城的渔民供应鱼饵和诱饵，确保像吉尔伯特·格雷这样的老顾客永远不会因为缺少发光的浮漂或扭动的夜行虫而不得不提前收竿。"}},faq={{q="吉尔伯特·格雷是谁？",a="吉尔伯特·格雷是一位年迈的渔夫，驻守在暴风城港口的水边。他满足于在海边度过抛竿垂钓的日子，当补给不足时，他会请路过的冒险者帮忙去取新鲜的鱼饵和诱饵。",al={"吉尔伯特·格雷","老格雷","谁发布的任务"}},{q="凯瑟琳·莱兰是谁？",a="凯瑟琳·莱兰是暴风城的常驻渔具供应商。她的商店位于贸易区以西的城市运河沿岸，在那里她向王国的垂钓者出售渔具和鱼饵。",al={"凯瑟琳·莱兰","暴风城渔具供应商","莱兰 暴风城"}},{q="吉尔伯特·格雷在哪里钓鱼？",a="吉尔伯特·格雷位于暴风城港口的水边，在那里他可以避开拥挤的城市街道，欣赏广阔的海景。",al={"吉尔伯特·格雷位置","吉尔伯特·格雷在哪里","港口渔夫"}},{q="吉尔伯特·格雷需要什么补给？",a="吉尔伯特·格雷需要夜行虫作为鱼饵，还需要一个发光的浮漂作为诱饵，这两样东西都可以从运河边的凯瑟琳·莱兰那里买到。",al={"钓鱼时间任务物品","格雷需要什么鱼饵"}},{q="为什么吉尔伯特·格雷不自己去取补给？",a="当你与他交谈时，鱼正咬钩咬得欢，他不想为了跑回城里补货而错过这个绝佳的垂钓点或放跑好鱼。",al={"为什么格雷不能自己买鱼饵","为什么格雷需要帮助"}},{q="凯瑟琳·莱兰的商店在运河哪里？",a="她的商店位于贸易区以西，正对着运河水域，可以直接从横跨城市水道网的石砌人行道到达。",al={"凯瑟琳·莱兰位置","莱兰的商店在哪里","贸易区运河"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="玛塞斯特拉遗物",s="这个任务指引联盟探险者沿着黑海岸的海岸线向北，去搜寻杂草丛生的玛塞斯特拉废墟。欧努，一位扎根于古树之林的知识古树，正在寻找这些古老的卡多雷神器，以了解暮光之锤教派是如何利用暗夜精灵魔法来举行邪恶仪式的。",h="这个任务指引联盟探险者沿着黑海岸的海岸线向北，去搜寻杂草丛生的玛塞斯特拉废墟。欧努，一位扎根于古树之林的知识古树，正在寻找这些古老的卡多雷神器，以了解暮光之锤教派是如何利用暗夜精灵魔法来举行邪恶仪式的。",kw={"黑海岸","古树之林","主宰之剑","玛塞斯特拉","欧努","遗物","玛塞斯特拉废墟","暮光之锤"},ang={["class:Druid"]="帮助欧努可以让德鲁伊侍奉自然界最伟大的长者哨兵之一，保护黑海岸的古老历史不被黑暗教徒所扭曲。",["faction:Alliance"]="防止暮光之锤将古代魔法武器化，对于保护卡利姆多北部免受黑暗地下势力的侵害至关重要。",["race:NightElf"]="对于暗夜精灵来说，看着他们大分裂前辉煌时期的遗物被从土里挖出来，这既是对文明衰落的沉痛提醒，也是一个令人震惊的警告：他们祖先的强大技艺正被末日疯子所利用。"},sec={{t="一项令人不安的发现",b="在探险者从潜伏在名为“主宰之剑”的巨大纪念碑周围的教徒手中找回一份被污染的羊皮纸后，欧努解读出了一个令人不安的真相。上面的文字并非本土教派的经文，而是一段被诅咒的古暗夜精灵文字残片。这份被暮光之锤污染的羊皮纸揭示，这些末日狂热者正在利用被遗忘的精灵魔法来唤醒或召唤他们古老的主人回到凡间。"},{t="陨落的壁垒",b="为了对抗这一邪恶企图，欧努指引英雄们前往位于黑海岸东北岸的玛塞斯特拉废墟。很久以前，玛塞斯特拉曾是上层精灵文明的一座辉煌壁垒，但在大分裂中毁于一旦。虽然这座城市已经沦为瓦砾、杂草丛生并遭到纳迦的入侵，但其最初奥术和精神魔法的强大残余仍萦绕在散落于石基之上的破碎骨灰瓮和古代遗物中。"},{t="洞悉黑暗阴谋",b="通过从废墟杂草丛生的瓦砾中收集幸存的工艺品，黑海岸的守卫者们希望揭开教徒们打算利用的具体手段。欧努研究着注入在这些遗物中的残留魔法，与时间赛跑，试图在暮光之锤完全扭曲古老的卡多雷魔法以解放其地下主人之前，解读出教派的计划。"}},faq={{q="什么是黑暗深渊遗物？",a="它们是遗留在玛塞斯特拉废墟中的附魔陶器、骨灰瓮和工艺品的碎片。它们创造于大分裂前古暗夜精灵文明的鼎盛时期，至今仍散发着残留的魔法能量。",al={"什么是遗物","黑暗深渊遗物背景","玛塞斯特拉精灵遗物"}},{q="欧努为什么想要这些遗物？",a="欧努发现暮光之锤教派正在利用古老的精灵魔法，试图将他们的黑暗主人带回这个世界。通过研究从玛塞斯特拉找回的完整遗物，欧努希望了解该教派打算如何操纵那股古老的力量。",al={"欧努为何需要遗物","黑暗深渊遗物的用途"}},{q="玛塞斯特拉废墟位于何处？",a="废墟位于黑海岸的东北海岸线沿途，在亚米萨兰和巴莎兰废墟以北，刚过奥萨拉克斯之塔。",al={"玛塞斯特拉在哪里","玛塞斯特拉位置"}},{q="暮光之锤试图召回谁？",a="该教派崇拜古老而邪恶的主人；欧努警告说，他们正在使用古老的精灵魔法将那些古老的主人带回艾泽拉斯。",al={"暮光之锤的主人是谁","黑海岸教派主人"}},{q="玛塞斯特拉在成为废墟之前是什么？",a="玛塞斯特拉曾是数千年前暗夜精灵的一座伟大壁垒和城市。它在大分裂期间沦为废墟，此后被荒野、鬼魂以及像纳迦这样邪恶的沿海生物所占据。",al={"玛塞斯特拉历史","玛塞斯特拉是什么"}},{q="谁提供了“黑暗深渊遗物”任务？",a="该任务由欧努提供，这是一位扎根于黑海岸中南部古树之林的远古树人，在调查过主宰之剑后即可领取。",al={"谁发布黑暗深渊遗物任务","黑暗深渊遗物任务发放者"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="银松森林的Trevan Rol请你把材料带给塔伦米尔的奥特，并请他承接一份定制委托。他打造的简易刀刃令幽暗城的铁匠们刮目相看，这份委托给了他展示手艺的机会。",h="银松森林的Trevan Rol请你把材料带给塔伦米尔的奥特，并请他承接一份定制委托。他打造的简易刀刃令幽暗城的铁匠们刮目相看，这份委托给了他展示手艺的机会。",kw={"委托","定制刀刃","奥特","铁匠","塔伦米尔","幽暗城","武器匠"},sec={{t="铁匠的机会",b="Trevan Rol请你把材料带给塔伦米尔的奥特，并请他承接一份委托。奥特以向旅人出售简易刀刃而闻名。Trevan买了一把，后来带到幽暗城保养，当地铁匠对它的品质感到惊讶。他们以为那是出自名匠之手，没想到竟是奥特的作品。如今，你要给他一个机会，让他按你的要求锻造一把刀刃。"},{t="奥特的答复",b="奥特说，以前从没人请他承接定制委托。他通常按自己的风格打造朴实实用的武器，并表示自己并不追求名声。虽然愿意一试，但他不明白，你为何选择他，毕竟幽暗城也有铁匠承接定制委托。"}},faq={{q="奥特是谁？",a="奥特是塔伦米尔的一名武器匠，向旅人出售简易刀刃。",al={"奥特 铁匠","奥特是谁","塔伦米尔铁匠"}},{q="为什么幽暗城的铁匠要我去找奥特？",a="那名铁匠买过奥特打造的刀刃，听到幽暗城的铁匠称赞它的品质后感到惊讶。他想给奥特一个机会，让他打造一件特别的作品。",al={"为什么找奥特","幽暗城铁匠委托","奥特 委托"}},{q="我要给奥特带什么？",a="你要把材料带给塔伦米尔的奥特，并请他承接委托，为你锻造一把刀刃。",al={"给奥特的材料","我要带什么","奥特 材料"}},{q="奥特会打造定制武器吗？",a="奥特说，以前从没人请他承接定制委托，但他很乐意一试。",al={"奥特 定制刀刃","奥特能为我锻造吗","奥特 定制委托"}},{q="为什么奥特问我为何选择他？",a="奥特说幽暗城也有铁匠承接定制委托，他不明白你为何舍近求远来找他。",al={"为什么选奥特","奥特纳闷原因","为什么不找幽暗城铁匠"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="一名港口管理员请你清剿东风海岸的鱼人。水手、渔夫，甚至他的孩子们，都一直在抱怨这些麻烦家伙。",h="一名港口管理员请你清剿东风海岸的鱼人。水手、渔夫，甚至他的孩子们，都一直在抱怨这些麻烦家伙。",kw={"东风海岸","渔夫","murloc","murloc oracle","murloc warrior","港口管理员","水手","saltwater savages"},sec={{t="港口的抱怨",b="港口管理员听够了水手、渔夫，甚至自己孩子们的抱怨。鱼人让他头疼，但他还得经营港口。他请你去东风海岸杀掉一些鱼人，希望周围的喧闹能消停一阵。"}},faq={{q="港口管理员为什么要杀鱼人？",a="水手、渔夫和港口管理员的孩子们总在抱怨鱼人。他称它们是麻烦，并希望经营港口时能清静一些。",al={"为何杀鱼人","鱼人骚扰港口"}},{q="他指的是哪些鱼人？",a="他请你去东风海岸杀掉 Murloc Oracles 和 Murloc Warriors。",al={"鱼人种类","预言者和战士"}},{q="鱼人在哪里？",a="港口管理员告诉你去东风海岸找鱼人。",al={"东风海岸的鱼人","鱼人在哪里"}},{q="杀掉这些鱼人能解决问题吗？",a="港口管理员料想很快会有更多鱼人回来，但他希望它们死后，自己能清静一阵。",al={"鱼人会回来","事情结束了吗"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95119"] = {n="Unfriendly Competition",s="爆破引线港的一位店主请你制止 Eastsea crew 袭击货物和船只。他们最近的成员就在 Eastwind Shore 一带。",h="爆破引线港的一位店主请你制止 Eastsea crew 袭击货物和船只。他们最近的成员就在 Eastwind Shore 一带。",kw={"货物失窃","eastsea 海盗","eastsea crew","eastsea 火枪手","eastwind shore","爆破引线港","船只沉没","竞争对手"},sec={{t="沿岸地带",b="船只沉没，货物失窃，爆破引线港店主的生意因此受损。离港口最近的是 Eastsea crew 的海盗和火枪手，他们就在北面的 Eastwind Shore 一带。店主希望你先对付他们；这伙人的其他行动仍是个隐患。"}},faq={{q="谁在求助？",a="爆破引线港的一位店主请你对付 Eastsea crew。",al={"谁发布了这个任务","港口店主","爆破引线港的人"}},{q="Eastsea crew 是什么人？",a="据说 Eastsea crew 残暴嗜血，他们偷窃货物、击沉船只。",al={"eastsea 海盗","eastsea 的人","eastsea 是什么人"}},{q="店主为什么想制止他们？",a="这伙人偷窃货物、击沉船只，让店主蒙受损失。",al={"为何对付 eastsea","货物失窃","船只为何沉没"}},{q="Eastsea crew 在港口附近的什么地方？",a="离爆破引线港最近的成员就在北面的 Eastwind Shore 一带。",al={"eastwind shore","海盗在哪里","北部海滩"}}},fp="22,142,15.313.0,23.71.0,25.100.0,42.68.0,47.86.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="码头主管Whizzbuzz悬赏征求Old Rot-Chum死亡的证据。这只好斗的鱼人一直在南部海域袭击小船。",h="码头主管Whizzbuzz悬赏征求Old Rot-Chum死亡的证据。这只好斗的鱼人一直在南部海域袭击小船。",kw={"鱼人","鱼人岛屿","old rot-chum","划艇","小船","南部海域","码头主管whizzbuzz"},sec={{t="海上威胁",b="南部海域的水手和游泳者经常遭到袭击，目标是划艇和其他小船。当地渔夫称袭击者为Old Rot-Chum，这是一只好斗的鱼人。码头主管Whizzbuzz悬赏征求它死亡的证据，并请你把证据带给他。"}},faq={{q="Old Rot-Chum是谁？",a="Old Rot-Chum是当地渔夫给一只格外好斗的鱼人起的绰号。",al={"old rot-chum","rot-chum","谁是rot-chum"}},{q="在哪里见过Old Rot-Chum？",a="有人在南部海域见过Old Rot-Chum，那里靠近鱼人横行的岛屿。",al={"old rot-chum在哪里","rot-chum的位置","鱼人在哪里"}},{q="Old Rot-Chum袭击什么？",a="Old Rot-Chum一直在袭击划艇和其他小船。",al={"rot-chum袭击什么","船只遇袭","鱼人与划艇"}},{q="谁提供悬赏？",a="码头主管Whizzbuzz悬赏征求Old Rot-Chum死亡的证据。",al={"谁要rot-chum的证据","码头主管的悬赏","谁悬赏抓old rot-chum"}},{q="Whizzbuzz要什么证据？",a="码头主管Whizzbuzz请你带来Old Rot-Chum死亡的证据。",al={"rot-chum的什么证据","带来证据","死亡的证据"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz想为他的水上咖啡馆新炖菜准备新鲜海鲜。你收集当地食材，为菜单换换花样。",h="Fimbo Greasemitz想为他的水上咖啡馆新炖菜准备新鲜海鲜。你收集当地食材，为菜单换换花样。",kw={"海滩","咖啡馆","fimbo greasemitz","鱼","鱼人眼睛","烤野猪肉","sand crawler的肉","海鲜炖菜"},ang={["profession:Cooking"]="作为一名厨师，你看得出Fimbo正在寻找新鲜的本地食材，准备做一道海鲜炖菜。"},sec={{t="一道新菜",b="Fimbo Greasemitz经营着一家水上咖啡馆，每天的菜单上都有烤野猪肉和鱼。他想试做一道海鲜炖菜，请你从附近的海滩带回鱼人的眼睛和Sand Crawler的肉。"}},faq={{q="Fimbo Greasemitz是谁？",a="Fimbo Greasemitz经营着一家水上咖啡馆，想在菜单上添一道海鲜炖菜。",al={"fimbo是谁","fimbo咖啡馆","fimbo grease­mitz"}},{q="Fimbo需要什么食材？",a="Fimbo请你为他的海鲜炖菜带回鱼人的眼睛和Sand Crawler的肉。",al={"炖菜食材","什么肉","鱼人眼睛"}},{q="Fimbo为什么想做海鲜？",a="他想用一道新的海鲜炖菜给咖啡馆每天供应的烤野猪肉和鱼换换花样。",al={"为什么炖菜","新菜单","咖啡馆食物"}},{q="在哪里能找到这些食材？",a="Fimbo说，附近的海滩上能找到鱼人的眼睛和Sand Crawler的肉。",al={"哪里有肉","哪里有食材","海滩上的东西"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95122"] = {n="Unchecked Expansion",s="码头管理员 Whizzbuzz 说，这里的北面有东海海盗，他们比你先前对付过的敌人更具威胁。他们的袭击让迎风庄园化为焦土，他希望阻止他们向内陆推进。",h="码头管理员 Whizzbuzz 说，这里的北面有东海海盗，他们比你先前对付过的敌人更具威胁。他们的袭击让迎风庄园化为焦土，他希望阻止他们向内陆推进。",kw={"eastsea bombardiers","东海海盗","eastsea raiders","海盗","unchecked expansion","码头管理员 whizzbuzz","迎风庄园"},sec={{t="化为灰烬的迎风庄园",b="东海海盗洗劫迎风庄园，劫走财物后将其付之一炬。码头管理员 Whizzbuzz 请你削弱这里北面的劫掠者和轰炸兵。他担心海盗会把地盘进一步扩展到内陆。"}},faq={{q="谁请求你帮忙对付东海海盗？",a="码头管理员 Whizzbuzz 请你削弱东海海盗的兵力。",al={"谁需要帮助","whizzbuzz 的任务","码头管理员"}},{q="迎风庄园遭遇了什么？",a="东海海盗洗劫了迎风庄园，劫走财物，并将其夷为平地。",al={"迎风庄园被烧毁","这里发生了什么","迎风庄园为何消失"}},{q="目标是哪一伙海盗？",a="码头管理员 Whizzbuzz 指出，Eastsea Raiders 和 Eastsea Bombardiers 是需要削弱的海盗。",al={"海盗类型","我该对付谁","eastsea raiders"}},{q="Whizzbuzz 为什么想削弱他们的兵力？",a="他想阻止海盗将地盘进一步扩展到内陆。",al={"为何阻止海盗","海盗进入内陆","为何对付东海海盗"}}},fp="19,188,18.241.0,46.66.0,27.87.0,29.91.0,44.68.0"}
P.entries["quest:95123"] = {n="A Blast Ye Scurvy Dogs!",s="码头管理员 Whizzbuzz 想用火药摧毁 Eastsea 海盗船。你受命前往被夷为平地的 Winstead 附近寻找火药桶。",h="码头管理员 Whizzbuzz 想用火药摧毁 Eastsea 海盗船。你受命前往被夷为平地的 Winstead 附近寻找火药桶。",kw={"eastsea 海盗","火药","海盗船","火药桶","码头管理员 whizzbuzz","winstead"},sec={{t="给码头管理员的火药",b="在 Eastsea 海盗之后，Whizzbuzz 接下来要对付的就是那些船。他认为海盗可能把火药存放在北面刚被夷为平地的 Winstead 附近。你受命寻找火药桶；他稍后会解释自己的计划。"}},faq={{q="谁在索要火药？",a="码头管理员 Whizzbuzz 想要火药，用来对付 Eastsea 的船只。",al={"谁要火药桶","whizzbuzz 火药","谁派我来"}},{q="Whizzbuzz 为什么想要火药？",a="他想摧毁 Eastsea 的船只，免得它们逃走并召来援兵。",al={"为什么要火药","火药有什么用","eastsea 船只计划"}},{q="海盗可能把火药存放在哪里？",a="Whizzbuzz 认为海盗可能把火药存放在北面刚被夷为平地的 Winstead 附近。",al={"火药位置","火药桶在哪里","winstead 火药"}},{q="Whizzbuzz 的计划是什么？",a="Whizzbuzz 说他稍后会解释计划；眼下，他要你去找火药。",al={"他的计划是什么","whizzbuzz 计划","会发生什么"}}},fp="23,137,26.241.0,29.75.0,34.78.0,47.105.0,25.88.0"}
P.entries["quest:95124"] = {n="Admiral Lamora",s="码头主管 Whizzbuzz 派你去追杀 Admiral Lamora。他乘坐一艘位于 Whizzbuzz 东北方的 Eastsea 船只。Lamora 的战利品或许能帮 Whizzbuzz 挽回掠夺造成的部分损失。",h="码头主管 Whizzbuzz 派你去追杀 Admiral Lamora。他乘坐一艘位于 Whizzbuzz 东北方的 Eastsea 船只。Lamora 的战利品或许能帮 Whizzbuzz 挽回掠夺造成的部分损失。",kw={"admiral lamora","eastsea","钥匙","战利品","掠夺","藏匿处","码头主管 whizzbuzz"},sec={{t="Whizzbuzz 的损失",b="码头主管 Whizzbuzz 要求杀死 Admiral Lamora，并带回他的战利品。Lamora 在 Whizzbuzz 东北方的一艘 Eastsea 船只上。你要找出他乘坐哪艘船，以及他把掠夺来的财物藏在哪里。若财物被锁了起来，Whizzbuzz 猜测钥匙就在 Lamora 身上。"}},faq={{q="是谁派我去追杀 Admiral Lamora？",a="码头主管 Whizzbuzz 派你去追杀 Admiral Lamora，并要你带回 Lamora 的战利品。",al={"谁想杀死 lamora","whizzbuzz 的请求","admiral lamora 任务"}},{q="Admiral Lamora 在哪里？",a="Lamora 在一艘 Eastsea 船只上，就在码头主管 Whizzbuzz 的东北方。",al={"lamora 在哪儿","lamora 的位置","哪艘 eastsea 船"}},{q="Whizzbuzz 为什么要杀死 Lamora？",a="Whizzbuzz 说，Lamora 的掠夺让他损失惨重，他想挽回部分损失。",al={"为何杀死 lamora","whizzbuzz 复仇","lamora 和 whizzbuzz"}},{q="Whizzbuzz 想从 Lamora 那里得到什么？",a="Whizzbuzz 要求杀死 Lamora，并带回他的战利品。他猜测，如果藏匿处上了锁，钥匙就在 Lamora 身上。",al={"从 lamora 那里拿什么","lamora 的战利品","藏匿处是什么"}},{q="我回来之后会怎样？",a="Whizzbuzz 说，他原本不确定你能否在与 Lamora 的交锋中活下来，随后表示愿意帮你一个忙，还说以后可能会再找你。",al={"whizzbuzz 说了什么","回到 whizzbuzz 那里","whizzbuzz 感谢"}}},fp="14,192,18.272.0,39.96.0,24.81.0,36.104.0,37.113.0,28.127.0"}
P.entries["quest:95125"] = {n="Ott's Masterwork",s="奥特已准备好用上好的材料为你锻造一把利刃。你受邀观看他的工作。",h="奥特已准备好用上好的材料为你锻造一把利刃。你受邀观看他的工作。",kw={"铁匠","利刃","锻造","杰作","材料","奥特"},sec={{t="在锻炉旁",b="奥特认为这些材料品质上乘，也希望自己的作品能达到你的期望。他为你锻造利刃，随后将其交给你，供你踏上旅途。"}},faq={{q="谁在为我锻造利刃？",a="奥特正在用你提供的上好材料锻造利刃。",al={"谁在锻造","奥特的利刃","奥特铁匠"}},{q="我能观看奥特锻造吗？",a="奥特请你退后一些，随后开始锻造；你要做的是观看他工作。",al={"观看奥特锻造","看利刃如何制成","锻造过程"}},{q="利刃完成后，奥特会说什么？",a="奥特称这把利刃是他的得意之作，并希望它在你的旅途中能派上用场。",al={"奥特完工","奥特说什么","利刃完成"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="Trevan Rol请你将Ott's Masterwork带给他，地点在银松森林。这把剑是他面对野兽前完成的最后一件作品。",h="Trevan Rol请你将Ott's Masterwork带给他，地点在银松森林。这把剑是他面对野兽前完成的最后一件作品。",kw={"野兽","露米娜","月银之刃","奥特","奥特的杰作","银松森林","特雷文·罗尔"},sec={{t="这把剑",b="奥特感谢你给了他这个机会，并请你代他向Trevan转达谢意。你将Ott's Masterwork带回银松森林，交给Trevan Rol。"},{t="Trevan的认可",b="Trevan检查了这把剑，认可奥特的手艺。他说接下来只剩下杀死野兽，并让你准备好后去找Lumina。"}},faq={{q="是谁打造了奥特的杰作？",a="奥特打造了这把剑，并让你把它送给特雷文·罗尔。",al={"谁打造了这把剑","奥特的剑","杰作打造者"}},{q="特雷文·罗尔是谁？",a="特雷文·罗尔负责在银松森林接收并检查奥特的杰作。",al={"特雷文是谁","特雷文的剑","特雷文·罗尔"}},{q="我该把这把剑带到哪里？",a="把奥特的杰作带到银松森林交给特雷文·罗尔。",al={"剑要送到哪里","把奥特的杰作带到哪里","剑的去处"}},{q="特雷文觉得这把剑怎么样？",a="特雷文检查了这把剑，说它很合用。",al={"特雷文喜欢这把剑吗","奥特的剑好吗","特雷文的认可"}},{q="特雷文之后我该和谁交谈？",a="特雷文让你准备好后去找露米娜。",al={"接下来做什么","露米娜是谁","找露米娜交谈"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger让你在银松森林用月银之刃猎杀Old Fire-Eye。塑风者正等着他毙命，Lumina希望这把剑能助你一臂之力。",h="Lumina Windsinger让你在银松森林用月银之刃猎杀Old Fire-Eye。塑风者正等着他毙命，Lumina希望这把剑能助你一臂之力。",kw={"巴农","吉尔尼斯","露米娜·风歌","月银之刃","老火眼","银松森林","塑风者"},sec={{t="剑的使命",b="你已从塑风者那里得到月银之刃。当地人说，Old Fire-Eye常在此地以南一带广阔的区域出没，通常就在通往吉尔尼斯的大门附近。Lumina让你找到他，用这把剑了结他。塑风者的感激全系于此。"},{t="狩猎归来",b="你回来后，Lumina向你道谢，并说Banon终于可以安息了。随后，她将一丝族人的魔力施加在染血的剑刃上，希望风能引领它前行。"}},faq={{q="是谁让我去猎杀老火眼？",a="露米娜·风歌让你用月银之刃猎杀老火眼。",al={"谁派我来","露米娜的任务","风之歌唱者"}},{q="我在哪里能找到老火眼？",a="当地人说，老火眼在露米娜以南的一大片区域出没，通常在通往吉尔尼斯的大门附近。",al={"火眼的位置","老火眼在哪里","吉尔尼斯大门"}},{q="我该用什么对付老火眼？",a="露米娜让你用月银之刃了结老火眼。",al={"对付火眼的剑","月银武器","用什么武器"}},{q="露米娜为什么要杀死老火眼？",a="露米娜说，老火眼死后，塑风者会感激你。",al={"为何杀死火眼","为何猎杀他","火眼的缘由"}},{q="巴农是谁？",a="露米娜说，老火眼被杀后，巴农就能安息了。",al={"巴农是谁","巴农安息","谁是巴农"}},{q="露米娜对剑做了什么？",a="露米娜将一丝族人的魔力施加在染血的月银之刃上。",al={"剑的魔力","露米娜为剑附魔","风之魔法"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="一名兽人指引你前往洛格玛，这座哨站坐落在战火纷飞的河林。去向Krom'rosh报到，他的经验帮助哨站一次次抵御了袭击。",h="一名兽人指引你前往洛格玛，这座哨站坐落在战火纷飞的河林。去向Krom'rosh报到，他的经验帮助哨站一次次抵御了袭击。",kw={"袭击","东海岸","krom'rosh","哨站","河林","洛格玛","斯通纳德"},sec={{t="屹立不倒的哨站",b="河林位于斯通纳德东北方，沿东海岸延伸。许多人都曾试图夺取这片土地，成功者却寥寥无几。洛格玛是一座屡遭袭击却存留下来的小哨站。你奉命前往那里向Krom'rosh报到。这位老盟友的作战经验帮助哨站一次次抵御袭击。"}},faq={{q="洛格玛在哪里？",a="洛格玛位于河林，在斯通纳德东北方，沿东海岸而建。",al={"洛格玛位置","洛格玛在哪里","洛格玛哨站"}},{q="我该向谁报到？",a="你要前往洛格玛哨站向Krom'rosh报到。",al={"向谁报到","krom'rosh是谁","krom'rosh"}},{q="洛格玛是什么地方？",a="洛格玛是河林中的一座小哨站，曾抵御过无数次袭击。",al={"洛格玛是什么","河林哨站","小哨站"}},{q="Krom'rosh为何在洛格玛？",a="Krom'rosh与敌人作战的经验帮助哨站坚持了下来。",al={"krom'rosh为何在那里","krom'rosh的职责","谁管理洛格玛"}},{q="河林是怎样的一片土地？",a="河林位于斯通纳德东北方，沿东海岸而伸展，是一片饱经战火的土地。",al={"河林","河林是什么样的地方","饱经战火的土地"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="一位旅人请你寻找他的兄弟 Tan'jani。消息称他在洛克莫丹以南，最新的线索指向河林的洛格玛。",h="一位旅人请你寻找他的兄弟 Tan'jani。消息称他在洛克莫丹以南，最新的线索指向河林的洛格玛。",kw={"血迹斑斑的信","洛克莫丹","失踪的兄弟","河林","洛格玛","tan jani","tan'jani"},sec={{t="失踪的兄弟",b="一位旅人的兄弟 Tan'jani 外出寻找某样未知的东西。一条消息称他在洛克莫丹以南的某处。一封血迹斑斑的信提到了更南边的河林和洛格玛，旅人请你去那里寻找他。"}},faq={{q="Tan'jani 是谁？",a="Tan'jani 是请你寻找他的那位旅人的兄弟。",al={"tan'jani","tan jani","失踪的兄弟"}},{q="最后一次提到 Tan'jani 是在哪里？",a="一封血迹斑斑的信提到了河林和洛格玛，那里比洛克莫丹更靠南。",al={"tan'jani 在哪里","tan'jani 的位置","洛格玛"}},{q="Tan'jani 在寻找什么？",a="Tan'jani 总是在寻找某样东西，但他的兄弟不知道那是什么。",al={"他在寻找什么","tan'jani 在寻找什么","他为什么离开"}},{q="消息里说了什么？",a="一位旅人说，他曾在洛克莫丹以南的某处遇见 Tan'jani。一封血迹斑斑的信提到了河林和洛格玛，但信上大部分内容都无法辨认。",al={"tan'jani 的消息","血迹斑斑的信","信后来怎么样了"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
P.entries["quest:95144"] = {n="Overseas Delivery",s="Fizzgrimble请你将一个密封箱运过海，交给河林的Friz Frazzlespark。箱中物品在抵达爆破引线港前必须保密。",h="Fizzgrimble请你将一个密封箱运过海，交给河林的Friz Frazzlespark。箱中物品在抵达爆破引线港前必须保密。",kw={"fizzgrimble","friz frazzlespark","神秘箱子","海外送货","爆破引线港","河林","热砂港"},sec={{t="谨慎渡海",b="Fizzgrimble让你向东前往热砂港，那里通常有船可以载你渡海。这个箱子要送给河林爆破引线港的Friz Frazzlespark。途中要轻拿轻放；Fizzgrimble警告你不要打开或摇晃它。"}},faq={{q="包裹是给谁的？",a="Friz Frazzlespark正在河林的爆破引线港等着收箱子。",al={"谁会收到箱子","friz frazzlespark的包裹"}},{q="我该把箱子送到哪里？",a="把箱子送到河林爆破引线港，交给Friz Frazzlespark。",al={"箱子送达地点","爆破引线港在哪里"}},{q="我在哪里能搭船渡海？",a="Fizzgrimble建议你向东前往热砂港，那里通常有船可以安全渡海。",al={"如何渡海","热砂港的船"}},{q="途中我该怎么处理箱子？",a="保持箱子封好，避免倾斜、摇晃或突然移动。",al={"如何搬运箱子","我能打开包裹吗"}},{q="箱子里装着什么？",a="Friz Frazzlespark请你转过身去，好让他们查看里面的东西，并保留这份惊喜。",al={"箱中物品","惊喜是什么"}}},fp="17,178,18.262.0,23.81.0,30.67.0,40.101.0,43.85.0,25.98.0"}
P.entries["quest:95156"] = {n="Stuff 'Em and Stick 'Em",s="Ember需要从Wheeler的农场取些干草，修补磨损的训练假人。新兵需要完好的目标进行战斗训练。",h="Ember需要从Wheeler的农场取些干草，修补磨损的训练假人。新兵需要完好的目标进行战斗训练。",kw={"ember","农场","干草","新兵","stuff 'em and stick 'em","训练假人","训练场","wheeler"},sec={{t="磨损的目标",b="在训练场，Ember需要干草来修补新兵使用的训练假人。假人磨损严重，可能会让新兵无法为战斗做好准备。要塞外有一座农场，属于Wheeler，他或许有多余的干草。Ember愿意为他能提供的物资付报酬。"},{t="崭新的目标",b="Ember希望干草一到，就立刻修好几个训练目标。新兵的训练离不开能经受住操练的假人。"}},faq={{q="Ember为什么需要干草？",a="Ember需要干草来修补训练场上磨损的训练假人。",al={"ember要的干草","为什么要干草","训练假人用的干草"}},{q="Wheeler是谁？",a="Wheeler是在要塞外经营小农场的人，Ember希望他能匀出些干草。",al={"wheeler的农场","谁有干草","农场的人"}},{q="为什么要修补训练假人？",a="训练假人已经磨损，Ember担心不修补的话，新兵可能无法为战斗做好准备。",al={"磨损的假人","损坏的训练目标","为什么要修训练目标"}},{q="Wheeler会得到干草的报酬吗？",a="Ember说，如果Wheeler能匀出物资，就会得到报酬。",al={"wheeler会得到报酬吗","干草的报酬","草捆的报酬"}},{q="Ember会用干草做什么？",a="Ember打算马上用干草修补几个训练目标。",al={"干草有什么用","修理训练目标","干草的用途"}}},fp="23,134,12.279.0,13.157.1,24.72.0,15.102.0,35.106.0,33.64.0,32.73.0"}
P.entries["quest:95161"] = {n="Remember That I Love You",s="\"Remember That I Love You\"是一项联盟任务，起始于暴风城孤儿院，指引旅行者前往阴森的暮色森林。探险者需要递送一封凄惨的“染血的信”，并追踪一位新近被领养的孤儿Jeremy Heartweaver以及他的养母艾瓦特·菲尔伍德。",h="\"Remember That I Love You\"是一项联盟任务，起始于暴风城孤儿院，指引旅行者前往阴森的暮色森林。探险者需要递送一封凄惨的“染血的信”，并追踪一位新近被领养的孤儿Jeremy...",kw={"艾瓦特·菲尔伍德","染血的信","暮色森林","杰里米·织心","记住我爱你","暴风城","暴风城孤儿院"},ang={["faction:Alliance"]="将逝去或失踪亲人的信物带给被领养的孤儿，凸显了在这个王国动荡局势下，人们所承受的持久的个人代价。",["race:Human"]="对于暴风城的人类来说，这一差事连接起了相对安全的王国中心地带与暮色森林中那些闹鬼且被遗忘的定居点。"},sec={{t="给孤儿的信",b="暴风城孤儿院的孩子们肩负着沉重的负担，战争、苦难和笼罩王国的混乱让他们失去了家人。Jeremy Heartweaver曾是其中一员，直到最近他被一位名叫艾瓦特·菲尔伍德的妇女领养。尽管暮色森林阴森的林地里充满了危险和繁重的劳动，但孤儿院的看护人认为，与其让他被关在城里，不如给他一个拥有家庭的机会。"},{t="凄惨的信物",b="该任务围绕着递送一封寄给Jeremy的“染血的信”展开，信件需交由艾瓦特·菲尔伍德代收。打探消息会指引旅行者向南穿过安全的艾尔文森林，进入暮色森林的阴影中。包裹所透露出的惨状暗示着一段过去的悲剧，这段悲剧一直跟随着年幼的Jeremy，直到暴风城的大门之外。"}},faq={{q="谁是杰里米·织心者？",a="杰里米·织心者曾是在暴风城孤儿院抚养长大的一名小男孩。他最近被艾瓦特·菲尔伍德领养，离开了城市，去往暮色森林的阴影之地生活和工作。",al={"杰里米","杰里米是谁","孤儿杰里米"}},{q="谁是艾瓦特·菲尔伍德？",a="艾瓦特·菲尔伍德是杰里米刚认的养母，居住在暮色森林。暴风城的修女们认为她是个和善的女人，领养杰里米很可能是为了找个帮手来处理日常劳作。",al={"艾瓦特","艾瓦特是谁","养母"}},{q="什么是“染血的信”？",a="“染血的信”是一件寄给杰里米·织心者的阴郁的递送物品，需直接交到他的养育者艾瓦特·菲尔伍德手中，信中承载着暴力或悲剧的余波。",al={"染血的信","这封信","什么是这封信"}},{q="我在哪里可以找到艾瓦特·菲尔伍德？",a="艾瓦特·菲尔伍德居住在暮色森林，这片黑暗的森林领地位于艾尔文森林河对岸的正南方。",al={"艾瓦特·菲尔伍德的位置","艾瓦特在哪里","寻找艾瓦特"}},{q="为什么杰里米被送往暮色森林？",a="杰里米是从暴风城孤儿院被领养走的。虽然暮色森林是一片危险且令人望而却步的土地，但他的看护人认为，与家人一起生活并从事诚实的劳动，比继续留在孤儿院里要好得多。",al={"为什么是暮色森林","杰里米为什么离开暴风城","孤儿院暮色森林"}},{q="哪个阵营可以接取此任务？",a="该任务仅限联盟接取，起始于人类主城暴风城，并深入到联盟控制的领地暮色森林。",al={"这是联盟任务吗","仅限联盟","部落任务"}}},fp="24,136,23.349.0,12.253.1,26.146.0,23.196.0,33.150.0,32.101.0,32.173.0,34.125.0"}
P.entries["quest:95162"] = {n="Paletusk Harvesting",s="Na'zok让你在Bolder'ok附近收集paletusk肉。战事推进，牧场为附近的食人魔提供食物，也为洛格玛供给肉食。",h="Na'zok让你在Bolder'ok附近收集paletusk肉。战事推进，牧场为附近的食人魔提供食物，也为洛格玛供给肉食。",kw={"野猪肉","bolder'ok","na'zok","食人魔","paletusk","paletusk狩猎","牧场","洛格玛"},sec={{t="牧场所需的肉",b="Na'zok在Bolder'ok附近的牧场需要更多肉食。食人魔让Na'zok留在牧场，条件是肉食不断供应。战事推进，食物需求日益增加，食人魔也开始把Na'zok当作下一顿饭。你需要为饥饿的食人魔和洛格玛收集大块野猪肉。"}},faq={{q="谁在索要肉食？",a="Na'zok让你在Bolder'ok附近收集野猪肉，供给食人魔和洛格玛。",al={"谁需要肉食","na'zok的请求","na'zok是谁"}},{q="Na'zok为何需要肉食？",a="牧场是Na'zok少数几个食物来源之一，只要肉食不断供应，食人魔就会让Na'zok留下。",al={"为何需要肉食","为何收集野猪肉","饥饿的食人魔"}},{q="洛格玛是谁？",a="洛格玛是一处定居点，并非某个人。Na'zok希望能留够肉，供给那里。",al={"给洛格玛的肉","洛格玛的肉食"}},{q="Na'zok在哪里？",a="Na'zok在Bolder'ok附近。",al={"na'zok的位置","牧场在哪里"}},{q="需要什么肉？",a="Na'zok要的是paletusk身上的大块野猪肉。",al={"野猪肉","paletusk肉","肉块"}}},fp="19,126,18.294.0,23.77.0,30.106.0,15.87.0,16.25.0,20.50.0"}
P.entries["quest:95163"] = {n="Drive Them Back",s="Na'zok让你把逃跑的幼年 Paletusks 带回他位于 Bolder'ok 附近的农场。小猪崽已经过了河，它们得回到猪圈里。",h="Na'zok让你把逃跑的幼年 Paletusks 带回他位于 Bolder'ok 附近的农场。小猪崽已经过了河，它们得回到猪圈里。",kw={"bolder'ok","逃跑的小猪崽","农场","gorgegut","na'zok","paletusk","猪","幼年 paletusks"},sec={{t="逃跑的小猪崽",b="Na'zok位于 Bolder'ok 附近的农场里，山谷中散养的猪比猪圈里的还多。Gorgegut算不上称职的农场帮手，不过他能挡住人类。几只幼年 Paletusks 已经过了河，它们还太小，不能在野外收割。Na'zok给你一根棍子，让你把它们赶回猪圈。"}},faq={{q="小猪崽为什么跑出了猪圈？",a="几只幼年 Paletusks 从 Na'zok的农场逃到了河对岸。",al={"逃跑的小猪崽","散养的猪","猪为什么在外面"}},{q="Gorgegut是谁？",a="Gorgegut是Na'zok的农场帮手，不过Na'zok说他不太称职。",al={"gorgegut农场帮手","gorgegut是谁","养猪场的人"}},{q="为什么要把幼年 Paletusks 带回去？",a="幼年 Paletusks 还太小，不能在野外收割，所以Na'zok想把它们带回农场。",al={"带回小猪崽","为什么要把猪带回去","幼年 paletusk"}},{q="Na'zok的农场在哪里？",a="Na'zok的农场在 Bolder'ok 附近。",al={"na'zok农场位置","bolder'ok附近的农场","养猪场在哪里"}}},fp="15,148,19.313.0,38.70.0,16.78.0,35.106.0,23.32.0"}
P.entries["quest:95165"] = {n="See Ya, Scallywags!",s="码头主管有个计划，要对 Eastsea 的三艘船动手脚。你要在船体内安放定时炸药，然后离开，让他引爆。",h="码头主管有个计划，要对 Eastsea 的三艘船动手脚。你要在船体内安放定时炸药，然后离开，让他引爆。",kw={"船只","火炮","eastsea","火药","远程引爆炸药","再见了，无赖们","定时炸药","码头主管"},sec={{t="船上安放炸药",b="码头主管要用你偷来的火药，为 Eastsea 的船制作定时炸药。你要在每艘船的船体内、靠近火炮的地方安放一枚。安放完毕后，赶紧离开，让他引爆炸药。"}},faq={{q="码头主管要我做什么？",a="在 Eastsea 的三艘船各自的船体内、靠近火炮的地方安放一枚远程引爆炸药。",al={"我该做什么","eastsea船只任务"}},{q="为什么要用我偷来的火药？",a="码头主管用这些火药为船制作定时炸药。",al={"偷来的火药","火药的用途"}},{q="为什么要把炸药安放在火炮附近？",a="码头主管说，火药会让火炮附近的爆炸威力更大。",al={"火炮附近的炸药","炸药安放位置"}},{q="涉及多少艘船？",a="你要在 Eastsea 的三艘船上各安放一枚炸药。",al={"多少艘船","三艘船"}},{q="码头主管懂得什么爆炸物知识？",a="他说自己以前靠不太正当的手段谋生。",al={"码头主管爆炸物","他为什么会制作炸弹"}}},fp="19,136,14.230.0,40.101.0,30.71.0,39.91.0,28.64.0,48.45.0"}
P.entries["quest:95183"] = {n="Step One: Rock",s="Bolder'ok的Hamur想要附近河里的好石头。把石头带给他，他就能为小小的生物打造一件小小的武器。",h="Bolder'ok的Hamur想要附近河里的好石头。把石头带给他，他就能为小小的生物打造一件小小的武器。",kw={"bolder'ok","好石头","hamur","食人魔武器","河流","小小的武器"},sec={{t="Hamur的请求",b="Bolder'ok的Hamur说，你太矮小， wield不了像样的食人魔武器。要是你给他带来好石头，他就愿意为你打造一件小小的武器。他想要Bolder'ok外河里的石头，只有最好的石头才行。"}},faq={{q="Hamur是谁",a="Hamur在Bolder'ok。只要你带来好石头，他就愿意为你打造一件小小的武器。",al={"hamur是谁","谁想要石头"}},{q="我在哪里能找到石头",a="Hamur想要Bolder'ok外河里的好石头。",al={"石头位置","石头在哪里"}},{q="Hamur为什么想要石头",a="Hamur说，他会用好石头为小小的生物打造一件小小的武器。",al={"为什么要石头","石头用途"}},{q="Hamur想要什么样的石头",a="Hamur想要Bolder'ok外河里的好石头；他说，并非每块石头都合适。",al={"好石头","哪种石头"}}},fp="14,119,15.217.0,13.87.0,26.59.0,26.80.0,35.92.0"}
P.entries["quest:95184"] = {n="The Sharpest of Blades",s="Ember Bladewhisper想为Farholde的新兵准备磨刀石。经验丰富的利刃往往决定着胜利与死亡。",h="Ember Bladewhisper想为Farholde的新兵准备磨刀石。经验丰富的利刃往往决定着胜利与死亡。",kw={"ember bladewhisper","farholde","新兵","磨刀石","solid sharpening stones","训练场"},sec={{t="新兵的刀刃",b="在Farholde训练场，Ember Bladewhisper发现新兵们几乎分不清练习剑和老兵精心保养的利刃。你受托为她带来磨刀石，让新兵们明白锋刃的意义。"}},faq={{q="谁需要磨刀石？",a="Farholde训练场的Ember Bladewhisper需要磨刀石。",al={"谁要磨刀石","ember bladewhisper磨刀石"}},{q="Ember为什么要磨刀石？",a="她想让新兵们明白，磨过的刀刃与训练用剑有何不同。",al={"为什么要磨刀石","磨刀石的用途"}},{q="我该把磨刀石带到哪里？",a="把磨刀石交给Farholde训练场的Ember Bladewhisper。",al={"磨刀石交到哪里","farholde磨刀石"}},{q="Ember需要哪种磨刀石？",a="Ember需要Solid Sharpening Stones。",al={"需要哪种磨刀石","磨刀石类型"}}},fp="22,137,19.258.0,28.79.0,31.89.0,32.83.0,36.39.0"}
P.entries["quest:95189"] = {n="Crest of Lordaeron",s="Crest of Lordaeron是一件饱经风霜的遗物，上面刻有这个陨落的北方王国的皇室印记。在首都废墟中可以找到这样的遗物，自从王国覆灭以来，这些遗物变得十分稀有，而暴风城里的某个人对此非常感兴趣，希望能得到它。",h="Crest of Lordaeron是一件饱经风霜的遗物，上面刻有这个陨落的北方王国的皇室印记。在首都废墟中可以找到这样的遗物，自从王国覆灭以来，这些遗物变得十分稀有，而暴风城里的某个人对此非常感兴趣，希望能得到它。",kw={"洛丹伦徽记","纹章","丹娜·肯尼迪女勋爵","洛丹伦","遗物","洛丹伦废墟","暴风城","提瑞斯法林地"},ang={["faction:Alliance"]="洛丹伦的徽章代表了最初联盟的基石，因此找回它不仅是象征性的胜利，也对抗了天灾军团和被遗忘者对其历史的彻底抹除。",["race:Human"]="对于人类，尤其是那些曾经把北方当作家园的家庭来说，这枚徽章是提醒人们曾经有一个伟大的王国引领过联盟的辛酸记忆。"},sec={{t="破碎的遗产",b="当亡灵天灾席卷洛丹伦王国时，它的宫殿、档案馆和引以为傲的徽章大多被摧毁，或是在幽暗城的阴影下腐朽殆尽。幸存下来的、带有皇室徽记的实物极为罕见。从北方废墟中找回一件完整或风化的徽章，代表着从遗忘中拯救出了一段真实的人类历史。"},{t="南方的避难所",b="第三次战争后，成千上万的北方难民逃往南方的暴风城王国，只带着对家园的记忆。在暴风城，丹娜·肯尼迪女勋爵渴望获得这些洛丹伦的遗存，这使得像这枚徽章这样的遗物在南方首都很受珍视。"}},faq={{q="什么是洛丹伦纹章？",a="这是一枚风化的纹章，展示了洛丹伦的官方标志。在王国沦陷于亡灵天灾后被遗弃，对于人类幸存者来说，这是一件珍贵的历史遗物。",al={"洛丹伦纹章","什么是洛丹伦纹章","洛丹伦徽章物品"}},{q="谁想要洛丹伦纹章？",a="这枚徽章被送交给了暴风城的贵族赞助人丹娜·肯尼迪女勋爵，她致力于收集和保护来自陨落北方王国的稀有文物。",al={"谁需要徽章","我应该把洛丹伦纹章交给谁","徽章上交"}},{q="这枚徽章是在哪里发现的？",a="它是在提瑞斯法林地的洛丹伦废墟中发现的，那座被毁的首都城市如今就坐落在被遗忘者要塞幽暗城的正上方。",al={"徽章位置","废墟徽章","哪里可以获得徽章"}},{q="为什么洛丹伦的文物如此稀有？",a="王国在第三次战争中迅速而灾难性的覆灭，导致了其人民的系统性屠杀和地产的毁灭。很少有个人传家宝能在天灾军团以及随后崛起的被遗忘者手中幸存下来。",al={"为什么洛丹伦遗物稀有","洛丹伦文物稀有度"}},{q="为什么暴风城关心洛丹伦的遗物？",a="暴风城接纳了大量逃离北方浩劫的难民、骑士和贵族。保护这些遗物不仅是对联盟陨落的姐妹王国的缅怀，也是为了延续北方人类的文化遗产。",al={"为什么暴风城关心","暴风城洛丹伦遗物"}},{q="丹娜·肯尼迪女勋爵是谁？",a="丹娜·肯尼迪女勋爵是一位居住在暴风城的贵族女性，她热衷于搜救来自洛丹伦的历史残存和传家宝。",al={"丹娜·肯尼迪女勋爵","丹娜·肯尼迪是谁"}}},fp="18,193,20.268.0,19.292.0,31.177.0,33.110.0,26.141.0,41.176.0,50.174.0,25.126.0"}
P.entries["quest:95194"] = {n="Our Man in Theramore",s="SI:7在一名自称瓦里安·乌瑞恩的男子被冲上塞拉摩岛岸边后，前来寻求你的帮助。去旅店见他们的特工苏利，了解接下来会发生什么。",h="SI:7在一名自称瓦里安·乌瑞恩的男子被冲上塞拉摩岛岸边后，前来寻求你的帮助。去旅店见他们的特工苏利，了解接下来会发生什么。",kw={"jaina proudmoore","塞拉摩的我方人员","si:7","暴风城国王","苏利","塞拉摩岛","瓦里安·乌瑞恩","被冲上岸"},sec={{t="塞拉摩的宣称",b="SI:7听说Jaina Proudmoore的海军陆战队员把一名男子带到了塞拉摩岛。他自称是失踪的暴风城国王瓦里安·乌瑞恩。他们的特工苏利正在旅店等你，SI:7希望你查明发生了什么。"}},faq={{q="SI:7为什么要我去塞拉摩？",a="一名被冲上塞拉摩岛岸边的男子自称是瓦里安·乌瑞恩。SI:7要你去见他们的特工苏利，查明发生了什么。",al={"为何前往塞拉摩","塞拉摩的si:7","si:7需要什么"}},{q="苏利是谁？",a="苏利是一名矮人，也是驻扎在塞拉摩岛的SI:7特工。他正在旅店等你。",al={"谁是苏利","塞拉摩的苏利","矮人特工"}},{q="是谁把那名男子带上岸的？",a="Jaina Proudmoore的海军陆战队员发现那名男子被冲上岸后，把他带到了塞拉摩。",al={"被冲上岸的男子","谁发现了瓦里安","塞拉摩海军陆战队员"}},{q="被冲上岸的男子自称是什么人？",a="他自称是暴风城国王瓦里安·乌瑞恩。",al={"岸边的男子","瓦里安的自称","那是瓦里安吗"}},{q="我在哪里能找到苏利？",a="苏利正在塞拉摩岛的旅店等你。",al={"苏利的位置","特工在哪里","塞拉摩旅店"}}},fp="20,151,20.235.0,35.141.0,13.97.0,27.99.0,34.52.0,23.46.0"}
P.entries["quest:95195"] = {n="Bloodied Insignia",s="Bloodied Insignia是洛丹伦已故守军的悲剧遗物，散落在王国那被摧毁的废墟之中。这些饱经风霜的徽记上印着旧联盟的纹章，代表着那些在第三次战争期间举家南逃至暴风城的士兵。",h="Bloodied Insignia是洛丹伦已故守军的悲剧遗物，散落在王国那被摧毁的废墟之中。这些饱经风霜的徽记上印着旧联盟的纹章，代表着那些在第三次战争期间举家南逃至暴风城的士兵。",kw={"联盟","染血的徽章","洛丹伦","马库斯·乔纳森","难民","洛丹伦废墟","暴风城","第三次战争"},ang={["class:Paladin"]="许多在首都战死的士兵曾与白银之手骑士团并肩作战；找回他们的勋章是对这一神圣骑士团那些失散兄弟姐妹的致敬。",["faction:Alliance"]="将这些徽记交还给马库斯·乔纳森将军，不仅是一种职责，也是对那些为了保卫最初的联盟而献出生命的士兵的缅怀。",["race:Human"]="对于联盟的人类来说，这些徽记是人类最伟大王国陨落的庄严提醒，它将居住在暴风城的难民与他们在北方的阵亡亲人联系在了一起。"},sec={{t="阵亡者的信物",b="当阿尔萨斯王子带着天灾军团回到洛丹伦进行大清洗时，其庞大的军队遭到了压制与屠戮。无数士兵在保卫首都及其周边土地时战死，除却锈迹斑斑的铠甲和沾满血迹的黄铜，几乎没有留下什么实体痕迹。这些旧联盟的徽记属于那些在亡灵大军面前坚守阵地的勇士们。每一枚勋章都被践踏在废墟的泥土与瓦砾之中，它们是王国最后一搏的绝望见证。"},{t="流亡者的信使",b="许多洛丹伦的幸存者渡海向南逃亡，作为难民定居在暴风城。几十年的联盟与血缘关系将这两个人类王国紧密相连，这也让许多南方人渴望得知他们失踪亲人的下落。暴风城卫队指挥官马库斯·乔纳森将军负责保管这些Bloodied Insignia，以便让北方守军的记忆得以留存，并让他们的幸存家人最终能知晓他们的命运。"}},faq={{q="什么是染血的徽记？",a="它们是洛丹伦王国士兵的军用勋章，这些士兵曾在第三次战争期间为了联盟的旗帜而战并牺牲。",al={"染血的徽记物品","这个徽记是什么","徽记背景故事"}},{q="这些徽记在哪里可以找到？",a="它们在提瑞斯法林地的洛丹伦废墟各处被寻获，那是王国守军对阵天灾军团的最后战场。",al={"徽记在哪里掉落","徽记位置","洛丹伦废墟徽章"}},{q="为什么马库斯·乔纳森将军想要这些东西？",a="马库斯·乔纳森将军负责管理暴风城的防御，如今那里居住着无数的北方难民。他收集这些遗物是为了纪念洛丹伦战士们的牺牲，并让在南方的幸存亲属们获得解脱。",al={"马库斯·乔纳森是谁","为什么交给暴风城","马库斯·乔纳森徽记"}},{q="为什么洛丹伦士兵佩戴着联盟的徽记？",a="最初的联盟是在泰瑞纳斯·米奈希尔二世国王的领导下，在洛丹伦为了击败旧部落而组建的。在第二次和第三次战争期间，洛丹伦一直是洛丹伦联盟的核心与领导者。",al={"洛丹伦联盟纹章","洛丹伦联盟徽章"}},{q="那些佩戴勋章的士兵遭遇了什么？",a="当阿尔萨斯·米奈希尔王子背叛王国、刺杀其父并将亡灵天灾军团释放到首都时，他们在第三次战争中牺牲了。",al={"是什么杀死了士兵","洛丹伦士兵的命运"}},{q="这些士兵还有健在的亲人吗？",a="是的。在瘟疫和天灾入侵期间，成千上万的平民和士兵撤离了洛丹伦，最终在暴风城王国找到了避难所。",al={"洛丹伦难民暴风城","谁在怀念这些士兵"}}},fp="17,169,20.402.0,26.384.0,32.119.0,32.141.0,43.191.0,55.176.0,52.147.0,51.144.0"}
P.entries["quest:95196"] = {n="Watch Yer Back",s="苏利 McCleary让你到镇外的墓地旁与他碰面。他想在避开尾随者的同时，告诉你更多有关任务的事。",h="苏利 McCleary让你到镇外的墓地旁与他碰面。他想在避开尾随者的同时，告诉你更多有关任务的事。",kw={"尘泥沼泽","墓地","任务","苏利 mccleary","塔","当心背后"},sec={{t="一次静谧的会面",b="苏利 McCleary打算从你身后的门离开。他走后，你要到镇外的墓地后面与他碰面，并确保没人跟踪。"},{t="接下来的消息",b="在尘泥沼泽，苏利 McCleary让你调查一座塔，尽可能打探消息。接下来的行动取决于你在那里发现什么。"}},faq={{q="是谁让我去和他碰面？",a="苏利 McCleary让你到镇外的墓地后面与他碰面。",al={"苏利是谁","苏利 mccleary","与苏利碰面"}},{q="我在哪里和苏利碰面？",a="等苏利从你身后的门离开后，到镇外的墓地后面与他碰面。",al={"苏利的位置","在哪里见他","墓地会面"}},{q="为什么要确保没人跟踪？",a="苏利让你在与他碰面前，确保没有人跟踪你。",al={"避开尾随者","为何不能被跟踪","当心背后"}},{q="苏利要我接下来做什么？",a="苏利让你潜入一座塔，尽可能打探消息。",al={"塔里的任务","什么任务","苏利要什么"}}},fp="14,132,15.159.0,13.135.1,29.70.0,22.91.0,38.66.0,35.63.0"}
P.entries["quest:95198"] = {n="The Return of the King?",s="一名联络人派你乔装前往塞拉摩法师塔，打探海滩上发现的那名男子的消息。你得知的情况让国王获救一事变得扑朔迷离。",h="一名联络人派你乔装前往塞拉摩法师塔，打探海滩上发现的那名男子的消息。你得知的情况让国王获救一事变得扑朔迷离。",kw={"alcaz","迪菲亚","伪装","幻化伪装","吉安娜","国王","库尔提拉斯水兵","法师塔","塞拉摩"},sec={{t="法师塔",b="一名联络人给你一件由故乡法师制作的幻化伪装，让你扮成库尔提拉斯水兵。你前往塞拉摩法师塔，留意吉安娜和她的核心圈子是否提到海滩上发现的那名男子。吉安娜能看穿伪装，所以要和她保持距离。"},{t="Alcaz上的监狱",b="海滩上发现的那名人类并非他们要找的人。不过，关于Alcaz监狱和迪菲亚参与其中的消息，让联络人怀疑国王可能曾被囚禁在那里。联络人打算采取行动，将国王带回暴风城。"}},faq={{q="谁给我伪装？",a="一名联络人给你一件由故乡法师准备的幻化伪装，让你看起来像库尔提拉斯水兵。",al={"谁给伪装","伪装提供者"}},{q="我该去哪里打探消息？",a="你受命前往塞拉摩法师塔，留意吉安娜和她的核心圈子。",al={"打探地点","法师塔"}},{q="我该避免接近谁？",a="和吉安娜保持距离，她能看穿伪装。",al={"避开吉安娜","吉安娜伪装"}},{q="伪装要让我看起来像什么？",a="这件幻化伪装会让你看起来像库尔提拉斯水兵。",al={"水兵伪装","库尔提拉斯伪装"}}},fp="23,172,17.269.0,17.241.1,26.97.0,30.81.0,36.64.0,40.62.0"}
P.entries["quest:952"] = {n="古树之林",s="“古树之林”是一个联盟的递送任务，指引冒险者走出达纳苏斯，跨过海洋前往黑海岸。在大德鲁伊范达尔·鹿盔的指派下，信使负责将信件送给奥伯丁南部的安努，一位受人尊敬的知识古树。",h="“古树之林”是一个联盟的递送任务，指引冒险者走出达纳苏斯，跨过海洋前往黑海岸。在大德鲁伊范达尔·鹿盔的指派下，信使负责将信件送给奥伯丁南部的安努，一位受人尊敬的知识古树。",kw={"知识古树","奥伯丁","塞纳里奥议会","黑海岸","达纳苏斯","范达尔·鹿盔","古树之林","安努","神谕林地"},ang={["class:Druid"]="在达纳苏斯的大德鲁伊和安努之间传递信件，让年轻的德鲁伊们接触到了塞纳里奥议会长者们截然不同的性情，对比了鹿盔的干劲与知识古树的宁静耐心。",["faction:Alliance"]="对于在达纳苏斯完成事务的联盟勇士来说，这项递送任务提供了一个早期的激励，去开启角鹰兽航线并探索黑海岸的沿海领土。",["race:NightElf"]="这项任务标志着从泰达希尔的庇护摇篮自然过渡到卡利姆多大陆更广阔的荒野，凸显了范达尔·鹿盔与玛法里奥·怒风教义之间的哲学对比。"},sec={{t="离开枝桠",b="在协助处理了泰达希尔顶部神谕林地的事务后，冒险者发现自己被大德鲁伊范达尔·鹿盔粗鲁地召集去执行进一步的任务。鹿盔从不浪费闲人，他指派信使携带一份紧急公文跨海前往黑海岸的古老森林，并指示他们从城里预订一架角鹰兽航班。"},{t="耐心的对比",b="抵达黑海岸并前往奥伯丁南部的古树之林后，信使将信件交给了安努。这位高耸的知识古树在安静的沉思中接过了信件，微妙地指出了鹿盔那无休止的不耐烦。对于安努和森林的古老守护者来说，万物皆有其时——这是一种珊多玛法里奥·怒风所体现的宁静而持久的智慧，而鹿盔显然缺乏这种品质。"}},faq={{q="谁发布了任务“古树之林”？",a="在你完成关于神谕林地的前序任务后，大德鲁伊范达尔·鹿盔会在达纳苏斯的塞纳里奥区发布该任务。",al={"古树之林任务发布者","谁发布古树之林任务","范达尔·鹿盔任务"}},{q="古树之林位于何处？",a="古树之林位于黑海岸的大陆上，坐落在海滨港口奥伯丁的正南方。",al={"古树之林位置","古树之林在哪里","安努位置"}},{q="安努是谁？",a="安努是一位居住在黑海岸，睿智而受人尊敬的知识古树。作为自然智慧的保护者和记录者，他接收来自达纳苏斯德鲁伊领袖的信件。",al={"安努是谁","安努 黑海岸","知识古树 安努"}},{q="如何从泰达希尔前往黑海岸？",a="旅行者通常会从达纳苏斯前往鲁瑟兰村，然后乘坐角鹰兽飞越水域，抵达黑海岸的港口定居点奥伯丁。",al={"如何前往黑海岸","前往奥伯丁","角鹰兽前往黑海岸"}},{q="为什么安努提到了珊多·怒风？",a="在收到信件后，安努评述了大德鲁伊鹿盔那躁动不安的急躁。他反思道，森林以自己的步调运行，这是一种珊多玛法里奥·怒风所理解并尊重的永恒耐心。",al={"安努评价玛法里奥","珊多·怒风提及","为什么提及珊多"}},{q="在此任务之前有什么任务？",a="该任务是一个简短的三部分序列的最后一步，该序列始于神谕林地，随后是泰达希尔，最后指引你前往黑海岸。",al={"古树之林前置任务","古树之林任务链","安努之前任务"}}},fp="21,226,18.230.0,22.341.0,43.135.0,43.109.0,11.160.0,43.126.0,39.192.0,33.143.0"}
P.entries["quest:95204"] = {n="Crest of Lordaeron",s="洛丹伦徽记是一件饱经风霜的历史文物，上面刻着这个已覆灭王国的纹章。在天灾军团的破坏下，几乎没有多少这样的宝物幸存下来，因此它被送往幽暗城的奥兰·斯内克威瑟手中，以帮助保护被遗忘者的过去遗产。",h="洛丹伦徽记是一件饱经风霜的历史文物，上面刻着这个已覆灭王国的纹章。在天灾军团的破坏下，几乎没有多少这样的宝物幸存下来，因此它被送往幽暗城的奥兰·斯内克威瑟手中，以帮助保护被遗忘者的过去遗产。",kw={"洛丹伦徽记","被遗忘者","洛丹伦","奥兰·斯内克威瑟","遗物","幽暗城"},ang={["faction:Horde"]="协助幽暗城的被遗忘者档案管理员工作，有助于在天灾军团留下的废墟中保护洛丹伦的物质遗产。",["race:Undead"]="作为洛丹伦的曾经的公民，被遗忘者将他们已覆灭王国的幸存遗物视为他们过去生活和遗产的稀有残余。"},sec={{t="已覆灭王国的幸存象征",b="洛丹伦王国在第三次战争期间分崩离析，只留下了灰烬、废墟和天灾军团的荒芜。由于该国的大部分物质文化都被抹除了，像洛丹伦徽记这样幸存下来的徽章和纹章极为罕见。对于居住在首都废墟之下的被遗忘者来说，这些幸存下来的物品是连接他们曾经所属文明的宝贵物质纽带。"},{t="保护被遗忘者遗产",b="当从广阔的世界中寻回这枚风化的徽记后，它会被送交到幽暗城的奥兰·斯内克威瑟处。奥兰会验证其真实性——甚至会通过咬它来测试金属——然后确认它是家园一件正宗且基本完好的传家宝。对于奥兰和被遗忘者档案管理员来说，每一件回收的物品都有助于拼凑出一段天灾军团试图彻底抹去的历史。"}},faq={{q="什么是洛丹伦徽记？",a="洛丹伦徽记是一枚饱经风霜的纹章，上面刻着这个已覆灭人类王国的标志。由于在天灾军团的破坏下，极少有实物遗物留存下来，因此对于那些试图保护洛丹伦遗产的人来说，这是一件无价的历史文物。",al={"什么是洛丹伦徽记","洛丹伦徽记任务","徽记物品"}},{q="谁在幽暗城需要这枚徽记？",a="这枚徽记会被带给住在幽暗城的奥兰·斯内克威瑟。奥兰会仔细检查并妥善保管这些与旧王国有关的回收文物。",al={"谁接收徽记","在哪里上交徽记","在幽暗城上交徽记"}},{q="为什么奥兰·斯内克威瑟要咬这枚徽记？",a="在收到徽记后，奥兰·斯内克威瑟会咬它一下，以验证其真实性和材质成分，然后才宣布它是洛丹伦一件正宗且基本完好的遗物。",al={"为什么要咬徽记","奥兰咬徽记"}},{q="为什么被遗忘者珍视洛丹伦的遗物？",a="被遗忘者是洛丹伦前人口的亡灵残部。尽管他们已死且有了新的效忠对象，但他们被摧毁的家园的遗物代表了与他们历史和身份的切实联系。",al={"为什么被遗忘者关心洛丹伦","被遗忘者遗物"}},{q="徽记上交后会怎样？",a="奥兰·斯内克威瑟会接管这枚徽记以确保其安全，并将其视为一件珍贵的历史宝藏，以此来帮助恢复和铭记他们王国的遗产。",al={"徽记会怎样","徽记保存"}},{q="洛丹伦幸存的遗物有多罕见？",a="第三次战争前的实物徽章和遗物非常稀缺。当阿尔萨斯和天灾军团横扫该国时，洛丹伦的大多数象征物都被砸碎、掠夺或腐蚀了。",al={"徽记稀有吗","还剩多少徽记"}}},fp="18,148,40.264.0,28.278.0,31.183.0,33.113.0,41.137.0,46.153.0,52.134.0,45.150.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Never Saddle on Quality是丹莫罗冻石农场的一项联盟任务。驯兽师需要完好的山豹毛皮来为即将支援奥特兰克远征军的座骑公羊制作保暖鞍座。这项工作确保了坐骑和骑手能够抵御北部山脉刺骨的严寒。",h="Never Saddle on Quality是丹莫罗冻石农场的一项联盟任务。驯兽师需要完好的山豹毛皮来为即将支援奥特兰克远征军的座骑公羊制作保暖鞍座。这项工作确保了坐骑和骑手能够抵御北部山脉刺骨的严寒。",kw={"奥特兰克","奥特兰克远征军","冻石农场","丹莫罗","豹皮","马鞍品质绝不妥协","完好的豹皮","公羊","鞍座"},ang={["class:Hunter"]="这项任务呼吁技术娴熟的追踪者和猎人去寻找丹莫罗最凶猛的山豹，以获取完好的毛皮。",["faction:Alliance"]="冻石农场的公羊繁育工作直接为在奥特兰克寒冷高地作战的联盟部队提供了坐骑支援。",["race:Dwarf"]="丹莫罗耐寒的山羊是标志性的矮人坐骑，冻石农场的饲养员拒绝给它们配备劣质的装备。"},sec={{t="为远征军备鞍",b="在丹莫罗的冻石农场，驯兽师们正在准备一批强壮的山羊，以支援在奥特兰克作战的联盟远征军。然而，由于缺乏制作耐用且防寒的兽鞍所需的合适材料，准备工作陷入了停滞。"},{t="高海拔山口的温暖保障",b="为了抵御奥特兰克山脉严酷的冰冻天气，远征军的坐骑需要厚实、高等级的隔热材料。猎人们被派往东部的悬崖峭壁去追踪丹莫罗体型最大、最凶猛的山豹，并获取它们完好的毛皮，以确保联盟部队得到的装备能够适应高海拔山口的生存需求。"}},faq={{q="质量绝不将就是什么？",a="质量绝不将就是基于丹莫罗冻石农场的一项任务。一位饲养员需要高质量的豹皮来为一批准备支援奥特兰克远征军的公羊制作结实、保暖的鞍座。",al={"这是什么任务","品质绝不妥协任务","什么是品质绝不妥协"}},{q="为什么需要豹皮？",a="这些毛皮用于制作耐用且保暖的远征军坐骑鞍座。丹莫罗的山豹提供了厚实、隔热性能良好的皮毛，适合保护骑手和坐骑免受奥特兰克刺骨山风的侵袭。",al={"为什么需要豹皮","兽皮有什么用","为什么需要完好的毛皮"}},{q="这些公羊将被送往何处？",a="这些坐骑将被送往在奥特兰克远征军中服役的联盟部队。由于高海拔山口气候恶劣且作战持续，装备精良的坐骑公羊是至关重要的支援。",al={"公羊要去哪里","谁接收公羊","奥特兰克援军"}},{q="冻石农场在此任务中扮演什么角色？",a="冻石农场位于卡拉诺斯以东，丹莫罗的雪山之中。它是矮人山羊的主要繁育和训练基地。",al={"冻石农场在哪里","冻石农场位置"}},{q="山豹在哪里出没？",a="凶猛的雪豹在冻石农场以东的丹莫罗雪山脊和悬崖间出没，猎人必须追踪这些体型最大的野兽以获得完好的兽皮。",al={"哪里找山豹","丹莫罗的山豹在哪里"}},{q="为什么防寒保护对远征军如此重要？",a="奥特兰克王国的山峰以严寒和强风而闻名。如果没有厚实、高质量的鞍具材料，坐骑和骑手在山地地形中将面临冻伤和力竭的风险。",al={"奥特兰克冷吗","为什么要保暖鞍座"}}},fp="23,229,23.201.0,26.290.0,32.198.0,29.181.0,30.175.0,37.125.0,27.157.0,63.166.0"}
P.entries["quest:95213"] = {n="Stolen Blasting Powder",s="“被盗的爆破火药”涉及在古博拉采掘场附近的穴居人中发现的一个空的、危险的炸药桶。将这个丢失的容器交给采掘场主管瑟斯滕，会暴露出该采掘场在安保和炸药储备方面存在的危险漏洞。",h="“被盗的爆破火药”涉及在古博拉采掘场附近的穴居人中发现的一个空的、危险的炸药桶。将这个丢失的容器交给采掘场主管瑟斯滕，会暴露出该采掘场在安保和炸药储备方面存在的危险漏洞。",kw={"爆破火药","丹莫罗","空火药桶","古博拉采掘场","火药桶","采掘场主管瑟斯滕","被盗的爆破火药","瑟斯滕","穴居人"},ang={["faction:Alliance"]="确保丹莫罗的补给线和采矿前哨站不受穴居人入侵，对于联盟在卡兹莫丹的行动至关重要。",["profession:Engineering"]="爆破火药是一种危险的易燃材料；工程师比任何人都清楚穴居人使用未经授权的炸药会造成多大的破坏。",["profession:Mining"]="采掘场运作依赖于受控爆破来提取石料，但丢失的火药桶预示着挖掘坑内存在严重危险。",["race:Dwarf"]="古博拉采掘场为铁炉堡提供至关重要的石料和资源，因此其采矿炸药的安全性对任何矮人来说都是紧迫的关切。"},sec={{t="危险的发现",b="一个印有严重危险警告的空桶揭示出，危险的爆破火药已经从古博拉采掘场的授权人员手中流失。这种炸药是严格限制在采掘场主管直接授权下用于受控开采的。在敌对的穴居人中发现这个桶，表明该挖掘点正面临比日常劳动力中断更具破坏性的威胁。"},{t="采掘场主管的警觉",b="将空容器归还给采掘场主管瑟斯滕证实了矮人监督者们最担心的事。瑟斯滕看到这个桶时脸色变得苍白，意识到丢失的爆破火药已经被该地区泛滥的穴居人清空并动用。这一发现使采掘场领导层急于评估这些生物下一步打算炸毁什么。"}},faq={{q="什么是“被盗的爆破火药”？",a="“被盗的爆破火药”是一个任务，在古博拉采掘场附近的穴居人手中发现一个印有危险警告的空爆破火药桶后触发。它向采掘场主管瑟斯滕警示了易燃采矿物资被盗的情况。",al={"什么是被盗的爆破火药","火药桶任务","空火药桶背景"}},{q="谁应该接收这个空的火药桶？",a="空的火药桶必须直接交给在丹莫罗的古博拉采掘场负责运营的采掘场主管瑟斯滕。",al={"把桶带到哪里","谁是瑟斯滕","采掘场主管位置"}},{q="为什么被盗的爆破火药很危险？",a="这个桶上清楚地标有采掘场主管的授权警告，且装有危险的爆破火药。穴居人持有或引爆重型炸药会威胁到整个采掘场的挖掘工作及附近的定居点。",al={"为什么火药危险","携带炸药的穴居人","穴居人为什么有火药"}},{q="什么是古博拉采掘场？",a="古博拉采掘场是一个位于丹莫罗的矮人挖掘点，负责为铁炉堡开采石料和矿物。",al={"古博拉在哪里","采掘场位置","丹莫罗古博拉"}},{q="为什么采掘场主管瑟斯滕脸色苍白？",a="看到空桶时，采掘场主管瑟斯滕脸色明显变苍白，并询问是在哪里找到的，因为他立即意识到这些危险的内容物已经落入了敌对的穴居人手中。",al={"为什么瑟斯滕脸色苍白","瑟斯滕的反应","瑟斯滕说了什么"}},{q="穴居人在古博拉采掘场附近做什么？",a="穴居人已经侵扰了古博拉采掘场的下层区域和外围，干扰了矮人矿工，并从挖掘现场搜刮设备和爆破火药。",al={"穴居人在采掘场吗","丹莫罗穴居人入侵","穴居人为什么偷火药"}}},fp="22,191,21.331.0,24.279.1,31.192.0,40.119.0,44.169.0,25.107.0,40.168.0,44.164.0"}
P.entries["quest:95214"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder是丹莫罗的古博拉采掘场内的一项任务，探险者们必须在此找回遗失的军需品。原始的穴居怪偷走了一批足以夷平一座堡垒侧翼的炸药粉，迫使采掘场主管西斯登在灾难发生前招募谨慎的帮手。",h="Stolen Blasting Powder是丹莫罗的古博拉采掘场内的一项任务，探险者们必须在此找回遗失的军需品。原始的穴居怪偷走了一批足以夷平一座堡垒侧翼的炸药粉，迫使采掘场主管西斯登在灾难发生前招募谨慎的帮手。",kw={"爆破炸药","丹莫罗","炸药","古博拉采掘场","铁炉堡","国王麦格尼","采掘场主管西斯登","西斯登","穴居怪"},ang={["faction:Alliance"]="丹莫罗的补给线和石矿工程对联盟的山脉据点至关重要。维持和平并看管危险军需品能确保附近铁炉堡内王座厅的安全。",["profession:Mining"]="爆破炸药是深层挖掘中清理岩石和开掘矿脉不可或缺的工具，但操作它需要纪律——丢失大量炸药给野蛮的穴居怪是每一位采掘场主管的噩梦。",["race:Dwarf"]="古博拉采掘场为铁炉堡的石艺和挖掘工作提供能源。让地底穴居怪在国王麦格尼的家门口将采矿炸药武器化，这对任何矮人主管来说都是一场丢脸的安全事故。"},sec={{t="遗失的库存",b="在丹莫罗的古博拉采掘场，矮人的作业极其依赖强力爆破装药来破碎岩石并开掘深处的矿脉。然而，由于安保疏忽，潜伏在附近岩架上的原始穴居怪成功偷走了一整批高等级的爆破炸药。采掘场主管西斯登不得不匆忙寻找可靠的人手，以免这群小偷无意中引爆炸药。"},{t="岩架上的火药桶",b="遗失物资的数量极其惊人：西斯登指出，这些炸药桶所蕴含的爆炸威力足以将国王麦格尼·铜须的宏伟王座大厅变成露天庭院。穴居怪将这些危险的战利品运往了东边粗陋的山脚营地。如果放任不管，用不了多久，这些野蛮的生物就会发现火源，或是让石头撞出火花。"},{t="悄然解决",b="一旦从穴居怪手中夺回被盗的装药并安全送回采掘场仓库，西斯登如释重负地松了一口气。这位采掘场主管用一点奖励酬谢了探险者，并谨慎地恳求对方不要向任何人提及这起小事故。"}},faq={{q="谁是采掘场主管西斯登？",a="采掘场主管西斯登负责监管丹莫罗古博拉采掘场的挖掘工作。他负责工地的安全与生产效率，但他现在陷入了尴尬的困境，因为在他看管下，大量工业爆破炸药失踪了。",al={"谁是西斯登","采掘场主管西斯登","谁发布了这个任务"}},{q="在哪里可以找到被盗的爆破炸药？",a="炸药被古博拉采掘场正东面的岩架和洞穴中出没的穴居怪偷走了。探险者被派往那些岩石露头区域，从这些生物手中抢回危险的炸药桶和麻袋，以防灾难发生。",al={"被偷走的爆破粉在哪里","穴居怪位置","炸药位置"}},{q="穴居怪为什么要偷爆破炸药？",a="穴居怪是原始的地底生物，受本能的狡诈和领地侵略性驱使。虽然它们是从采掘场工人那里顺手牵羊偷走了炸药桶，但采掘场主管西斯登担心，即便是笨拙的实验也可能导致它们意外引爆炸药。",al={"为什么穴居怪要偷炸药","穴居怪要炸药做什么"}},{q="被盗的爆破炸药有多危险？",a="据采掘场主管西斯登所述，丢失的炸药桶内装有极其不稳定的爆破炸药，威力足以将国王麦格尼的王座大厅炸成露天庭院。如果这些炸药在封闭的采掘场或洞穴中同时引爆，后果将是毁灭性的。",al={"炸药威力如何","麦格尼王座大厅炸药","炸药危险吗"}},{q="为什么采掘场主管西斯登希望将此事保密？",a="当你归还炸药时，西斯登付给了你报酬，并请求你不要向任何人提及这起小事故。他没有说明原因，但显然，让穴居怪偷走如此大量的炸药是他不愿声张的事情。",al={"为什么要保密","西斯登的秘密","不要提及事故"}},{q="什么是古博拉采掘场？",a="古博拉采掘场是丹莫罗东部著名的矮人挖掘点，负责为王国各地的建筑和工程项目开采石料。其深坑经常需要应对从岩石中钻出的穴居怪等地下害虫。",al={"什么是古博拉","古博拉采掘场","古博拉在哪里"}}},fp="22,183,19.282.0,25.250.0,16.202.1,28.188.0,46.166.0,45.194.0,44.189.0,59.199.0,25.191.0"}
P.entries["quest:95216"] = {n="The New Plague",s="新的瘟疫是由萨多雷·格雷夫在幽暗城的炼金房内开展的一项研究工作。Griffs 正在调查关于地面废墟中出现一种致命节肢动物的报告，这种生物的毒液甚至能腐蚀亡灵的血肉，他试图分析并逆向工程这种生物的致命毒素。",h="新的瘟疫是由萨多雷·格雷夫在幽暗城的炼金房内开展的一项研究工作。Griffs 正在调查关于地面废墟中出现一种致命节肢动物的报告，这种生物的毒液甚至能腐蚀亡灵的血肉，他试图分析并逆向工程这种生物的致命毒素。",kw={"炼金房","毒液","洛丹伦废墟","新的瘟疫","萨多雷·格雷夫","剧毒菌株","幽暗城","枯牙"},ang={["faction:Horde"]="尽管部落将被遗忘者视为东部王国中的战术盟友，但在炼金房中酝酿的邪恶生物实验往往会引起那些更崇尚荣誉的成员的不安。",["race:Undead"]="皇家药剂师协会不懈地追求能够伤害生者与死者的毒素，以确保被遗忘者的霸权并保护他们初生的国家。"},sec={{t="药剂师的雄心",b="在炼金房阴暗潮湿的深处，皇家药剂师协会不断从艾泽拉斯各地收集剧毒制剂。作为该协会的一名专注研究员，萨多雷·格雷夫会追踪奇异的野兽和致命的污染物，以推动被遗忘者炼金术的创新。在听到有毒生物在上方破碎的石块间潜行的传闻后，Griffs 派遣冒险者在机会溜走之前去获取一个可用的样本。"},{t="一种消融血肉的毒素",b="该研究的目标是 Witherfang，这是一种潜伏在洛丹伦废墟地表的有毒节肢动物。它的毒液拥有一种罕见而可怕的特性，不仅能分解活体组织，还能分解死亡并经过防腐处理的血肉。对于一位致力于完善生物战并保卫被遗忘者王国的药剂师来说，揭开这种毒素如何绕过亡灵抗性的秘密，具有极其宝贵的化学研究价值。"},{t="逆向工程体液",b="虽然冒险者在消灭 Witherfang 而不是活捉它时，Griffs 表现出了沮丧，但收集到的毒液样本仍提供了足够的分析材料。通过分解这种生物的体液，这位药剂师打算逆向工程出该毒液的致病机理，确保即使是一只被压碎的节肢动物也能为幽暗城日益增长的化学实力做出贡献。"}},faq={{q="萨多雷·格雷夫是谁？",a="萨多雷·格雷夫是一位在幽暗城的炼金房工作的药剂师研究员。他调查强效毒素和奇异标本，为被遗忘者合成化合物，对任何无法欣赏这种精妙炼金工艺的人表现得漠不关心。",al={"谁发布了 新的瘟疫","萨多雷·格雷夫","萨多雷·格雷夫 是谁"}},{q="枯牙 是什么？",a="枯牙 是一种致命的有毒节肢动物，潜伏在幽暗城上方的洛丹伦废墟中。它会产生一种极具腐蚀性的毒素，甚至能够溶解坚韧的亡灵血肉。",al={"枯牙 是什么","枯牙 在哪里","洛丹伦废墟的节肢动物"}},{q="为什么萨多雷·格雷夫想要 枯牙 的毒液？",a="萨多雷·格雷夫试图研究 枯牙 的毒液，以确定其毒素如何侵蚀亡灵血肉，并希望将该物质逆向工程，开发成被遗忘者炼金武器库中的强效菌株。",al={"萨多雷 想要 枯牙 做什么","为什么收集剧毒菌株"}},{q="为什么萨多雷·格雷夫在你回来时感到生气？",a="萨多雷·格雷夫本希望标本能保持完整或被小心采集，而不是直接被杀死。虽然他对 枯牙 被杀感到恼火，但他还是设法从残骸中回收了足够的残留毒液来研究其特性。",al={"为什么 萨多雷 很生气","我毁掉样本了吗"}},{q="炼金房的目的是什么？",a="炼金房是皇家药剂师协会在洛丹伦之下的研究中心。它被描述为幽暗城最重要的区域，致力于测试剧毒菌株、调制炼金武器以及对奇异生物进行实验。",al={"炼金房 的目的","为什么 炼金房 很重要"}},{q="萨多雷 认为剧毒菌株最好的传播方式是什么？",a="根据萨多雷·格雷夫的说法，剧毒传播最有效且可靠的途径始终是直接注入血液。",al={"毒液是如何传播的","传播方式"}}},fp="14,171,25.338.0,24.301.0,29.280.1,23.260.0,19.139.0,49.156.0,45.172.0,40.236.0,64.109.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="The Quarry's Smith 是一项由弗拉斯·多克纳提供的安排，他是一位驻扎在采掘场营地的工匠。由于预期的补给迟迟未到，这位铁匠不得不求助于过往的旅行者，收集生金属和结实的皮革来进行必要的营地维修。作为交换，多克纳会向有志于金属加工的人传授实用的锻造技巧。",h="The Quarry's Smith...",kw={"锻造","铜锭","丹莫罗","矮人","弗拉斯·多克纳","古博拉采掘场","铁炉堡","采石场的铁匠","坚韧的野猪皮"},ang={["faction:Alliance"]="协助多克纳可以确保这个偏远的矮人采掘场保持运作，从而加强雪山高地当地的基础设施和装备准备状况。",["profession:Blacksmithing"]="弗拉斯·多克纳担任学徒铁匠的实地导师，他将自己来之不易的锻造技巧传授给任何愿意提供保持铁砧炽热所需的生金属和皮革的人。",["profession:Mining"]="在周边矿点工作的矿工会发现他们的熔炼铜锭在当地有直接的消费者，将原材料矿石转化为实用的训练和营地维修。",["race:Dwarf"]="古博拉采掘场代表了铜须氏族在丹莫罗的企业和工业，即使在补给车队延误时，矮人的决心也能让熔炉保持燃烧。"},sec={{t="采掘场的物资短缺",b="在活跃的挖掘现场，生活需要不断的维护，从磨快镐头和更换磨损的支架，到加固营地装备，无所不包。当重要的补给品未能按时送达时，日常工作就会陷入停滞。由于主要贸易路线上的物资供应中断，现场的工匠们被迫随机应变，寻求过往冒险者的帮助以维持营地运作。弗拉斯·多克纳在这些持续的延误中坚持锻造，他依靠那些愿意搜集基础金属和兽皮的人，而不是坐等可能遥遥无期的运输马车。"},{t="学徒的交易",b="传统的矮人锻造公会重视纪律和严密守护的方法，很少将行业秘密传授给随意的流浪者。然而，多克纳在当地的需求与正式的公会礼仪之间取得了平衡。面对修补工具和营地装备所急需的铜和耐用皮革的短缺，他提供了一项务实的交易：将原材料直接送到他的铁砧前，他就会向你传授他个人的锻造技巧。这是一场源于边境需求的互利交易，用宝贵的职业知识换取了即时的生存和维护。"}},faq={{q="弗拉斯·多克纳是谁？",a="弗拉斯·多克纳是一位驻扎在采掘场营地的经验丰富的铁匠，负责维护现场工人的工具、结构配件和设备。当物流延误切断了他的正常补给线时，他亲自出马，招募过往的冒险者来获取他急需的原材料。",al={"弗拉斯·多克纳背景故事","采掘场铁匠是谁","采掘场铁匠"}},{q="为什么采掘场需要铜锭和野猪皮？",a="挖掘和营地维护消耗了大量的坚固材料。铜是一种易于获取、延展性好的金属，适合锻造替换配件、钉子、紧固件，以及为损坏的工具加固箍带。坚韧的野猪皮提供了必要的弹性皮革，用于制作风箱、工具裹布、绑带和防护围裙，以抵御采掘场日常工作中严酷的火花和沉重的研磨。",al={"为什么需要铜锭和野猪皮","采掘场铁匠所需的材料","采掘场维修材料"}},{q="为什么补给品运输会迟到？",a="虽然弗拉斯·多克纳没有详细说明延误的具体原因，但横跨雪峰和山隘的陆路补给路线经常受到严酷暴风雪、四处游荡的野生动物以及敌对的穴居人或强盗伏击的困扰。每当运输马车延误时，偏远的采矿营地和采掘场往往是最先感受到压力的定居点。",al={"补给品运输延迟","补给品出了什么事","为什么补给延迟"}},{q="弗拉斯·多克纳用什么来交换这些材料？",a="弗拉斯·多克纳不仅仅提供金钱，他还承诺将个人的锻造技巧传授给任何为他收集所需补给的人。对于有抱负的工匠来说，直接向驻扎在实地的老练工匠学习，能提供关于金属加工和设备维护的实用见解，而这是正规的城市公会大厅很少向新手传授的。",al={"采掘场铁匠奖励背景","弗拉斯教什么","弗拉斯的锻造技巧"}},{q="这个采掘场位于哪里？",a="弗拉斯·多克纳在丹莫罗的古博拉采掘场工作，这是一个坐落在卡拉诺斯以南雪山脚下的矮人挖掘场。采掘场面临着严酷的冬季天气和具有攻击性的地下穴居人的持续作业压力，它们经常骚扰矿工并扰乱从铁炉堡出发的贸易车队。",al={"这是哪个采掘场","弗拉斯·多克纳在哪里","采掘场铁匠位置"}},{q="弗拉斯·多克纳隶属于铁炉堡吗？",a="是的，弗拉斯·多克纳和采掘场营地在铜须氏族和铁炉堡王国的领地内运作。从丹莫罗的山脉中开采石料和提取矿石对于矮人王国的建筑项目和防御工事至关重要，这使得像多克纳这样的当地铁匠成为铁炉堡工业力量不可或缺的一部分。",al={"弗拉斯·多克纳与铁炉堡","采掘场属于铁炉堡吗","采掘场矮人效忠对象"}}},fp="18,217,23.504.0,23.468.0,20.252.0,52.315.0,32.278.0,59.287.0,29.246.0,42.258.0"}
P.entries["quest:95219"] = {n="From Port to Port",s="港口商人让你把一桶精心包装的货物送到羽月要塞。漫长的旅途需要格外小心。",h="港口商人让你把一桶精心包装的货物送到羽月要塞。漫长的旅途需要格外小心。",kw={"木桶","送货","羽月要塞","菲拉斯","港口到港口","mardrack greenwell","爆破引线港"},sec={{t="远方的顾客",b="一名商人在菲拉斯的羽月要塞有位顾客，你要把一桶爆破引线港送过去。商人说木桶密封严实，但提醒你，有东西可能会引爆它。送往 Mardrack Greenwell 的途中务必小心搬运。"}},faq={{q="我要送什么？",a="你要把一桶爆破引线港送到羽月要塞的 Mardrack Greenwell 手中。",al={"木桶里装着什么","爆破引线港运送","港口木桶"}},{q="我要把木桶送到哪里？",a="这桶货要送往菲拉斯羽月要塞的 Mardrack Greenwell。",al={"送货地点","羽月要塞送货","菲拉斯木桶"}},{q="为什么要小心搬运？",a="商人提醒你，有东西可能会引爆这只密封包装的木桶。",al={"木桶危险吗","为何小心","什么东西可能引爆它"}},{q="是谁包装的木桶？",a="商人的一名手下把木桶密封包装好了。",al={"谁包装了货物","密封包装","商人的手下"}}},fp="17,112,18.250.0,21.91.0,27.78.0,33.71.0,20.49.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Abominable Creatures 是一个任务，由 Captain Truman 布置，他是一名坚守在洛丹伦废墟郊外，绝望地等待着援军的人类忠诚派。Truman 坚信他的指挥官——一位受人尊敬的大元帅——仍在附近的洛丹伦废墟中英勇奋战，因此请求一位有能力的 The Adventurer 去寻找他。这项任务揭示了该王国失踪的守卫者们那悲惨的命运，以及在幸存的忠诚派之间阴燃的痛苦敌意。",h="Abominable Creatures 是一个任务，由 Captain Truman 布置，他是一名坚守在洛丹伦废墟郊外，绝望地等待着援军的人类忠诚派。Truman...",kw={"可憎的生物","杜鲁门 队长","大元帅","男爵的徽记","洛丹伦","洛丹伦废墟","男爵","洛丹伦真正的子民"},ang={["faction:Alliance"]="该任务突显了联盟阵营的残余势力在北洛丹伦的枯萎废墟中试图行动时所面临的危险与孤立困境。它强调了残留的忠诚派分遣队是如何在希望渺茫以及对抗压倒性怪物所带来的心理重负下苦苦挣扎的。",["race:Human"]="人类 The Adventurer 目睹了洛丹伦沦陷领导层那令人心碎的命运，即便是受人尊敬的大元帅也被转化成了恐怖的亡灵怪物。Captain Truman 的痛苦和民族主义狂热反映了人类幸存者为收复祖国而承受的沉重创伤。",["race:Undead"]="对于被遗忘者来说，男爵那怪诞的转化是一个严峻的提醒，它展示了天灾军团如何将洛丹伦最优秀的守卫者残忍地扭曲成可怕的憎恶。Captain Truman 发誓要清除废墟中所有的野兽和亡灵，这反映了活着的忠诚派对幽暗城人民所怀有的持续敌意。"},sec={{t="绝望的守望",b="Captain Truman 坚守在自己的岗位上，焦虑地等待着迟迟未到的援军来支持洛丹伦的防守。他对自己上级——一位被他描述为身材高大、像雕像般英雄的知名大元帅——的武艺充满信心。在接到指挥官冲入战场而自己必须坚守阵地的命令后，Truman 始终恪尽职守。由于对局外人持有深切怀疑，并公开鄙视那些他认为低劣的种族，这位队长拒绝信任当地的非正规军。当一位有能力的旅行者接近时，Truman 抓住了寻求援助的机会，恳求对方冒险进入废墟领地，去查看他主人的安危并评估战斗情况。"},{t="洛丹伦废墟",b="这次搜寻直接将 The Adventurer 指引向危险的洛丹伦废墟，这座在第三次战争中沦陷于天灾军团的破碎首都。尽管 Captain Truman 期望他那光荣的领袖能在死者中凯旋，但在这片枯萎的城市中，现实却要残酷得多。废墟中到处都是恐怖之物、亡灵残余以及在破碎的石制广场上徘徊的憎恶。穿过这些荒废的街道，需要面对那些进入城市的守卫者们所遭遇的残酷真相。旅行者们并没有发现一位完美的骑士在坚守阵线，而是发现指挥官在占据庭院的怪物群中遭遇了悲惨、扭曲的终结。"},{t="恐怖的真相",b="在找到失踪的指挥官（被称为男爵）后，The Adventurer 有了一个恐怖的发现：那位曾经像雕像般英俊的英雄已经被转化成了一个怪诞的亡灵怪物。完成这项严峻的任务需要击杀该生物，并将男爵的徽记带回给 Captain Truman。当看到他前任领主的断头时，Truman 的反应是震惊、恐惧和极度的厌恶。无法接受指挥官那可怕的命运，这位队长在痛苦中爆发，指责 The Adventurer 与怪物勾结，并发誓洛丹伦真正的子民终有一天会收复他们的土地并清除所有的野兽。"}},faq={{q="谁布置了 可憎的生物 任务？",a="该任务由 特鲁曼上尉 提供，他是一名驻扎在已沦陷王国周边地区的人类忠诚派。特鲁曼 在焦虑地坚守岗位、等待援军的同时，急切地寻求关于他指挥官的消息，那位大元帅曾冲入了附近的洛丹伦废墟。",al={"谁发布了 可憎的生物","可憎的生物 任务发布者","如何开始 可憎的生物"}},{q="可憎的生物 任务发生在什么地方？",a="该任务指引 冒险者 进入洛丹伦废墟，这是被天灾军团的恐怖之物和亡灵残余所淹没的破碎首都。特鲁曼上尉 在这片枯萎的首都外保持着哨位，请求勇敢的旅行者直接冒险进入危险的废墟，以定位他失踪的长官。",al={"可憎的生物 位置","可憎的生物 在哪里完成","可憎的生物 区域"}},{q="特鲁曼上尉 的长官是谁？",a="特鲁曼上尉 将他的长官称为大元帅，赞扬他是位高大、像雕像一样的军事英雄。然而，任务目标将这位失踪的贵族称为“男爵”，表明他是一位领导王国防御的高级贵族和军事指挥官。",al={"杜鲁门 的指挥官是谁","杜鲁门 的大元帅身份","男爵是谁"}},{q="洛丹伦废墟里的大元帅发生了什么？",a="大元帅并没有胜利地坚守下来，而是在洛丹伦废墟中被杀，并被转化为一个可怕的亡灵怪物。当 冒险者 找到他时，发现他已经成了被称为“男爵”的憎恶，被迫将其消灭并带回男爵的徽记。",al={"男爵发生了什么","大元帅的命运","大元帅死了吗"}},{q="为什么 特鲁曼上尉 在你完成任务时会生气？",a="特鲁曼上尉 期望他那像雕像般的指挥官能活着并获得胜利。当看到男爵的徽记时，特鲁曼 被恐惧和厌恶所淹没，愤怒地指责 冒险者 在开恶毒的玩笑并与邪恶的野兽勾结。",al={"为什么 杜鲁门 会生气","杜鲁门 对 可憎的生物 的反应","为什么 杜鲁门 对你大喊大叫"}},{q="特鲁曼上尉 所说的“洛丹伦真正的子民”是什么意思？",a="特鲁曼上尉 用这个词来描述那些致力于收复破碎家园的狂热人类爱国者。他的话表达了一种激烈、不宽容的愿景，即合法的人类幸存者将把王国从所有的亡灵、野兽以及任何被视为与它们勾结的人手中清除出去。",al={"洛丹伦真正的子民是什么意思","谁是洛丹伦真正的子民","杜鲁门 真正的子民"}},{q="为什么 特鲁曼上尉 拒绝信任“混血儿”？",a="特鲁曼上尉 对非人类种族和非正规盟友表现出极大的蔑视，将他们斥为不可信的混血儿和污秽之徒。他强烈的仇外心理使他除了那些他认为代表了王国的合格人员外，拒绝向任何人吐露心声。",al={"杜鲁门 混血儿","为什么 杜鲁门 队长有种族偏见","杜鲁门 的仇外心理"}}},fp="20,312,17.524.0,22.516.0,23.483.1,41.230.0,53.227.0,31.222.0,61.182.0,61.234.0,62.233.0,54.218.0"}
P.entries["quest:95254"] = {n="WANTED: Trapclaw",s="Fimbo Greasemitz 想要 Trapclaw 的钳子，因为这只巨型螃蟹在码头下方偷鱼饵、剪断钓线。把钳子带给他，他答应用自己的秘制香料调料做一顿美餐。",h="Fimbo Greasemitz 想要 Trapclaw 的钳子，因为这只巨型螃蟹在码头下方偷鱼饵、剪断钓线。把钳子带给他，他答应用自己的秘制香料调料做一顿美餐。",kw={"鱼饵","螃蟹","蟹肉","码头","fimbo greasemitz","钓线","钳子","trapclaw"},sec={{t="码头下方",b="Fimbo Greasemitz 想要蟹肉，而 Trapclaw 一直在码头下方爬行。这只大螃蟹偷鱼饵，还剪断钓线。Fimbo 请你把 Trapclaw 的钳子带给他，他打算用它做一顿饭。"}},faq={{q="谁想要 Trapclaw 的钳子？",a="Fimbo Greasemitz 想要 Trapclaw 的钳子来获取蟹肉。",al={"谁想要钳子","fimbo greasemitz 的请求"}},{q="Trapclaw 在做什么？",a="Trapclaw 在码头下方爬行，偷鱼饵并剪断钓线。",al={"为什么找 trapclaw","码头下的螃蟹"}},{q="Fimbo 为什么想要这只钳子？",a="Fimbo 想要蟹肉，因此向你索要 Trapclaw 的钳子。",al={"钳子有什么用","索要蟹肉"}},{q="Fimbo 答应做什么？",a="Fimbo 说他会用黄油和自己的秘制香料调料做一道菜。",al={"做什么饭","fimbo 做的菜"}}},fp="16,188,15.218.0,36.59.0,23.75.0,31.54.0,32.68.0"}
P.entries["quest:95260"] = {n="Terrors From the Deep",s="在爆破引线港，你要寻找一位水手，请他辨认兽皮上描绘的海怪。这幅奇异的图像或许指向这片海域中的某头巨兽。",h="在爆破引线港，你要寻找一位水手，请他辨认兽皮上描绘的海怪。这幅奇异的图像或许指向这片海域中的某头巨兽。",kw={"鱼内脏","画着图案的兽皮","爆破引线港","水手","海怪","鱿鱼墨汁","深海惊魂"},sec={{t="描绘的巨兽",b="一张画着图案的兽皮把你带到了爆破引线港，那里或许有水手认得这头巨兽。鱼内脏和鱿鱼墨汁描绘出一个从海浪中升起的长颈身影。如果这片海域中真有这样的怪物，常在此处航行的人或许知道它。"}},faq={{q="兽皮上画着什么？",a="兽皮上画着一头从海浪中升起的长颈海怪，颜料是鱼内脏和鱿鱼墨汁。",al={"兽皮上画着什么","海怪图像"}},{q="在哪里能找到认得这头海怪的人？",a="最近的港口是爆破引线港，那里的水手或许认得这种生物。",al={"该去哪里","爆破引线港水手"}},{q="这头海怪是真的吗？",a="这幅画让人怀疑这片海域中潜伏着一头海怪，但你要找的是一位能辨认它的水手。",al={"真实的海兽","怪物是真的吗"}}},fp="21,143,15.242.0,28.101.0,39.83.0,24.131.0"}
P.entries["quest:95261"] = {n="It Takes Guts",s="Argo Brinewhistle向你索要野兽内脏和Rotflesh mushrooms，想用它们作诱饵，捕捉他在群岛附近见过的一种长颈生物。他希望抓到它后，别人会相信他的故事。",h="Argo Brinewhistle向你索要野兽内脏和Rotflesh mushrooms，想用它们作诱饵，捕捉他在群岛附近见过的一种长颈生物。他希望抓到它后，别人会相信他的故事。",kw={"argo brinewhistle","诱饵","野兽内脏","群岛","it takes guts","长颈怪物","rotflesh mushrooms","windstead"},sec={{t="Argo's Bait",b="Argo Brinewhistle说，他出海时在群岛附近见过一只长颈怪物。他想让你收集野兽内脏和Rotflesh mushrooms作诱饵。这种蘑菇长在Windstead附近的洞穴里，Argo希望能借此抓住那只生物。"}},faq={{q="Argo Brinewhistle是谁？",a="Argo Brinewhistle是一名渔夫，他声称在群岛附近见过一只长颈怪物。",al={"argo是谁","argo渔夫","argo的身世"}},{q="Argo需要什么作诱饵？",a="Argo请你给他带来野兽内脏和Rotflesh mushrooms。",al={"argo需要什么诱饵","argo内脏","臭诱饵"}},{q="Rotflesh mushrooms长在哪里？",a="Rotflesh mushrooms长在Windstead附近的洞穴里。",al={"rotflesh位置","蘑菇生长地点","windstead洞穴"}},{q="Argo为什么需要诱饵？",a="Argo想用诱饵抓住那只他声称在群岛附近见过的长颈生物。",al={"诱饵用途","argo要抓什么","长颈怪物"}},{q="为什么没人相信Argo？",a="Argo说，人们觉得他是个醉醺醺的渔夫，所以不相信他的故事。",al={"人们为何怀疑argo","argo醉汉","谁相信argo"}}},fp="13,187,11.250.0,25.95.0,29.65.0,33.47.0,28.94.0,32.80.0"}
P.entries["quest:95262"] = {n="The Secret Prison",s="苏利请你前往 Alcaz Prison，查明暴风城之王的下落。国王的命运牵动着整个暴风城。",h="苏利请你前往 Alcaz Prison，查明暴风城之王的下落。国王的命运牵动着整个暴风城。",kw={"alcaz","alcaz 监狱","暴风城之王","暴风城","苏利","the secret prison"},sec={{t="Alcaz 的搜寻",b="苏利派你前往 Alcaz，这座前哨站自第三次大战以来便被认为已经废弃。他认识的人中，没有谁提起过那里有座监狱。然而，暴风城之王或许就在里面，苏利需要你查明他的下落。"},{t="你的发现",b="在 Alcaz Prison，你得知暴风城之王已经身亡。你还发现，在你击败的那头次级龙背后，有一股更强大的势力在操纵一切。苏利必须知道你发现了什么。"}},faq={{q="苏利派我去哪里？",a="苏利派你前往 Alcaz Prison，那座监狱位于一处自第三次大战以来便被认为已经废弃的前哨站。",al={"该去哪里","alcaz 监狱","监狱在哪里"}},{q="苏利想让我查明什么？",a="苏利想让你查明暴风城之王的下落。",al={"要找什么","暴风城之王","寻找国王"}},{q="人们认为 Alcaz 是什么地方？",a="人们认为 Alcaz 是一处在第三次大战期间留下的废弃前哨站。",al={"alcaz 是什么","alcaz 前哨站","废弃之地"}},{q="苏利为什么派我去 Alcaz？",a="苏利派你前往 Alcaz，因为暴风城之王或许在那里。",al={"为何去 alcaz","为何前往那里","苏利的理由"}}},fp="17,130,17.235.0,13.198.2,25.91.0,33.62.0,29.63.0,32.77.0"}
P.entries["quest:95263"] = {n="Somber News",s="苏利 McCleary在尘泥沼泽等你，想听听你打探到的国王消息。国王之死震动了暴风城，苏利想知道你查到了什么。",h="苏利 McCleary在尘泥沼泽等你，想听听你打探到的国王消息。国王之死震动了暴风城，苏利想知道你查到了什么。",kw={"尘泥沼泽","逃跑尝试","国王","娜迦","纸条","somber news","暴风城","苏利 mccleary"},sec={{t="带给苏利的消息",b="苏利 McCleary正在尘泥沼泽等你带回消息。国王已死，暴风城面临沉重的打击。你把一张纸条交给苏利；他读着纸条，神情渐渐阴沉。"}},faq={{q="谁在等我？",a="苏利 McCleary正在尘泥沼泽等你，想听听你打探到的消息。",al={"谁想知道消息","苏利是谁","我该去哪儿"}},{q="国王怎么了？",a="国王在逃跑途中遇害，就在娜迦发动袭击前不久。",al={"国王死了","国王怎么了","谁杀了国王"}},{q="我给苏利带了什么？",a="你给苏利带来一张纸条，上面写着你打探到的消息。",al={"苏利的纸条","我要给他什么","送交纸条"}},{q="苏利有什么反应？",a="苏利读着纸条，神情渐渐阴沉，并称这消息糟透了。",al={"苏利的反应","苏利难过吗","他说了什么"}}},fp="11,141,14.188.0,22.71.0,26.73.0,22.45.0,21.80.0"}
P.entries["quest:95264"] = {n="Shaw Needs To Know",s="Matthias 肖尔需要你把紧急消息带到暴风城。他警告说，处理方式可能影响城中百姓。",h="Matthias 肖尔需要你把紧急消息带到暴风城。他警告说，处理方式可能影响城中百姓。",kw={"matthias 肖尔","消息","保密","si:7","暴风城","紧急消息"},sec={{t="回到肖尔身边",b="在暴风城，Matthias 肖尔读完你带来的消息，并让你对此守口如瓶。他说，为了城中百姓，必须谨慎处理此事。"}},faq={{q="谁需要这条消息？",a="暴风城的 Matthias 肖尔需要你把消息带给他。",al={"该告诉谁","肖尔的消息","肖尔是谁"}},{q="为什么要保密？",a="肖尔说，如果在他们准备好之前消息就传开，暴风城的百姓会遭殃。",al={"为何保密","保守秘密","能告诉谁"}},{q="肖尔会如何处理这条消息？",a="肖尔读完纸上的文字，说接下来交给他处理。",al={"消息会如何处理","肖尔读了消息","他说了什么"}},{q="这条消息讲的是什么？",a="据说这条消息可能给暴风城带来灾难，但这里没有说明具体内容。",al={"什么消息","发生了什么","是什么灾难"}}},fp="18,123,12.170.0,19.59.0,29.100.0,32.69.0,23.100.0"}
P.entries["quest:95267"] = {n="The Monster Surfaces",s="Argo Brinewhistle想让你用一大团诱饵，把海怪从鱼人群岛附近的海域引出来。他要你把海怪的头带回去，装饰船只。",h="Argo Brinewhistle想让你用一大团诱饵，把海怪从鱼人群岛附近的海域引出来。他要你把海怪的头带回去，装饰船只。",kw={"argo brinewhistle","一大团诱饵","船只装饰","海怪头","鱼人群岛","海怪","残骸"},sec={{t="水中的残骸",b="Argo Brinewhistle指引你前往鱼人群岛，你曾在那里发现一幅图画。如今，水中新出现的残骸标出了该投下诱饵的位置。Argo想引出的正是那只海怪，而它的头将用来装饰船只。"}},faq={{q="Argo想让我做什么？",a="Argo要你在鱼人群岛附近水中的新残骸旁使用一大团诱饵，然后把海怪的头带给他。",al={"argo诱饵任务","海怪诱饵","海怪现身任务"}},{q="我该在哪里投下诱饵？",a="Argo指引你前往鱼人群岛附近水中的新残骸处，你曾在那里发现一幅图画。",al={"诱饵投放地点","鱼人群岛诱饵","新鲜残骸"}},{q="Argo为什么要海怪的头？",a="Argo想把这只生物的头做成船上的装饰。",al={"为什么要海怪头","船只装饰","船上的海怪头"}},{q="诱饵称作什么？",a="它叫一大团诱饵。",al={"一大团诱饵","一团内脏","诱饵名称"}}},fp="20,161,21.241.0,29.136.0,26.98.0,38.68.0,24.34.0"}
P.entries["quest:95278"] = {n="It Is Time, Brother...",s="危险日益加剧，必须将一封信送到洛格玛的Krom'rosh手中。Da'grosh的警告让人想起村庄与部落昔日的希望。",h="危险日益加剧，必须将一封信送到洛格玛的Krom'rosh手中。Da'grosh的警告让人想起村庄与部落昔日的希望。",kw={"da'grosh","部落","krom'rosh","信","洛格玛","村庄","警告","勇士"},ang={["class:Warrior"]="身为战士，你也在Da'grosh的期望之中：他希望村中族人成为伟大的部落勇士。",["faction:Horde"]="身为部落的一员，你听到了Da'grosh儿时的愿望：村中族人或许能成为拯救族人的勇士。"},sec={{t="给洛格玛的警告",b="威胁已远超最初的估计，必须警告洛格玛。你要把信送给Krom'rosh，途中不能为任何人停留。"},{t="昔日的希望",b="Da'grosh曾劝村中族人成为伟大的部落勇士，保护族人免受危险。如今，Krom'rosh看到了检验这一希望的机会。"}},faq={{q="需要警告谁？",a="威胁比最初估计的更大，因此必须警告洛格玛。",al={"需要警告谁","警告谁"}},{q="信要送给谁？",a="洛格玛的Krom'rosh会收到这封信。",al={"把信送给谁","谁收信"}},{q="为什么途中不能停留？",a="这封信必须送到Krom'rosh手中，警告中还说，途中不要为任何人停留。",al={"为什么不能停留","不能停下"}},{q="Da'grosh小时候对村里人说了什么？",a="Da'grosh劝村中族人成为伟大的部落勇士，保护族人免受危险。",al={"dagrosh童年","dagrosh说了什么"}}},fp="22,132,21.159.0,11.169.1,23.72.0,25.42.0,31.90.0,46.105.0"}
P.entries["quest:95283"] = {n="The Missing Kor'kron",s="一支被派往尘泥沼泽的库卡隆精锐小队未按时联络。你被派往蕨墙村，向纳泽尔 Bloodspike 打听他所知的情况。",h="一支被派往尘泥沼泽的库卡隆精锐小队未按时联络。你被派往蕨墙村，向纳泽尔 Bloodspike 打听他所知的情况。",kw={"蕨墙村","联络","尘泥沼泽","库卡隆精锐","失踪的库卡隆","纳泽尔 bloodspike","特殊任务"},sec={{t="尘泥传来的消息",b="这支小队没有回音，任务情况也无从得知。在蕨墙村，纳泽尔 Bloodspike 比任何人都了解尘泥沼泽的情况。你被派来向他打听失踪的库卡隆精锐。"}},faq={{q="是谁派库卡隆精锐前往尘泥沼泽的？",a="派你去找纳泽尔的伊崔格说，他那边不久前派他们执行一项特殊任务。",al={"谁派遣了库卡隆","谁派他们去的"}},{q="库卡隆精锐为什么失踪了？",a="他们约定的联络时间已过，却没有任何消息传来。",al={"库卡隆为何失踪","他们出了什么事"}},{q="库卡隆被派去了哪里？",a="一支库卡隆精锐小队被派往尘泥沼泽执行一项特殊任务。",al={"库卡隆在哪里","库卡隆的位置"}},{q="我在蕨墙村应该找谁谈谈？",a="去找纳泽尔 Bloodspike。他是个兽人，了解尘泥沼泽的情况。",al={"纳泽尔是谁","纳泽尔 bloodspike"}}},fp="20,153,20.230.0,48.99.0,35.68.0,29.81.0,47.77.0"}
P.entries["quest:95284"] = {n="The Elite of the Elite",s="海岸附近的一名补给商请你寻找一支失踪的库卡隆精锐部队。他们的踪迹指向奥卡兹岛，那里可能出了什么差错。",h="海岸附近的一名补给商请你寻找一支失踪的库卡隆精锐部队。他们的踪迹指向奥卡兹岛，那里可能出了什么差错。",kw={"奥卡兹岛","海岸","精锐士兵","岛屿","库卡隆","失踪的库卡隆","补给商"},ang={["faction:Horde"]="作为部落的一员，你受托寻找一支失踪的库卡隆士兵队伍。"},sec={{t="令人不安的踪迹",b="几天前，一队库卡隆士兵曾在这里采购补给、休息，然后继续上路。补给商听见其中一人提到了某座岛，而奥卡兹岛就在近海。如今，你受托寻找失踪的精锐士兵，并查明他们遭遇了什么。"}},faq={{q="失踪的库卡隆是什么人？",a="他们是一小队库卡隆士兵，曾在这里补充给养、休息，然后继续上路。",al={"库卡隆精锐","失踪的士兵","失踪的库卡隆"}},{q="库卡隆可能去了哪里？",a="其中一名士兵提到过一座岛，补给商猜测他们去了近海的奥卡兹岛。",al={"是哪座岛","库卡隆的岛","他们去了哪里"}},{q="补给商为什么感到担忧？",a="库卡隆休息后便继续上路，但补给商觉得事情出了差错。",al={"出了什么差错","为何寻找库卡隆","失踪的精锐士兵"}},{q="奥卡兹岛是什么样的地方？",a="补给商说，奥卡兹岛是个相当凶险的地方。",al={"奥卡兹岛","奥卡兹岛危险吗","凶险的岛屿"}}},fp="22,157,16.250.0,31.102.0,37.94.0,28.83.0,26.53.0"}
P.entries["quest:95285"] = {n="Right Place, Wrong Time",s="中士Ulka请你听取有关Alcaz Isle局势的说明。其余任务详情仅向有需要知情的人透露。",h="中士Ulka请你听取有关Alcaz Isle局势的说明。其余任务详情仅向有需要知情的人透露。",kw={"alcaz isle","简报","任务","时机不对","中士ulka","大酋长"},ang={["faction:Horde"]="作为部落的一员，中士Ulka问你是否准备好履行对大酋长的职责。"},sec={{t="Ulka的简报",b="中士Ulka在Alcaz Isle与你交谈时，挣扎着想坐起身。你伸手扶她，她却一把拍开。她说会向你说明最新情况，但任务的其余详情仍会严格保密。你为大酋长效力的职责正在等着你。"}},faq={{q="谁要向我说明最新情况？",a="中士Ulka与你交谈时，挣扎着想坐起身。",al={"谁是ulka","中士ulka"}},{q="Alcaz Isle发生了什么事？",a="中士Ulka说，她会向你说明Alcaz Isle的局势。",al={"alcaz局势","这里发生了什么"}},{q="Ulka为什么不肯透露全部任务详情？",a="中士Ulka说，其余任务详情仅限有需要知情的人了解。",al={"为何仅限知情","详情是什么"}},{q="Ulka要我做什么？",a="与中士Ulka交谈，了解Alcaz Isle的局势。",al={"我该做什么","与ulka交谈"}},{q="Ulka问我的职责是什么？",a="中士Ulka问你是否准备好履行对大酋长的职责。",al={"准备好为大酋长效力","职责问题"}}},fp="23,138,15.245.0,29.57.0,32.72.0,45.66.0,25.73.0,33.73.0"}
P.entries["quest:95288"] = {n="Smuggler's Paradise",s="在爆破引线港，Friz Frazzlespark 派你去追捕夺走她赃物的 Eastsea pirates。她称这是你学会对付背叛者的第一课。",h="在爆破引线港，Friz Frazzlespark 派你去追捕夺走她赃物的 Eastsea pirates。她称这是你学会对付背叛者的第一课。",kw={"eastsea海盗","friz frazzlespark","地精","爆破引线港","走私货物","smuggler's paradise","赃物"},sec={{t="Friz的教训",b="爆破引线港的 Friz Frazzlespark 要你夺回被 Eastsea pirates 抢走的货物。她说，那些货物是她先偷来的，并称夺回货物是你作为她跟班要上的第一课。"},{t="第一课",b="Friz 说你已经学好了第一课。她免费传授自己的经验，随后又给你指派了另一项任务。"}},faq={{q="Friz Frazzlespark是谁？",a="Friz Frazzlespark 是一名地精，她让你从 Eastsea pirates 手中夺回被盗的货物。",al={"friz","friz是谁","爆破引线港的地精"}},{q="Eastsea海盗拿走了什么？",a="Eastsea pirates 抢走了一批货物，Friz 说那批货物是她先偷来的。",al={"海盗拿走的货物","被偷走了什么","走私货物"}},{q="Friz想把货物送回哪里？",a="Friz 要你在爆破引线港替她收回货物。",al={"friz在哪里","爆破引线港","货物要送到哪里"}},{q="Friz为什么想拿回货物？",a="Friz 说那些货物是她先偷来的，却被 Eastsea pirates 抢走了；她称夺回货物是对付背叛者的一课。",al={"为什么要追回货物","friz为何在意","背信者的缘由"}}},fp="19,157,13.180.0,14.131.1,25.94.0,34.81.0,40.62.0,34.120.0"}
P.entries["quest:95293"] = {n="Smuggler's Special",s="Friz派你把一箱名为The Friz Special的货物送到Eastwind Shore的Captain Bentcoin手中。这是她对他企图染指自己地盘的回应。",h="Friz派你把一箱名为The Friz Special的货物送到Eastwind Shore的Captain Bentcoin手中。这是她对他企图染指自己地盘的回应。",kw={"captain bentcoin","箱子","eastsea pirates","eastwind shore","friz","smuggler's special","the friz special","贸易战"},sec={{t="Friz的回应",b="你刚登上Captain Bentcoin的船，他便出言威胁。Friz派你带着一箱名为The Friz Special的货物，送给Eastwind Shore的船长。原本属于她的货物本该直接送到她手中，而她认为Bentcoin正企图染指自己的地盘。她称这是给他的第二课，并把这箱货物当作对他讨价还价的恰当回应。"},{t="箱中之物",b="Bentcoin收到Friz送来的箱子时，以为这代表她知道自己已经落败。随后，他听见了滴答声。"}},faq={{q="Friz是谁？",a="原本属于Friz的货物被截走后，她派你带着一箱名为The Friz Special的货物去找Captain Bentcoin。",al={"friz","谁派我来的","friz special任务给予者"}},{q="Captain Bentcoin是谁？",a="Captain Bentcoin是Friz派你去见的人，他在Eastwind Shore附近的船上。",al={"bentcoin","船长是谁","eastwind船长"}},{q="我在运送什么？",a="你带着The Friz Special，这是Friz为Captain Bentcoin准备的一箱货物。",al={"friz special","箱子","我带什么"}},{q="Friz为什么要送礼？",a="Friz说，你从Eastsea pirates那里弄来的货物本该直接运给她，而她认为Bentcoin正企图染指自己的地盘。",al={"为何送礼给bentcoin","friz的送货任务","贸易战"}},{q="我在哪里能找到Captain Bentcoin？",a="Captain Bentcoin在Eastwind Shore附近的船上。",al={"bentcoin的位置","船长在哪里","eastwind shore"}},{q="我到达时Bentcoin说了什么？",a="Bentcoin威胁要把擅自登船的你绑在龙骨下拖行，并要求你说出一个饶你一命的理由。",al={"bentcoin的反应","船长说了什么","登上船"}}},fp="18,158,13.362.0,9.132.1,12.111.0,24.88.0,21.74.0,27.157.0,33.53.0,37.98.0"}
P.entries["quest:95294"] = {n="Smuggler's Bargain",s="一名Eastsea海盗向Friz Frazzlespark提出交易，条件是他不插手她的生意。你把口信带回爆破引线港交给她。",h="一名Eastsea海盗向Friz Frazzlespark提出交易，条件是他不插手她的生意。你把口信带回爆破引线港交给她。",kw={"船长","eastsea海盗","friz frazzlespark","地精","海盗","爆破引线港","走私者的交易"},sec={{t="船长的提议",b="Friz Frazzlespark引起了Eastsea海盗的注意，其中一人提出不让手下插手她的生意。作为回报，他提议达成一桩有利可图的交易。你把口信带回爆破引线港交给Friz，她会听听是谁自称掌权。"},{t="Friz的教训",b="Friz以警告回应海盗的提议，说明与她作对要付出什么代价。她的话让交易条件变得悬而未决。"}},faq={{q="海盗向Friz提出什么条件？",a="一名Eastsea海盗提出不让手下插手Friz的生意，并提议达成一桩有利可图的交易。",al={"eastsea海盗的提议","friz的交易"}},{q="我该向谁回报？",a="你回到爆破引线港，向Friz Frazzlespark复命。",al={"返回地点","口信交给谁"}},{q="船长传了什么口信？",a="他想让Friz知道，新船长已经掌权，并预见双方能建立一段有利可图的关系。",al={"船长的口信","告诉friz什么"}},{q="新船长是谁？",a="Friz质疑这位船长究竟是谁，而口信中并未提及他的名字。",al={"船长是谁","海盗头目"}}},fp="18,135,17.279.0,13.124.1,32.118.0,24.51.0,35.93.0,23.69.0"}
P.entries["quest:95295"] = {n="I Know a Guy",s="Friz让你前往藏宝海湾，与她的联系人拉兹戈特会面。联系人从当地的亡命徒那里取得货物，并会说明接下来该做什么。",h="Friz让你前往藏宝海湾，与她的联系人拉兹戈特会面。联系人从当地的亡命徒那里取得货物，并会说明接下来该做什么。",kw={"藏宝海湾","联系人","自由掠夺者","friz","货物","我认识一个人","海盗","拉兹戈特"},sec={{t="藏宝海湾的联系人",b="Friz说，她的联系人是拉兹戈特，正在藏宝海湾等候。他从那里的海盗手中取得货物，Friz称他们为亡命徒。找到拉兹戈特，他会说明其余的事。"}},faq={{q="Friz的联系人是谁？",a="Friz说他的联系人是拉兹戈特，人在藏宝海湾。",al={"friz的联系人","拉兹戈特是谁","藏宝海湾联系人"}},{q="Friz派我去哪儿？",a="Friz派你去藏宝海湾见拉兹戈特。",al={"该去哪儿","拉兹戈特在哪儿","藏宝海湾"}},{q="拉兹戈特做什么？",a="拉兹戈特从藏宝海湾当地的海盗那里收货。",al={"联系人做什么","拉兹戈特的货物","海盗货物"}},{q="Friz为什么称海盗为自由掠夺者？",a="Friz说，有些人把海盗称作自由掠夺者，还开玩笑说这个词里有“免费战利品”的意思。",al={"自由掠夺者的含义","海盗还是自由掠夺者","为何称自由掠夺者"}}},fp="12,141,22.166.0,22.47.0,24.44.0,21.55.0,43.98.0"}
P.entries["quest:95296"] = {n="Shipping and Handling",s="你的雇主让你把一只木箱送到热砂港。那里有个地精，应该会偿清欠款。",h="你的雇主让你把一只木箱送到热砂港。那里有个地精，应该会偿清欠款。",kw={"木箱","送货","欠款","地精","货运与搬运","热砂港","塔纳利斯","wharfmaster steamfizzle"},sec={{t="待送达的木箱",b="你的雇主正忙着在镇上谈判，于是把一个木箱交给你，让你转交给她的伙伴。她希望你从码头乘船前往塔纳利斯的热砂港。到了那里，你需要找 Wharfmaster Steamfizzle，而一名地精应缴的款项也悬而未决。"}},faq={{q="是谁把木箱交给我的？",a="你的雇主忙着在镇上处理谈判时，把木箱交给了你。",al={"送木箱","谁派我来的","送货差事"}},{q="木箱要送到哪里？",a="这只木箱是要送给你雇主在塔纳利斯热砂港的熟人。",al={"木箱目的地","送到哪里","热砂港送货"}},{q="我在热砂港该找谁？",a="在热砂港，你要找的人是 Wharfmaster Steamfizzle。",al={"码头管理员","steamfizzle","港口联系人"}},{q="我为什么要搬运木箱？",a="你的雇主正忙着在镇上谈判，于是请你替她送木箱。",al={"为什么送木箱","木箱里有什么","送货原因"}},{q="那个地精应该做什么？",a="你的雇主希望热砂港的一个地精偿清欠款。",al={"地精欠款","偿清欠款","为什么是地精"}}},fp="21,105,18.256.0,22.73.0,24.81.0,41.67.0,26.84.0,34.68.0"}
P.entries["quest:953"] = {n="亚米萨兰的毁灭",s="哨兵坦莎·月刃委托冒险者去探索黑海岸那令人毛骨悚然的亚米萨兰废墟，以破译古代石板。这些铭文记录了天崩地裂期间降临在那座上层精灵城市身上的悲剧与毁灭。所收集的知识是提供给奥伯丁的古籍学会的，旨在恢复在上古之战中大部分失传的历史。",h="哨兵坦莎·月刃委托冒险者去探索黑海岸那令人毛骨悚然的亚米萨兰废墟，以破译古代石板。这些铭文记录了天崩地裂期间降临在那座上层精灵城市身上的悲剧与毁灭。所收集的知识是提供给奥伯丁的古籍学会的，旨在恢复在上古之战中大部分失传的...",kw={"亚米萨兰","奥伯丁","艾萨拉","古籍学会","黑海岸","上层精灵","天崩地裂","石板","坦莎·月刃"},ang={["class:Mage"]="这些石板让人清醒地看到了天崩地裂前精灵法术的造诣巅峰，以及当这种力量失控时所带来的可怕毁灭。",["faction:Alliance"]="协助哨兵们守护黑海岸的历史，有助于为在卡利姆多领导联盟的暗夜精灵领袖们保存重要的知识。",["race:NightElf"]="亚米萨兰的废墟是一个严酷的警示，提醒人们注意你们的祖先在艾萨拉女王统治下的傲慢，以及不受节制的奥术魔法所带来的灾难性后果。"},sec={{t="上层精灵的回响",b="在海岸破碎成如今雾气弥漫的黑海岸之前很久，亚米萨兰曾是一个繁荣的定居点，艾萨拉女王的精英法师们在此研习强大的奥术魔法。一万年前永恒之井的灾难性毁灭之后，这座城市沦为破碎的大理石和开裂的石柱。今天，它仍然徘徊着那些在黄金时代分崩离析时死去、因痛苦而不得安息的上层精灵灵魂。"},{t="发掘失落的编年史",b="由于上古之战将暗夜精灵文明推向了混乱的求生边缘，在天崩地裂后，几乎没有文字记录完整保存下来。哨兵坦莎·月刃曾试图亲自勘察这些废墟，并发现了两块巨大的刻字石板——《亚米萨兰之歌》和《亚米萨兰的陨落》——但在幽灵般的上层精灵鬼魂迫使她撤退之前，她只来得及看这些。找回这些记载，能确保有关那场远古灾难的历史真相传达给奥伯丁古籍学会的学者们。"}},faq={{q="亚米萨兰是什么？",a="亚米萨兰是位于黑海岸中部的一处古代暗夜精灵废墟。一万年前，这里是一座城市，艾萨拉女王的上层精灵贵族们在此公开施展和研习宏大的奥术魔法，直到它在天崩地裂中陨落。",al={"亚米萨兰背景知识","亚米萨兰是什么","谁生活在亚米萨兰"}},{q="为什么亚米萨兰会有鬼魂？",a="在废墟中游荡的那些不得安息的鬼魂，是曾经生活并死在那里的上层精灵的灵魂。他们被那场突然而剧烈的、摧毁了永恒之井并分裂了卡利姆多的灾难所困，这些灵魂在永恒的折磨中被束缚在废墟里。",al={"为什么亚米萨兰会有鬼魂","亚米萨兰鬼魂","不得安息的上层精灵"}},{q="哨兵坦莎·月刃是谁？",a="哨兵坦莎·月刃是一名驻扎在黑海岸道路旁的暗夜精灵哨兵。她的任务是勘察古代遗址，并为奥伯丁的古籍学会寻回失落的历史记录。",al={"坦莎·月刃","谁发布了亚米萨兰的陨落任务"}},{q="为什么古籍学会想要解读这些石板？",a="永恒之井的毁灭使卡利姆多陷入了巨大的动荡，无数图书馆和纪念碑被夷为平地。由于上古之战后留下的文字记录寥寥无几，这些石板提供了从上层精灵视角出发的、关于天崩地裂的珍贵第一手资料。",al={"为什么要阅读石板","古籍学会石板","亚米萨兰之歌含义"}},{q="石板在什么位置？",a="两块巨大的石板——《亚米萨兰之歌》和《亚米萨兰的陨落》——刻在亚米萨兰废墟庭院中的耸立石碑上，周围游荡着该城昔日居民的鬼魂。",al={"亚米萨兰石板位置","石板位置","如何阅读亚米萨兰石板"}},{q="天崩地裂期间亚米萨兰的上层精灵遭遇了什么？",a="当永恒之井在上古之战的高潮中内爆时，巨大的震动和奥术反噬将卡利姆多撕裂。亚米萨兰在毁灭中坍塌，埋葬了它的居民，留下了在废墟中徘徊的鬼魂。",al={"亚米萨兰是如何陨落的","亚米萨兰毁灭"}}},fp="22,278,23.289.0,26.458.0,19.221.0,35.199.0,32.190.0,56.311.0,30.204.0,66.216.0"}
P.entries["quest:95309"] = {n="No Orc Left Behind",s="你被派往 Alcaz Prison，寻找 Commander Folkar，并查明要塞下方发生了什么。地牢里有一支军队，你被警告不要独自前往。",h="你被派往 Alcaz Prison，寻找 Commander Folkar，并查明要塞下方发生了什么。地牢里有一支军队，你被警告不要独自前往。",kw={"alcaz prison","commander folkar","地牢","要塞","库卡隆","no orc left behind","ulka"},sec={{t="要塞之下",b="Commander Folkar 就在要塞下方的地牢某处，你被派往 Alcaz Prison 寻找他。若他还活着，你就要救他出来，并查明那里发生了什么。下方有一支军队，因此有人警告你，必须有盟友相助才能活下来。"},{t="搜寻",b="Ulka 在历经一场致命遭遇后，派你去寻找 Commander Folkar。Folkar 称赞她为 库卡隆 效力，并表示会确保她获得战地晋升。但他说任务尚未完成，你还不能离开 Alcaz Prison。"}},faq={{q="我会被派往哪里？",a="你将前往 Alcaz Prison，那里位于要塞下方的地牢中。",al={"前往何处","alcaz prison 位置","要塞下方"}},{q="我要找谁？",a="你要在 Alcaz Prison 寻找 Commander Folkar。",al={"寻找谁","commander folkar","folkar 下落"}},{q="我要查明什么？",a="你需要查明要塞下方的地牢里发生了什么。",al={"发生了什么","查明发生了什么","监狱情况"}},{q="为什么警告我要带上盟友？",a="地牢里有一支军队，你被警告，独自待在那里无法生还。",al={"需要盟友","能否独自前往","下方的军队"}}},fp="18,166,14.259.0,10.253.1,22.65.0,21.53.0,28.74.0,32.88.0"}
P.entries["quest:95312"] = {n="Coming to Collect",s="Friz的欠债人把她的钱押在加基森竞技场的Slugjaw身上，并称奖金已经可以领取。你受命去找Fizbuz Mithril。",h="Friz的欠债人把她的钱押在加基森竞技场的Slugjaw身上，并称奖金已经可以领取。你受命去找Fizbuz Mithril。",kw={"竞技场","coming to collect","fizbuz mithril","friz","加基森","赌博","slugjaw","奖金"},sec={{t="Friz的钱",b="欠Friz钱的赌徒说，他把她的钱押在了Fizbuz位于加基森的竞技场里的Slugjaw身上。他声称赌赢了，但还没领取奖金。你正好在替Friz跑腿，他便请你去加基森找Fizbuz Mithril。"}},faq={{q="谁欠Friz钱？",a="一名赌徒把Friz的钱押在Fizbuz的竞技场里，因而欠她钱。",al={"friz的钱","friz的欠债人","谁欠friz钱"}},{q="他为什么要押她的钱？",a="他说，他觉得押Slugjaw是笔稳妥的投资。",al={"为何押她的钱","slugjaw赌注","赌徒下注"}},{q="Slugjaw是谁？",a="Slugjaw是这名赌徒在加基森押注的竞技场斗士。",al={"slugjaw","slugjaw竞技场","slugjaw是谁"}},{q="奖金在哪里？",a="赌徒说他还没领取奖金，并让你去加基森找Fizbuz Mithril。",al={"friz的奖金","领取钱款","钱在哪里"}},{q="我该去加基森找谁？",a="去加基森找Fizbuz Mithril，询问奖金的事。",al={"fizbuz","加基森竞技场","替friz跑腿"}}},fp="17,158,14.268.0,20.74.0,30.61.0,15.61.0,23.107.0,35.58.0"}
P.entries["quest:95314"] = {n="That Shadowvale Green Elixir",s="布瑞尔的卡罗莱·安尼斯正在寻求从影谷的废弃定居点中抢救物资，该定居点位于深藏于耳语森林的幽僻处。在洛丹伦王国覆灭之前，这个村庄就以蒸馏一种名为耳语药剂的特殊本地草药而闻名——即使在洛丹伦被列为禁品后，它在黑市上依然备受追捧。",h="布瑞尔的卡罗莱·安尼斯正在寻求从影谷的废弃定居点中抢救物资，该定居点位于深藏于耳语森林的幽僻处。在洛丹伦王国覆灭之前，这个村庄就以蒸馏一种名为耳语药剂的特殊本地草药而闻名——即使在洛丹伦被列为禁品后，它在黑市上依然备受追...",kw={"炼金师","布瑞尔","卡罗莱·安尼斯","毒药","影谷","提瑞斯法","耳语药剂","耳语森林"},ang={["class:Rogue"]="长期以来，耳语药剂一直受到那些在洛丹伦前任治安官眼皮底下活动的非法用毒者和恶棍的珍视。",["profession:Herbalism"]="这种药剂的效力来源于那些只在幽僻的耳语森林那阴森的树冠下茁壮生长的独特草药。",["race:Undead"]="对于被遗忘者来说，回收洛丹伦被遗忘的蒸馏品，既能带来可观的商业利润，也为幽暗城初期的炼金实验提供了素材。"},sec={{t="被禁的佳酿",b="在第三次战争和天灾军团入侵很久之前，影谷那离群索居的居民们酿造了一种独特的混合物，被称为耳语药剂。这种药剂由提瑞斯法林地独有的稀有草药蒸馏而成，在北洛丹伦声名狼藉。尽管在王都已被正式取缔，但其不同寻常的特性使它一直受到神秘主义者、用毒者以及愿意违抗王室法令的炼金师们的追捧。"},{t="耳语森林的废墟",b="影谷隐藏在西提瑞斯法的耳语森林深处。村民们历来排外且多疑，极少欢迎外来者。天灾入侵后，该定居点沦为废墟，但那些陈年的绿色药剂遗存仍埋在瓦砾之中。卡罗莱·安尼斯在布瑞尔经营生意，利用黑市持续的需求，雇佣那些愿意冒险进入森林那令人不安的寂静中的冒险者。"},{t="耳语诅咒",b="虽然卡罗莱倾向于将这些传闻视为单纯的迷信，但耳语森林确实名声不佳。当地传说，森林的土壤和根系本身就受到古老诅咒的侵蚀，这种诅咒直接渗透进了被影谷酿造师们采集的植物中。无论是什么样的邪恶力量在废弃的村落中徘徊，都未能浇灭远方买家对这些瓶装遗存的渴望。"}},faq={{q="什么是影谷？",a="影谷是一个隐藏在西提瑞斯法林地的耳语森林中的幽僻村庄。在天灾军团席卷该地区之前，这里的人们是孤立主义者，主要以从当地野外蒸馏稀有混合物而闻名。",al={"影谷在哪里","谁住在影谷","影谷村"}},{q="什么是耳语药剂？",a="这是一种强效的绿色药剂，由提瑞斯法林地发现的独特草药酿制而成。该饮料深受神秘主义者、用毒者和炼金师的青睐，在洛丹伦覆灭前于王都被列为禁品。",al={"药剂有什么用","影谷绿色药剂背景故事","耳语药剂"}},{q="卡罗莱·安尼斯是谁？",a="卡罗莱·安尼斯是一位足智多谋的被遗忘者，居住在布瑞尔。她充当珍贵和违禁物品的中间商，获取像影谷药剂这样的非法试剂，并将其卖给王国各地的买家。",al={"卡罗莱·安尼斯","谁发布影谷绿色药剂任务","布瑞尔任务发布者"}},{q="为什么这种药剂在王都被禁？",a="原因未明。卡罗莱只说这种药剂在城里被禁，且尽管如此，炼金师、神秘主义者和用毒者依然在寻求它。有些人认为耳语森林受到诅咒，而从其根系中蒸馏出的药剂带有同样的诅咒，但卡罗莱将此视为迷信，从未将其与禁令联系起来。",al={"为什么耳语药剂是非法的","这种药剂有毒吗"}},{q="为什么耳语森林被认为很危险？",a="丧钟镇以西那片幽僻的树林被普遍认为阴森且受到诅咒。那些冒险进入那里的人谈论着深重的邪恶和奇怪的林地现象，传言称这些现象污染了从土壤中生长出来的草药。",al={"耳语森林受诅咒了吗","耳语森林背景故事"}},{q="谁想要购买这种药剂？",a="根据卡罗莱·安尼斯的说法，有许多买家渴望获得幸存的战前药剂瓶，但她没有透露具体是谁。",al={"谁购买这种药剂","卡罗莱·安尼斯的买家"}}},fp="28,195,13.300.0,30.405.0,20.331.1,19.190.0,26.192.0,21.142.0,46.280.0,50.204.0,39.105.0"}
P.entries["quest:95315"] = {n="The Riverglades Report",s="尼艾丝队长派你南下，前往法霍德要塞把信件送给 Demar Brant。一名斥候报告，湿地以南有一支敌军正在集结，附近有个名叫 Farholde 的聚居地。",h="尼艾丝队长派你南下，前往法霍德要塞把信件送给 Demar Brant。一名斥候报告，湿地以南有一支敌军正在集结，附近有个名叫 Farholde 的聚居地。",kw={"尼艾丝队长","信件","demar brant","farholde","法霍德要塞","河林报告","斥候","湿地"},sec={{t="斥候的报告",b="尼艾丝队长听说，湿地以南很远的地方有一支大批敌军正在集结。那里或许有个名叫 Farholde 的聚居地，不过他只听说过这个名字。他把信件交给你，让你送给 Demar Brant。Demar Brant 负责驻守河林东南海岸的法霍德要塞。"}},faq={{q="斥候报告了什么？",a="斥候报告说，湿地以南很远的地方有一支大批敌军正在集结。",al={"斥候报告","南边发生了什么"}},{q="尼艾丝队长派我去找谁？",a="你要把尼艾丝队长的信件送到法霍德要塞，交给 Demar Brant。",al={"信件交给谁","demar brant"}},{q="法霍德要塞在哪里？",a="法霍德要塞位于河林东南海岸。",al={"farholde 在哪里","要塞位置"}},{q="Farholde 是什么地方？",a="尼艾丝队长听说，集结的敌军附近有个名叫 Farholde 的聚居地。",al={"farholde 聚居地","farholde 是什么"}}},fp="22,180,16.302.0,26.80.0,35.83.0,23.67.0,17.81.0"}
P.entries["quest:95321"] = {n="Tazzik's Dues",s="Tazzik派你去加基森替他领取赌金，可他的竞技场斗士一无所获。你得找Tazzik算清这笔欠债。",h="Tazzik派你去加基森替他领取赌金，可他的竞技场斗士一无所获。你得找Tazzik算清这笔欠债。",kw={"竞技场","friz","热砂港","塔纳利斯","tazzik","tazzik的欠款","赌金"},sec={{t="返回热砂港",b="收货人让你回塔纳利斯的热砂港找Tazzik。Tazzik的斗士很快就在竞技场落败，因此没有赌金可收。你和收货人交谈时，Tazzik可能正想搭船离港。"},{t="Tazzik的答复",b="Tazzik承认，为了偿还Friz，他把所有家当都押在了这些比赛上，结果输得一干二净。他说自己无法归还她的财物，并请求你帮忙。"}},faq={{q="Tazzik的赌金怎么了？",a="Tazzik的斗士在竞技场落败了，收货人说这场比赛一铜币也没赚到。",al={"tazzik的赌金","tazzik的钱在哪里"}},{q="Tazzik要我去哪里？",a="收货人让你回塔纳利斯的热砂港找Tazzik对质。",al={"去哪里找tazzik","tazzik的位置"}},{q="我为什么要赶回港口？",a="收货人觉得Tazzik可能正想搭上离开热砂港的下一艘船。",al={"tazzik逃跑","tazzik要离开吗"}},{q="Friz是谁？",a="Tazzik欠Friz钱。他拿她的钱押了一场加基森竞技场的比赛，而他的斗士输了。",al={"friz与tazzik","tazzik与friz"}}},fp="13,143,16.233.0,15.152.1,35.87.0,32.80.0,36.90.0,12.103.0"}
P.entries["quest:95327"] = {n="All's Well That Ends Well",s="拉兹戈特说，风险投资公司已经为自己在这笔交易中的所作所为付出了代价，Friz也拿到了她的战利品。你回到爆破引线港找Friz Frazzlespark，拉兹戈特则在等待下一批货物。",h="拉兹戈特说，风险投资公司已经为自己在这笔交易中的所作所为付出了代价，Friz也拿到了她的战利品。你回到爆破引线港找Friz Frazzlespark，拉兹戈特则在等待下一批货物。",kw={"交易","friz frazzlespark","爆破引线港","河林","货物","南海海盗","风险投资公司"},sec={{t="另一批货物",b="下一批货物正在运往拉兹戈特那里，Friz Frazzlespark正在爆破引线港等候。风险投资公司已经遭到惩罚，Friz也拿到了她的战利品，你便回到河林去找她。拉兹戈特称这笔交易十分顺利。现在，南海海盗该给他送来下一批货物了。"}},faq={{q="Friz Frazzlespark是谁？",a="Friz Frazzlespark正在河林的爆破引线港等你。",al={"friz是谁","friz frazzlespark"}},{q="风险投资公司怎么了？",a="拉兹戈特说，风险投资公司已经遭到惩罚。",al={"风险投资公司交易","风险投资公司怎么样了"}},{q="Friz拿到战利品了吗？",a="是的。拉兹戈特说，Friz会拿到她的战利品。",al={"friz的战利品","她拿到了吗"}},{q="接下来会有什么？",a="拉兹戈特期待南海海盗送来下一批货物。",al={"下一批货物","南海海盗"}}},fp="25,185,16.312.0,25.75.0,33.49.0,22.37.0,20.59.0"}
P.entries["quest:95328"] = {n="Whispering Horror Residue",s="Whispering Horror Residue是人们从耳语森林下方发现的一种奇异野兽那蠕动的残骸。勇敢的冒险者们收集了这些被虚空侵蚀的遗骸，并将它们带给幽暗城军事区的兰克斯特神父，用于进行暗影研究。",h="Whispering Horror Residue是人们从耳语森林下方发现的一种奇异野兽那蠕动的残骸。勇敢的冒险者们收集了这些被虚空侵蚀的遗骸，并将它们带给幽暗城军事区的兰克斯特神父，用于进行暗影研究。",kw={"兰克斯特神父","暗影","提瑞斯法","幽暗城","虚空","军事区","耳语森林","低语恐魔残渣"},ang={["class:Priest"]="像兰克斯特神父这样的被遗忘者暗影牧师对虚空样本有着浓厚的学术和神学兴趣，他们将这种奇异的位面残骸视为研究对象，而非仅仅是畸形怪物。",["faction:Horde"]="效忠于部落的冒险者从提瑞斯法林地隐秘的荒野中回收不安的样本，为首都废墟下的研究工作提供燃料。",["race:Undead"]="幽暗城的被遗忘者积极研究整个洛丹伦的禁忌魔法和非自然腐蚀，试图利用黑暗现象来巩固他们在这个王国岌岌可危的统治。"},sec={{t="不安的收获",b="Whispering Horror Residue是人们从栖息在耳语森林下方的一只被击败的野兽身上刮下的奇怪且蠕动的残骸。资源丰富的冒险者们并没有抛弃这种极不自然的猎奇之物，而是收集了这些还在抽搐的物质，希望幽暗城的学者们能让它们发挥作用。"},{t="暗影研究",b="这种生物的残骸在位于幽暗城军事区的兰克斯特神父那里找到了渴望的研究者。兰克斯特指出，耳语森林长期以来一直受到虚空的侵蚀，他很乐意借此机会在钻研暗影奥秘的同时，对这些黑暗腐蚀的物理残骸进行检查。"}},faq={{q="什么是低语恐魔残渣？",a="低语恐魔残渣由从耳语森林下方击败的奇异野兽身上采集到的蠕动躯体残骸组成。尽管其本质令人不安，但暗影魔法学者发现它在奥术和神秘学研究中极具价值。",al={"什么是残骸","什么是低语恐魔残渣","残骸物品"}},{q="谁需要低语恐魔残渣？",a="这些残骸会被送到位于幽暗城军事区的被遗忘者兰克斯特神父手中。他很乐意借此机会探索暗影和虚空侵蚀现象的奥秘。",al={"谁接收残骸","谁是兰克斯特神父","在哪里上交残骸"}},{q="这个样本是从哪里来的？",a="该样本源自耳语森林下方，这是一片位于提瑞斯法林地丧钟镇以西的阴森林地。正如兰克斯特神父所观察到的那样，这片邪恶区域众所周知受到了虚空的侵蚀。",al={"怪物残骸从何而来","耳语森林背景故事","耳语森林下方"}},{q="为什么兰克斯特神父想要这些残骸？",a="兰克斯特神父致力于研究暗影和虚空的奥秘。对于那些探索禁忌艺术的被遗忘者从业者来说，受虚空污染的生物残骸能提供罕见的见解和研究材料。",al={"为什么兰克斯特需要这个","幽暗城暗影研究","为什么要研究残骸"}},{q="在哪里可以找到兰克斯特神父？",a="兰克斯特神父居住在幽暗城的军事区。军事区是洛丹伦废墟之下被遗忘者战士、学者和军事策划者们繁忙的聚集中心。",al={"军事区在哪里","兰克斯特位于何处","幽暗城兰克斯特位置"}},{q="耳语森林受到虚空的侵蚀了吗？",a="在提瑞斯法的当地人眼中，耳语森林长期以来一直有着邪恶的名声。兰克斯特神父指出，这片邪恶的林地及其地下的空间受到虚空的侵蚀，这早已不是什么秘密。",al={"耳语森林受到诅咒了吗","耳语森林虚空腐蚀","什么侵蚀了耳语森林"}}},fp="25,138,21.162.0,17.197.0,38.149.0,40.151.0,34.147.0,43.154.0,36.168.0,45.147.0"}
P.entries["quest:95329"] = {n="Out in the Field",s="Terral's Watch 的一名观察者监视平原，留意部落的动向。你受命去取回他的情况报告。",h="Terral's Watch 的一名观察者监视平原，留意部落的动向。你受命去取回他的情况报告。",kw={"cornelius","部落","观察塔","身处前线","情况报告","terral's watch","观察者"},sec={{t="偏远哨站",b="一座高塔从 Terral's Watch 俯瞰北部平原。观察者 Cornelius 独自驻守在那里，追踪部落军队的动向。他的哨站位置偏远，而且他向来寡言。你受命去找他谈谈，并带回一份情况报告。"}},faq={{q="Cornelius 是谁？",a="Cornelius 是独自驻守在 Terral's Watch 的观察者，在那里监视平原，留意部落的动向。",al={"观察者 cornelius","观察者是谁","cornelius 的报告"}},{q="Terral's Watch 是什么地方？",a="Terral's Watch 是一处俯瞰北部平原的观察哨，用于追踪部落军队的动向。",al={"terral's watch","瞭望塔","北方的高塔"}},{q="我需要去取什么报告？",a="你受命去 Terral's Watch 找观察者 Cornelius 谈谈，并取得一份情况报告。",al={"情况报告","cornelius 需要什么","cornelius 的任务"}},{q="Cornelius 为什么独自驻守？",a="Cornelius 独自驻守在偏远的观察哨。他向来沉默寡言，这被视为将他派驻此地的原因。",al={"他为什么独自驻守","cornelius 的哨站","为何派驻此地"}}},fp="16,115,14.265.0,17.115.0,23.116.0,30.88.0,33.140.0"}
P.entries["quest:95330"] = {n="Love Thy Neighbor",s="卡桑德拉·惠勒请你把农场多余的农产品送给特纳伐木营地的哈尔利根·特纳。她希望工人们能在饭菜中换换口味。",h="卡桑德拉·惠勒请你把农场多余的农产品送给特纳伐木营地的哈尔利根·特纳。她希望工人们能在饭菜中换换口味。",kw={"cassandra wheeler","farholde","农产品","水果","halligan turner","爱邻如己","特纳伐木营地","蔬菜"},sec={{t="邻人的馈赠",b="卡桑德拉·惠勒在 Farholde 北边经营农场，收获后会带到那里出售。她把剩下的农产品留给需要鼓励的人。伐木营地位于她的农场以北，靠着河边。她觉得那里的工人也需要些水果和蔬菜。你把她多余的农产品送给营地工头哈尔利根·特纳。"},{t="营地之中",b="哈尔利根·特纳感激地收下了货物。工人们平日除了肉和面包，几乎吃不到别的东西，所以他打算把这些农产品分给大家。他希望日后能回报卡桑德拉的善意。"}},faq={{q="是谁请你送货？",a="卡桑德拉·惠勒请你把农场多余的农产品送给哈尔利根·特纳。",al={"谁想要这个","卡桑德拉的请求","农产品任务"}},{q="哈尔利根·特纳是谁？",a="哈尔利根·特纳是特纳伐木营地的工头。",al={"哈尔利根是谁","伐木营地工头","特纳那个人"}},{q="伐木营地在哪里？",a="特纳伐木营地位于卡桑德拉的农场以北，靠着河边。",al={"特纳营地在哪里","营地位置","伐木营地"}},{q="卡桑德拉送了什么货物？",a="她送来农场多余的水果和蔬菜。",al={"我要送什么","农产品","卡桑德拉的货物"}},{q="卡桑德拉为什么要留出农产品？",a="收获之后，卡桑德拉会把没卖掉的农产品留给需要鼓励的人。",al={"为什么送食物","卡桑德拉的理由","帮助邻人"}},{q="伐木营地的工人平时吃什么？",a="哈尔利根说，工人们平日除了肉和面包，几乎吃不到别的东西。",al={"伐木工吃什么","营地工人的食物","肉和面包"}}},fp="17,168,17.318.0,11.191.1,31.82.0,23.56.0,26.69.0,31.53.0,40.93.0,45.60.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="这段旅程标志着塑风者从Zephras抵达艾泽拉斯，他们作为先遣先锋队，此前因瓦拉纳尔的邪教活动而延误。旅客们在旅店外登上一艘破天者飞船，随后降落在莫高雷，并会见Alaana Stormwalker，开始适应这个广阔而危险的新世界。",h="这段旅程标志着塑风者从Zephras抵达艾泽拉斯，他们作为先遣先锋队，此前因瓦拉纳尔的邪教活动而延误。旅客们在旅店外登上一艘破天者飞船，随后降落在莫高雷，并会见Alaana...",kw={"阿拉娜·风暴行者","巴努-阿拉","邪教","莫高雷","破天者","大地之环","瓦拉纳尔","塑风者","泽弗拉斯"},ang={["class:Shaman"]="塑风者和萨满对元素有着深刻的崇敬，依赖风的指引来完成他们的空中穿越。以大地之环的名义抵达，将他们直接与正在莫高雷扎根的元素传统联系在了一起。",["race:Skyborne"]="对于离开瓦拉纳尔的空降冒险者来说，这段旅程标志着他们作为先遣先锋队历史性地抵达艾泽拉斯。抛开家乡的邪教麻烦，他们迈出了踏上莫高雷草海平原的第一步。",["race:Tauren"]="作为莫高雷的原住民看护者，牛头人目睹了来自Zephras的新旅客降临在他们祖先的平原上。欢迎这些乘风而来的访客，为他们与这些正在这片土地上建立据点的盟友提供了早期的联系。"},sec={{t="离开瓦拉纳尔",b="前往艾泽拉斯的旅客由于最近瓦拉纳尔邪教活动的干扰，必须调整计划。尽管高级领导人留守在旅店以处理紧急事务并平息邪教威胁，但一支小型的塑风者先遣队已被先行派遣。这些先驱者前往旅店外的码头，登上了一艘飞向天空的破天者飞船。虽然他们的指挥官承诺很快会加入他们，但最初的探险完全由这支先头部队承担，他们被派遣到前方，以便在大部队到来前建立据点。"},{t="抵达莫高雷",b="在降落在莫高雷的草海平原后，来自Zephras的冒险者们受到了Alaana Stormwalker的欢迎。在艾泽拉斯立足需要时间和谨慎的努力，新来者被鼓励去侦察周围的领土，以适应新的环境。尽管风向对此次远征有利，但艾泽拉斯依然是一个陌生且危险的领域。在来自瓦拉纳尔的其余旅客到达并加入之前，熟悉当地的地形、野生动物和邻近居民是至关重要的第一步。"}},faq={{q="为什么塑风者要前往艾泽拉斯？",a="一支塑风者先遣队被先行派遣到艾泽拉斯以建立据点，而他们的领导人则留在了瓦拉纳尔。最近涉及当地邪教的麻烦扰乱了最初的旅行计划，延误了其余队员的行程。因此，这支先头部队独自前往，以完成登陆并确保建立据点，直到后续增援部队能够跟上。",al={"为什么去艾泽拉斯","塑风者任务","为什么塑风者在莫高雷"}},{q="阿拉娜·风行者是谁？",a="阿拉娜·风行者是等待迎接抵达莫高雷的塑风者的联络人。她欢迎来自泽弗拉斯的旅客，并指出在这片新土地上建立稳固的据点需要时间。在准备工作进行的同时，她建议刚抵达的冒险者探索周边地区，并为艾泽拉斯的危险做好准备。",al={"阿拉娜是谁","阿拉娜·风暴行者的角色","阿拉娜·风暴行者在哪里"}},{q="为什么主要行程被延误了？",a="从瓦拉纳尔出发的主航程由于最近涉及当地邪教的麻烦事件而被推迟。处理这些邪教带来的并发症迫使远征队领导人留在旅店以完成他们的事务。为了不完全中止任务，他们派遣了一小队塑风者搭乘破天者飞船前往艾泽拉斯带路。",al={"为什么延误","什么邪教延误了行程","为什么留在瓦拉纳尔"}},{q="旅客如何从瓦拉纳尔前往莫高雷？",a="旅客们通过搭乘停靠在瓦拉纳尔旅店外的一艘破天者飞船进行旅行。这艘船载着先遣队穿过天空，飞往莫高雷的平原，作为在初始远征期间连接泽弗拉斯与艾泽拉斯大陆的主要交通工具。",al={"如何到达莫高雷","船在哪里","如何前往艾泽拉斯"}},{q="泽弗拉斯是什么？",a="泽弗拉斯是搭乘破天者飞船抵达的冒险者们的家乡或起源地。当旅客到达莫高雷时，阿拉娜·风行者认出他们是来自泽弗拉斯的新人，并指出有利的风向引导了他们进入艾泽拉斯这片陌生而危险的领土。",al={"泽弗拉斯在哪里","泽弗拉斯是什么","泽弗拉斯背景故事"}},{q="冒险者抵达莫高雷后应该做什么？",a="新抵达的冒险者被鼓励去侦察和探索莫高雷的周边土地。因为建立定居点需要时间，熟悉附近的地形、生物和当地威胁是为在这个令人兴奋却又危险的新世界中航行所做的必要准备。",al={"在莫高雷做什么","抵达后的下一步行动","下一步做什么"}}},fp="16,272,23.440.0,18.424.0,45.264.0,26.240.0,35.192.0,50.190.0,16.215.0,52.209.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="“Welcome to Azeroth”是一个引导任务，派遣一名旅行者代表塑风者从雷霆崖前往奥格瑞玛。在大地之环精神纽带的指引下，使者会见萨尔大酋长，旨在与部落建立生存纽带和盟友关系。",h="“Welcome to Azeroth”是一个引导任务，派遣一名旅行者代表塑风者从雷霆崖前往奥格瑞玛。在大地之环精神纽带的指引下，使者会见萨尔大酋长，旨在与部落建立生存纽带和盟友关系。",kw={"大地之环","部落","奥格瑞玛","萨尔","雷霆崖","智慧谷","欢迎来到艾泽拉斯","塑风者"},ang={["class:Shaman"]="在大地之环的指引和风的祝福下，这段旅程将精神同胞直接与智慧谷的萨满领导核心连接起来。",["faction:Horde"]="这次外交任务使与部落的关系正式化，将新来者直接介绍给大酋长萨尔，使他们成为在卡利姆多生存的关键盟友。",["race:Skyborne"]="离开高空前往下方的地表世界，天生的塑风者向雷霆崖和奥格瑞玛伸出援手，以巩固他们在新盟友中的地位。"},sec={{t="更广阔世界中的盟友",b="踏入卡利姆多广袤的土地，新来者很快就会发现生存取决于手足情谊。塑风者将目光投向了孤立的起源之外，看向下方行走的人民，他们认识到孤立无法抵御艾泽拉斯的威胁。通过向邻近的牛头人城市雷霆崖伸出援手，并望向东部的兽人堡垒，他们寻求坚定的伙伴，共同在荒野中闯荡。"},{t="觐见大酋长",b="这趟旅程将使者带到雷霆崖高耸的塔楼，然后指引他们穿过贫瘠之地前往部落强大的首都奥格瑞玛。在宁静的智慧谷等待着的是大酋长萨尔，他是联盟的核心向导。站在萨尔面前，标志着塑风者正式进入卡利姆多的政治和精神领域，因为共同的目标和对元素的共同尊重而结合在一起。"}},faq={{q="任务“欢迎来到艾泽拉斯”的目的是什么？",a="“欢迎来到艾泽拉斯”是一个外交引导任务，派遣一名使者代表塑风者在奥格瑞玛会见大酋长萨尔。它是通往更广泛的部落和卡利姆多地表世界的正式介绍。",al={"这个任务是什么","欢迎来到艾泽拉斯任务","欢迎来到艾泽拉斯的目的"}},{q="塑风者是谁？",a="塑风者是一个从高处向地表盟友伸出援手的群体，寻求通过与大地之环和部落的友谊来生存。他们派遣旅行者直接与杜隆塔尔的部落领袖交谈。",al={"塑风者是谁","塑风者是什么"}},{q="为什么你要被派去与萨尔交谈？",a="作为部落的大酋长和受人尊敬的萨满领袖，萨尔在智慧谷统筹联盟的主要盟友关系。与他取得联系可以使塑风者和部落之间的关系正式化。",al={"为什么要拜访萨尔","与奥格瑞玛的萨尔交谈","为什么要前往奥格瑞玛"}},{q="如何从雷霆崖前往奥格瑞玛？",a="旅行者可以从雷霆崖中心栖息地的飞行管理员处起飞，飞越卡利姆多的平原，向东进入奥格瑞玛的峡谷要塞。",al={"如何前往奥格瑞玛","雷霆崖飞行管理员","从雷霆崖前往奥格瑞玛"}},{q="大地之环在这次任务中起什么作用？",a="在这次接触中，大地之环被描述为与部落志同道合的各族联盟保持一致，帮助促进萨满教派与卡利姆多各国之间的纽带。",al={"大地之环在部落的角色","大地之环是部落吗"}},{q="萨尔在奥格瑞玛的什么位置？",a="大酋长萨尔驻扎在智慧谷，那是奥格瑞玛西部一处安静的精神圣地，萨满祭司和部落顾问常在此集会。",al={"萨尔在哪里","智慧谷萨尔位置"}}},fp="18,196,25.303.0,29.350.0,52.156.0,24.200.0,38.208.0,50.154.0,48.142.0,37.139.0"}
P.entries["quest:95383"] = {n="Shipping and Handling",s="码头主管 Steamfizzle 让你把 Friz’s Secret Stash 交给 Tazzik。这批货物是否通过海关，引人质疑。",h="码头主管 Steamfizzle 让你把 Friz’s Secret Stash 交给 Tazzik。这批货物是否通过海关，引人质疑。",kw={"海关","friz","friz’s secret stash","爆破引线港","shipping and handling","热砂港","tazzik","码头主管 steamfizzle"},sec={{t="码头上",b="Tazzik 正在热砂港的码头等着你送来的货箱。码头主管 Steamfizzle 指引你去找他，却声称自己对这批货物一无所知。他催你抓紧时间，并警告你别引起不必要的注意。这批货物来自爆破引线港，是否通过海关仍有疑问。"}},faq={{q="是谁让我送这个货箱？",a="码头主管 Steamfizzle 让你把 Friz’s Secret Stash 交给 Tazzik。",al={"谁派我来的","谁给了我包裹"}},{q="我要把 Friz’s Secret Stash 交给谁？",a="你要把 Friz’s Secret Stash 交给热砂港的 Tazzik。",al={"货箱要送到哪里","把货物交给谁"}},{q="Friz’s Secret Stash 是什么？",a="这是 Friz 送给 Tazzik 的一批货物。完成任务的文本称赞了它的品质。",al={"货箱里是什么","friz 的包裹"}},{q="这批货物来自哪里？",a="Tazzik 说他能从你身上闻出爆破引线港的气味。",al={"货箱的来源","爆破引线港的货物"}},{q="为什么 Steamfizzle 让我快点？",a="Steamfizzle 警告你别引起不必要的注意。",al={"为什么要快点","引起不必要的注意"}},{q="这批货物通过海关了吗？",a="Tazzik 说这批货物已经通过海关，但暗示 Friz 的钱可能有问题。",al={"通过海关了吗","这合法吗"}}},fp="21,141,11.327.0,38.73.0,45.72.0,30.79.0,33.48.0,38.54.0,36.99.0"}
P.entries["quest:95384"] = {n="Partial Mystical Notes",s="一张奇特的魔法卷轴上写满了你看不懂的符号，但你感觉不到其中有任何不稳定的力量。你把它带给藏宝海湾的 Dudd Fizzlescroll，他看出了其中魔法的潜力。",h="一张奇特的魔法卷轴上写满了你看不懂的符号，但你感觉不到其中有任何不稳定的力量。你把它带给藏宝海湾的 Dudd Fizzlescroll，他看出了其中魔法的潜力。",kw={"藏宝海湾","dudd fizzlescroll","魔法卷轴","神秘魔法","残缺的神秘笔记","残缺的卷轴","奇特符号"},sec={{t="未读符号",b="你发现了一张写满奇特符号的魔法卷轴，但你看不懂上面的文字。你感觉其中的魔法无害，便把这张残缺的卷轴带给藏宝海湾的 Dudd Fizzlescroll。他认出这是强大的魔法，打算将其译出并记录下来。"}},faq={{q="卷轴上写着什么？",a="这张魔法卷轴上写着奇特的符号，所用的语言你并不懂。",al={"符号是什么","卷轴文字","神秘笔记"}},{q="这张卷轴看起来危险吗？",a="你感觉不到卷轴中有任何特别不稳定的力量。",al={"是否不稳定","卷轴是否危险","安全的魔法"}},{q="谁想要这张卷轴？",a="藏宝海湾的 Dudd Fizzlescroll 认出了卷轴上的魔法，并打算将其译出并记录下来。",al={"谁来接收","dudd fizzlescroll","卷轴收集者"}},{q="我该把残卷带到哪里？",a="你把残卷带给了藏宝海湾的 Dudd Fizzlescroll。",al={"卷轴该带到哪里","藏宝海湾的卷轴","卷轴去向"}}},fp="22,180,14.261.0,22.72.0,31.60.0,21.105.0,36.63.0"}
P.entries["quest:95385"] = {n="Torn Mystical Scroll",s="一卷残破卷轴上留有微弱的魔法气息和陌生符文。你将它带给藏宝海湾的 Dudd Fizzlescroll，他从文字中看到了希望。",h="一卷残破卷轴上留有微弱的魔法气息和陌生符文。你将它带给藏宝海湾的 Dudd Fizzlescroll，他从文字中看到了希望。",kw={"藏宝海湾","dudd fizzlescroll","工程学","微弱的魔法","残缺的卷轴","符文","残破的神秘卷轴"},ang={["profession:Engineering"]="Dudd Fizzlescroll 打算把符文抄录到自己的作品中，并谈起成为传奇工程师的梦想。"},sec={{t="奇异的残页",b="微弱的魔法气息萦绕着这卷残破卷轴，符文对你而言十分陌生。你感觉它并无危险，尽管大多数人会觉得这张羊皮纸毫无用处。藏宝海湾的 Dudd Fizzlescroll 或许能派上这张残页的用场。"},{t="Dudd 的研究",b="Dudd Fizzlescroll 急切地想把符文抄录到自己的作品中。他谈起成为传奇工程师的梦想，随后提醒你离远些，以免受伤。"}},faq={{q="这卷残破卷轴是什么？",a="这是一张羊皮纸残片，上面留有微弱的魔法气息和陌生符文。你感觉它没有危险。",al={"残破卷轴","神秘卷轴","这是什么卷轴"}},{q="谁想要这卷卷轴？",a="藏宝海湾的 Dudd Fizzlescroll 对这卷残缺的卷轴很感兴趣。",al={"谁想要它","卷轴收藏者","dudd 卷轴"}},{q="为什么要把它带给 Dudd？",a="Dudd 或许能让羊皮纸上的陌生符文派上用场。",al={"为什么找 dudd","卷轴要送去哪","卷轴的用途"}},{q="这卷卷轴有危险吗？",a="卷轴散发着微弱的魔法气息，但你凭直觉觉得它没有危险。",al={"卷轴安全吗","危险的卷轴","它有魔法吗"}}},fp="20,139,15.208.0,11.157.1,24.104.0,21.67.0,21.62.0,24.74.0"}
P.entries["quest:954"] = {n="巴莎兰",s="盘踞在古老暗夜精灵城市巴莎兰的恶魔萨特和凶残格罗尔不敢靠近一座散发着诡异蓝色光芒的神龛。奥伯丁的长者桑德里斯·风织派遣冒险者前去调查这处未受侵扰的圣所的源头。",h="盘踞在古老暗夜精灵城市巴莎兰的恶魔萨特和凶残格罗尔不敢靠近一座散发着诡异蓝色光芒的神龛。奥伯丁的长者桑德里斯·风织派遣冒险者前去调查这处未受侵扰的圣所的源头。",kw={"阿斯特利安","巴莎兰","蓝色光芒","黑海岸","格罗尔","卡多雷遗迹","萨特","桑德里斯·风织"},ang={["faction:Alliance"]="奥伯丁的斥候依靠联盟的流浪者深入黑海岸的纷争遗迹，在恶魔威胁蔓延到海岸之前将其消灭。",["race:NightElf"]="巴莎兰是一个阴郁的提醒，让人想起在大分裂时期所失去的一切，那里你古老族人的残余阴影仍在孤独地守望，对抗着步步紧逼的恶魔腐化。"},sec={{t="废墟中的信标",b="巴莎兰曾是古老卡多雷帝国的一处辉煌定居点，但如今它那破碎的大理石和杂草丛生的拱门却充斥着恶魔的污染。扭曲的萨特和堕落的格罗尔贪婪地汲取着废墟中残留的魔法能量，它们的恶意与日俱增。然而尽管有这些掠夺者的统治，奥伯丁的桑德里斯·风织还是发现了一个奇特的现象：在废墟西侧的一处悬崖上，一座神龛闪耀着飘渺的蓝色光芒，没有任何恶魔敢靠近。"},{t="受伤的阴影",b="冒着恶魔巡逻队的危险来到高处的神龛，你会发现那蓝光并非自然现象。它源自阿斯特利安，一位在长达几个世纪的孤独守望中坚持至今的古老灵魂。这疲惫的阴影被咆哮的野兽和邪恶的魔物所包围，即使是一位路过的陌生人，对他而言也是从数十年的与世隔绝中获得的片刻慰藉。"}},faq={{q="蓝色光芒在哪里？",a="蓝色光芒在巴莎兰废墟西缘的一处高耸小悬崖上闪耀，就在黑海岸奥伯丁的东面。它位于周围坍塌墙壁的稍高处。",al={"寻找蓝色光芒","阿斯特利安在哪里","巴莎兰神龛位置"}},{q="为什么萨特要避开那座神龛？",a="目前无人知晓。一种奇怪的蓝色光芒笼罩着神龛，而那些盘踞在废墟中的恶魔萨特和格罗尔却不敢靠近。桑德里斯·风织派遣你去寻找这光芒的源头。",al={"为什么恶魔感到恐惧","为什么萨特避之不及"}},{q="谁派遣你进行这项任务？",a="桑德里斯·风织，一位奥伯丁的暗夜精灵德鲁伊和长者。他在观察到东部废墟内不正常的恶魔活动后提供了这个任务。",al={"谁给予任务","任务发布者","桑德里斯·风织的位置"}},{q="巴莎兰是什么？",a="巴莎兰是一处坐落在黑海岸森林中的古老卡多雷遗迹。它在古老的大分裂时期被洗劫，如今已沦为魔法寄生虫、格罗尔和试图蚕食其沉睡的能量之线的萨特的温床。",al={"巴莎兰发生了什么","巴莎兰的历史"}}},fp="11,161,21.382.0,17.245.1,31.192.0,35.147.0,28.136.0,20.171.0"}
P.entries["quest:95417"] = {n="The Purple Ones",s="Clubtoe请你去阳光林地下方的洞穴寻找失踪的食人魔。有些食人魔回来后变了样，他想弄清原因。",h="Clubtoe请你去阳光林地下方的洞穴寻找失踪的食人魔。有些食人魔回来后变了样，他想弄清原因。",kw={"洞穴","clubtoe","黑暗符文","失踪的食人魔","食人魔","紫色","阳光林地","紫色的那些家伙","暮光之锤"},sec={{t="Clubtoe的忧虑",b="Clubtoe眼看着朋友们进入阳光林地下方的洞穴，却再也没有回来。有些食人魔回来了，浑身发紫，举止也不像他的朋友了。他请你去洞穴里寻找失踪的食人魔，却担心你也会变成那样。"},{t="洞穴之中",b="在阳光林地下方，你发现一具食人魔的尸体，周围刻着黑暗符文。暮光之锤仪式的力量已经压垮了他。"}},faq={{q="Clubtoe是谁？",a="Clubtoe是一名食人魔，他的朋友在阳光林地下方的洞穴里失踪了。",al={"clubtoe","clubtoe是谁"}},{q="Clubtoe为什么请我去洞穴里寻找？",a="Clubtoe的一些朋友进入洞穴后没有回来，还有一些回来后浑身发紫，举止也变了。",al={"失踪的食人魔","寻找clubtoe的朋友","洞穴食人魔"}},{q="失踪的食人魔在哪里？",a="Clubtoe请你去阳光林地下方的洞穴寻找失踪的食人魔。",al={"食人魔去了哪里","阳光林地洞穴","食人魔失踪"}},{q="回来的食人魔有什么奇怪之处？",a="有些食人魔回来后浑身发紫，举止也不像Clubtoe的朋友了。",al={"紫色食人魔","为什么变紫","食人魔举止异常"}}},fp="15,138,17.245.0,12.124.1,15.83.0,44.110.0,28.79.0,43.60.0"}
P.entries["quest:95418"] = {n="Spread the Word",s="Clubtoe请你在Chogg'Zac离开暮光之锤后，将他的头颅带给洛格玛的Tran'gul。叛逃的消息或许能让更多邪教食人魔挣脱束缚。",h="Clubtoe请你在Chogg'Zac离开暮光之锤后，将他的头颅带给洛格玛的Tran'gul。叛逃的消息或许能让更多邪教食人魔挣脱束缚。",kw={"chogg'zac","clubtoe","clugfist","食人魔叛离","洛格玛","传开消息","tran'gul","暮光之锤"},sec={{t="给Tran'gul的消息",b="Chogg'Zac的头颅要送回给你的朋友，而洛格玛的Tran'gul负责接收。Clubtoe说，他已经受够了暮光之锤，打算加入Clugfist——他所知道的最强壮的食人魔，许多其他食人魔也会同行。Clubtoe打算留在原地，直到安全为止。现在，Tran'gul必须得知Clubtoe做出了什么选择。"},{t="洞穴传来的消息",b="Tran'gul得知洞穴里还有另一个意外。你已经说服一名暮光之锤食人魔叛离，他还提到了其他同类。Tran'gul说，他们必须立刻根据这条消息采取行动。"}},faq={{q="Clubtoe是谁？",a="Clubtoe是一名食人魔。他说自己受够了暮光之锤，打算投奔自由的食人魔。",al={"clubtoe","clubtoe食人魔","clubtoe是谁"}},{q="Clugfist是谁？",a="Clugfist是Clubtoe所认识的最强壮的食人魔。Clubtoe说，他带着许多朋友离开了暮光之锤。",al={"clugfist","clugfist食人魔","最强壮的食人魔"}},{q="Clubtoe要我带什么？",a="Clubtoe要你把Chogg'Zac的头颅带回去交给他的同伴。",al={"chogg的头颅","chogg'zac的头颅","要带什么"}},{q="我该把Chogg'Zac的头颅带到哪里？",a="你要把Chogg'Zac的头颅交给洛格玛的Tran'gul。",al={"把头颅带到哪里","tran'gul","洛格玛"}},{q="Tran'gul为何忧心？",a="Tran'gul得知一名暮光之锤食人魔已经叛离，还提到了其他同类。",al={"tran'gul的反应","暮光洞穴","为何立即行动"}}},fp="15,178,22.329.0,18.202.1,15.99.0,16.109.0,34.62.0,33.59.0,26.94.0"}
P.entries["quest:95420"] = {n="Land of Giants",s="一名兽人请你把 Chogg 的头颅送到北方群山中的食人魔城市。这份贡品或许能为重续与食人魔的旧日盟约打开一条路。",h="一名兽人请你把 Chogg 的头颅送到北方群山中的食人魔城市。这份贡品或许能为重续与食人魔的旧日盟约打开一条路。",kw={"chogg","chogg’zac","clugfist","land of giants","北方群山","食人魔城市","食人魔","兽人联盟"},ang={["race:Orc"]="作为一名兽人，你带来了一份提议，它源自兽人与食人魔并肩作战的荣耀历史。"},sec={{t="旧日盟约",b="兽人看到了重续与食人魔旧日盟约的机会。据传，这个氏族的家园位于北方群山中的一座要塞，Chogg 的头颅将替你开口。把它带到食人魔城市，作为友谊的信物献上。如果他们没有先把你踩扁，这个氏族或许会听听你的提议。"},{t="Clugfist 门前",b="在食人魔城市，你把 Chogg 的头颅献给了 Clugfist。他认出你击败了 Chogg’Zac，并问你找他有什么事。友谊的提议为你争取到了与氏族首领交谈的机会。"}},faq={{q="我为什么要把 Chogg 的头颅带给食人魔？",a="兽人希望 Chogg 的头颅能成为友谊的信物，帮助他们重续与食人魔的旧日盟约。",al={"chogg 头颅","为何带走 chogg 头颅","食人魔头颅贡品"}},{q="食人魔氏族的家园在哪里？",a="据传，这个氏族的要塞位于遥远北方的群山中。",al={"食人魔城市位置","食人魔在哪里","北方群山的食人魔"}},{q="Clugfist 是谁？",a="Clugfist 是你在食人魔城市遇到的巨大食人魔。他问你找他有什么事。",al={"clugfist 是谁","食人魔首领","clug fist"}},{q="Chogg’Zac 是谁？",a="Clugfist 说，Chogg’Zac 是你击败的食人魔。",al={"chogg zac","chogg 背景故事","谁是 chogg"}},{q="兽人想从食人魔那里得到什么？",a="兽人希望借助与食人魔的旧日盟约，向这个氏族提出一项提议。",al={"兽人与食人魔的联盟","兽人想要什么","与食人魔交好"}}},fp="14,143,11.313.0,20.218.1,46.114.0,32.68.0,16.87.0,19.56.0,37.92.0"}
P.entries["quest:95424"] = {n="Might Makes Right",s="Clugfist要你在Bolder'ok证明自己的力量。暮光之锤食人魔就是考验。",h="Clugfist要你在Bolder'ok证明自己的力量。暮光之锤食人魔就是考验。",kw={"bolder'ok","clugfist","强者为尊","食人魔","天翔者","暮光火焰召唤者","暮光碾压者","暮光之锤"},sec={{t="Clugfist的考验",b="Clugfist以鲜血衡量力量，派你去对付Bolder'ok的Twilight Maulers和Twilight Firecallers。他怀疑你身材矮小，却给你机会展示本领。这场挑战要用你的力量对抗暮光食人魔。"}},faq={{q="Clugfist是谁？",a="Clugfist是Bolder'ok的一名食人魔，他要你证明自己的力量。",al={"clugfist","clugfist是谁","食人魔"}},{q="Clugfist要我做什么？",a="Clugfist要你在Bolder'ok击杀Twilight Maulers和Twilight Firecallers。",al={"clugfist想要什么","clugfist的任务","要杀什么"}},{q="Clugfist为什么怀疑我？",a="Clugfist说你太矮小，还质疑你是否有力量。",al={"为何怀疑我","太矮小","clugfist觉得我弱"}},{q="Bolder'ok是什么样的地方？",a="Clugfist说，Bolder'ok的食人魔看重力量和鲜血。",al={"bolder'ok","bolder'ok食人魔","这里会发生什么"}}},fp="17,98,15.248.0,16.76.0,33.81.0,27.61.0,23.64.0"}
P.entries["quest:95425"] = {n="Unworthy Champion",s="Bolder'ok的Clugfist要你从Klunk手中夺回Skullbasher。他不再认为Klunk配得上这件武器。",h="Bolder'ok的Clugfist要你从Klunk手中夺回Skullbasher。他不再认为Klunk配得上这件武器。",kw={"bolder'ok","洞穴","clugfist","klunk","食人魔冠军","skullbasher","暮光之锤"},sec={{t="Clugfist的要求",b="Clugfist派你去找Klunk。Klunk离开了Bolder'ok，带着食人魔去了水域东边的一处洞穴。Clugfist想要回自己的武器，称Klunk软弱。在Clugfist眼中，Skullbasher是冠军的象征，他打算另选一人。"}},faq={{q="Klunk是谁？",a="Klunk曾是Clugfist的冠军，但Clugfist如今称他软弱。",al={"klunk是谁","klunk的背景"}},{q="Clugfist是谁？",a="Clugfist是给了Klunk一件强大武器、如今又想要回它的食人魔。",al={"clugfist是谁","clugfist 食人魔"}},{q="Clugfist为什么想要Skullbasher？",a="Clugfist说Skullbasher属于他，还称Klunk配不上这件武器。",al={"为何夺回skullbasher","clugfist的武器"}},{q="Klunk去了哪里？",a="Klunk带着食人魔离开Bolder'ok，去了水域东边的一处洞穴。",al={"klunk的位置","klunk去了哪里"}},{q="Skullbasher是什么？",a="Skullbasher是Clugfist给Klunk的强大武器。",al={"skullbasher 武器","klunk的武器"}},{q="Clugfist接下来打算做什么？",a="Clugfist说，总有一天他会选出一位新冠军。",al={"新冠军","clugfist的计划"}}},fp="17,117,17.240.0,13.68.0,16.74.0,35.72.0,19.69.0,20.53.0,35.52.0"}
P.entries["quest:95426"] = {n="Rog'mar Supplies",s="一名当地联络人请求你截走从北面训练场运出的补给，以此阻挠洛格玛。补给延误可能会让部落部队战备不足。",h="一名当地联络人请求你截走从北面训练场运出的补给，以此阻挠洛格玛。补给延误可能会让部落部队战备不足。",kw={"部落","洛格玛","货运物资","补给物资","补给运输","训练营"},sec={{t="补给短缺",b="洛格玛附近的一名联系人看到了拖慢兽人发展的机会。你受命从洛格玛北面的训练场夺走他们的补给物资。这里的补给运输十分困难，劫走物资是为了拖延部落的战备。"}},faq={{q="我需要做什么？",a="你受命从洛格玛北面的训练营夺走部落的补给物资。",al={"洛格玛补给","劫走物资","劫掠补给"}},{q="为什么要夺走补给？",a="劫走物资是为了拖慢洛格玛的发展，并让部落军队无法做好充分的战斗准备。",al={"为何劫走补给","拖慢洛格玛","部落补给"}},{q="补给物资在哪里？",a="部落的补给物资在洛格玛北面的训练营。",al={"补给在哪里","训练营","洛格玛以北"}}},fp="16,167,17.258.0,28.86.0,22.101.0,24.70.0"}
P.entries["quest:95427"] = {n="Twilight No More!",s="Clubtoe让你去阳光林地的洞穴中对付Chogg'Zac。他指责他们害死了自己的朋友，还违背了让食人魔变强的承诺。",h="Clubtoe让你去阳光林地的洞穴中对付Chogg'Zac。他指责他们害死了自己的朋友，还违背了让食人魔变强的承诺。",kw={"洞穴","chogg'zac","clubtoe","朋友","食人魔","阳光林地","暮光"},sec={{t="Clubtoe的恳求",b="Clubtoe说他的朋友都死了，并把责任归咎于Chogg'Zac。他们曾承诺让食人魔变强，但他认为他们撒了谎。于是，他请你帮他在阳光林地的洞穴中反抗他们。他想要他们的头颅，也不愿再为他们砸石头。"},{t="一个新名字",b="Chogg'Zac死后，Clubtoe欢呼雀跃。他说自己再也不会为小个子砸石头，也再不会失去朋友。他宣布自己不再是暮光。"}},faq={{q="Clubtoe是谁？",a="Clubtoe是一名食人魔。他说Chogg'Zac曾承诺让食人魔变强，并指责他们害死了自己的朋友。",al={"clubtoe","clubtoe是谁","clubtoe的背景"}},{q="Clubtoe为什么想杀死Chogg'Zac？",a="Clubtoe说Chogg'Zac在让食人魔变强这件事上撒了谎，还指责他们害死了自己的朋友。",al={"为什么杀chogg'zac","chogg zac的缘由","chogg'zac任务"}},{q="Chogg'Zac在哪里？",a="Chogg'Zac在阳光林地的洞穴中。",al={"chogg'zac的位置","chogg zac在哪里","阳光林地洞穴"}},{q="Clubtoe想让你做什么？",a="Clubtoe请你杀死Chogg'Zac，并收集他们的头颅。",al={"clubtoe想要什么","为clubtoe拿什么","clubtoe的头颅"}}},fp="17,141,14.247.0,10.155.1,15.108.0,37.94.0,20.37.0,32.59.0"}
P.entries["quest:95428"] = {n="Clugfist's Decree",s="Skyborne击败暮光之锤后，Clugfist暂时准许你留在Bolder'ok。他要你告诉其他族人，氏族很快就会再次开战。",h="Skyborne击败暮光之锤后，Clugfist暂时准许你留在Bolder'ok。他要你告诉其他族人，氏族很快就会再次开战。",kw={"bolder'ok","bolderok","clugfist","命令","部落","krom'rosh","洛格玛","skyborne","暮光之锤"},ang={["faction:Horde"]="作为部落的一员，如果你的族人继续赢得Bolder'ok人的信任，他们就可能成为强大的盟友。"},sec={{t="给洛格玛的消息",b="洛格玛的Krom'rosh正等着你的消息。Clugfist暂时准许你留在Bolder'ok，并让你把消息带给其他Skyborne。氏族预计很快就会再次厮杀。"},{t="信任与同盟",b="Krom'rosh认为，Bolder'ok氏族有望成为部落的盟友。他们最近为摆脱暮光之锤、争取自由而战，这让人想起部落自身血腥的历史。你的报告或许能帮助部落继续赢得他们的信任。"}},faq={{q="Clugfist要我做什么？",a="Clugfist要你告诉其他Skyborne，Bolder'ok氏族预计很快就会再次开战。",al={"clugfist的命令","我该报告什么","clugfist的指示"}},{q="我该去哪里报告？",a="Clugfist让你去洛格玛向Krom'rosh报告。",al={"向kromrosh报告","krom'rosh在哪里","rogmar报告"}},{q="我能留在Bolder'ok吗？",a="Clugfist暂时准许你留在Bolder'ok。",al={"留在bolderok","clugfist准我留下","bolder'ok许可"}},{q="Bolder'ok人是什么人？",a="Bolder'ok人是一个最近为争取自由、摆脱暮光之锤而战的氏族。",al={"bolderok氏族","clugfist是谁","clugfist的人"}},{q="部落为何关心Bolder'ok人？",a="Krom'rosh认为，如果部落继续赢得他们的信任，Bolder'ok人就可能成为强大的盟友。",al={"部落与bolderok","bolderok盟友","kromrosh为何关心"}}},fp="17,168,16.182.0,19.225.1,33.97.0,18.55.0,24.52.0,22.85.0,44.105.0"}
P.entries["quest:95431"] = {n="Rumblings of Discontent",s="一名斥候请你去此地以西的洞穴寻找一名Bolder'ok战士。食人魔异见者渴望获得Bolder'ok族人已经争取到的自由。",h="一名斥候请你去此地以西的洞穴寻找一名Bolder'ok战士。食人魔异见者渴望获得Bolder'ok族人已经争取到的自由。",kw={"bolder'ok","clugfist","crag'rog","自由","食人魔异见者","不满的暗流"},sec={{t="斥候的请求",b="一名斥候发现，食人魔中有些异见者渴望获得Bolder'ok族人享有的自由。斥候听闻了你的事迹，请你去此地以西的洞穴寻找一名Bolder'ok战士，并协助他召集族人。"},{t="熟悉的名字",b="在洞穴里，Bolder'ok战士Crag'rog认出你是Clugfist的战士。"}},faq={{q="我要找谁？",a="斥候以西不远处的洞穴里有一名Bolder'ok战士。",al={"bolder'ok战士","洞穴里的食人魔"}},{q="为什么要派我去找他？",a="斥候请你协助这名战士，召集那些渴望自由的食人魔。",al={"为何寻找bolder'ok","斥候的请求"}},{q="Crag'rog是谁？",a="Crag'rog是洞穴里的Bolder'ok战士。",al={"crag'rog","crag'rog是谁"}},{q="食人魔异见者想要什么？",a="异见者渴望获得与Bolder'ok族人相同的自由。",al={"食人魔叛乱者","bolder'ok的自由"}}},fp="23,133,17.236.0,15.85.1,21.58.0,32.83.0,16.46.0,33.60.0"}
P.entries["quest:95432"] = {n="Rise Up!",s="Crag'rog请你帮忙解救暮光势力的食人魔。他想让他们回家喝炖肉汤。",h="Crag'rog请你帮忙解救暮光势力的食人魔。他想让他们回家喝炖肉汤。",kw={"crag'rog","解救食人魔","食人魔矿工","食人魔","奋起反抗","炖肉汤","暮光"},sec={{t="食人魔与暮光",b="Crag'rog想解救暮光势力的食人魔，也欢迎你伸出援手。你们一起招募食人魔矿工加入战斗。Crag'rog说，之后食人魔就能回家喝炖肉汤了。"},{t="Crag'rog的清点",b="Crag'rog说，许多食人魔已经获得自由，弱小怯懦的食人魔也都死了。他数来数去，只剩一个怯懦的食人魔。"}},faq={{q="Crag'rog是谁？",a="Crag'rog是一名食人魔，他想解救暮光势力的食人魔。",al={"crag'rog","crag'rog是谁"}},{q="Crag'rog为什么想解救食人魔？",a="他听说你在解救食人魔，现在他也想解救他们。",al={"为何解救食人魔","食人魔获得自由"}},{q="Crag'rog与谁并肩作战？",a="Crag'rog与你并肩对抗暮光势力。",al={"谁帮助crag'rog","小型职业"}},{q="Crag'rog请你招募什么？",a="Crag'rog请你招募食人魔矿工。",al={"招募食人魔","食人魔矿工"}},{q="Crag'rog后来对食人魔说了什么？",a="Crag'rog说，许多食人魔已经获得自由，只剩一个怯懦的食人魔。",al={"食人魔的遭遇","crag'rog任务完成"}}},fp="8,89,18.176.0,16.112.1,16.60.0,37.67.0,34.43.0,38.41.0,49.70.0"}
P.entries["quest:95433"] = {n="Death to the Executioner",s="Clugfist要你迎战守住暮光出口的食人魔Morg。他希望你把Morg的钉头锤带回给Bolder’ok。",h="Clugfist要你迎战守住暮光出口的食人魔Morg。他希望你把Morg的钉头锤带回给Bolder’ok。",kw={"bolder’ok","clugfist","crag’rog","行刑者morg","executioner’s mace","morg","暮光 shroud","暮光之锤"},ang={["race:Tauren"]="作为一名牛头人，Clugfist在Morg死后称你为“满肚子花招的小牛头人”。"},sec={{t="一条出路",b="在Bolder’ok的Clugfist要你去暮光 Shroud迎战Morg。这个行刑者是个食人魔，几乎和Clugfist一样高大。Clugfist说，他依靠较小的同伴保护自己。把钉头锤带回给他，暮光之锤就会知道，食人魔不会再挑战他们。"},{t="Bolder’ok的回应",b="Crag’rog说你已加入他的战斗，Clugfist则问你带回了什么。Morg死了，Clugfist称赞了你的花招。他说暮光之锤已在Bolder’ok的力量面前溃败，食人魔自由了。"}},faq={{q="Morg是谁？",a="Morg是暮光 Shroud的一名行刑者，是个几乎和Clugfist一样高大的食人魔。",al={"morg是谁","行刑者morg","暮光食人魔"}},{q="Clugfist为什么要Morg死？",a="Clugfist说，Morg挡住了他离开暮光的路，而且依靠较小的同伴保护自己。",al={"为何杀死morg","clugfist要morg","morg带来的麻烦"}},{q="Clugfist想让你带回什么？",a="Clugfist要你把Morg的Executioner’s Mace带回给他，交到Bolder’ok。",al={"morg的钉头锤","要带回什么","executioner’s mace"}},{q="Morg在哪里？",a="Morg在暮光 Shroud。",al={"morg的位置","行刑者在哪里","暮光 shroud"}}},fp="24,122,9.288.0,22.227.1,12.83.0,33.114.0,42.76.0,14.31.0"}
P.entries["quest:95454"] = {n="The Honor of the Kor'kron",s="Folkar指挥官麾下的库卡隆奉命前往Alcaz Prison，活捉瓦里安·乌瑞恩。指挥官受伤，精锐部队也已阵亡，搜索任务落到了你肩上。",h="Folkar指挥官麾下的库卡隆奉命前往Alcaz Prison，活捉瓦里安·乌瑞恩。指挥官受伤，精锐部队也已阵亡，搜索任务落到了你肩上。",kw={"alcaz prison","黑龙","folkar指挥官","荣誉","库卡隆","奥格瑞玛","瓦里安·乌瑞恩"},ang={["faction:Horde"]="身为部落的一员，你奉命将瓦里安·乌瑞恩活着带到奥格瑞玛。"},sec={{t="Alcaz的国王",b="库卡隆来到Alcaz Prison，寻找暴风城之王瓦里安·乌瑞恩。大酋长命令他们将他活着带到奥格瑞玛。如今，他们的指挥官持斧的手臂已断，大部分精锐部队也已阵亡。你接手搜索，指挥官则留在后方。"},{t="搜寻",b="黑龙让库卡隆寻找瓦里安的行动变得更加棘手。你击杀一条较弱的龙后，发现似乎有更强大的力量在幕后操纵。是时候把你的发现告诉Folkar指挥官了。"}},faq={{q="库卡隆为何会在Alcaz Prison？",a="他们奉大酋长之命前来寻找瓦里安·乌瑞恩，并将他活着带到奥格瑞玛。",al={"alcaz的库卡隆","他们为何在此"}},{q="库卡隆在寻找谁？",a="他们正在Alcaz Prison搜寻暴风城之王瓦里安·乌瑞恩。",al={"搜寻瓦里安","他们在找谁"}},{q="为什么搜索任务落到了我肩上？",a="指挥官持斧的手臂已断，他的大部分精锐部队也已阵亡，因此他请你继续搜寻。",al={"指挥官受伤","库卡隆精锐"}},{q="什么让库卡隆的搜寻变得棘手？",a="黑龙的出现让他们寻找瓦里安的行动变得更加棘手。",al={"alcaz黑龙","巨龙威胁"}}},fp="25,161,15.258.0,10.201.1,39.99.0,35.68.0,31.108.0,43.70.0"}
P.entries["quest:95472"] = {n="Consolation Prize",s="Tazzik请你把他的汗湿衬衣带给爆破引线港的Friz Frazzlespark。Friz还没收到欠款，而这件衬衣是Tazzik仅剩的东西。",h="Tazzik请你把他的汗湿衬衣带给爆破引线港的Friz Frazzlespark。Friz还没收到欠款，而这件衬衣是Tazzik仅剩的东西。",kw={"安慰奖","friz frazzlespark","还款","爆破引线港","利润","汗湿衬衣","tazzik"},sec={{t="给Friz的衬衣",b="Tazzik许下的承诺让他只剩下一件衬衣。在爆破引线港，Friz Frazzlespark正等着你把衬衣带给他。Tazzik无力偿还Friz，这件衬衣是他唯一能拿出来的东西。"},{t="Friz的那份",b="你把衬衣交给Friz时，他愤怒不已。他把衬衣踩进地里，随后提出分给你一份利润，还坚持让你收下。"}},faq={{q="Tazzik为什么要交出衬衣？",a="Tazzik说他无力偿还Friz，身边只剩下这件衬衣。",al={"tazzik的衬衣","为什么给衬衣","汗湿衬衣"}},{q="Friz Frazzlespark是谁？",a="Tazzik欠Friz Frazzlespark钱。",al={"friz是谁","friz","friz那个人"}},{q="我该把Tazzik的衬衣带到哪里？",a="把Tazzik's Sweaty Shirt带给爆破引线港的Friz Frazzlespark。",al={"衬衣在哪","带去给friz","爆破引线港衬衣"}},{q="Friz对这件衬衣怎么说？",a="得知事情经过后，Friz难以置信。",al={"friz的反应","friz说什么","衬衣的回应"}},{q="Friz会给我什么？",a="Friz提出分给你一份利润，并说这份就是你的。",al={"friz还钱","我的那份","利润"}}},fp="17,149,16.192.0,12.145.1,34.71.0,25.50.0,31.68.0,35.56.0,24.60.0"}
P.entries["quest:95483"] = {n="Thrall Needs to Know",s="萨尔需要你将瓦里安·乌瑞恩在奥格瑞玛的命运带给他。这则消息关系到部落在艾泽拉斯的地位。",h="萨尔需要你将瓦里安·乌瑞恩在奥格瑞玛的命运带给他。这则消息关系到部落在艾泽拉斯的地位。",kw={"folkar","部落","库卡隆","奥格瑞玛","萨尔","ulka","瓦里安·乌瑞恩","大酋长"},ang={["faction:Horde"]="身为部落的一员，你将消息带给萨尔。他说，这条消息有助于巩固部落在艾泽拉斯各地的势力。"},sec={{t="带给萨尔的消息",b="指挥官 Folkar 请你代他将消息带给奥格瑞玛的萨尔。确认 Ulka 适合旅行后，他会返回那里。你受命将瓦里安·乌瑞恩的遭遇告知大酋长。"},{t="大酋长的答复",b="萨尔得知 Folkar 的库卡隆大多在为他传递消息时阵亡。他说，部落会利用这条情报巩固自己在艾泽拉斯各地的势力。他并不庆祝瓦里安的离世，但他认为，任何削弱联盟的事都对部落有利。"}},faq={{q="萨尔需要知道什么？",a="萨尔需要得知瓦里安·乌瑞恩的命运。",al={"萨尔需要知道","瓦里安发生了什么","瓦里安的命运"}},{q="我该把消息带到哪里？",a="你要把消息带给奥格瑞玛的萨尔。",al={"萨尔在哪里","把消息带给萨尔","奥格瑞玛萨尔"}},{q="是谁让我传递消息？",a="指挥官 Folkar 请你代他将情报带给萨尔。他称你为部落的战士。",al={"是谁派我来的","谁要传递消息","这名战士"}},{q="为什么这名战士要返回奥格瑞玛？",a="Folkar 会先与 Ulka 会合，确认他适合旅行，然后才返回奥格瑞玛。",al={"关于 ulka","战士为何耽搁","ulka 旅行"}},{q="萨尔如何看待库卡隆？",a="萨尔说，Folkar 的库卡隆大多在为他传递情报时阵亡。",al={"folkar 的库卡隆","库卡隆的损失","库卡隆遭遇了什么"}},{q="部落会如何利用这条情报？",a="萨尔说，部落会利用这条情报巩固自己在艾泽拉斯各地的势力。",al={"部落的计划","巩固势力","萨尔会怎么做"}}},fp="20,132,15.193.0,20.287.1,30.41.0,26.49.0,30.111.0,42.108.0,40.83.0,39.88.0"}
P.entries["quest:95494"] = {n="Bruised Pride and Lion Hides",s="“Bruised Pride and Lion Hides”是一项任务，旨在帮助一位受伤的猎人或商人，他们需要生狮皮来满足与当地制革匠的贸易协议。由于受伤无法安全进行狩猎，他们只能依靠路过的冒险者来递送材料，以维持自己完美的职业记录。",h="“Bruised Pride and Lion...",kw={"受挫的骄傲与狮皮","狩猎","皮具","狮皮","制革匠","贸易"},sec={{t="猎人的困境",b="“Bruised Pride and Lion Hides”需要帮助一位受伤的猎人，由于最近受到身体伤害，他无法追踪野兽。为了避免未能履行与附近工匠达成的贸易协议，他们雇佣了一位冒险者来追踪野狮并收集它们的毛皮。"},{t="履行契约",b="收集到的生皮会与当地制革匠交换任务发布者生计所需的成品皮质装备。尽管受了伤，且因为需要外界帮助而感到自尊心受挫，但履行这项契约确保了他们的职业声誉不会受损。"}},faq={{q="这个任务是关于什么的？",a="狮皮是为一位受伤的猎人或商人收集的，他会向当地制革匠供应原材料。作为交换，任务发布者会收到其生计所必需的成品皮具。",al={"受挫的自尊与狮皮是什么","任务目标","狮皮的用途"}},{q="为什么任务发布者需要帮助来收集毛皮？",a="任务发布者受了伤，无法亲自猎狮。为了不破坏与当地制革匠长期以来的业务协议，他们依靠冒险者来完成交付。",al={"为什么需要帮助","为什么不能狩猎"}},{q="谁会收到狮皮？",a="生皮会被交易给当地的制革匠。制革匠将它们加工成任务发布者日常贸易和工作所需的成品皮具。",al={"谁得到狮皮","毛皮去向"}},{q="“受挫的自尊与狮皮”这个名字是什么意思？",a="这个标题用了双关语：既指必须被狩猎的狮群（狮子群），也指受伤猎人的个人自尊心（自尊），因为尽管目前身体受限，他们从未在履行合同时失信。",al={"受挫的自尊的含义","为什么叫受挫的自尊"}},{q="与制革匠的协议是否处于危险之中？",a="是的。受伤使任务发布者无法狩猎，导致下一次交付面临风险。收集狮皮让他们能够履行协议，而不会违约。",al={"制革匠的协议是否成立","贸易协议破裂"}},{q="任务发布者是怎么受伤的？",a="任务发布者遭受了伤痛，导致其无法在野外猎狮，但受伤的具体原因并未详述。递送毛皮让他们得以保住自己的声誉。",al={"任务发布者受伤","猎人发生了什么"}}},fp="28,174,18.195.0,24.236.0,25.157.0,51.130.0,28.128.0,55.170.0,44.136.0,32.171.0"}
P.entries["quest:95495"] = {n="The Hermit Tanner",s="“The Hermit Tanner”是贫瘠之地的一项本地运送任务，冒险者需要将一捆兽皮送到一位居住在无水岭上方山脊的隐居工匠手中。该任务展现了这片大草原上偏远地区的商业合作，并介绍了一位虽然与世隔绝但仍保持定期贸易的奇特隐士。",h="“The Hermit...",kw={"贫瘠之地","一捆兽皮","无水岭","隐士剥皮师","山脊","剥皮师","弗朗"},ang={["faction:Horde"]="穿越中部大草原的旅行者经常协助像Vrang这样的当地商人，在贫瘠之地崎岖的地形中运送必要的贸易物资。"},sec={{t="贫瘠之地的一座山脊",b="贫瘠之地的崎岖大草原促进了坚韧的居民之间的贸易，不过并非所有的工匠都喜欢在十字路口或定居点那种喧闹的环境中工作。在无水岭的阴影下，一位名叫Vrang的商人经常与一位隐居的剥皮师交换货物，这位剥皮师在俯瞰山脊的上方建立了一个安静的宅基地。由于沿着岩石山坡陡峭的攀爬对Vrang来说过于吃力，他只能依靠路过的冒险者将一捆捆生皮运送给他那位隐居的合作伙伴。"},{t="一位不寻常的工匠",b="在打发旅行者上路之前，Vrang特意对这位隐居的工匠提出了特别警告。这位隐士有着令人惊恐且不同寻常的外表，可能会让毫无准备的访客感到吃惊，但Vrang坚称这位隐居的剥皮师对客人毫无威胁。当隐士在山脊上的住所收到生皮后，他会热情地欢迎送信人，但他同时也感叹Vrang没能亲自爬上来，因为他还有一件事情希望能与那位商人当面商讨。"}},faq={{q="谁让你去进行这项送货任务的？",a="一位名叫弗朗的商人安排了这项任务，他请求路过的旅行者将一捆生皮送到位于上方山脊的商业伙伴那里。",al={"谁发布了隐士剥皮师任务","任务起始地点","弗朗的运送任务"}},{q="隐居的剥皮师住在哪里？",a="隐居的剥皮师独自居住在贫瘠之地无水岭上方的一座高耸山脊的偏僻宅基地里。",al={"隐士剥皮师位置","隐士剥皮师在哪里","山脊上的隐士"}},{q="为什么弗朗要警告你关于剥皮师的外貌？",a="弗朗预先警告旅行者不要被剥皮师不寻常或令人不安的外表所惊吓，并保证尽管他看起来很吓人，但这位隐士对访客并不构成威胁。",al={"隐士外貌","为什么隐士看起来很可怕","隐士长相"}},{q="为什么弗朗自己不能爬上去？",a="弗朗解释说，沿着崎岖的山坡陡峭攀爬对他来说不是一件轻松的事，因此他只能雇用送信人代劳。",al={"为什么需要运送","为什么弗朗无法亲自前往"}},{q="运送到山脊上的物品是什么？",a="运送的物品是一捆用于剥皮师生意的兽皮，这是两人经常合作的一项工艺。",al={"什么是一捆兽皮","运送的任务物品"}},{q="隐居的剥皮师想和弗朗商讨什么？",a="在收到货物后，剥皮师表达了对弗朗未能亲自攀登上来而感到遗憾，并提到有一件事他需要与弗朗直接沟通。",al={"剥皮师想和弗朗商讨什么","剥皮师与弗朗的生意"}}},fp="17,169,22.210.0,27.293.0,31.100.0,34.108.0,54.122.0,42.107.0,44.89.0,55.101.0"}
P.entries["quest:955"] = {n="巴莎兰",s="阿斯特利安，一位在巴莎兰古代废墟中徘徊的悲伤上层精灵幽灵，正在寻找解除束缚他灵魂形式的封印魔法的方法。他认为当地顽皮的劣魔触碰过禁锢他的封印，因此委托旅行者收集它们的耳环，以便追踪上面残留的魔法共鸣。",h="阿斯特利安，一位在巴莎兰古代废墟中徘徊的悲伤上层精灵幽灵，正在寻找解除束缚他灵魂形式的封印魔法的方法。他认为当地顽皮的劣魔触碰过禁锢他的封印，因此委托旅行者收集它们的耳环，以便追踪上面残留的魔法共鸣。",kw={"阿斯特利安","巴莎兰","束缚","黑海岸","幽灵","劣魔","劣魔耳环","封印"},ang={["class:Mage"]="阿斯特利安利用附魔饰品追踪残留魔法波动的手段，反映了上层精灵古代奥术占卜的习俗。",["faction:Alliance"]="清理巴莎兰周围混乱的劣魔，有助于平定黑海岸北部充满危险的地区，为联盟的利益提供保障。",["race:NightElf"]="对于卡多雷来说，遇见阿斯特利安是一个发人深省的提醒，让他们意识到在大分裂期间陨落的古老文明，留下了这些被困在废墟中数千年的受苦灵魂。"},sec={{t="数百年的折磨",b="在巴莎兰破碎的大理石建筑间徘徊着阿斯特利安，一位承受了数百年禁锢之苦的古代暗夜精灵灵魂。他被困在生与真正死亡之间，在黑海岸的树冠下过着痛苦的等待。由于被奥术技艺直接束缚在这片废墟聚落中，阿斯特利安无法独自打破枷锁，无尽的孤独与绝望让他心力交瘁。"},{t="荒野中的踪迹",b="阿斯特利安怀疑，他获得解脱的关键是隐藏在废墟某处的一道古老封印。虽然他无法亲自搜寻灌木丛和坍塌的石块，但盘踞在巴莎兰的野蛮劣魔经常会搜寻并偷走一些小饰品。阿斯特利安请求旅行者收集这些生物佩戴的耳环，打算通过解读饰品上残留的魔法印记，来定位禁锢他灵魂的封印。"}},faq={{q="阿斯特利安是谁？",a="阿斯特利安是一位古代暗夜精灵幽灵，被束缚在黑海岸的巴莎兰废墟中。他被一道神秘的封印困住了数百年，在痛苦中看着时光流逝，渴望从这种幽灵状态中解脱出来。",al={"阿斯特利安背景故事","谁是巴莎兰的幽灵","阿斯特利安任务发布者"}},{q="为什么阿斯特利安想要劣魔耳环？",a="劣魔是臭名昭著的拾荒者，喜欢囤积闪亮的饰品和珠宝。阿斯特利安认为这些生物触碰过禁锢他的魔法封印，这意味着它们佩戴的耳环可能带有足够的魔法残留，可以帮助他找到封印。",al={"为什么需要劣魔耳环","劣魔耳环的作用","黑海岸耳环任务"}},{q="巴莎兰是什么？",a="巴莎兰是一处古老的暗夜精灵遗迹，位于黑海岸的森林海岸边，其历史可以追溯到大分裂之前。这里到处都是野生的劣魔、萨特以及早已覆灭的定居者留下的幽灵残骸。",al={"什么是巴莎兰","巴莎兰历史","巴莎兰废墟"}},{q="收集耳环后会发生什么？",a="阿斯特利安检查了耳环，感觉到虽然劣魔并没有直接携带封印本身，但它们在相对近期的活动中触碰过它。这一踪迹让他能够缩小封印在废墟中的位置范围。",al={"耳环显示了什么","劣魔身上有封印吗","劣魔耳环结果"}},{q="为什么阿斯特利安会被困在这里？",a="阿斯特利安在数百年前被一道古老的魔法封印束缚在巴莎兰。这种束缚将他的灵魂锚定在废墟的物理位置上，阻止他前往安息之地。",al={"谁束缚了阿斯特利安","阿斯特利安如何被束缚","阿斯特利安的封印"}},{q="什么是劣魔？",a="劣魔是卡利姆多森林中原生的体型细小、心怀恶意的林地生物。它们以顽皮的天性、锋利的爪子和对饰品的喜爱而闻名，经常侵扰旧遗迹并攻击过往的旅行者。",al={"什么是劣魔","劣魔背景","黑海岸劣魔"}}},fp="11,257,23.299.0,18.346.0,16.183.0,38.133.0,20.187.0,43.223.1,29.145.0,16.164.0"}
P.entries["quest:95507"] = {n="Vrang's Game",s="Vrang请你检查贫瘠之地一处山谷里的陷阱。捕获的小型猎物能帮到他，但其他野生动物可能让这里变得危险。",h="Vrang请你检查贫瘠之地一处山谷里的陷阱。捕获的小型猎物能帮到他，但其他野生动物可能让这里变得危险。",kw={"贫瘠之地","小型猎物","陷阱捕获的猎物","陷阱","山谷","弗朗","野生动物"},sec={{t="Vrang的陷阱",b="Vrang在山谷各处布下了陷阱，请你带回陷阱捕获的小型猎物。他提醒你，若不留神，附近的其他野生动物可能会带来危险。"}},faq={{q="弗朗想要什么？",a="弗朗请你检查他的陷阱，并带回捕获的小型猎物。",al={"弗朗的陷阱","弗朗的猎物","弗朗需要什么"}},{q="弗朗的陷阱在哪里？",a="弗朗说，他的陷阱散布在贫瘠之地的山谷各处。",al={"陷阱在哪里","陷阱位置","贫瘠之地的陷阱"}},{q="陷阱附近有什么危险？",a="弗朗提醒你，若不留神，这里的其他野生动物可能会带来危险。",al={"附近的危险","其他动物","野生动物的危险"}}},fp="12,154,13.185.0,21.82.0,24.59.0,35.81.0"}
P.entries["quest:95508"] = {n="Unwelcome Guests",s="有人感谢你帮助他们在遭遇不速之客后活了下来。他们的感激之情显而易见，但你们相遇的缘由并未说明。",h="有人感谢你帮助他们在遭遇不速之客后活了下来。他们的感激之情显而易见，但你们相遇的缘由并未说明。",kw={"人情债","帮助","活下来","感谢","不速之客"},faq={{q="这里发生了什么？",a="说话者表示你帮助他们活了下来，却没有透露遭遇的详情。",al={"发生了什么","不速之客","客人闹事"}},{q="是谁在感谢我？",a="任务完成文本没有提到说话者的名字。",al={"这是谁","谁感谢了我","任务给予者"}},{q="他们为什么欠我人情？",a="他们说你帮助他们活了下来，却没有解释发生了什么。",al={"为什么谢我","他们为什么欠我人情","帮助他们"}}},fp="16,128,19.82.0,19.40.0,24.77.0"}
P.entries["quest:95534"] = {n="Strahnbrad Mystery",s="一张烧焦的字条请你调查斯坦恩布莱德旧风箱周围的异动，并将调查结果报告给希尔斯布莱德的人们。",h="一张烧焦的字条请你调查斯坦恩布莱德旧风箱周围的异动，并将调查结果报告给希尔斯布莱德的人们。",kw={"火元素","火焰魔法","希尔斯布莱德","旧风箱","烧焦的字条","斯坦恩布莱德","斯坦恩布莱德之谜"},sec={{t="烧焦的字条",b="一张在斯坦恩布莱德发现的字条警告说，没人看着时，旧风箱似乎会自己动起来。写字条的人说这不过是鬼故事，却坚持要你在他们回来之前查明真相。他们相信斯坦恩布莱德蕴藏着强大的力量，而火焰魔法烧掉了字条的其余部分。"},{t="你的发现",b="在希尔斯布莱德，镇民听取了你对斯坦恩布莱德旧风箱的报告。风箱里曾住着一个火元素，但它为何会在那里仍是个谜。"}},faq={{q="旧风箱有什么古怪之处？",a="一张烧焦的字条声称，没人看着时，斯坦恩布莱德的旧风箱就会自己动起来。",al={"旧风箱之谜","风箱自行移动","斯坦恩布莱德风箱"}},{q="是谁留下了字条？",a="字条没有写明作者的名字，只说他们会回来。",al={"字条作者","烧焦字条的作者","神秘字条"}},{q="字条提到了斯坦恩布莱德的什么？",a="写字条的人相信斯坦恩布莱德蕴藏着强大的力量。",al={"斯坦恩布莱德的力量","那里有强大的力量","斯坦恩布莱德有什么"}},{q="我该去哪里报告发现？",a="有人请你到希尔斯布莱德的镇上报告调查结果。",al={"报告调查结果的地点","希尔斯布莱德报告","在镇上报告"}}},fp="18,128,15.291.0,13.167.1,38.90.0,18.60.0,40.51.0,30.59.0"}
P.entries["quest:95561"] = {n="Apple of My Eye",s="在法霍德要塞，Tessa Dawnbright请你为挑剔的婴儿Emma寻找苹果。她想给孩子做苹果泥。",h="在法霍德要塞，Tessa Dawnbright请你为挑剔的婴儿Emma寻找苹果。她想给孩子做苹果泥。",kw={"苹果泥","掌上明珠","婴儿","emma","法霍德要塞","新鲜苹果","tessa dawnbright"},sec={{t="挑剔的孩子",b="Tessa Dawnbright正在法霍德要塞照料婴儿Emma，孩子的哭声响彻要塞。Tessa说，她丈夫外出收集补给，她忙得脱不开身。她请你找些新鲜苹果，好给Emma做苹果泥。"}},faq={{q="谁在请求寻找苹果？",a="Tessa Dawnbright请你在法霍德要塞为婴儿Emma寻找苹果。",al={"tessa 苹果","谁需要苹果","苹果任务发布者"}},{q="Tessa为什么需要苹果？",a="Tessa想给挑剔的婴儿Emma做苹果泥。",al={"为什么要苹果","给婴儿的苹果","苹果有什么用"}},{q="Tessa在哪里需要帮助？",a="Tessa在法霍德要塞请求帮助。",al={"tessa在哪里","法霍德苹果","苹果的位置"}},{q="Tessa为什么不能亲自去拿补给？",a="Tessa说，她丈夫外出寻找补给时，她忙着照料Emma，实在脱不开身。",al={"tessa的丈夫","她丈夫在哪里","她为什么不能去"}}},fp="15,115,13.244.0,25.72.0,27.47.0,27.37.0,41.88.0"}
P.entries["quest:95562"] = {n="Cut Off the Heads",s="学徒 Claire 请你铲除阳光林地地下的威胁。洞穴首领是 Chogg'Zac，Claire 想要你带回它们的首级。",h="学徒 Claire 请你铲除阳光林地地下的威胁。洞穴首领是 Chogg'Zac，Claire 想要你带回它们的首级。",kw={"学徒 claire","洞穴","chogg'zac","斩下首级","lady amberhall","食人魔","阳光林地"},sec={{t="Claire的请求",b="进入阳光林地下方的洞穴前，学徒 Claire 告诉你她为何来到此地。Lady Amberhall 派她来采集样本，但阳光林地曾是她的家，她决定回来。怪物仍在此地作祟，她想杀死它们的首领。Chogg'Zac 就在洞穴深处，Claire 请你带回首级。"},{t="战斗之后",b="你回来时，Claire 问 Chogg'Zac 和食人魔是否都已死去。她认可你完成了正当之事，并催促你与她一同离开。"}},faq={{q="是谁让我去阳光林地下方？",a="学徒 Claire 请你杀死阳光林地下方洞穴里的 Chogg'Zac，并取回首级。",al={"谁派我来","claire的任务","学徒 claire"}},{q="Claire为何来到阳光林地？",a="战争夺走阳光林地之前，这里曾是 Claire 的家。只要怪物还留在那里，她就无法安心。",al={"claire为何在此","claire的家","阳光林地往事"}},{q="Chogg'Zac是谁？",a="Chogg'Zac 是阳光林地下方洞穴里的首领。",al={"chogg zac","洞穴首领","食人魔首领"}},{q="Claire要我带回什么？",a="Claire 请你杀死 Chogg'Zac 后取回首级。",al={"要带回什么","给 claire 的首级","要取回什么"}}},fp="17,139,13.330.0,15.134.1,42.100.0,34.115.0,17.56.0,39.62.0"}
P.entries["quest:956"] = {n="巴莎兰",s="阿斯特利安，一位被困在巴莎兰废墟支柱间的暗夜精灵灵魂，正在寻找束缚他于此世的圣物。在察觉到当地格罗尔身上存在禁锢他的腐蚀力量后，他指引旅行者去猎杀那些驱使格罗尔的萨特，并取回远古月亮石封印。",h="阿斯特利安，一位被困在巴莎兰废墟支柱间的暗夜精灵灵魂，正在寻找束缚他于此世的圣物。在察觉到当地格罗尔身上存在禁锢他的腐蚀力量后，他指引旅行者去猎杀那些驱使格罗尔的萨特，并取回远古月亮石封印。",kw={"远古月亮石封印","阿斯特利安","巴莎兰","黑海岸","格罗尔","卡多雷","暗夜精灵幽灵","萨特"},ang={["class:Druid"]="萨特扭曲的影响力仍在不断腐蚀黑海岸的野生动物，并惊扰着那些本应在自然循环中安息的古老灵魂。",["faction:Alliance"]="清除黑海岸废墟中的萨特腐蚀，不仅能确保卡利姆多北海岸的安全，也能帮助卡多雷告慰他们那段悲剧性的过去。",["race:NightElf"]="巴莎兰是你族人古老过去的一个沉痛提醒，那些久久不愿离去的先祖们，被那些体现了天崩地裂时恶魔背叛的萨特束缚在这片土地上。"},sec={{t="古石之牢",b="一千多年来，阿斯特利安的灵魂一直被禁锢在巴莎兰的废墟之中。周围的大理石柱像是一座坚不可摧的牢笼，无论是他那日渐衰弱的灵魂力量，还是他所掌握的古老魔法，都无法将其打破。他被一件被诅咒的圣物束缚于此，几个世纪以来，他只能望着黑海岸那雾气缭绕的树冠，怀疑即便周围的岩石风化殆尽，自己能否获得解脱。"},{t="萨特与月亮石封印",b="在发现附近的格罗尔身上带有维持他囚禁状态的魔法痕迹后，阿斯特利安推断出这种附魔的源头已经落入驱使这些混乱生物的萨特手中。这些恶魔化的暗夜精灵游荡在古老的树林中，严密地看守着远古月亮石封印。夺回这件护身符是打破束缚阿斯特利安于神龛之上的无形枷锁的关键一步。"}},faq={{q="谁是阿斯特利安？",a="阿斯特利安是一位被困在巴莎兰废墟中的古老暗夜精灵幽灵。由于古老魔法的束缚，他被禁锢在神龛耸立的石柱间超过了一千年，无法超脱，也无法离开这座石之囚笼。",al={"谁是阿斯特利安","阿斯特利安的背景故事","巴莎兰的幽灵"}},{q="为什么萨特持有远古月亮石封印？",a="萨特在黑海岸北部领导并影响着那些野生的格罗尔。因为格罗尔身上带有禁锢魔法的痕迹，阿斯特利安意识到，是它们邪恶的萨特主人夺走了远古月亮石封印，以此来折磨并禁锢当地的灵魂。",al={"为什么萨特有封印","萨特月亮石封印","远古月亮石封印"}},{q="封印被找回后会发生什么？",a="阿斯特利安将收回这件束缚了他几个世纪的圣物。取回远古月亮石封印是他获得自由的倒数第二步，这使得封印能够被解除，从而让他最终能再次自由地行走于森林之中。",al={"封印的作用","取回封印"}},{q="什么是巴莎兰？",a="巴莎兰是位于黑海岸北部雾气弥漫的海岸线旁的一处古老暗夜精灵废墟。它曾经是一处宏伟的定居点或圣地，如今已支离破碎，被格罗尔、萨特以及困于此处的往昔灵魂所侵扰。",al={"巴莎兰背景故事","什么是巴莎兰"}},{q="阿斯特利安被困在这里多久了？",a="阿斯特利安已经被囚禁了一千多年。由于没有物理手段或魔法来摧毁边界，他被迫在漫长的岁月中等待，不知道自己是否还有重获自由的一天。",al={"阿斯特利安的年龄","被困多久"}},{q="阿斯特利安可以直接离开神龛吗？",a="不能。远古月亮石封印在神龛周围维持着一道形而上的屏障。这些石柱就像一座无法逾越的牢笼，阻挡了他的幽灵形态跨越此界。",al={"阿斯特利安能离开吗","为什么幽灵被困"}}},fp="11,211,25.361.0,29.356.0,16.200.0,50.207.0,40.163.1,20.218.0,40.178.0,46.141.0"}
P.entries["quest:95601"] = {n="The Purple Ones",s="Clubtoe请你阻止暮光之锤在阳光林地举行仪式。这些仪式会增强一些食人魔的力量，也会杀死其他食人魔。",h="Clubtoe请你阻止暮光之锤在阳光林地举行仪式。这些仪式会增强一些食人魔的力量，也会杀死其他食人魔。",kw={"clubtoe","empowered brutes","食人魔","阳光林地","the purple ones","暮光仪式师","暮光之锤"},sec={{t="阳光林地的仪式",b="Clubtoe派你前往阳光林地，对付暮光仪式师和Empowered Brutes。一具食人魔的尸体似乎就是Clubtoe一直在寻找的朋友之一。这些仪式会增强部分成员的力量，却会杀死更多成员，因此Clubtoe想在仪式施行者及其造物扩散之前阻止他们。"}},faq={{q="Clubtoe是谁？",a="Clubtoe请求你阻止阳光林地的暮光仪式师。",al={"clubtoe","谁是clubtoe"}},{q="The Purple Ones在做什么？",a="暮光仪式师会对他们的成员施行仪式。有些成员因此获得力量，更多成员却被杀死。",al={"the purple ones","the purple ones在做什么"}},{q="Clubtoe为什么想阻止这些仪式？",a="Clubtoe担心仪式施行者和他们的怪物会扩散开来。",al={"为什么阻止仪式","为什么杀死仪式施行者"}},{q="Clubtoe的朋友们怎么了？",a="一具食人魔的尸体似乎就是Clubtoe正在寻找的朋友之一。",al={"clubtoe的朋友","朋友在哪里"}},{q="Clubtoe在哪里？",a="Clubtoe在阳光林地。",al={"clubtoe的位置","阳光林地的clubtoe"}}},fp="15,111,19.274.0,15.76.0,31.98.0,42.65.0,35.71.0,17.25.0"}
P.entries["quest:95602"] = {n="Sickening Lights",s="Clubtoe让你砸毁阳光林地下方闪闪发光的仪式法阵。光芒让他感到恶心，他还担心独自行动会惹怒Chogg'Zac。",h="Clubtoe让你砸毁阳光林地下方闪闪发光的仪式法阵。光芒让他感到恶心，他还担心独自行动会惹怒Chogg'Zac。",kw={"洞穴","chogg'zac","clubtoe","光芒","闪亮的图画","令人作呕的光芒","阳光林地","暮光仪式法阵"},sec={{t="令人作呕的光芒",b="Clubtoe在阳光林地下方的洞穴里为Chogg'Zac砸石头。他在石头中发现了闪闪发光的光芒，其他人还用它们画图。光芒让Clubtoe感到恶心，但他担心砸坏这些图画会受到Chogg'Zac惩罚。你受托摧毁暮光仪式法阵，Clubtoe希望光芒不再困扰他。"}},faq={{q="是谁要我砸毁法阵？",a="Clubtoe让你摧毁阳光林地下方的暮光仪式法阵。",al={"clubtoe是谁","clubtoe的任务","谁想砸掉光芒"}},{q="Clubtoe为什么想砸掉这些光？",a="光芒让Clubtoe感到恶心，他想砸毁这些闪亮的图画。",al={"为什么砸掉光芒","光芒让clubtoe恶心","clubtoe讨厌光芒"}},{q="Chogg'Zac是谁？",a="Chogg'Zac是Clubtoe的老板，Clubtoe担心砸毁法阵会惹他生气。",al={"chogg'zac","clubtoe的老板","大老板"}},{q="那些闪亮的图画是什么？",a="它们是阳光林地下方洞穴各处的暮光仪式法阵。Clubtoe称它们为闪亮的图画。",al={"闪亮的图画","暮光法阵","这些光是什么"}},{q="Clubtoe在洞穴里做什么？",a="Clubtoe为Chogg'Zac砸石头，还在石头中发现了闪亮的光芒。",al={"clubtoe的工作","砸石头","clubtoe在做什么"}},{q="砸毁法阵后，Clubtoe感觉好些了吗？",a="你砸毁法阵后，Clubtoe说他已经感觉好多了。",al={"clubtoe任务完成","砸掉后有用吗","光芒让他感觉好些"}}},fp="16,147,16.364.0,38.75.0,41.78.0,17.90.0,28.116.0,34.76.0,55.66.0"}
P.entries["quest:95603"] = {n="Bats in the Belfry",s="Sister Rowland请你清除Farholde大教堂里的蝙蝠。她希望战事结束后，圣光能重返教堂。",h="Sister Rowland请你清除Farholde大教堂里的蝙蝠。她希望战事结束后，圣光能重返教堂。",kw={"钟楼里的蝙蝠","lowley兄弟","教堂","farholde大教堂","light","栖息的暮色蝙蝠","sister rowland"},sec={{t="大教堂",b="Sister Rowland请你帮忙清理Farholde大教堂，暮色蝙蝠在教堂上层栖息。她和Lowley兄弟如今以更世俗的身份为Farholde效力，教堂也因此荒废了。Rowland希望教堂能维持正常运作，但她担心战事还会持续很久。"}},faq={{q="大教堂里为什么有蝙蝠？",a="一群蝙蝠在Farholde大教堂的上层筑巢栖息。",al={"大教堂蝙蝠","钟楼里的蝙蝠","蝙蝠为何出现"}},{q="是谁让我清除蝙蝠？",a="Sister Rowland请你清除栖息在Farholde大教堂里的蝙蝠。",al={"谁交代了这件事","sister rowland","rowland与蝙蝠"}},{q="Sister Rowland为什么想让教堂维持正常运作？",a="Sister Rowland希望战事结束后，圣光能重返教堂。",al={"为何维护教堂","教堂维护","rowland与教堂"}},{q="教堂发生了什么？",a="Sister Rowland和Lowley兄弟开始以更世俗的身份为Farholde效力后，教堂便荒废了。",al={"教堂荒废","为何荒废","farholde教堂"}}},fp="18,134,13.305.0,36.79.0,30.76.0,62.79.0,28.124.0"}
P.entries["quest:95613"] = {n="Keeping the Light On",s="罗兰修女请你将圣洁蜡烛送到法霍德要塞。她在教堂地下墓穴中点燃蜡烛，纪念阵亡者，让人们铭记他们的牺牲。",h="罗兰修女请你将圣洁蜡烛送到法霍德要塞。她在教堂地下墓穴中点燃蜡烛，纪念阵亡者，让人们铭记他们的牺牲。",kw={"教堂","地下墓穴","阵亡者","法霍德要塞","圣洁蜡烛","长明灯","玛拉","罗兰修女"},sec={{t="献给阵亡者的蜡烛",b="法霍德要塞的罗兰修女请你带来圣洁蜡烛。教堂如今已不再举行礼拜，但她仍在地下墓穴中阵亡者的墓前点燃蜡烛。烛火象征着逝者仍被铭记，他们的牺牲并非徒劳。罗兰修女的朋友玛拉住在教堂外不远处的屋子里，或许有多余的蜡烛。"}},faq={{q="罗兰修女为何一直点着蜡烛？",a="罗兰修女在教堂地下墓穴中阵亡者的墓前点燃蜡烛，让人们铭记他们，他们的牺牲也不会白费。",al={"蜡烛的用途","地下墓穴蜡烛","献给逝者的蜡烛"}},{q="罗兰修女希望把蜡烛送到哪里？",a="罗兰修女请你把圣洁蜡烛送到法霍德要塞交给她。",al={"蜡烛送往何处","送蜡烛","罗兰修女的蜡烛"}},{q="玛拉是谁？",a="玛拉是罗兰修女的朋友，住在教堂外不远处的屋子里，或许有多余的蜡烛。",al={"玛拉的蜡烛","谁有蜡烛","蜡烛来源"}},{q="教堂还举行礼拜吗？",a="教堂如今已不再举行礼拜，不过罗兰修女仍在地下墓穴中点着蜡烛。",al={"教堂礼拜","教堂关闭","不再举行礼拜"}}},fp="20,158,22.365.0,41.133.0,51.70.0,13.113.0,37.107.0"}
P.entries["quest:95615"] = {n="In Memoriam",s="Sister Rowland请你重新点燃法霍德要塞的纪念蜡烛。这一小小的举动既是对逝者的敬意，也能让教堂继续维持下去。",h="Sister Rowland请你重新点燃法霍德要塞的纪念蜡烛。这一小小的举动既是对逝者的敬意，也能让教堂继续维持下去。",kw={"礼拜堂墓地","教堂","法霍德要塞","坟墓","追悼","点燃","纪念蜡烛","sister rowland"},sec={{t="为逝者点燃的蜡烛",b="在法霍德要塞，Sister Rowland请你照料礼拜堂墓地。在三座熄灭了旧烛火的坟墓上放置新蜡烛，默默追念逝者。"}},faq={{q="是谁请我点燃蜡烛？",a="法霍德要塞的Sister Rowland请你在礼拜堂墓地点燃纪念蜡烛。",al={"sister rowland是谁","sister rowland的蜡烛"}},{q="蜡烛要放在哪里？",a="把纪念蜡烛放在法霍德要塞礼拜堂墓地的坟墓上。",al={"蜡烛位置","坟墓在哪里"}},{q="有几座坟墓需要放蜡烛？",a="Sister Rowland请你在坟墓上放置三支纪念蜡烛。",al={"蜡烛数量","需要几支蜡烛"}},{q="为什么要点燃蜡烛？",a="蜡烛是为了纪念逝者，也能让教堂继续维持下去。",al={"为什么要点蜡烛","这件事的用途"}}},fp="11,132,22.184.0,33.91.0,24.78.0,29.66.0,22.69.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="“Trouble in the Valley”讲述了一支神秘的库尔提拉斯人小队在山谷底部进行搜寻的故事。武装部队在南边一辆损毁的大篷车附近扎营，这促使当地侦察兵寻求消除这一威胁，并揭开他们意外搜寻背后的目的。",h="“Trouble in the Valley”讲述了一支神秘的库尔提拉斯人小队在山谷底部进行搜寻的故事。武装部队在南边一辆损毁的大篷车附近扎营，这促使当地侦察兵寻求消除这一威胁，并揭开他们意外搜寻背后的目的。",kw={"大篷车","库尔提拉斯","士兵","山谷中的麻烦","山谷","损毁的大篷车"},ang={["race:Human"]="看到身穿代表岛国库尔提拉斯的海绿色和锚徽制服的士兵在山谷中活动，标志着与这个与世隔绝的人类航海民族进行了一次罕见且出人意料的邂逅。"},sec={{t="山谷中的可疑活动",b="一名正在俯瞰低地的警觉步枪手发现了一支库尔提拉斯人小队正在山谷底部进行搜寻。通过步枪瞄准镜仔细观察，侦察兵清晰地辨认出了那个海上王国库尔提拉斯的纹章和制服。他们出人意料地出现在山谷中立刻引发了警觉，因为武装外来者很少会如此大摇大摆地行动而不引起注意。"},{t="损毁的大篷车",b="士兵们在南边一辆损毁的大篷车附近驻扎。无论是什么吸引他们来到这辆损毁的马车旁，这都是一个亟待解决的谜团。当地观察员认为这种入侵性的武装存在是一个迫在眉睫的问题，因此派遣调查员去消灭这些士兵，并揭开他们远征的真正目的。"}},faq={{q="库尔提拉斯人士兵在山谷里做什么？",a="一名神枪手发现了一支库尔提拉斯人分遣队正在下方的山谷中搜寻某物。他们在南边一辆损毁的大篷车附近建立了营地，这促使当地侦察兵去调查他们不同寻常的动机。",al={"库尔提拉斯人为什么在这里","山谷里的库尔提拉斯士兵","库尔提拉斯人在做什么"}},{q="库尔提拉斯人营地在哪里？",a="士兵们在俯瞰山谷的侦察点南侧的一辆损毁大篷车附近建立了营地。",al={"损毁的大篷车位置","库尔提拉斯营地在哪里","大篷车地点"}},{q="库尔提拉斯人的存在是如何被发现的？",a="一名监视山谷的侦察兵使用步枪瞄准镜从远处观察那群神秘的人类，并轻易地辨认出了库尔提拉斯特有的制服和徽章。",al={"他们是如何被发现的","库尔提拉斯制服"}},{q="调查营地的目标是什么？",a="任务要求前往南方的损毁大篷车处，与驻扎在那里的库尔提拉斯人士兵对峙，并查明是什么吸引他们搜寻该区域。",al={"目标是什么","山谷中的麻烦任务目标"}},{q="为什么这些库尔提拉斯人士兵被视为敌人？",a="因为一支武装外国士兵分遣队在没有解释的情况下，正在损毁的大篷车周围积极搜寻领土，侦察兵认为他们是一个必须予以制服以探明意图的威胁。",al={"为什么要与库尔提拉斯战斗","库尔提拉斯人是敌对的吗"}},{q="谁在山谷里发现了这些士兵？",a="监视山谷的隐士制革工首先通过步枪瞄准镜识别出了这些士兵，并雇佣了一名冒险者去消灭他们，弄清他们为何出现在这里。",al={"谁发现了士兵","谁发布了任务"}}},fp="21,177,33.236.0,19.264.0,48.174.0,36.100.0,42.130.0,48.127.0,50.180.0,40.164.0"}
P.entries["quest:95642"] = {n="Abominable Magics",s="学徒Claire请你前往阳光林地下方的洞穴，收集暮光之锤魔法的样本。Farholde需要这些样本，以便研究该教派的巫术。",h="学徒Claire请你前往阳光林地下方的洞穴，收集暮光之锤魔法的样本。Farholde需要这些样本，以便研究该教派的巫术。",kw={"邪恶魔法","学徒claire","ashe amberhall","crystal catalyst","farholde","河林","阳光林地","暮光之锤","巫术"},sec={{t="Claire的请求",b="Ashe Amberhall派Claire前往河林调查暮光之锤，那里有教徒正在挖掘某种东西。她需要一份巫术样本来了解这种巫术。你带着一枚经过附魔的Crystal Catalyst，可以吸收符文或教徒身上的该教派之力。Claire说，Farholde急需它收集到的东西。"},{t="强力样本",b="你回来时，Claire触碰水晶，里面噼啪作响的魔力让她一惊。收集到的力量比她担心的还要强大，她说必须小心处理。"}},faq={{q="谁需要这些样本？",a="学徒Claire请你替她收集暮光之锤魔法的样本。",al={"谁需要样本","claire的样本请求"}},{q="Claire为什么需要这些样本？",a="Claire想研究该教派的巫术，她说Farholde急需这些样本。",al={"为什么要样本","样本有什么用"}},{q="教徒们在哪里挖掘？",a="暮光之锤正在河林里挖掘某种东西。",al={"暮光之锤在哪里挖掘","教徒挖掘"}},{q="Crystal Catalyst有什么作用？",a="经过附魔的Crystal Catalyst可以吸收符文或教徒身上的暮光之锤魔法之力。",al={"水晶物品","催化剂的用途"}},{q="是谁派Claire去调查的？",a="Ashe Amberhall派Claire去调查暮光之锤。",al={"谁派了claire","amberhall"}}},fp="17,168,16.318.0,15.181.1,30.80.0,33.94.0,31.66.0,34.99.0,31.60.0"}
P.entries["quest:95643"] = {n="Indiscriminate Purge",s="Lady Amberhall的学徒请你前往阳光林地下方，对付注入虚空能量的食人魔。暮光之重型钉锤将会感受到损失。",h="Lady Amberhall的学徒请你前往阳光林地下方，对付注入虚空能量的食人魔。暮光之重型钉锤将会感受到损失。",kw={"学徒","empowered brutes","不分青红皂白的清剿","lady amberhall","阳光林地","twilight ritualists","暮光之锤","注入虚空能量的食人魔"},sec={{t="阳光林地下方",b="Lady Amberhall的学徒被食人魔及其首领抓进了阳光林地下方的洞穴。她请你在那里除掉 Twilight Ritualists 和 Empowered Brutes。这些损失将重创暮光之重型钉锤。"}},faq={{q="谁在阳光林地下方请求援助？",a="Lady Amberhall的学徒请你杀死阳光林地下方洞穴里的食人魔。",al={"amberhall学徒","请求援助的人","lady amberhall任务"}},{q="洞穴里有什么？",a="阳光林地下方的洞穴里有注入虚空能量的食人魔和它们的首领。",al={"阳光林地洞穴","食人魔种类","洞穴敌人"}},{q="谁是食人魔的首领？",a="学徒称食人魔的首领是 Twilight Ritualists。",al={"食人魔首领","twilight ritualists","控制食人魔的人"}},{q="学徒提到了哪些食人魔？",a="她提到洞穴里的野兽中有 Empowered Brutes。",al={"empowered brutes","要杀死哪些食人魔","食人魔名称"}},{q="学徒为什么请你杀死它们？",a="她说，怀有目的的狂热分子不会带来好事，无论他们是否受到强化。",al={"为何杀死食人魔","为何进行清剿","为何帮助lady amberhall"}},{q="学徒如何评价自己的能力？",a="她说自己通常有能力独自处理事情，但还是被食人魔抓住了。",al={"学徒被抓","amberhall学徒的能力","她遭遇了什么"}}},fp="20,133,16.224.0,37.89.0,21.71.0,29.70.0,37.57.0,45.86.0,53.90.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="绿色守卫者雷希耶尔感知到一股邪恶的腐蚀力量正穿过山沟，渗入湿地之上的淡水区域。冒险者必须前往发掘现场，消灭一只高地恐魔并回收它的根核。雷希耶尔发现一股古老的能量正在苏醒，并警告称持续的挖掘行为威胁到了该地区所有人的安全。",h="绿色守卫者雷希耶尔感知到一股邪恶的腐蚀力量正穿过山沟，渗入湿地之上的淡水区域。冒险者必须前往发掘现场，消灭一只高地恐魔并回收它的根核。雷希耶尔发现一股古老的能量正在苏醒，并警告称持续的挖掘行为威胁到了该地区所有人的安全。",kw={"腐蚀","发掘现场","高地恐魔","高地上的恐怖","雷希耶尔","绿色守卫者雷希耶尔","根核","湿地"},ang={["class:Druid"]="雷希耶尔通过他的根系和水道感知到了自然平衡的改变；与大地协调一致的德鲁伊会意识到淡水生物在面对古老腐蚀时的脆弱性。",["faction:Alliance"]="在山区进行发掘作业的联盟探险家和勘探员有惊扰埋藏在地底的古老力量的风险。",["race:Dwarf"]="高地上的矮人发掘场出土的东西远不止古老的遗物，这促使雷希耶尔敦促挖掘者在更邪恶的东西苏醒之前停止挖掘。"},sec={{t="沟壑中的污染",b="在湿地的深处，绿色守卫者雷希耶尔感知到了大地发生了令人不安的变动。一股邪恶的污染穿过一条山沟，感染了高地之上的淡水生物。与那些在苦咸的低地水域中淬炼出的顽强生命不同，这些淡水生物从未接触过海洋的保护性盐分，这使它们在面对蔓延的邪恶时毫无防御能力。雷希耶尔呼吁冒险者前往发掘现场，消灭一只高地恐魔，并取回它的根核。"},{t="古老的苏醒",b="当高地恐魔的根核被带到雷希耶尔面前时，这位守护者的担忧得到了证实：一股古老的能量已经开始苏醒。困扰高地生物的病痛并非寻常的疾病，而是近期挖掘行为的后果。雷希耶尔紧急警告称，在山区工作的心急火燎的挖掘者必须立即停止挖掘，否则他们盲目的好奇心会给湿地带来更可怕的灾难。"}},faq={{q="谁发布了“高地的恐怖”任务？",a="绿色守卫者雷希耶尔，一位守护着湿地的古老保护者，在感知到附近山沟渗出的邪恶腐蚀后发布了这个任务。",al={"谁发布高地恐怖任务","高地恐怖任务发布者","雷希耶尔任务"}},{q="在哪里可以找到高地恐魔？",a="高地恐魔栖息在低地之上的高地发掘现场，靠近腐蚀渗出的山沟附近。",al={"高地恐魔在哪里","高地恐魔位置","如何找到高地恐魔"}},{q="为什么高地生物如此容易受到腐蚀？",a="高地的淡水生物缺乏湿地低处海洋特有的盐分浸润，这使得它们体质脆弱，在面对腐蚀性的污染时反应格外剧烈。",al={"为什么生物受到污染","为什么高地生物被腐蚀","淡水腐蚀"}},{q="什么是高地恐魔的根核？",a="根核是受腐蚀的高地恐魔的心脏。雷希耶尔需要它来检查蔓延在水道中的非自然力量，并确认腐蚀的性质。",al={"什么是根核","高地恐魔核心","为什么要取回根核"}},{q="当你交还根核时，雷希耶尔发现了什么？",a="在检查了核心后，雷希耶尔意识到一股古老的能量已经开始从地底深处苏醒，这很可能是因为发掘现场鲁莽的挖掘行为所惊扰。",al={"雷希耶尔发现了什么","湿地古老能量","挖掘危险"}},{q="为什么雷希耶尔希望挖掘者停止挖掘？",a="雷希耶尔警告说，在高地工作的心急火燎的挖掘者应该为了自身的安全立即停止挖掘，因为他们的挖掘行为有释放危险的古老力量的风险。",al={"雷希耶尔停止挖掘","挖掘者应该做什么","矮人挖掘场警告"}}},fp="23,266,18.437.0,19.372.1,45.144.0,36.131.0,60.132.0,43.189.0,57.170.0,53.127.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="一位忧心忡忡的炼金师请求路过的旅行者去寻找她失踪的丈夫阿丁·格拉斯曼（Ardin Grassman）。阿丁在追寻关于高耸、未知的草类的传闻后失踪了。他对植物的好奇心将他引向了附近的一处挖掘场，那里的考察队正遭到危险野生生物和蜘蛛的围攻。",h="一位忧心忡忡的炼金师请求路过的旅行者去寻找她失踪的丈夫阿丁·格拉斯曼（Ardin...",kw={"炼金术","阿丁","阿丁·格拉斯曼","挖掘场","草药学","遗失在灌木丛中的物品","蜘蛛","高耸的草类"},ang={["class:Druid"]="关注荒野平衡的德鲁伊可能会对阿丁感知植物的天赋，以及挖掘场附近导致野生生物反常躁动的原因感兴趣。",["profession:Herbalism"]="阿丁·格拉斯曼拥有感知植物和草药的与生俱来的天赋，经常攀登险峻的地形，为炼金术收集稀有植物。"},sec={{t="采药人的呼唤",b="在“Lost in the Thicket Things”中，一位炼金师寻求帮助以寻找她失踪的丈夫阿丁·格拉斯曼。阿丁拥有一种令人难以置信的、对大自然的本能亲和力，经常冒着险攀登陡峭的悬崖，前往遥远的荒野，为妻子的炼金补给收集稀有草药和植物标本。当一支经过的挖掘队带来关于前所未见的奇异高耸草类的消息时，阿丁的好奇心占了上风，他出发去亲自考察这些植物。"},{t="挖掘场埋伏",b="阿丁追踪考察队来到了他们的挖掘场，却直接陷入了危险之中。周围土地上的某种东西扰乱了当地的动物，导致极具攻击性的野生生物——最显著的是成群的敌对蜘蛛——猛扑过来并淹没了挖掘小队。被不断逼近的野兽困住，阿丁和队员们陷入重围，直到有旅行者介入救援了这位被困的植物学家。"}},faq={{q="谁是阿丁·格拉斯曼？",a="阿丁·格拉斯曼是一位拥有感知植物和草药的天赋的采集者。他经常搜寻悬崖和山峰，为妻子的炼金工艺提供野生植物，但他对奇异的高耸草类的好奇心将他引向了一处挖掘场。",al={"阿丁是谁","阿丁·格拉斯曼背景故事","谁是阿丁·格拉斯曼"}},{q="阿丁为什么要闯入荒野？",a="阿丁无意中听到挖掘队在描述一种他们从未见过的高耸巨草。出于对奇异植物和花卉的喜爱，他冒险前往，想要亲眼见识一下这些奇怪的植被，结果却没能回家。",al={"阿丁为什么离开","为什么阿丁失踪了","阿丁在寻找什么"}},{q="阿丁去哪了？",a="在听到一支经过的考察队的消息后，阿丁前往了附近的挖掘场。寻找他的旅行者必须仔细搜查考察队建立作业点的地方。",al={"阿丁在哪里","阿丁的位置","在哪里找到阿丁·格拉斯曼"}},{q="阿丁在挖掘场发生了什么？",a="阿丁到达时发现挖掘营地已被当地野生生物的猛烈攻击所淹没。巨型蜘蛛和其他被激怒的野兽埋伏了考察队，将阿丁和队员们困住，直到外部支援到来。",al={"阿丁发生了什么","阿丁死了吗","什么攻击了阿丁"}},{q="谁在寻找阿丁？",a="搜寻工作始于阿丁的妻子，一位依赖丈夫的草药采集来补充炼金材料的炼金师。当他调查关于奇异草类的传闻而未能归来时，她寻求了能干的旅行者来带他回家。",al={"谁发布了迷失在灌木丛中","谁发起了这个任务","阿丁的妻子"}},{q="为什么野生生物会攻击挖掘队？",a="挖掘场周围的野生生物突然变得狂暴不安，尽管造成它们躁动的根本原因尚不明确。这种骚乱驱使具有攻击性的生物，尤其是蜘蛛，蜂拥而至并淹没了挖掘队。",al={"为什么蜘蛛在攻击","什么激怒了动物","为什么野兽如此愤怒"}}},fp="26,183,19.303.0,22.250.1,22.215.0,39.168.0,19.133.0,46.178.0,25.183.0,48.162.0"}
P.entries["quest:95663"] = {n="Dragonmaw Rumors",s="亡灵哨兵想查明湿地流传的龙喉氏族魔法传闻。你受命前往氏族营地上方的山丘，与他们的密探碰面。",h="亡灵哨兵想查明湿地流传的龙喉氏族魔法传闻。你受命前往氏族营地上方的山丘，与他们的密探碰面。",kw={"残缺的符号","亡灵哨兵密探","亡灵哨兵","束缚巨龙","龙喉氏族","龙喉氏族营地","龙喉氏族传闻","湿地"},sec={{t="湿地的传闻",b="湿地的一名亡灵哨兵需要你的帮助，关于龙喉氏族的传闻正越来越多。据说他们掌握着束缚巨龙的魔法，还有传言称，他们正准备展示这种力量。残缺的符号未能提供确凿的证据，因此你受命前往他们营地上方的山丘，与一名密探碰面。"}},faq={{q="传闻中，龙喉氏族正在做什么？",a="传闻称，龙喉氏族正准备展示一种强大的魔法，足以让巨龙为他们效命。",al={"龙喉氏族传闻","龙喉氏族在计划什么","龙喉氏族魔法"}},{q="亡灵哨兵为什么需要帮助？",a="关于龙喉氏族，亡灵哨兵手中只有残缺的符号和未经证实的传闻，因此一名密探需要有人前往氏族营地上方的山丘协助她。",al={"亡灵哨兵需要帮助","为何帮助亡灵哨兵","他们需要什么"}},{q="亡灵哨兵的密探在哪里？",a="密探就在湿地龙喉氏族营地上方的山丘中。",al={"密探位置","在哪里与密探碰面","亡灵哨兵密探山丘"}},{q="残缺的符号揭示了什么？",a="残缺的符号只透露了一些未经证实的传闻，说龙喉氏族准备展示魔法。",al={"残缺的符号","符号揭示了什么","符号龙喉氏族"}},{q="与密探碰面后会发生什么？",a="当你在龙喉氏族营地上方的山丘中与那名亡灵哨兵密探碰面时，她会告知你接下来的行动。",al={"与密探碰面","接下来的行动","密探说什么"}}},fp="16,151,24.300.0,43.98.0,35.151.0,32.67.0,35.94.0,37.106.0"}
P.entries["quest:95664"] = {n="Elder Knowledge",s="一件奇异的泰坦圣物如同有生命的棱镜一般散射着光芒，其本质却仍不明朗。你带着它前往雷霆崖的长者高地，寻找能解释其古老力量的人。",h="一件奇异的泰坦圣物如同有生命的棱镜一般散射着光芒，其本质却仍不明朗。你带着它前往雷霆崖的长者高地，寻找能解释其古老力量的人。",kw={"古老的力量","复合碎片","elder knowledge","长者高地","有生命的棱镜","雷霆崖","泰坦圣物"},sec={{t="光之碎片",b="你保管的这块奇特的复合碎片，如同有生命的棱镜一般散射着光芒。它的本质尚不明朗，但它的力量给人一种古老的感觉。你带着泰坦圣物前往雷霆崖的长者高地，寻找能告诉你更多信息的人。"}},faq={{q="泰坦圣物是什么？",a="这是一块奇特的复合碎片，如同有生命的棱镜一般散射着光芒。它的本质尚不明朗，但它的力量给人一种古老的感觉。",al={"泰坦圣物","圣物是什么","棱镜碎片"}},{q="我该把泰坦圣物带到哪里？",a="把泰坦圣物带到雷霆崖的长者高地，寻找能解释它的人。",al={"圣物送到哪里","长者高地圣物","雷霆崖碎片"}},{q="我为什么带着这块碎片？",a="你正在长者高地寻找能告诉你更多有关泰坦圣物信息的人。",al={"为什么带着这件圣物","碎片有什么用","elder knowledge任务"}}},fp="15,186,16.232.0,24.127.0,32.92.0,28.82.0"}
P.entries["quest:95682"] = {n="Open the Maw",s="一名亡灵哨兵密探请你清除Excavation Sites的龙喉氏族，并带回任何值得注意的东西。这个氏族可能正在寻找重掌权势的途径。",h="一名亡灵哨兵密探请你清除Excavation Sites的龙喉氏族，并带回任何值得注意的东西。这个氏族可能正在寻找重掌权势的途径。",kw={"黑暗女王","亡灵哨兵密探","龙喉氏族","excavation site","被遗忘者","潦草的兽人文字","雷德"},sec={{t="悄然潜入",b="Excavation Site外的一名亡灵哨兵密探想让你清除那里的龙喉氏族部队。这个曾经驯服巨龙的氏族，其残余势力相信自己找到了能让他们恢复昔日力量的东西。必须清除这群乌合之众，好让亡灵哨兵悄然进入。带回你找到的任何值得注意的东西，并将此事保密，只有密探和王室指挥层可以知晓。"},{t="带回的潦草字迹",b="亡灵哨兵密探认出了带回物品上的兽人文字。文字表明，龙喉氏族希望取悦他们的伪酋长雷德。密探认为此举徒劳无益，但这些情报对黑暗女王很有价值。密探将带回的物品留给你，并警告你不要透露这次任务的任何消息。"}},faq={{q="是谁派我去Excavation Site的？",a="Excavation Site外的一名亡灵哨兵密探请你清除龙喉氏族，并带回任何值得注意的东西。",al={"谁想清除龙喉氏族","亡灵哨兵密探的任务","谁派我来的"}},{q="龙喉氏族希望做什么？",a="龙喉氏族的残余势力相信自己找到了能让他们恢复昔日力量的东西。",al={"龙喉氏族的计划","龙喉氏族为何在此","龙喉氏族重掌权势"}},{q="亡灵哨兵为什么要清除那里的敌人？",a="他们想在不被察觉的情况下进入Excavation Site。",al={"为何清除excavation site的敌人","亡灵哨兵进入","他们需要什么"}},{q="我应该带回什么？",a="把你从龙喉氏族那里找到的任何值得注意的东西带给亡灵哨兵密探。",al={"要带回什么","龙喉氏族的物品","密探想要什么"}},{q="黑暗女王是谁？",a="密探用这个称号来称呼被遗忘者的领袖希尔瓦娜斯。",al={"黑暗女王的含义","黑暗女王是谁","sylvanas的称号"}}},fp="12,153,16.379.0,20.323.1,35.117.0,36.95.0,47.50.0,25.77.0,21.63.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Changing Tastes是奥格瑞玛的一个关于博斯坦的火坑烹饪抱负的任务。在扎姆沙的建议和关于巨型迅猛龙爪的传说的推动下，博斯坦委托冒险者穿越无尽之海前往湿地，以获取异域的灌木迅猛龙肉。",h="Changing Tastes是奥格瑞玛的一个关于博斯坦的火坑烹饪抱负的任务。在扎姆沙的建议和关于巨型迅猛龙爪的传说的推动下，博斯坦委托冒险者穿越无尽之海前往湿地，以获取异域的灌木迅猛龙肉。",kw={"博斯坦","博斯坦的火坑","变换口味","挖掘场","奥格瑞玛","灌木迅猛龙","灌木迅猛龙肉","湿地","扎姆沙"},ang={["faction:Horde"]="供应博斯坦的火坑意味着要深入跨越海洋的争夺领土，将异域肉类带回奥格瑞玛。",["profession:Cooking"]="博斯坦旨在将传统的乡村餐点提升为足以在部落首都享用的盛宴，凸显了烹饪口味和旅店菜单如何超越乡村主食而演变。"},sec={{t="提升首都烹饪水平",b="在奥格瑞玛的中心地带，博斯坦的火坑正寻求扩大其烹饪种类。扎姆沙建议引入家常迅猛龙烹饪，以吸引那些怀念家乡舒适、熟悉饭菜的旅行者。博斯坦喜欢供应迅猛龙肉以吸引新客人的想法，但他觉得仅仅重现乡村菜肴对于伟大的部落首都不太合适。相反，他设想了一个更宏大、更粗犷的经典主食版本。"},{t="湿地狩猎",b="当一位猎人带着从在湿地挖掘场徘徊的灌木迅猛龙身上取下的巨大爪子回到奥格瑞玛时，灵感便出现了。博斯坦对这些野兽的品质和体型很感兴趣，于是安排冒险者穿越无尽之海前往东部王国，勇闯挖掘场，并为他咆哮的炉火获取上等的灌木迅猛龙肉。"}},faq={{q="什么是改变口味任务？",a="改变口味是奥格瑞玛发布的一项烹饪任务。博斯坦的火坑的所有者博斯坦，寻求来自遥远湿地的灌木迅猛龙肉，以提升其旅店菜单的档次，超越基本的乡村烹饪。",al={"什么是口味变化","口味变化任务"}},{q="扎姆沙是谁？",a="扎姆沙是奥格瑞玛的一位同事或同行烹饪工作者，她建议在博斯坦的火坑增加家常迅猛龙菜肴，以吸引通常不会光顾的顾客。",al={"谁是扎姆沙","扎姆沙烹饪"}},{q="什么是博斯坦的火坑？",a="博斯坦的火坑是位于部落首都奥格瑞玛的一家餐馆，以向旅行者和当地居民提供丰盛的熟肉而闻名。",al={"博斯坦的火坑","博斯坦在哪里"}},{q="博斯坦为什么需要灌木迅猛龙肉？",a="虽然扎姆沙提议用普通的家常迅猛龙烹饪来吸引食客，但博斯坦想要一种更宏大的熟悉口味。受到猎人关于巨型爪子的故事的启发，他选择了在湿地发现的灌木迅猛龙。",al={"为什么要迅猛龙肉","为什么要灌木迅猛龙"}},{q="灌木迅猛龙位于哪里？",a="灌木迅猛龙栖息在位于湿地的挖掘场，这是一个横跨无尽之海、位于东部王国的联盟倾向地区。",al={"我能在哪里找到灌木迅猛龙","湿地挖掘场迅猛龙"}},{q="谁发布了改变口味任务？",a="博斯坦，奥格瑞玛博斯坦的火坑的经营者，在受到扎姆沙的建议和一位冒险的猎人带回的战利品的启发后，提供了这个任务。",al={"谁发布了口味变化","博斯坦任务发布者"}}},fp="15,189,25.341.0,24.317.0,34.184.0,13.162.0,26.124.0,42.179.0,38.130.0,36.162.0"}
P.entries["quest:957"] = {n="巴莎兰",s="这个任务要求冒险者帮助位于巴莎兰废墟中被困的阿斯特利安之灵。通过将他的束缚封印带往南方的姐妹废墟亚米萨兰，冒险者将设法打破他身上的远古羁绊。",h="这个任务要求冒险者帮助位于巴莎兰废墟中被困的阿斯特利安之灵。通过将他的束缚封印带往南方的姐妹废墟亚米萨兰，冒险者将设法打破他身上的远古羁绊。",kw={"亚米萨兰","阿斯特利安","阿斯瑞库斯","艾萨拉","巴莎兰","黑海岸","上层精灵","月亮石封印"},ang={["class:Mage"]="束缚阿斯特利安的持久附魔和亚米萨兰幸存的火焰，让人得以一窥远古上层精灵法师所掌控的原始奥术力量。",["faction:Alliance"]="清除黑海岸的远古诅咒，为从奥伯丁向外扩张的暗夜精灵新定居点确保了边境的安全。",["race:NightElf"]="对于现代卡利姆多的暗夜精灵来说，解放阿斯特利安是一次沉重的经历，让他们直面自己种族在大分裂前的过去，以及艾萨拉女王的上层精灵贵族所留下的腐化。"},sec={{t="远古法术的囚笼",b="阿斯特利安的灵魂在巴莎兰徘徊了数千年，在死后被一枚远古月亮石封印所禁锢。这枚封印由大分裂前上层精灵一族强大的法术锻造而成，凡人的力量无法将其击碎。若要摧毁它，需要借助一种远古火焰的特殊魔法，而这种火焰至今仍在南方的亚米萨兰坍塌的石构建筑中燃烧。"},{t="黑海岸的双生废墟",b="巴莎兰和亚米萨兰曾是卡多雷文明中充满活力的姐妹定居点，那时艾萨拉女王统治着帝国，永恒之井仍是帝国的基石。如今，两处遗迹都已是荒草丛生、鬼魂萦绕的废墟，充斥着挥之不去的幽灵和不稳定的奥术能量。在亚米萨兰的一座石亭内，一盏青色火焰的神秘火盆提供了唯一足以吞噬阿斯特利安束缚遗物的力量。"},{t="复仇之火觉醒",b="随着封印被摧毁，阿斯特利安终于卸下了重担。他凝视着支离破碎的卡利姆多，这里的景象与他记忆中的黄金时代相比已是天差地别。然而，自由并没有带给他平静。当感觉到他曾经的主人兼狱卒——上层精灵阿斯瑞库斯依然存在时，阿斯特利安心中远古的绝望很快转化为一种冰冷而灼热的复仇渴望。"}},faq={{q="阿斯特利安是谁？",a="阿斯特利安是一位被困在巴莎兰废墟中的暗夜精灵之灵。他可以追溯到一万年前艾萨拉女王统治的时期，并被一枚由上层精灵中最强大的法师所制作的封印束缚在废墟中。",al={"阿斯特利安","幽灵是谁","非玩家角色 阿斯特利安"}},{q="我在哪里可以摧毁远古月亮石封印？",a="封印必须带往南方的亚米萨兰，那是巴莎兰的双生废墟。寻找一座石亭，里面有一个巨大的立方体火盆，燃烧着一种远古的青绿色魔法火焰。",al={"火焰在哪里","远古火焰位置","摧毁封印"}},{q="巴莎兰和亚米萨兰之间有什么关系？",a="在大分裂之前，它们是远古暗夜精灵帝国的姐妹城市。一万年前，这两座城市都遭到了毁灭，留下了闹鬼的石柱、残留的奥术能量和不安的灵魂。",al={"双生废墟","亚米萨兰联系","巴莎兰 亚米萨兰"}},{q="是谁监禁了阿斯特利安？",a="阿斯特利安说，上层精灵中最强大的一位创造了束缚他的封印。关于他前主人的更多信息将在任务链中揭晓。",al={"谁囚禁了阿斯特利安","阿斯瑞库斯是谁","阿斯特利安的主人"}},{q="阿斯特利安记得的是哪个时代？",a="阿斯特利安最后行走于世间时，最初的永恒之井依然存在，艾萨拉女王统治着帝国，而上层精灵贵族在大分裂前拥有着他们辉煌的宫廷。",al={"阿斯特利安的过去","永恒之井时代","阿斯特利安有多古老"}},{q="解放阿斯特利安会让他的灵魂安息吗？",a="摧毁封印旨在打破阿斯特利安的牢笼。当你回到他身边时，他对于获得自由的反应自会揭晓。",al={"阿斯特利安会安息吗","阿斯特利安发生了什么","自由后的阿斯特利安"}}},fx={["8275c861"]={q="阿斯特利安为什么要摧毁远古月亮石封印？",a="远古月亮石封印是将阿斯特利安的灵魂困在巴莎兰遗迹中受苦的根源。这件封印由强大的高等精灵巫术在数千年前打造，使他身陷囹圄，无法看见外面的世界。只有在亚米萨兰的神秘古焰中摧毁它，才能斩断他的幽灵枷锁，让他获得自由，并看清卡利姆多如今的模样。",al={"为什么摧毁月亮石封印","阿斯特利安的动机","阿斯特利安为什么想打破封印"}},["51df5ddd"]={q="阿斯特利安为什么要你把封印带到亚米萨兰？",a="古老的高等精灵魔法将阿斯特利安束缚在巴莎兰，他连遗迹附近都无法离开，更别说南下前往亚米萨兰了。他需要一位旅人将封印带到古焰中。",al={"阿斯特利安为什么不能摧毁封印","阿斯特利安为什么需要我","为什么派冒险者去摧毁封印"}}},fp="11,147,27.134.0,23.371.0,17.273.1,16.195.0,46.180.0,60.221.0,24.132.1,32.178.0,45.113.1"}
P.entries["quest:95737"] = {n="Seeking Caitlin",s="一位炼金师请你去米奈希尔港寻找凯特林·格拉斯曼。她或许知道，为什么丈夫还没有汇报在挖掘现场发现的稀有草药。",h="一位炼金师请你去米奈希尔港寻找凯特林·格拉斯曼。她或许知道，为什么丈夫还没有汇报在挖掘现场发现的稀有草药。",kw={"炼金师","凯特林·格拉斯曼","挖掘","草药种子","米奈希尔港","原始草药","寻找凯特琳","湿地"},ang={["profession:Herbalism"]="身为草药学家，你受托去看看 Caitlin 的情况。她丈夫的队伍发现了一种稀有原始草药的踪迹。"},sec={{t="迟迟未到的报告",b="炼金师听 Caitlin 说，她丈夫的挖掘队发现了原始草药的踪迹。她还不知道发现了多少，也不清楚能否采到。炼金师请你去米奈希尔港找 Caitlin，两人都在等着了解承诺带回的种子究竟出了什么事。"}},faq={{q="凯特林·格拉斯曼是谁？",a="凯特林·格拉斯曼是米奈希尔港的一名炼金师。她的丈夫曾加入一支挖掘队，并发现了原始草药的踪迹。",al={"凯特林","谁是 凯特林","凯特林·格拉斯曼"}},{q="炼金师要我做什么？",a="炼金师请你去米奈希尔港找凯特林·格拉斯曼谈谈。",al={"寻找 凯特林","与 凯特林 谈谈","凯特林 任务"}},{q="挖掘队发现了什么？",a="挖掘队发现了早已失落的原始草药的踪迹，但其数量和是否容易采集仍不得而知。",al={"原始草药","稀有草药","挖掘发现"}},{q="她们为什么担心？",a="凯特林 曾答应炼金师，她丈夫会带回草药种子，但种子至今未到。两人都怀疑挖掘现场出了什么问题。",al={"种子在哪里","失踪的草药种子","为何担心"}}},fp="15,161,16.313.0,24.130.0,38.73.0,34.117.0,23.151.0"}
P.entries["quest:95748"] = {n="The Gurubashi Legends of Old",s="一位巨魔学者想在暗礁海以北拓印一块古老石板。石板上的传说或能说明失落的 I'lalai 究竟有多大。",h="一位巨魔学者想在暗礁海以北拓印一块古老石板。石板上的传说或能说明失落的 I'lalai 究竟有多大。",kw={"古老遗迹","古拉巴什","i'lalai","传说","拓印","石板","巨魔","暗礁海"},ang={["race:Troll"]="身为巨魔，你受托帮助一位学者研究有关失落巨魔城市的传说。"},sec={{t="海岸边的石板",b="学者将你带来的石板碎片与暗礁海附近的遗迹进行比较。碎片上的文字描述了一座辽阔的文明，而那些遗迹似乎太小，无法与之相符。因此，学者请你去北面的海岸丘陵，在一处古老的巨魔遗迹中拓印一块石板。"},{t="久远的记忆",b="学者欣然收下拓印，说年轻时见过这块石板。距上次读到它已经过去许多个满月，学者的记忆也渐渐模糊了。"}},faq={{q="学者想要什么？",a="学者想要拓印一块石板，上面记载着失落的巨魔城市 I'lalai 的传说。",al={"石板拓印","他需要什么","拓印请求"}},{q="石板在哪里？",a="它位于暗礁海以北海岸丘陵的一处古老巨魔遗迹中。",al={"石板位置","石板在哪里","暗礁海以北"}},{q="学者为什么想要拓印？",a="你带来的石板碎片将 I'lalai 描述为一座辽阔的文明，而暗礁海附近的遗迹似乎太小，无法与之相符。",al={"为何拓印","i'lalai 石板","失落城市传说"}},{q="I'lalai 是什么？",a="石板碎片称，I'lalai 是一座失落的巨魔城市，也是一个辽阔的文明。",al={"i'lalai 城市","失落的巨魔城市","ilalai"}},{q="学者对这块石板怎么说？",a="学者说，年轻时曾读过这块石板，但许多个满月已经过去，记忆也渐渐模糊了。",al={"学者的记忆","以前读过石板","古老的巨魔传说"}}},fp="28,122,21.278.0,13.159.0,27.93.0,20.71.0,36.128.0,16.91.0,43.105.0"}
P.entries["quest:95770"] = {n="Locating the Lost City",s="肯维雷请你前往暗礁海，寻找一处与失落之城有关的洞穴。聚集在那里的纳迦或许发现了值得调查的东西。",h="肯维雷请你前往暗礁海，寻找一处与失落之城有关的洞穴。聚集在那里的纳迦或许发现了值得调查的东西。",kw={"洞穴","i'lalai","肯维雷","寻找失落之城","lost city","鱼人","纳迦","暗礁海"},sec={{t="礁石中的洞穴",b="肯维雷记得，在鱼人定居暗礁海遗迹之前，他曾在那里潜水。他记得有一处洞穴，请你探索暗礁海，寻找洞穴入口。如今纳迦聚集在这片区域，他想知道是什么吸引了他们。"},{t="可能的发现",b="你回来后，肯维雷听你讲述所见。纳迦不断进出洞穴遗迹，但他们的目的仍不清楚。他猜想那里是否与 I'lalai 和 Lost City 有关；巨魔长久以来都认为那只是传说。如今他想展开调查。"}},faq={{q="是谁让我去搜索暗礁海？",a="肯维雷请你探索暗礁海，寻找洞穴入口。",al={"谁派我来的","肯维雷的请求","谁有此请求"}},{q="我为什么要找洞穴？",a="肯维雷记得暗礁海遗迹中有一处洞穴，并怀疑那里可能有助于找到 Lost City。",al={"为何寻找洞穴","失落之城线索","我要找什么"}},{q="纳迦为什么聚集在那里？",a="肯维雷听说纳迦聚集在这片区域，但他们的目的尚不清楚。",al={"礁石上的纳迦","纳迦为何聚集","纳迦的目的"}},{q="暗礁海遗迹发生了什么？",a="肯维雷年轻时曾在暗礁海潜水，后来鱼人定居在了遗迹中。",al={"暗礁海遗迹","那里的鱼人","谁定居在礁石"}},{q="洞穴入口在哪里？",a="洞穴入口位于暗礁海。肯维雷请你探索这片海域，寻找入口。",al={"洞穴位置","寻找入口","洞穴在哪里"}}},fp="22,146,20.228.0,20.259.1,41.76.0,30.102.0,33.88.0,37.103.0,29.88.0"}
P.entries["quest:95772"] = {n="Songblade Search",s="“寻回歌刃”是一项矮人任务，多林·歌刃请求旅行者们去湿地确认他兄弟达文的情况。达文带着一支来自洛克莫丹的考古队出发去未被探索的丘陵挖掘，但他一反常态的沉默让他的兄弟深感不妙。",h="“寻回歌刃”是一项矮人任务，多林·歌刃请求旅行者们去湿地确认他兄弟达文的情况。达文带着一支来自洛克莫丹的考古队出发去未被探索的丘陵挖掘，但他一反常态的沉默让他的兄弟深感不妙。",kw={"达文·歌刃","迪尔斯","多林·歌刃","洛克莫丹","寻找歌刃","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="往返于洛克莫丹和米奈希尔港之间的联盟旅行者经常会经过这些挖掘场，为陷入困境的矮人探矿者和工匠们提供帮助。",["race:Dwarf"]="矮人探险队和考古挖掘在卡兹莫丹随处可见，但走出洛克莫丹的安全范围，进入危险的湿地，往往会给族人带来巨大的风险。"},sec={{t="兄弟的担忧",b="多林·歌刃留在了他的工作室里，因为忙于重新装配皮带扣的订单而抽不开身，而他的兄弟达文则加入了一支从洛克莫丹出发的矮人挖掘队。达文北上进入了湿地崎岖的丘陵，渴望探索尚未被矮人镐头触及的处女地。然而，达文通常在抵达后会立刻写信，他的沉默让多林深感不安。"},{t="湿地的挖掘",b="前往湿地的旅行者们可以在维尔加挖掘场的挖掘者中找到达文·歌刃。达文与他的兄弟多林长得非常像，他带着一把独特的步枪，枪托上刻着“DLS”的缩写，这证明他确实到达了这片沼泽地中偏远的挖掘营地。"}},faq={{q="谁发布了“寻回歌刃”这个任务？",a="多林·歌刃发布了这个任务。他是一位工匠，目前正忙于重新装配一大堆皮带扣，这让他无法陪同他的兄弟进行考古挖掘。",al={"谁发布了寻回歌刃","寻回歌刃任务发布者","多林·歌刃"}},{q="达文·歌刃是谁？",a="达文·歌刃是多林·歌刃的兄弟。他与一支从洛克莫丹出发的挖掘队一起前往湿地那片未驯服的丘陵，但并没有像他通常做的那样寄回消息。",al={"多林的兄弟是谁","失踪的歌刃矮人","达文·歌刃"}},{q="在哪里可以找到达文？",a="达文位于湿地的维尔加挖掘场。你可以通过他与多林极其相似的长相，以及他那支枪托上刻有“达文·歌刃”的姓名缩写的火枪来辨认他。",al={"达文在哪里","去哪找达文·歌刃","寻回歌刃地点"}},{q="达文为什么要去湿地？",a="达文加入了一支从洛克莫丹出发的矮人挖掘探险队，前往湿地寻找未知的丘陵进行考古挖掘。",al={"为什么达文去了湿地","维尔加挖掘场的目的","矮人们为什么去湿地"}},{q="刻在枪上的缩写是什么意思？",a="刻在火枪枪托上的姓名缩写属于达文·歌刃，这证实了在挖掘场发现的那名矮人确实是多林失踪的兄弟。",al={"三个首字母代表什么","三个首字母枪上的刻字","三个首字母缩写"}},{q="多林为什么担心他的兄弟？",a="多林感到担忧是因为达文在踏上旅程后通常会及时回信。在前往湿地后迟迟没有收到信件，多林有一种不安的预感，觉得出事了。",al={"多林为什么担心","为什么要寻找达文","寻回歌刃的原因"}}},fp="16,183,18.330.0,23.239.1,37.155.0,24.160.0,26.152.0,38.111.0,44.147.0,40.170.0"}
P.entries["quest:95773"] = {n="Enemies in the Water",s="娜迦聚集在近海的古老巨魔遗迹附近，而部落的商队已遭到袭击。你受命应对这场威胁，证明自己的价值。",h="娜迦聚集在近海的古老巨魔遗迹附近，而部落的商队已遭到袭击。你受命应对这场威胁，证明自己的价值。",kw={"血顶","brinescale","水中的敌人","格罗姆高","部落","娜迦","食人魔","三叉戟","巨魔遗迹"},ang={["faction:Horde"]="部落想保护自己的商队，同时警惕来自海上的袭击。"},sec={{t="海岸传来的报告",b="部落收到报告，称娜迦正聚集在海底的古老巨魔遗迹附近。血顶和食人魔的袭击已令部落防线吃紧，来自海上的威胁更是刻不容缓。你受命对付Brinescale散兵，并带回他们的三叉戟作为证明。"},{t="葛罗’gol的消息",b="在葛罗’gol，你带回的三叉戟将被插在城门外。展示这些战利品，是为了警告众人别把部落当成好欺负的对象。你的表现也赢得了指挥官的赞许。"}},faq={{q="娜迦为何在海岸附近？",a="报告称，娜迦正聚集在海底的古老巨魔遗迹附近。",al={"海岸娜迦","水中的娜迦","娜迦为何在这里"}},{q="这里的敌人是谁？",a="威胁来自Brinescale散兵，据报是一群在海岸附近出没的娜迦。",al={"水中敌人","娜迦是谁","brinescale"}},{q="部落为何要对付娜迦？",a="部落已疲于保护商队，使其免受血顶和食人魔袭击，也担心海上会有突袭。",al={"为何杀娜迦","部落的娜迦麻烦","海上袭击"}},{q="需要什么证明？",a="你受命带回Brinescale三叉戟，证明自己已成功完成任务。",al={"三叉戟证明","带回什么","brinescale三叉戟"}},{q="这些三叉戟会怎么处理？",a="它们将被插在葛罗’gol的城门外，警告众人别把部落当成好欺负的对象。",al={"三叉戟传达的信息","插下三叉戟","葛罗’gol的三叉戟"}},{q="这如何证明我的价值？",a="指挥官赞许了你的表现，并说你很快就证明了自己对部落的价值。",al={"证明价值","部落的认可","我为何在这里"}}},fp="20,188,22.299.0,23.197.1,32.74.0,25.86.0,44.135.0,24.73.0,33.104.0,29.89.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="得知奥格拉在战斗中阵亡后，曼科里克决心为她建造一座长存的纪念碑。他请你从附近的剃刀沼地掠夺者手中找回她遗失的骨饰，好让它们陪伴在她的纪念碑旁。",h="得知奥格拉在战斗中阵亡后，曼科里克决心为她建造一座长存的纪念碑。他请你从附近的剃刀沼地掠夺者手中找回她遗失的骨饰，好让它们陪伴在她的纪念碑旁。",kw={"饰品","曼科里克","纪念碑","奥格拉","抛光骨头","野猪人","剃刀沼地掠夺者"},sec={{t="缅怀逝者",b="尽管一位治疗者设法救下了曼科里克，奥格拉却在战场上伤重不治。悲痛的战士决心让她的名字与牺牲永不被遗忘，正准备建造一座长存的纪念碑，以纪念她。"},{t="遗失的珍爱之物",b="奥格拉佩戴着珍爱的抛光骨饰，但这些饰品已不在她的安息之地。曼科里克想从附近的剃刀沼地掠夺者手中找回这些私人物品，让它们陪伴在他为她建造的纪念碑旁。"}},faq={{q="奥格拉是谁？",a="奥格拉在与野猪人的战斗中阵亡。曾帮助曼科里克的治疗者设法救下了他，却没能救回她。曼科里克打算永远缅怀她。",al={"奥格拉是谁","曼科里克的妻子","谁死了"}},{q="奥格拉的饰品是什么？",a="她的饰品是用抛光骨头制成的珍贵手工珠宝，她在遇害前一直佩戴着它们。",al={"奥格拉的饰品是什么","奥格拉的珠宝","饰品是什么做的"}},{q="为什么要追捕剃刀沼地掠夺者？",a="奥格拉倒下后，她的饰品被人拿走了。曼科里克因此派你前往她遇害地点附近，对付剃刀沼地掠夺者并找回饰品。",al={"为什么杀剃刀沼地掠夺者","谁偷了奥格拉的饰品","饰品在哪里"}},{q="曼科里克会如何处置找回的饰品？",a="曼科里克打算将找回的骨饰放在他为奥格拉建造的纪念碑旁，让她的记忆永不褪色。",al={"曼科里克的纪念碑","曼科里克会如何处置饰品","曼科里克为什么想要饰品"}}},fp="17,152,19.165.0,14.226.0,13.135.0,28.111.0,43.127.0,51.122.0"}
P.entries["quest:95775"] = {n="The Drowned City",s="一位学者请你查看由娜迦守卫的遗迹，并拓下石板上的刻痕。这座城市可能是藏有丰富失落历史的 I’lalai。",h="一位学者请你查看由娜迦守卫的遗迹，并拓下石板上的刻痕。这座城市可能是藏有丰富失落历史的 I’lalai。",kw={"木炭","沉没之城","兽皮","i’lalai","失落的历史","娜迦","拓印","遗迹","石板"},sec={{t="穿过洞穴",b="学者年事已高，无法进入遗迹，因此请你代为前往。穿过由娜迦守卫的洞穴后，学者猜测遗迹可能是 I’lalai。那座失落之城或许藏有大量历史知识。你要拓下找到的石板，并带回来。"}},faq={{q="沉没之城是什么？",a="派你前去的学者认为，这些遗迹可能是失落之城 I’lalai。",al={"沉没之城","这是什么城市","i’lalai 遗迹"}},{q="谁想让我探索遗迹？",a="一位学者请你探索遗迹，因为他们年事已高，无法亲自前往。",al={"是谁派我来的","谁要拓印","学者的请求"}},{q="我为什么要去那里？",a="学者希望遗迹中藏有大量失落的历史知识。",al={"为何探索","为何拓石板","失落的历史"}},{q="我应该带回什么？",a="用兽皮和木炭拓下你找到的石板，然后交还给学者。",al={"要带回什么","石板拓印","拓印任务"}},{q="遗迹在哪里？",a="遗迹位于由娜迦守卫的洞穴另一侧。",al={"沉没之城在哪里","娜迦洞穴","遗迹位置"}}},fp="16,132,17.294.0,25.83.0,34.82.0,26.77.0,33.95.0,20.62.0"}
P.entries["quest:95776"] = {n="The Only Good Brinescale...",s="海岸附近水域出现纳迦，引发了人们对更大威胁的担忧。你受命前往沉没之城寻找他们的首领。",h="海岸附近水域出现纳迦，引发了人们对更大威胁的担忧。你受命前往沉没之城寻找他们的首领。",kw={"brinescale","海岸","沉没之城","渗入","肯维雷","纳迦","var'taka"},sec={{t="近海威胁",b="海岸附近的纳迦虽已被杀，但他们的数量预示着更大的危险。肯维雷认为，Brinescale 纳迦正在进入沉没之城的废墟。他们出现在那里，说明他们在寻找某样可能危及海岸的东西。你受命杀死他们的首领 Var'Taka。"},{t="归来",b="你回来时，雇主认为你的到来意味着 Var'Taka 已死。纳迦首领不复存在，海岸便少了一分隐患。"}},faq={{q="Brinescale 纳迦为何在沉没之城？",a="肯维雷认为，Brinescale 纳迦正在沉没之城寻找某样东西，但他们要找什么尚不清楚。",al={"纳迦为何在那里","brinescale 的目的","纳迦在寻找什么"}},{q="肯维雷是谁？",a="肯维雷认为，Brinescale 纳迦正在渗入沉没之城。",al={"肯维雷","肯维雷是谁"}},{q="Var'Taka 是谁？",a="Var'Taka 是沉没之城中 Brinescale 纳迦的首领。",al={"var'taka","纳迦首领","brinescale 首领"}},{q="我受命做什么？",a="你受命在沉没之城杀死 Var'Taka。",al={"我该做什么","任务是什么","要杀谁"}}},fp="27,126,17.299.0,10.143.1,48.121.0,18.89.0,16.66.0,22.51.0"}
P.entries["quest:95786"] = {n="An Acquaintance in Southshore",s="尼麦兹修士派你带着一份报告前往南海镇，交给博学者迪布斯。躁动不安的巨魔和“I'lalai”一词，或许与库尔森上校的腐化有关。",h="尼麦兹修士派你带着一份报告前往南海镇，交给博学者迪布斯。躁动不安的巨魔和“I'lalai”一词，或许与库尔森上校的腐化有关。",kw={"尼麦兹修士","库尔森上校","腐化","护符","i'lalai","博学者迪布斯","斥候报告","南海镇","荆棘谷","巨魔传说"},sec={{t="报告中的一个词",b="尼麦兹修士让你从荆棘谷前往南海镇，带去一捆巨魔传说、护符和一份斥候的报告。当地的巨魔躁动不安，还提到了“I'lalai”。尼麦兹希望博学者迪布斯能判断，这些是否与库尔森上校被腐化的心智有关。"},{t="抵达南海镇",b="博学者迪布斯在南海镇接待了你，并提起你从荆棘谷远道而来。他问你此行的目的，而你手中带着尼麦兹的报告和材料。"}},faq={{q="是谁派我去南海镇的？",a="尼麦兹修士派你从荆棘谷前往南海镇，与博学者迪布斯交谈。",al={"谁派我来的","尼麦兹南海镇","尼麦兹修士"}},{q="我为什么要去南海镇？",a="尼麦兹希望博学者迪布斯检查巨魔传说、护符和一份斥候的报告，看看它们是否与库尔森上校的腐化有关。",al={"为何去南海镇","迪布斯报告","我带了什么"}},{q="博学者迪布斯是谁？",a="博学者迪布斯是尼麦兹在希尔斯布莱德丘陵的朋友，研究巨魔传说和邪恶魔法。",al={"迪布斯是谁","迪布斯南海镇","博学者"}},{q="斥候的报告说了什么？",a="报告称，当地的巨魔躁动不安，并提到了“I'lalai”。",al={"斥候报告","巨魔躁动不安","i'lalai是什么"}},{q="我在哪里能找到博学者迪布斯？",a="博学者迪布斯在南海镇。",al={"迪布斯位置","寻找迪布斯","南海镇"}}},fp="29,161,20.281.0,13.171.0,26.74.0,29.144.0,24.110.0,33.79.0,33.34.0"}
P.entries["quest:95787"] = {n="Take Two With Water",s="博学者迪布斯请你从 Drowned City 带回传说，他相信失落的巨魔城市 I’lalai 已经升起。他称这或许是本世纪最重要的考古发现。",h="博学者迪布斯请你从 Drowned City 带回传说，他相信失落的巨魔城市 I’lalai 已经升起。他称这或许是本世纪最重要的考古发现。",kw={"drowned city","i’lalai","洛阿","博学者迪布斯","石板拓印","潮汐","巨魔传说","赞达拉语"},sec={{t="迪布斯的发现",b="博学者迪布斯读过一份侦察报告和巨魔传说，其中暗示失落的巨魔城市 I’lalai 已在荆棘谷海岸附近升起。他请你从 Drowned City 带回传说。这一发现或许会改变世人对古代遗迹的认知。"},{t="石板",b="迪布斯欢迎你从巨魔遗迹归来，迫不及待地想知道你的发现。四块石板带来了新的传说，不过他古老的赞达拉语已经生疏。他认为，石板上或许提到了一个与潮汐有关的陌生洛阿。"}},faq={{q="谁在寻求这些传说？",a="博学者迪布斯请你收集 Drowned City 的传说。",al={"迪布斯是谁","博学者迪布斯","迪布斯的请求"}},{q="Drowned City 是什么地方？",a="迪布斯认为那里可能是失落的巨魔城市 I’lalai，它已在荆棘谷海岸附近升起。",al={"drowned city","什么城市","水下巨魔城市"}},{q="迪布斯要我带回什么？",a="他请你为在 Drowned City 找到的石板拓下炭印，并带回传说。",al={"要收集什么","石板拓印","drowned city 请求"}},{q="迪布斯为什么想要这些传说？",a="他相信侦察报告和巨魔传说或许指向失落的城市 I’lalai。",al={"为什么要传说","迪布斯的研究","他在研究什么"}},{q="I’lalai 可能在哪里？",a="迪布斯认为 I’lalai 已在荆棘谷海岸附近升起。",al={"i’lalai 在哪里","i’lalai 位置","失落的巨魔城市"}}},fp="19,194,19.263.0,11.226.1,32.67.0,25.93.0,38.102.0,32.90.0,25.71.0"}
P.entries["quest:95788"] = {n="Magics of the Drowned City",s="一位学者请你带回 I'lalai 的巨魔祭品，以供研究。它们奇异的造型或许与使沉没之城升起的魔法有关。",h="一位学者请你带回 I'lalai 的巨魔祭品，以供研究。它们奇异的造型或许与使沉没之城升起的魔法有关。",kw={"尼麦兹修士","黑暗魔法","沉没之城","祭品","i'lalai","纳迦","海盗","海蛇","巨魔","亡灵"},sec={{t="用于研究的祭品",b="曾研究过尼麦兹修士的裂颅者祭品的学者，请你再从 I'lalai 收集一些。据传，这座失落的巨魔城市已从水底升起，而其中或许涉及黑暗魔法。学者想将这些祭品与先前研究过的进行比较。"},{t="诸般魔法",b="你返回后，学者发现 I'lalai 的祭品别具一格，构造精巧却又简洁，还带有巨型海蛇图案。你讲述了亡灵、海盗、鲜血仪式和纳迦势力在废墟中汇聚的情形。如今，这座城市汇集了诸般魔法，学者认为有必要继续研究。"}},faq={{q="谁想要这些祭品？",a="曾研究过尼麦兹修士的裂颅者祭品的学者，请你带回 I'lalai 的巨魔祭品。",al={"谁想要祭品","学者与祭品"}},{q="为什么要收集这些祭品？",a="学者想研究 I'lalai 的祭品是否与传闻中使这座城市升起的黑暗魔法有关。",al={"收集祭品的原因","祭品研究"}},{q="I'lalai 是什么地方？",a="I'lalai 是一座失落的巨魔城市，据传它已从水底升起。",al={"沉没之城","巨魔城市"}},{q="I'lalai 的祭品有何特别之处？",a="它们带有巨型海蛇图案，构造有些方面更为精巧，有些方面则比先前研究过的祭品更为简洁。",al={"祭品造型","海蛇祭品"}},{q="哪些势力正在 I'lalai 汇聚？",a="你讲述了在废墟中游荡的亡灵、入侵的海盗、鲜血仪式和纳迦势力。",al={"谁在 i'lalai","亡灵海盗纳迦"}}},fp="26,142,18.273.0,11.331.1,26.111.0,36.115.0,16.74.0,43.148.0,38.104.0"}
P.entries["quest:95789"] = {n="Shady Saltseers",s="大财主里维加兹的一名联系人派你前往 Drowned City，追查 Saltseers——一群搜集魔法神器的海盗。沉没的巨魔遗迹再次升起后，他们的赃物引来了关注。",h="大财主里维加兹的一名联系人派你前往 Drowned City，追查 Saltseers——一群搜集魔法神器的海盗。沉没的巨魔遗迹再次升起后，他们的赃物引来了关注。",kw={"大财主里维加兹","drowned city","魔法神器","海盗","saltseers","shady saltseers","巨魔遗迹","voodoo infused artifacts"},sec={{t="大财主的请求",b="大财主里维加兹的一名联系人请你从 Drowned City 的 Saltseers 手中夺回神器。这些海盗搜集魔法物品，遗迹重现后，那里留下了许多可供掠取的物品。里维加兹的联系人要找的正是他们偷走的神器。"}},faq={{q="谁想要 Saltseers 的神器？",a="大财主里维加兹的一名联系人请你夺回这些神器。",al={"是谁派我来的","大财主里维加兹的联系人","谁想要神器"}},{q="Saltseers 是什么人？",a="Saltseers 是一群搜集魔法神器的海盗。",al={"saltseers 海盗","saltseers 是什么人","saltseers"}},{q="Saltseers 在哪里？",a="他们在 Drowned City，那是一座再次升起的沉没巨魔遗迹。",al={"drowned city 在哪里","saltseers 的位置","drowned city"}},{q="我要找什么神器？",a="你受命夺回被 Saltseers 偷走的 Voodoo Infused Artifacts。",al={"要收集什么","巫毒神器","赃物"}}},fp="15,205,19.255.0,37.62.0,22.56.0,24.71.0,32.74.0"}
P.entries["quest:95791"] = {n="The Saltseer Captain",s="一名竞争对手猎人想让 Captain Dreadrise 和他的 Saltseer Coroners 从 Drowned City 消失。他们的船员不断搜集他想要的魔法物品。",h="一名竞争对手猎人想让 Captain Dreadrise 和他的 Saltseer Coroners 从 Drowned City 消失。他们的船员不断搜集他想要的魔法物品。",kw={"captain dreadrise","drowned city","魔法物品","海盗","saltseer","saltseer coroners"},sec={{t="城中的竞争对手",b="一名竞争对手猎人在 Drowned City 寻求你的帮助，Saltseer 海盗已经成了他的眼中钉。Captain Dreadrise 和他的 Saltseer Coroners 正在搜集他想要的魔法物品。他要你除掉船长和他的三名船员。"}},faq={{q="Captain Dreadrise 是谁？",a="Captain Dreadrise 领导着 Drowned City 的 Saltseer 海盗。",al={"dreadrise","saltseer 船长","船长那个人"}},{q="Saltseer Coroners 是什么人？",a="Saltseer Coroners 是 Captain Dreadrise 的船员，协助他搜集魔法物品。",al={"saltseer 船员","coroners","dreadrise 的船员"}},{q="委托人为什么想让 Dreadrise 消失？",a="Captain Dreadrise 和他的船员不断搜集委托人一直在寻找的魔法物品，他已经厌倦了这种竞争。",al={"为什么杀 dreadrise","为什么除掉船长","dreadrise 的竞争对手"}},{q="Captain Dreadrise 和 Saltseer 在哪里？",a="Captain Dreadrise 和 Saltseer 海盗在 Drowned City。",al={"dreadrise 在哪里","saltseer 的位置","drowned city 海盗"}},{q="委托人要我做什么？",a="委托人要你在 Drowned City 击杀 Captain Dreadrise 和三名 Saltseer Coroners。",al={"我该做什么","dreadrise 任务","saltseer 任务"}}},fp="20,154,19.268.0,25.65.0,30.99.0,39.127.0,46.67.0,33.93.0"}
P.entries["quest:95792"] = {n="Clear 'em Out",s="Gelinda Coppergleam想清除洞穴里的龙。洞穴蕴藏着丰富矿藏。她承诺给予报酬，并在采矿生意盈利后分你一份。",h="Gelinda Coppergleam想清除洞穴里的龙。洞穴蕴藏着丰富矿藏。她承诺给予报酬，并在采矿生意盈利后分你一份。",kw={"洞穴","cinderscale战士","cinderscale幼龙","清除它们","gelinda coppergleam","矿藏","采矿"},sec={{t="洞穴采矿计划",b="Gelinda Coppergleam在身后的洞穴里发现了矿藏，但Cinderscale龙挡住了去路。她请你把它们清理干净，好让她带采矿队进洞。作为回报，她会给你报酬，并承诺生意盈利后分你一份。"}},faq={{q="Gelinda Coppergleam是谁？",a="Gelinda Coppergleam计划在一处矿藏丰富的洞穴里采矿。",al={"gelinda","gelinda是谁","coppergleam"}},{q="Gelinda想清除什么？",a="Gelinda请你清除洞穴里的Cinderscale幼龙和战士。",al={"清理干净","洞穴里有什么","龙的问题"}},{q="洞穴里有什么？",a="洞穴里有尚未开采的矿藏，还有Cinderscale幼龙和战士。",al={"洞穴矿石","矿藏","gelinda身后有什么"}},{q="Gelinda会给什么？",a="Gelinda会给你报酬，并承诺采矿生意盈利后分你一份。",al={"报酬是什么","gelinda的条件","采矿分成"}}},fp="13,153,14.261.0,27.86.0,35.76.0,20.83.0,24.88.0"}
P.entries["quest:95793"] = {n="Stemming the Demon Tide",s="你受命在 Dae'gun 消灭邪能卫士哨兵，遏止恶魔潮汐。这或许能让新生的植被重新生长。",h="你受命在 Dae'gun 消灭邪能卫士哨兵，遏止恶魔潮汐。这或许能让新生的植被重新生长。",kw={"dae'gun","恶魔","邪能卫士哨兵","植被重新生长","遏止恶魔潮汐"},sec={{t="新的开始",b="Dae'gun 的邪能卫士哨兵是你眼前的敌人。必须先减少他们的数量，新生的植被才能重新生长。"}},faq={{q="我需要在 Dae'gun 做什么？",a="你受命在 Dae'gun 消灭邪能卫士哨兵。",al={"dae'gun 任务","邪能卫士哨兵"}},{q="要消灭多少邪能卫士哨兵？",a="你受命消灭十二名邪能卫士哨兵。",al={"哨兵数量","需要多少哨兵"}},{q="之后可能会发生什么？",a="完成说明暗示，植被或许能重新生长。",al={"what comes next","植被重新生长"}}},fp="23,116,15.117.0,32.52.0,28.48.0,29.58.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="\"Fallen in the Fen\" 是一段忧伤的旅程，始于在挖掘场中发现一名倒下的矮人。将这个悲剧性的消息告知他在湖畔镇的兄弟多林·桑布雷德，为这位心碎的工匠带来了一个了结，他原本一直为他逝去的亲人锻造礼物。",h="\"Fallen in the Fen\" 是一段忧伤的旅程，始于在挖掘场中发现一名倒下的矮人。将这个悲剧性的消息告知他在湖畔镇的兄弟多林·桑布雷德，为这位心碎的工匠带来了一个了结，他原本一直为他逝去的亲人锻造礼物。",kw={"铁匠","多林","多林·桑布雷德","矮人","挖掘","挖掘场","沼泽中的陨落者","湖畔镇","歌刃"},ang={["faction:Alliance"]="为赤脊山的一位工匠带来慰藉，为在这王国动荡时期悲痛的城镇居民提供了一丝安抚。",["profession:Blacksmithing"]="Dorin将他的手艺倾注在原本打算给亲人的惊喜装备上，这些装备现在只能作为他兄弟英年早逝的提醒。",["race:Dwarf"]="矮人们理解失去兄弟于古老挖掘场和荒野中的苦痛，尤其是当锻造的金属比本应握住它们的手存在得更久时。"},sec={{t="挖掘场惨剧",b="挖掘场发生了一起静悄悄的悲剧，人们在那里发现了一具爱冒险的矮人的遗体。在用那名矮人自己的斗篷覆盖遗体后，一位冒险者将这沉痛的消息带回湖畔镇，去寻找他的亲人。"},{t="兄弟的悲痛",b="在湖畔镇，矮人工匠多林·桑布雷德得知兄弟的命运后崩溃了。Dorin曾花了几周时间在铁匠铺工作，为他的兄弟锻造了一套惊喜装备，但没能赶在探险队出发前完成。他因没有一同前往而深感懊悔，无法忍受重铸或出售自己亲手打造的作品，于是决定将成品赠送给带回消息的人。"}},faq={{q="什么是陨落沼泽？",a="\"陨落沼泽\" 是一项沉重的任务，始于在挖掘场发现一名倒下的矮人的遗体。用他的斗篷覆盖遗体后，你前往湖畔镇，亲自将他的命运告知这位悲痛的兄弟，多林·桑布雷德。",al={"什么是陨落于沼泽","陨落于沼泽 任务"}},{q="谁是多林·桑布雷德？",a="多林·桑布雷德是一位居住在湖畔镇的矮人铁匠。在得知挖掘场的惨剧之前，他一直在锻造装备作为送给兄弟的惊喜礼物。",al={"谁是多林·桑布雷德","湖畔镇的多林","多林·桑布雷德的角色"}},{q="在挖掘场发现的倒下的矮人是谁？",a="在挖掘场发现的倒下的矮人是多林·桑布雷德的兄弟。他最近刚路过湖畔镇为他的探险收集物资，随后在野外丧生。",al={"谁在沼泽中死了","挖掘场死去的矮人","谁的遗体在挖掘场"}},{q="在哪里可以找到多林·桑布雷德？",a="可以在赤脊山的主要定居点湖畔镇找到多林·桑布雷德，他在那里从事铁匠工作。",al={"多林·桑布雷德在哪里","多林·桑布雷德的位置"}},{q="多林在为他的兄弟锻造什么？",a="多林一直在忙着锻造打算送给兄弟的惊喜装备。遗憾的是，这份工作没能在兄弟出发探险前完成，这让他心碎不已，留下了他无法忍受保留或出售的装备。",al={"多林在锻造什么","多林的惊喜礼物"}},{q="为什么多林要把他制作的物品送人？",a="沉浸在没能陪同兄弟的悲伤和懊悔中，多林不想重铸或出售他辛苦打造的武器。他将成品赠送给带回他亲人消息的旅人，以示感激。",al={"为什么多林送出了装备","为什么多林给你装备"}}},fp="17,175,18.158.0,17.401.1,26.175.0,23.161.0,48.153.0,35.114.0,39.182.0,46.176.0"}
P.entries["quest:95798"] = {n="The Web of Magic",s="一位朋友请你把 I'lalai Fetish 带给达拉然的 Abra Cadabra。她对巨魔魔法很感兴趣，想要仔细查看它。",h="一位朋友请你把 I'lalai Fetish 带给达拉然的 Abra Cadabra。她对巨魔魔法很感兴趣，想要仔细查看它。",kw={"abra cadabra","相互冲突的魔法","达拉然","i'lalai fetish","肯瑞托","博学者迪布斯","巨魔魔法"},sec={{t="给 Abra 的护符",b="I'lalai Fetish 是要交给达拉然的 Abra Cadabra，由她仔细查看。有人请你把它带到那里，不过肯瑞托对进入他们城市的访客或许颇为挑剔。"},{t="Abra 的发现",b="Abra Cadabra 发现有数种不同的魔法作用于这件护符，其中一些彼此冲突。她警告说，落入不慎之人手中可能会很危险，并表示会把发现告知博学者迪布斯。"}},faq={{q="Abra Cadabra 是谁？",a="Abra Cadabra 是那位请你把 I'lalai Fetish 带给她的人的朋友。她对巨魔的习俗和魔法很感兴趣。",al={"abra 是谁","abra cadabra","abra"}},{q="I'lalai Fetish 是什么？",a="I'lalai Fetish 是一件物品，Abra Cadabra 正在查看其中不同且相互冲突的魔法。",al={"护符是什么","i'lalai 物品","护符"}},{q="Abra 为什么想查看它？",a="Abra 尤其对巨魔的习俗和魔法感兴趣，而这件护符是她可以查看的一项发现。",al={"abra 为什么想要它","abra 感兴趣","巨魔魔法"}},{q="护符要送到哪里？",a="有人请你把 I'lalai Fetish 带给达拉然的 Abra Cadabra。",al={"护符送到哪里","送往达拉然","abra 的位置"}},{q="为什么进入达拉然可能很困难？",a="肯瑞托对允许谁进入达拉然颇为挑剔，你可能需要赢得他们的好感。",al={"进入达拉然","肯瑞托准入","达拉然通行"}}},fp="16,131,17.184.0,15.204.1,20.132.0,27.95.0,33.108.0,33.69.0,38.110.0"}
P.entries["quest:95799"] = {n="Findings for the Explorer's League",s="博学者迪布斯请你将他对 I'lalai 石板的译文送到铁炉堡，交给史学家卡尼克。卡尼克认为，这一发现足以派遣一支队伍前往失落之城。",h="博学者迪布斯请你将他对 I'lalai 石板的译文送到铁炉堡，交给史学家卡尼克。卡尼克认为，这一发现足以派遣一支队伍前往失落之城。",kw={"探险者协会","探险者协会的发现","史学家卡尼克","i'lalai","铁炉堡","博学者迪布斯","石板","译文","巨魔"},sec={{t="致铁炉堡的一封信",b="史学家卡尼克是博学者迪布斯在铁炉堡探险者协会的同僚。迪布斯有了一项他称之为对历史意义重大的发现，并请你将他的信和一份 I'lalai 石板译文交给卡尼克。"},{t="卡尼克的回信",b="卡尼克对迪布斯的译文表示欢迎，并说他会召集一支队伍，寻找失落之城 I'lalai。他自己的研究涉及其他主题，但他尊重迪布斯对巨魔的兴趣。"}},faq={{q="是谁让我送这封信？",a="博学者迪布斯请你将他的信和一份 I'lalai 石板译文送到铁炉堡，交给史学家卡尼克。",al={"是谁交给我的","迪布斯的信","博学者迪布斯是谁"}},{q="史学家卡尼克是谁？",a="史学家卡尼克是探险者协会在铁炉堡的同僚，他负责接收博学者迪布斯的信和译文。",al={"卡尼克是谁","卡尼克 铁炉堡","那个史学家"}},{q="什么是 I'lalai 译文？",a="这是博学者迪布斯对与 I'lalai 有关的石板所作的译文。",al={"i'lalai 译文","石板译文","迪布斯的石板"}},{q="迪布斯为什么要我送信？",a="迪布斯说这项发现具有重大的历史意义，希望尽快通知他在铁炉堡的同僚。",al={"为什么送信","为什么去铁炉堡","迪布斯需要什么"}}},fp="34,175,21.244.0,17.183.1,37.124.0,24.120.0,34.72.0,42.114.0"}
P.entries["quest:95803"] = {n="A Token of Good Faith",s="Danitha让你把Rudolph Gelhardt的头颅送到幽暗城的希尔瓦娜斯·风行者那里。此举旨在向被遗忘者表明，你的人民致力于促进他们的繁荣。",h="Danitha让你把Rudolph Gelhardt的头颅送到幽暗城的希尔瓦娜斯·风行者那里。此举旨在向被遗忘者表明，你的人民致力于促进他们的繁荣。",kw={"诚意的信物","达妮莎","黑暗女王","被遗忘者","圣光","鲁道夫·格尔哈特","希尔瓦娜斯·风行者","幽暗城"},sec={{t="忠诚的证明",b="Danitha说希尔瓦娜斯不信任你们的人民，还公然贬低他们。她让你把Rudolph Gelhardt的头颅带给希尔瓦娜斯，以证明你们会管好自己的人，并支持被遗忘者。"},{t="黑暗女王的答复",b="希尔瓦娜斯怀疑Danitha的组织无法阻止更多成员将圣光用来对付自己的人民。她警告说，如果这个组织不再维护被遗忘者的利益，她或许就不会再容忍它，并表示会对他们严加监视。"}},faq={{q="是谁让我把鲁道夫·格尔哈特的头颅带给希尔瓦娜斯？",a="达妮莎让你把鲁道夫·格尔哈特的头颅送到幽暗城的希尔瓦娜斯·风行者那里。",al={"谁派我去找希尔瓦娜斯","达妮莎送头颅","把头颅交给黑暗女王"}},{q="达妮莎为什么要我把头颅带给希尔瓦娜斯？",a="达妮莎希望此举能向希尔瓦娜斯表明，你们会管好自己的人，并致力于促进被遗忘者的繁荣。",al={"为什么要带鲁道夫的头颅","送头颅是为了什么","证明忠诚"}},{q="希尔瓦娜斯为什么不信任达妮莎的人民？",a="达妮莎说希尔瓦娜斯非常不信任你们的人民，几乎公然贬低他们。",al={"希尔瓦娜斯为什么不信任我们","黑暗女王的不信任","她为什么贬低我们"}},{q="我该把鲁道夫·格尔哈特的头颅带到哪里？",a="她让你把鲁道夫·格尔哈特的头颅带到幽暗城的希尔瓦娜斯·风行者那里。",al={"希尔瓦娜斯在哪里","送头颅的地点","带去幽暗城"}}},fp="21,186,17.189.0,24.238.1,59.92.0,55.135.0,46.86.0,42.89.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Grace of 安瑟 and Mu'sha是一场神圣的牛头人朝圣之旅，在红云台地进行，旨在纪念作为大地母亲天界双眼的太阳和月亮。通过将易碎、闷燃的香火带到东南丘陵的一座高处祭坛，旅行者们向这些为平原带来温暖、生命和指引的天界之光表达敬意。",h="Grace of 安瑟 and...",kw={"安瑟","大地母亲","月亮","艾露恩","莫高雷","红云台地","祭坛","闷燃的香火","太阳","牛头人"},ang={["class:Druid"]="牛头人德鲁伊将太阳和月亮的永恒之舞视为平衡的原始体现，指引着他们对自然宇宙韵律的理解。",["class:Shaman"]="虽然萨满直接与土、火、水、风的尘世之灵沟通，但他们同样向这对天界孪生神祇致敬，它们的光芒维系着所有的生命能量。",["faction:Horde"]="在台地上进行的圣礼展示了游牧的牛头人带给部落盟友的那种深厚的、尊崇自然的文化。",["race:Tauren"]="对安瑟和艾露恩的敬畏是牛头人精神身份的核心，提醒年轻的勇士们，生活不仅需要像忠于大地母亲一样，还要忠实地敬奉这两道天界孪生之光。"},sec={{t="大地母亲的双眼",b="在牛头人的神话中，太阳和月亮被称为安瑟和艾露恩，被尊为大地母亲的双眼。虽然元素之灵直接居住在艾泽拉斯的岩石、风和水中，但这两位天界孪生神祇却在天界的至高处注视着这个世界。它们在天空中永恒的旅程标记着昼夜的永恒节奏，为所有生物带来温暖、指引和希望。纪念这两位孪生神祇是一项基本的精神职责，它教导我们要明白平衡不仅需要敬畏脚下的土地，也要敬畏从天而降的光芒。"},{t="高地上的祭礼",b="为了纪念这两位天界孪生神祇，朝圣者必须携带闷燃的香火前往俯瞰台地的东南丘陵，那里坐落在多刺的野猪人领地以南。这段旅程是对专注力和速度的考验：芬芳的余烬必须在燃尽成冰冷的灰烬之前送达，旅行者在沿途必须小心，避免让香火沾水。到达高处的祭坛后，朝圣者将余烬投入圣火中，让芳香的烟雾带着他们的敬意升入天空，飘向太阳和月亮。"}},faq={{q="安瑟和艾露恩是谁？",a="安瑟和艾露恩是牛头人神话中的太阳和月亮，被尊为大地母亲的双眼。与土、风、火、水之灵不同，它们并不直接居住在艾泽拉斯的土地中。相反，它们从上方的苍穹照亮世界，安瑟提供温暖和生命，而艾露恩则提供夜间的指引和慰藉。",al={"安瑟和艾露恩是谁","安瑟和艾露恩背景故事","牛头人的太阳和月亮神"}},{q="为什么牛头人要向太阳和月亮献祭？",a="牛头人的哲学教导说，平衡对万物的存在至关重要。虽然尘世之灵掌管着眼前的景观，但安瑟和艾露恩的光芒为所有生物赋予了至关重要的能量、远见和希望。在高处献上闷燃的香火是一种相互尊重的行为，承认凡人的生命若没有这两个天体的持续恩泽就无法繁荣。",al={"为什么要敬畏太阳和月亮","牛头人的天界崇拜","为什么要纪念安瑟和艾露恩"}},{q="安瑟和艾露恩的祭坛位于何处？",a="安瑟和艾露恩的祭坛位于台地东南方的高丘之上。它俯瞰着下方的广阔平原，坐落在多刺的野猪人领地以南。其高海拔提供了开阔、无遮挡的视野，使其成为向天空升起烟雾的理想之地。",al={"安瑟祭坛在哪里","祭坛位置 莫高雷","如何找到香火祭坛"}},{q="闷燃的香火有什么意义？",a="闷燃的香火是祈祷和敬意的有形媒介。当芬芳的余烬燃烧时，升起的烟雾将旅行者的虔诚直接带向天空，飘向太阳和月亮。将余烬投入祭坛圣火标志着仪式的结束，让朝圣者获得一种宁静的精神满足感。",al={"香火有什么作用","香火供奉的含义","为什么要燃烧闷燃的香火"}},{q="为什么要快速运送香火并保持干燥？",a="该仪式要求朝圣者保持警惕、速度和小心。香火投入祭坛圣火时必须仍处于闷燃状态，这意味着旅程必须在余烬烧成冷灰之前完成。此外，浸入水中会立即熄灭余烬，在祭品到达高处之前就将其毁坏。",al={"为什么要给香火计时","不要弄湿它","香火燃尽"}},{q="野猪人会威胁到前往祭坛的朝圣之旅吗？",a="野猪人部落占据了祭坛位置以北丘陵中防御严密的棘刺巢穴。虽然祭坛本身位于他们领地南侧的一处安静观景点，但旅行者必须小心不要误入野猪人的荆棘丛，因为敌对攻击很容易延误或破坏这一精细的旅程。",al={"祭坛附近的野猪人","野猪人会威胁朝圣者吗","台地南部的野猪人"}},{q="艾露恩与其他文化对月亮的看法有何不同？",a="牛头人神话将月亮视为艾露恩，即大地母亲充满慈爱、注视着凡人生命的左眼。艾泽拉斯的其他种族，尤其是暗夜精灵，将同一轮明亮的白色月亮尊为女神艾露恩，但牛头人传统认为她与其太阳孪生兄弟安瑟有着不可分割的联系。",al={"艾露恩是艾露恩吗","牛头人的月亮与艾露恩","艾露恩与暗夜精灵"}}},fp="26,245,27.439.0,26.365.0,26.278.0,53.262.0,49.238.0,51.250.0,55.237.0,54.242.0,61.217.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Heartwoven 是湿地的一个联盟任务，讲述了一个关于生存与关爱的简单故事。在为一名被困在沼泽中的采集者清理出逃生路线后，冒险者将一颗手工编织的芦苇心带回米奈希尔港交给凯特琳·格拉斯曼。",h="Heartwoven 是湿地的一个联盟任务，讲述了一个关于生存与关爱的简单故事。在为一名被困在沼泽中的采集者清理出逃生路线后，冒险者将一颗手工编织的芦苇心带回米奈希尔港交给凯特琳·格拉斯曼。",kw={"凯特琳·格拉斯曼","格拉斯曼","心织","米奈希尔港","芦苇心","芦苇","湿地"},ang={["faction:Alliance"]="米奈希尔港是湿地的一个关键联盟港口，这里的普通平民依赖过往的旅行者来确保危险的沼泽路线安全。",["profession:Cooking"]="收到芦苇心并得知丈夫幸存后，凯特琳立即着手准备一顿温暖丰盛的饭菜，欢迎他回家。"},sec={{t="来自沼泽的信号",b="在湿地险恶的沼泽中，生活与劳作总是伴随着危险。阿丁·格拉斯曼前往挖掘场查看奇异的草丛，却发现自己被困在沼泽的重重危机之中，直到一位路过的旅人清理出了一条荒野之路。他虽然精疲力竭，但意志坚定，在返回港口避难之前，他停下来喘口气，并整理好自己的收获。"},{t="米奈希尔的信物",b="在踏上归途之前，采集者从包里拿出沼泽芦苇，编织成了一颗草心。他将这件信物交给冒险者，请其带往米奈希尔港交给凯特琳·格拉斯曼。在这个繁忙的沿海定居点，凯特琳在深深的忧虑中等待着，当听说他幸存下来并很快就会回来享用热腾腾的饭菜时，她如释重负，将那颗编织的芦苇心紧紧地贴在胸前。"}},faq={{q="心意交织 是什么任务？",a="心意交织 是湿地的一个联盟任务。一位冒险者帮助了被困在沼泽挖掘场地的阿丁·格拉斯曼，他用芦苇制作了一件编织信物，作为生存和爱的信息，委托其交给米奈希尔港的凯特琳·格拉斯曼。",al={"心意交织 任务","心意交织 是什么","湿地 心意交织"}},{q="凯特琳·格拉斯曼是谁？",a="凯特琳·格拉斯曼是一位焦急地在米奈希尔港等待的联盟居民。她为丈夫阿丁的安危感到担忧，因为他深入湿地危险的挖掘场地，当你带去他幸存的消息时，她感到无比宽慰。",al={"凯特琳·格拉斯曼是谁","凯特琳 米奈希尔港","凯特琳·格拉斯曼"}},{q="芦苇编织的心是什么？",a="芦苇编织的心是那位被困的采集者用行囊里的沼泽芦苇手工制作的信物。他匆忙编织它，是为了证明自己还活着，并很快就能回家，以此让家人安心。",al={"芦苇心是什么","用芦苇编织的心","芦苇编织的心"}},{q="在哪里交 心意交织 任务？",a="该任务最终需要交给凯特琳·格拉斯曼，她正在湿地西海岸的联盟港口城市米奈希尔港等待。",al={"哪里交 心意交织 任务","心意交织 交任务地点","凯特琳·格拉斯曼在哪里"}},{q="谁发布了 心意交织 任务？",a="该任务由凯特琳的丈夫阿丁·格拉斯曼发布，他在湿地的挖掘场地中幸存了下来。在一位冒险者为他清理出一条安全通道后，他休息片刻，收集好自己的收获，并将一件手工制作的信物交给冒险者带给凯特琳。",al={"谁发布 心意交织 任务","谁制作了那颗心","心意交织 幸存者"}},{q="被困的采集者遭遇了什么？",a="阿丁前往挖掘场地查看奇异的高大草丛，却因受惊的野生动物（尤其是蜘蛛）袭击了挖掘队而被困。多亏了一位冒险者清理了周围的威胁，他才得以幸存，并能安全地收集好自己的收获，返回米奈希尔港。",al={"采集者遭遇了什么","他幸存了吗","心意交织 幸存者"}}},fp="10,154,25.296.0,18.318.0,29.211.0,24.201.0,29.156.0,32.125.0,35.182.0,39.273.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="“Lost Relic Carry”涉及回收一件古代岩石机械自动体的残片，并将其送交给湿地的勘察员维尔加。这件圣物的成分材质未知，暗示了泰坦高超的工程技术，这令矮人研究者对其肃然起敬。",h="“Lost Relic Carry”涉及回收一件古代岩石机械自动体的残片，并将其送交给湿地的勘察员维尔加。这件圣物的成分材质未知，暗示了泰坦高超的工程技术，这令矮人研究者对其肃然起敬。",kw={"自动体","挖掘场","探险者协会","搬运失落的圣物","勘察员维尔加","岩石机械","泰坦圣物","湿地"},ang={["profession:Engineering"]="岩石机械自动体的复合材质和精密设计暗示了远超标准凡人工程学的先进机械原理。",["race:Dwarf"]="探险者协会的矮人探险家们痴迷于发掘他们制造者的古代圣物，这使得这件自动体碎片成为矮人遗产中一件珍贵的发现。"},sec={{t="古代工艺的碎片",b="在古老之地的深处，冒险者可以发掘出一件岩石机械自动体的残损组件。它并非普通的碎石，其独特的复合材质揭示了一种与泰坦相关的、先进古代机械的工艺水准。"},{t="运往挖掘场",b="勘察员维尔加驻扎在湿地的挖掘场，负责研究古代遗迹。将圣物从危险中带出并交给他，为那些探索古代遗产的矮人学者提供了宝贵的实物证据。"}},faq={{q="什么是泰坦圣物？",a="这件圣物是一件古代岩石机械自动体的残片。它并非普通的石块碎片，而是由一种未知的复合材料构成，显然曾是某种精密机械装置的一部分。",al={"什么是圣物","物品是什么","岩石机械碎片"}},{q="勘察员维尔加是谁？",a="勘察员维尔加是一位矮人研究者，负责监管湿地的挖掘场。他研究在该地区挖掘点发现的古代土灵遗骸和圣物。",al={"维尔加是谁","维尔加背景","挖掘场负责人"}},{q="圣物需要送到哪里？",a="圣物需送到位于湿地的挖掘场交给勘察员维尔加，那里是矮人挖掘者调查古代遗迹的地方。",al={"我该送到哪里","去哪里交任务","维尔加位置"}},{q="是什么制造了岩石机械自动体？",a="该自动体碎片被确认为泰坦圣物。在矮人传说中，古代机械构装体和岩石自动体都与塑造世界的神秘泰坦有关。",al={"谁制造了岩石机械","自动体起源","泰坦关联"}},{q="为什么勘察员维尔加对圣物如此敬重？",a="冒险进入这些自动体栖息的深处极其危险。维尔加指出，能够从探索中幸存并带回这样一件完好的碎片，确实令人敬佩。",al={"为什么维尔加印象深刻","危险探索"}},{q="自动体的材质有什么不同寻常之处？",a="这种材料是一种独特的复合材料，具有不同于普通石材或锻造金属的陌生质感，展现了古代泰坦构装体高深而神秘的工艺。",al={"材质是什么","奇怪的复合材料"}}},fp="16,141,27.158.0,26.198.0,24.140.0,26.167.0,42.130.0,37.159.0,59.164.0,47.153.0"}
